INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_02', '韌性', 'Resilience', 'nan', '衡量從困難中恢復、處理變化並在困難時期保持情緒堅強的能力。反映情緒強度、靈活性以及在壓力下茁壯成長的能力', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_03', '認知彈性', 'Cognitive Flexibility', 'nan', '衡量根據新資訊或變化的環境調整思考策略和行為的能力，顯示心理靈活性和問題解決的多樣性', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_04', '適應敏捷', 'Change Agility', 'nan', '衡量快速適應、保持靈活性並對變化的環境、優先事項和期望做出積極回應的能力', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_05', '自主領導', 'Self-Leadership', 'nan', '衡量一個人透過目標設定、激勵和個人問責來領導自己的能力', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_06', '人際影響力', 'Social Influence', 'nan', '衡量說服、啟發和影響他人思想、態度或行為的能力。反映堅定自信、魅力、領導風範和溝通效能', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_07', '創造性思考', 'Creative Thinking', 'nan', '衡量產生原創想法、發散性思考以及以創新方式應對挑戰的能力', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_08', '卓越追求動機', 'Achievement Motivation', 'nan', '衡量一個人對卓越表現的驅動力、對技能精通的追求以及對卓越的承諾', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_09', '自我覺察', 'Self-Awareness', 'nan', '衡量一個人對自己的情緒、行為、動機以及對他人影響的覺察程度', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_10', 'AI科技素養', 'AI Literacy', 'nan', '衡量理解、使用和批判性評估人工智慧技術的能力', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_11', '同理心', 'Empathy', 'nan', '衡量設身處地的能力；並以他人的參考架構去理解或感受他人正在經歷甚麼', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_12', '積極傾聽', 'Active Listening', 'nan', '衡量專心傾聽、處理資訊並在對話中有效回應的能力', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_13', '好奇心', 'Curiosity', 'nan', '衡量學習、探索和理解新想法、經驗或資訊的渴望', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_14', '終身學習', 'Lifelong Learning', 'nan', '衡量持續追求新知識和技能以促進個人和專業發展的動機', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_15', '系統性思考', 'Systems Thinking', 'nan', '衡量理解和管理複雜系統、模式和相互依存關係的能力', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_16', '可靠性', 'Dependability', 'nan', '衡量一個人的可靠性、一致性和可信度', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_17', '準確嚴謹度', 'Attention to Detail', 'nan', '衡量在完成任務時達到徹底性和準確性的能力', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_18', '協調溝通', 'Interpersonal Communication', 'nan', '衡量基本的溝通能力，如清晰表達、理解他人、回應性互動、自信堅定和有效傾聽', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_19', '協商談判', 'Negotiation Skills', 'nan', '衡量一個人在談判情境中的方法、效能和心態', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_20', '批判性思考', 'Critical Thinking', 'nan', '衡量邏輯推理、資訊分析、批判評估和決策判斷能力', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_21', '社交智商', 'Social Intelligence', 'nan', '衡量社會覺察、情境理解和關係管理能力', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_22', '高效決策', 'Decision-Making', 'nan', '衡量在問題解決、信心、風險分析和果斷性方面的決策效能', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_02', '成就動機', 'Achievement Striving', 'nan', '衡量一個人對待工作認真的程度、提高工作表現的意願，以及努力達成目標的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_03', '審慎', 'Deliberation', 'nan', '評估一個人是否會於行動前審慎思考。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_04', '義務感', 'Dutifulness', 'nan', '衡量一個人有多大程度遵循良知和規範而行。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_05', '衝動管理', 'Impulse Control', 'nan', '衡量一個人為達長期目標，管理自身衝動、情緒和行為的能力。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_06', '條理性', 'Orderliness', 'nan', '衡量對例行程序、審議和細節方向的偏好。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_07', '完美主義', 'Perfectionism', 'nan', '衡量一個人追求完美和無瑕疵的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_08', '自我勝任感', 'Self Competence', 'nan', '衡量一個人覺得自己是否有能力、有效率且可以掌控局面。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_09', '自律性', 'Self Discipline', 'nan', '衡量延遲滿足、抗拒短期誘惑以實現長期目標的能力。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_10', '誠實謙遜', 'Honesty-Humility', 'nan', '評量受訪者在誠懇、公正、避免貪婪及謙虛面向的個人差異。例如在預期目標、利益下是否能維持誠實、公平對待他人，不會過度炫耀或重視財富、社會地位，或視特權為應得權益。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_11', '誠懇', 'Sincerity', 'nan', '評量為了達成目標而願意去操縱、欺騙他人的意願。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_13', '公正性', 'Fairness', 'nan', '評量為了領先他人是否願意欺騙、偷竊、貪污或利用他人的意願。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_14', '謙虛', 'Modesty', 'nan', '評量對於他人與自身關係上的看法。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_15', '心理資本', 'Psychological Capital', 'nan', '唯一重要正向特質，對態度、行為和表現有積極影響，包含以下四種心理特質：希望、效能、韌性和樂觀情緒。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_16', '希望', 'Hope', 'nan', '對於個人將目標與達成該目標的動機付諸概念化與策略化的能力，其看法為何。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_17', '目標效能感', 'Efficacy', 'nan', '個人對於自己付出努力達成目標的能力有信心的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_18', '韌性', 'Resilience', 'nan', '如何面對壓力或逆境以及降低自身的受損性;包含於衝突、失敗、責任變更(甚或加重)後的挽救的能力。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_19', '樂觀', 'Optimism', 'nan', '個人對事物的解讀方式或是看待生活中不如意的方式。高度樂觀者會解釋成不如意只是暫時的，而悲觀者則通常認為這些不如意將會是永久的且無所不在。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_20', '創新力', 'Innovativeness', 'nan', '用創新的方式做事及發現問題與找出解決方式的慾望;不想受限於既有思考方式以及挑戰主流規則。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_21', '效率取向', 'Approach to Efficiency', 'nan', '想要變得更精確、更可靠、更有效率的欲望。低分者在解決問題時更加遵循規範、精確且有條理。高分者對繁文縟節不太關心，不喜歡總是按照固定的程序和結構行事，且往往以不同尋常的角度來處理任務。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_23', '獨創性', 'Sufficiency of Originality', 'nan', '發揮其創新性、以另類觀點看待事情及用不同以往的方式做事的意願。高分者經常找出創新方法解決問題，而低分者的想法往往在規範或既定程序內，較少原創性想法。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_12', '低物質傾向', 'Materialism Avoidance', 'nan', '對於財富及地位這類事物的重視程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_01', '分析性思考', 'Analytical Thinking', 'nan', '衡量邏輯思考、識別模式、系統性分析資訊以及運用結構化推理解決問題的能力', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_23', '社會期望反應', 'Social Desirability', 'nan', '評估個體是否誠實回答，還是為了塑造樂觀形象和取得他人認可，而歪曲自己的信仰和答案。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_01', '盡責', 'Conscientiousness', 'nan', '個人的自制力程度以及把工作做到盡善盡美的慾望。包含成就追求、審慎（深思熟慮）、盡職盡責、衝動控制、條理性、完美主義、自我勝任感、自律。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_22', '紀律遵循度', 'Rule Governance', 'nan', '反映一個人願意在既定架構內工作或用傳統方式做事的程度。低分者喜歡以既有且被接受的方法來解決問題，他們在存在明確規則的情況下表現最佳。高分者則不依賴於被接受的方法來解決問題，他們更喜歡在沒有既定規則的情境中處理問題。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_24', '真實性', 'Authenticity', 'nan', '衡量個體的行為與其價值觀及欲望的一致性，儘管有著外界的社會從眾壓力，依然保持一致。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_25', '集體意識', 'Collective Orientation', 'nan', '衡量對個體間凝聚力重視和強調的程度，以及集體優先於個人的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_26', '同理心', 'Empathy', 'nan', '衡量設身處地的能力；並以他人的參考架構去理解或感受他人正在經歷甚麼。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_27', '權益公平感', 'Equity Perception', 'nan', '是指一個人對付出與回報的在意程度，以此來評測出一個人對職場公平/公正的在意程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_28', '感謝', 'Gratitude', 'nan', '評估個人表達感激的傾象差異。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_29', '人際適應力', 'Interpersonal Versatility', 'nan', '一個人在多大程度上能夠適應不同類型的人，管理所有人際交往中固有的自然緊張關係，並建立起互利互惠的關係。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_30', '個人責任感', 'Personal Accountability', 'nan', '衡量個人具備責任感和把事情做好的決心的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_31', '個人成長動機', 'Personal Growth Initiative', 'nan', '評估個人對個人成長的主動性以及參與改變和發展自我的渴望。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_32', '心理特權', 'Psychological Entitlement', 'nan', '評量其認為應得到特權及特殊待遇的程度，一般不太考慮到其實際能力、努力或績效高低。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_33', '社會期望反應', 'Social Desirability', 'nan', '評估個體是否誠實回答，還是為了塑造樂觀形象和取得他人認可，而歪曲自己的信仰和答案。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_34', '工作熱忱', 'Work Passion', 'nan', '對工作的熱忱程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_35', '生活熱情', 'Zest', 'nan', '衡量個體在日常工作與生活中，是否傾向以積極、充滿熱情與活力的方式行事，並對未來抱持期待與動能。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_36', '情緒易激度', 'Temper', 'nan', '衡量一個人在面對煩惱或挫折時，情緒被激起的容易程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_01', '心理資本', 'Psychological Capital', 'nan', '對態度、行為和表現有積極影響的個人發展情況；其特點是存在四種心理資源成分：希望、效能感、韌性和樂觀。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_02', '希望', 'Hope', 'nan', '對於個人將目標與達成該目標的動機付諸概念化與策略化的能力。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_03', '效能感', 'Efficacy', 'nan', '個人對於自己付出努力達成目標的能力有信心的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_04', '韌性', 'Resilience', 'nan', '如何面對壓力或逆境以及降低自身的受損性，包含於衝突、失敗、責任變更(或加重)後的恢復能力。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_05', '樂觀', 'Optimism', 'nan', '個人對事物的解讀方式或是看待生活中不如意的方式。高度樂觀者會解釋成不如意只是暫時的，而悲觀者則通常認為這些不如意將會是永久的且無所不在。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_06', '工作投入性', 'Job Involvement', 'nan', '一個人專注於工作和職位，較不關注生活其他方面的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_07', '職業素養', 'Professionalism', 'nan', '傾向於堅持既定的標準，並表現出超越基本要求的水準。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_08', '反饋尋求', 'Feedback Seeking', 'nan', '評量個人尋求績效反饋以協助適應、學習和改進的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_09', '權益公平感', 'Equity Perception', 'nan', '是指一個人對付出與回報的在意程度，以此來評測出一個人對職場公平 / 公正的在意程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_10', '精力充沛', 'Liveliness', 'nan', '評量過著步調快速與繁忙的生活的傾向，行事快速、積極、有拼勁。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_11', '可塑性', 'Malleability', 'nan', '衡量個人的可塑性，即個人被認為能夠改變其特質、智力和創造力的程度，這對動機、參與和績效有重要影響。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_12', '社會期望反應', 'Social Desirability', 'nan', '評估個體是否誠實回答，還是為了塑造樂觀形象和取得他人認可，而歪曲自己的信仰和答案。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_13', 'A型性格', 'Type A Personality', 'nan', '行為模式中可明顯看到其進取心、競爭力、掌握狀況、易被激發之敵意以及重視時間的觀念。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_14', '競爭欲望', 'Desire to Compete', 'nan', '衡量一個人在每項活動中渴求勝利，掌握所有任務並感到優越的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_15', '企圖心', 'Hard-Driving', 'nan', '發憤圖強和慾望導向高於一切的傾向。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_16', '匆忙/多工性', 'Hurry', 'nan', '有種急於想要完成所有工作的迫切欲望，常常同時進行多項任務並注重成果。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_17', '時間壓力', 'Pressed for Time', 'nan', '一個人做事傾向持續處於緊迫感中，與時間賽跑，對受延誤耽擱的事沒有耐心。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_18', '情緒反應', 'Temper', 'nan', '衡量面對煩惱或挫折感時的易衝動程度。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (13, 'ANI_01', 'A', 75, 100, '結構清晰', '能穩定運用邏輯與結構化方式拆解問題，辨識關鍵資訊與模式，在複雜或不確定情境下仍能維持分析品質。', '適合承擔問題定義、方案評估與多資訊整合任務。', '表現出穩定的分析性思考，能以邏輯與結構化方式拆解問題、辨識關鍵資訊與模式，面對複雜或不確定情境仍可維持分析品質。', '{"do": "可用於：①解釋其優勢在「結構化拆解、關鍵訊號辨識、方案比較」②給出任務/角色建議（如問題定義、方案評估、多資訊整合）③提醒仍需用資料/事實驗證結論與假設。", "dont": "禁止：①將此特質等同智商、學歷或專業能力高低②保證分析結論一定正確③用貼標/貶抑語氣（如「你就是理工腦」）④推論心理疾病或人格問題。"}', 'ANI', '你很擅長把複雜問題拆開來看、抓到重點與脈絡；即使情況不太明確，也能整理出清楚的分析方向。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (12, 'ANI_01', 'C', 0, 49, '分析支援', '在資訊複雜或模糊時容易出現焦點分散或結構不足，需要討論、範本或工具協助。', '適合搭配資料整理、拆解模板或團隊共識流程。', '在資訊複雜或模糊時，分析焦點可能較分散，較適合在拆解模板、工具或團隊討論的支援下進行梳理與決策，能更快建立可行的分析結構。', '{"do": "可用於：①提供具體支撐（拆解模板、問題清單、決策樹、範例）②建議用視覺化整理與共識流程（白板、表格、會議紀錄）③強調「需要支援≠不會思考」，把建議聚焦在如何搭建結構。", "dont": "禁止：①說「不會思考/不適合策略」等否定性判斷②把低分當成缺陷或道德評價③推論注意力/心理疾病④要求其在缺乏脈絡與支援下獨立完成高不確定分析。"}', 'ANI', '當資訊很多又不清楚時，你可能需要先把重點拉回來；用清單/模板或和團隊一起討論，會更快整理出可行方向。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (6, 'ANI_03', 'B', 50, 74, '調整中', '願意接受新方式，但需要時間理解與消化，熟悉後表現會明顯提升。', '提供背景、理由與示範，有助於縮短適應時間並降低摩擦。', '在變化情境下具備一定的調整能力，但較需要先理解背景、理由與可能影響，在釐清之後多數情況能接受新做法並逐步調整自己的運作方式。', '{"do": "可用於：①說明其屬於「理解後可調整」的型態，適合搭配充分溝通與示範②提供主管或團隊在引入改變時的操作建議（說明脈絡、給範例、設試行期）③鼓勵個人運用小步試驗或先在安全情境中嘗試新方法。", "dont": "禁止：①把需要理解過程解讀為「固執」或「抗拒」②用急切或壓迫性語言要求立即改變③忽略其對穩定性與可預期性的合理需求④推斷其不適合任何變革相關任務。"}', 'ANI', '面對新的做法或改變時，你不會完全排斥，但會需要先弄懂為什麼要這樣做、會影響到什麼；一旦理解之後，通常能慢慢跟上。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (15, 'ANI_04', 'C', 0, 49, '穩定導向', '面對頻繁變動時需要較多適應時間，較依賴既有流程與明確指示。', '適合變動較小或規範明確的環境；變更管理需提供緩衝與支援。', '在變化頻繁或方向多次調整的環境中，較容易感到壓力或不安，會更偏好遵循既有流程、清楚指示與穩定節奏，以維持工作品質與心理安全感。', '{"do": "可用於：①說明其對穩定性與預期性的需求，並建議在調整時提供足夠的說明、緩衝期與支援②協助設計較固定的作業節奏或明確 SOP，讓其在穩定框架中貢獻③提醒組織在大幅變革時，需特別關注這類成員的溝通與陪伴。", "dont": "禁止：①以「抗拒改變」「跟不上時代」等字眼貶低其風格②忽略其在穩定運作、流程維護上的價值③用恐嚇或壓力來逼迫迅速調整④將其描述為不適合任何涉及變化的職務。"}', 'ANI', '你會比較喜歡有清楚流程和固定節奏的環境；如果變化太多、太快，先有明確說明和一步一步的指引，會讓你比較安心、也比較做得好。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (17, 'ANI_05', 'B', 50, 74, '框架依賴', '在目標與期待清楚時表現穩定，但較依賴外部節奏與檢核。', '提供階段性目標、優先序與回饋節點，有助於維持動能。', '在目標與期待清楚時，能穩定完成任務並維持一定自我管理，但在缺乏結構或優先順序不明時，較仰賴外部框架與檢核來維持節奏。', '{"do": "可用於：①說明其適合在有明確目標與節奏設計的情境下發揮穩定表現②建議建立里程碑、檢核點與可視化進度板來支撐自我管理②協助個人學習如何拆解任務與設定自己的節奏，而非單純依賴他人提醒。", "dont": "禁止：①將對結構的需求解讀成「不負責任」或「被動」②用批判語氣描述其為「需要人盯」的對象③忽略組織在目標清晰度與任務設計上的責任④推論其不適合承擔任何自主性較高的工作。"}', 'ANI', '當方向、期限和標準都說清楚時，你可以把事情處理得不錯；如果一切都很模糊，會比較需要有人一起排優先順序、幫忙定節奏。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (21, 'ANI_06', 'C', 0, 49, '專業輸出', '影響多來自專業產出而非互動帶動，較少主動推動他人改變。', '適合專注型、個人貢獻或以成果說服的角色配置。', '在人際互動中，影響力多來自專業產出或成果本身，而非主動發起說服或帶動他人，較少在互動中主動推動他人改變或搶佔發言位置。', '{"do": "可用於：①說明其偏向以專業與成果影響他人，適合在重視品質與貢獻的情境中發揮②建議搭配明確的成果呈現管道（簡報、文件、評估報告），讓其影響力被看見③鼓勵在安全情境下，逐步練習表達觀點與說明思路，而非硬性要求改變風格。", "dont": "禁止：①將其標籤為「不擅長人際」「不合群」②要求其立即轉變為高度外向、強勢主導的溝通風格③忽略其在專業深度與穩定輸出上的價值④以此分數推論其不適合任何需要合作或溝通的職務。"}', 'ANI', '你比較習慣用「把事情做好、把成果做出來」來影響別人，而不是用說服、主導氣氛或去爭取舞台。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (24, 'ANI_07', 'C', 0, 49, '規範取向', '偏好既定流程與標準作法，較少主動提出新構想或冒險嘗試。', '適合高一致性、合規或標準化要求高的任務。', '在思考模式上偏好遵循既定流程與標準作法，較少主動提出新構想或冒險嘗試，更傾向在清楚規則下確保品質與一致性。', '{"do": "可用於：①說明其在標準化、品質管控與合規要求高的情境中具備穩定優勢②建議投入在需要一致輸出、精準執行或風險敏感度高的任務③鼓勵在安全範圍內，以小步調整或微創新方式逐步擴展彈性。", "dont": "禁止：①貼上「沒創意」「保守到不行」等負面標籤②忽略其在穩定營運與風險控管上的重要性③以恐嚇方式要求其頻繁冒險或快速接受高度不確定變化④將此分數視為學習能力或發展潛力的否定。"}', 'ANI', '你會比較喜歡照規則、依照既有做法把事情做好，而不是常常去試新的路線或大幅改變原本的做法。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (26, 'ANI_08', 'B', 50, 74, '目標導向', '在目標清楚與回饋機制明確時能穩定投入，動能與里程碑連動。', '設定清楚指標與階段成果，有助於維持節奏與投入。', '在有明確目標與回饋機制時能穩定投入，動機與節奏多與里程碑、成果回饋和外在環境連動，對清楚的期望與進度管理反應較佳。', '{"do": "可用於：①說明其動機表現與「目標清晰度、回饋頻率」之間的關係②建議透過清楚KPI、階段成果與定期回顧來維持投入度③協助個人學習在目標不夠清楚時，主動澄清與設定自己可控的小目標。", "dont": "禁止：①將其描述為「需要人盯才會動」②把所有動機起伏歸咎於個人意志力而忽略目標設計問題③用分數判斷其不適合承擔重要專案④以羞辱方式處理動力下降，而不是檢視系統與情境。"}', 'ANI', '當目標、指標和回饋都清楚時，你會比較有動力，也比較知道該怎麼調整步伐往前走。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (30, 'ANI_09', 'B', 50, 74, '情境覺察', '在特定情境或他人提醒下能察覺自身狀態，但不一定隨時保持反思。', '透過回饋節點與引導提問，可提升自我調節表現。', '在特定情境、他人回饋或事件觸發下，能察覺自己的情緒與反應，但不一定隨時保持自動反思模式，較需要外界提示或停頓空間來整理。', '{"do": "可用於：①說明其覺察多與「情境與他人回饋」連動，可透過定期檢視與對話提升自我調節②建議設計反思節點（如1對1談話、檢討會、個人筆記）來協助整理經驗③鼓勵主動提問與尋求回饋，逐步拉高平時的自我覺察頻率。", "dont": "禁止：①將此區間解讀為「不懂反省」②在缺乏具體例證時指責其「沒自覺」③忽略組織提供回饋文化與心理安全的重要性④用片面事件下的反應直接貼上長期標籤。"}', 'ANI', '當有人提醒你、或事情有點卡住時，你會開始回頭想「是不是自己哪裡有影響？」但平常不一定會一直處在自我檢視狀態。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (33, 'ANI_10', 'B', 50, 74, '使用導向', '能操作 AI 工具並產生產出，但策略性理解與風險判讀仍需引導。', '提供實例、最佳實務與使用邊界，有助於深化理解。', '在 AI 工具使用上已有一定經驗，能操作並產出成果，但對於更深一層的原理、策略性應用與風險判斷，仍較需要具體案例與引導說明。', '{"do": "可用於：①說明其目前重點在「實際使用」而非完整策略思維，適合透過工作坊、範例與最佳實務來深化②建議提供清楚的使用邊界、隱私與安全指引，幫助其把既有經驗轉成更穩健的判斷③鼓勵在實務中逐步累積「什麼場合適合用／不適合用」的經驗，而不是只看工具方便與否。", "dont": "禁止：①把此區間解讀為「只會亂玩工具」②忽視組織在教育訓練與治理框架上的責任，將所有誤用風險全丟給個人③以是否熟悉最新工具作為對其工作價值的單一評斷④用恐嚇式說法（例如「不會用 AI 就會被淘汰」）施壓。"}', 'ANI', '你會用一些 AI 工具，也知道大概能幫上什麼忙，但在更進一步評估限制、風險或長期影響時，會需要再多一點示範與說明。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (35, 'ANI_11', 'A', 75, 100, '情感理解', '能從他人立場理解情緒與需求，並在互動中做出適切回應。', '適合需要人際敏感度、團隊支持或客戶互動的角色。', '表現出高度同理心，能從他人角度感受情緒與需求，並在互動中給出適當回應，有助於建立信任關係與支持性的合作氛圍。', '{"do": "可用於：①說明其在人際敏感度、情緒辨識與關係修復上的優勢②建議投入在需要照顧他人感受、維繫團隊氣氛或大量對外互動的角色（例如客服、顧問、管理者）③提醒同理心仍需要搭配界線與判斷，避免過度承擔他人情緒或犧牲自身需求。", "dont": "禁止：①把高同理視為「一定要隨時配合他人」②鼓勵為了維持關係而壓抑合理界線或專業判斷③在衝突發生時，要求其單方面扮演「情緒垃圾桶」的角色④將其同理能力當成理所當然的情緒勞務，而缺乏相對應支持。"}', 'ANI', '你很能站在別人的立場想事情，也感受得到對方的情緒，通常會用對方可以接受的方式回應與支持。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (36, 'ANI_11', 'B', 50, 74, '理性同理', '能理解他人觀點與處境，但情感回應較偏理性與務實。', '在專業導向或任務型合作中表現穩定。', '在理解他人觀點與處境上具備一定能力，能理性掌握對方立場與需求，但情緒回應較偏務實與就事論事，較少表現強烈的情感回應。', '{"do": "可用於：①點出其同理風格偏向「理解與協助解決」而非強烈情感投入②建議運用在專業導向或任務型合作情境，如專案協作、問題分析等③鼓勵在需要情緒支持的情境中，多用一句確認感受或簡短回應情緒，再進入解決方案。", "dont": "禁止：①將此區間解讀為「冷淡」「沒溫度」②在需要實務決策時，反而過度要求情緒性回應而忽略其理性優勢③以單一互動片段判斷其是否「有同理心」④把所有關係維護責任交給其承擔。"}', 'ANI', '你聽得懂、也大致理解別人在想什麼、遇到什麼狀況，不過你的反應會比較偏向「就事論事」和幫忙想辦法，而不是很多情緒上的陪伴。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (37, 'ANI_11', 'C', 0, 49, '互動距離', '較少主動感受或回應他人情緒，互動多以任務完成為主。', '適合互動需求較低或分工明確的工作型態。', '在人際互動時較少自然而然地連結到他人的情緒狀態，對感受的敏感度較低，互動重心多放在任務完成、資訊交換或角色職責上。', '{"do": "可用於：①說明其人際風格偏任務導向，適合在角色分工清楚、情緒需求較低的工作情境②建議透過簡單的提問（例如「這樣你覺得還可以嗎？」）來補上基本的情緒確認③提醒組織在需要高情緒勞務的職位上，應評估是否安排足夠訓練或支援，而非單靠個人自行摸索。", "dont": "禁止：①直接貼上「沒同理心」「不在乎別人」等標籤②用道德批判的角度要求其改變，而不提供具體練習與範例③忽略其在穩定、務實與結果導向情境中的價值④將此分數視為無法改善的固定人格缺陷。"}', 'ANI', '你在和人互動時，比較會專注在事情本身、流程或結果上，不一定會第一時間注意到對方的情緒變化。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (58, 'ANI_19', 'B', 50, 74, '情境談判', '在準備充分或熟悉對象時表現佳，臨場變化大時較依賴框架。', '提供談判目標、底線與替代方案，可提升穩定度。', '在熟悉主題、準備充分或談判結構較清楚時，能有效表達訴求並爭取合理條件；但在臨場變動大或壓力較高時，較依賴事前框架與他人支援。', '{"do": "可用於：①說明其談判表現與準備程度高度相關②建議在重要協商前提供明確目標、底線、替代方案與常見問題回應③鼓勵在談判過程中適度暫停與回到團隊討論，而非勉強單獨承擔。", "dont": "禁止：①把在高壓即興情境中的不穩定表現簡化為「不會談」②要求其在完全沒準備的情況下處理關鍵談判③忽視組織在談判策略、資料與支援上的配置④以個別談判結果作為唯一評價依據。"}', 'ANI', '如果你對議題很熟、也先準備過要談的重點和底線，談判時表現通常不錯；但遇到臨時變卦或壓力很大的場合，就會比較需要事先規畫好的說法和同伴在場。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (10, 'ANI_12', 'A', 75, 100, '專注回應', '能專注理解對方內容與意圖，並透過提問與回饋確認關鍵資訊。', '適合面談、需求釐清、協調與衝突化解情境。', '在積極傾聽上表現成熟，能維持高度專注，不打斷對方發言，透過複述、總結與適當提問確認理解，同時留意語氣與非語言訊息，接住對方情緒並給予有建設性的回應。', '{"do": "可用於：①說明其具備接近「積極同理心傾聽／諮詢式傾聽」的能力，在面談、輔導、顧問或協調情境中是重要資源②建議運用複述、開放式提問與總結，協助對方釐清情緒與需求③鼓勵在給建議前先確認「對方想被聽見的是什麼」，讓回應更貼近對方關注點。", "dont": "禁止：①將其傾聽能力視為理所當然的情緒勞務，過度仰賴其處理他人情緒而忽略自身負荷②要求在所有情境下都以高強度情感投入回應③將其描繪成「一定能解決所有他人問題」或做心理治療式承諾④以此分數推論具備專業諮商／治療資格。"}', 'ANI', '你會很認真把對方講完，不會急著插話或下結論，會用「所以你的意思是…」這類方式確認自己有聽懂，也會觀察對方的情緒，再決定要怎麼回應。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (43, 'ANI_14', 'A', 75, 100, '持續投入', '主動規劃並投入長期學習與技能更新，能自我驅動累積新能力。', '適合快速演進的職能環境與需要持續升級的角色。', '在終身學習動機上表現積極，會主動規劃學習路徑與資源，持續更新知識與技能，並尋找應用機會，讓學習能回饋到工作與個人發展。', '{"do": "可用於：①說明其在長期學習與自我成長上的驅動力，適合投入在變化快速、需要持續升級的角色②建議提供清楚的發展路徑與舞台，讓其看得到學習如何轉化為實際機會③提醒高學習動機不一定等於成果立刻可見，仍需在選題與聚焦上給予支持。", "dont": "禁止：①把高學習意願視為可以無限加派新任務與責任的理由②忽略其在時間與精力上的限制，期待「什麼都學、什麼都懂」③用學習熱度作為衡量其全部價值的唯一指標④將所有培訓與知識更新的責任完全轉嫁給個人。"}', 'ANI', '你很在意自己不要停在原地，會主動找課程、資料或練習機會，讓自己一直有在進步與更新。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (47, 'ANI_15', 'C', 0, 49, '單點聚焦', '思考多集中於單一面向，較少主動考慮系統連動與外溢影響。', '適合職責明確、界線清楚的任務配置。', '目前在系統性思考上較偏向聚焦單一面向或眼前任務，較少自然而然地延伸思考決策對其他環節或長期影響。', '{"do": "可用於：①指出其適合在職責清楚、分工明確的任務中專注執行②建議在關鍵決策前，安排與其他相關角色的討論或檢查清單，協助看見外溢影響③鼓勵逐步練習從「這一點」往外多問一兩層，而非一次要求全面系統掌握。", "dont": "禁止：①將此區間解讀為「眼光短淺」或「只顧自己」②忽略組織在資訊透明度與跨部門協作設計上的責任③以羞辱方式要求其立即具備高階策略視野④把此結果當作否定其參與重要專案的理由。"}', 'ANI', '你會比較專心處理手上的那一塊，不一定會第一時間去想「這件事會怎麼影響到其他單位或後續流程」，如果有人提醒或一起討論，會比較容易連起來。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (48, 'ANI_16', 'A', 75, 100, '高度可靠', '能穩定兌現承諾，產出與行為高度可預期，團隊信任成本低。', '適合關鍵流程、交付責任與長期任務配置。', '在可靠性上表現穩定，能一貫地兌現承諾、如期完成交付，讓他人對其時間感與責任感有高度信任。', '{"do": "可用於：①說明其在長期任務、關鍵流程與客戶承諾上的信賴度優勢②建議擔任需要穩定交付與承諾管理的角色③提醒組織避免因可靠而持續加重其負荷，並留意資源與界線。", "dont": "禁止：①將其視為可以無限加派任務的對象②在整體流程設計不良時，把所有延誤責任歸於個人③忽略其休息與支持需求，以「你一向很可靠」要求超額付出④推論其可靠性等同於高效率或高產出。"}', 'ANI', '你說到的事情，多半都能確實做到，時間與品質也相對穩定，別人會覺得把事情交給你是放心的。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (50, 'ANI_16', 'C', 0, 49, '波動較大', '承諾與交付一致性不足，較容易受情境或狀態影響而延誤。', '適合拆解任務、短週期追蹤與更明確的交付標準。', '在交付穩定性上較具波動，承諾與實際完成之間可能會受到狀態、干擾或優先順序變動影響，較需要明確的排程管理與追蹤機制。', '{"do": "可用於：①指出其需要在任務拆解、時間管理與干擾管理上得到更多支援②建議運用短週期追蹤、明確交付標準與提醒機制來提升一致性③強調這反映的是節奏與管理方式需求，而非價值或意願的否定。", "dont": "禁止：①用「不可靠」「講話不算話」等貼標語言定義個人②忽視工作量、角色衝突與環境干擾等結構性因素③單靠責備或施壓期待其自動改善④以此結果否定其在適當支持下的成長可能。"}', 'ANI', '有時你會想把事情做好，但中間容易被其他突發或變動影響，導致時間或進度跟原本預期有落差；如果有更清楚的排程與追蹤，會比較穩。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (54, 'ANI_18', 'A', 75, 100, '清楚協調', '能清楚表達、理解他人並促進共識，溝通能兼顧內容與關係。', '適合跨部門協作、專案溝通與對齊共識的角色。', '在協調溝通上表現良好，能清楚表達想法、理解他人觀點並整理共識，兼顧資訊內容與關係維持，有助於降低誤解與衝突。', '{"do": "可用於：①說明其在跨部門協作、專案對齊與會議主持上的優勢②建議投入在需要整合不同利害關係人觀點的情境③鼓勵善用書面摘要與會後整理，放大其溝通貢獻。", "dont": "禁止：①將其視為理所當然的「溝通窗口」，卻未給予相應角色與資源②要求其在任何衝突中都扮演調解者③忽略組織制度與權力結構對溝通效果的影響④把溝通好等同於必須始終迎合他人。"}', 'ANI', '你通常能把自己的想法說清楚，也聽得懂別人在意的是什麼，會幫大家把重點整理出來，讓彼此比較好對齊。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (56, 'ANI_18', 'C', 0, 49, '互動落差', '在複雜或情緒性互動中容易產生理解差異，互動一致性較不穩。', '適合搭配確認機制、書面化與回饋節點降低誤解。', '在複雜、多方或情緒性較高的互動中，較容易出現理解落差或訊息偏差，如缺乏確認機制，可能導致雙方期待不一致。', '{"do": "可用於：①指出其在人際溝通上需要更多結構化支持，如書面說明、確認問題與明確結論②建議在關鍵對話後寫下重點並請對方確認，以減少誤會③鼓勵在重要場合前先準備要說的重點，提高表達穩定度。", "dont": "禁止：①將其標籤為「不會溝通」「溝通有問題的人」②忽略情境、權力關係與文化對溝通行為的影響③以負面評價而非具體建議回應其表現④推論其不適合任何需要對人互動的工作。"}', 'ANI', '當談話牽涉的人多、情緒又比較重時，你有時會很難完全掌握對方的重點，或沒辦法一次就把自己的想法說清楚，如果沒有再三確認，雙方期待可能會有誤差。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (62, 'ANI_20', 'C', 0, 49, '判斷依賴', '較容易依賴他人觀點或既有結論，較少主動質疑前提與證據。', '適合搭配審查機制、多元意見與推理框架訓練。', '目前較容易沿用現成結論或多數意見，較少主動檢查前提、證據與潛在風險，需要外部框架或他人帶領來啟動更深入的檢視。', '{"do": "可用於：①說明其目前較偏向依賴既有結論與權威意見，適合搭配清楚的評估步驟與示範②建議透過簡單的提問框架（例如「如果相反會怎樣？」「有沒有例外？」）逐步練習質疑前提③鼓勵在安全情境下練習提出不同觀點，而不是一次要求全面顛覆思考方式。", "dont": "禁止：①將此區間標籤為「沒在思考」「盲從」②忽視組織文化、權力結構與資訊不對稱對其判斷方式的影響③用羞辱或嘲諷方式要求其「要有批判性」④據此推論其不適合參與重要討論或決策。"}', 'ANI', '你在面對資訊或決策時，會比較傾向先參考「大家怎麼看」「過去怎麼做」，不一定會自己花很多力氣去拆解理由或找反例。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (66, 'ANI_22', 'A', 75, 100, '果斷判斷', '能在資訊有限時做出決策並承擔結果，遇到變化能快速定案調整。', '適合需要快速反應、決策頻繁的角色與任務。', '在高效決策上表現突出，能在資訊不完全的情況下仍做出合理選擇，並在環境變化時快速調整決策方向，願意承擔結果並持續修正。', '{"do": "可用於：①說明其在需要即時反應、決策頻繁的情境（如營運調度、專案現場）上的優勢②建議搭配簡明的決策準則與事後檢討機制，讓快速決策持續優化③鼓勵在重大高風險議題上，加入他人觀點與檢核，以平衡速度與品質。", "dont": "禁止：①以其決策速度為由，鼓勵在關鍵議題上「先做再說」而忽略風險評估②將快速決策等同於衝動或一意孤行③期待其單獨扛起所有決策結果，而忽視團隊與組織的共同責任④把偶爾的錯誤放大為「判斷草率」的固定標籤。"}', 'ANI', '遇到需要決定的時候，你不會一直卡著等完美資訊，會根據現有資料做出選擇，之後若情況變了，也能很快調整做法。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (68, 'ANI_22', 'C', 0, 49, '猶豫傾向', '面對多選項時較難快速定案，容易延後或反覆比較。', '提供選項排序、決策框架與期限，可協助定案。', '在面對多個選項或高度不確定的情境時，較容易陷入反覆比較或延後決定，擔心選錯帶來風險，因而需要更多結構化協助來推進決策。', '{"do": "可用於：①指出其目前在決策上偏向降低風險與避免後悔，需要清楚的決策框架（如利弊列表、優先順序）②建議透過設定決策期限、分階段決定（先小後大）來降低壓力③鼓勵在安全情境中練習「做出足夠好而非完美」的決策經驗，累積信心。", "dont": "禁止：①將其描述為「沒主見」「優柔寡斷」②忽略情境風險與過去經驗對其猶豫的影響③在沒有提供任何工具或支持的前提下，單純要求其「要果斷一點」④用這個結果否定其在分析、支持性角色或需要謹慎評估職務上的價值。"}', 'ANI', '當要在幾個選項之間做選擇、而且每個都有好壞時，你可能會一直來回想、很怕選錯，結果決定會拖比較久。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (241, 'ANI_23', 'A', 75, 100, '高度形象管理', '明顯傾向以社會期待方式作答，可能歪曲信念與答案以取得認可，導致評鑑可用性下降。', '更依賴行為證據、工作樣本與多方資料交叉驗證；避免只靠自述決策。', '作答時高度考量「別人會怎麼看」，較可能以理想化的自我形象作為回答依據，而非完全依照日常真實狀態。', '{"do": "可用於：①指出其他量表分數可能受到形象管理影響，需要搭配他評、行為觀察與面談綜合判斷②建議在回饋過程中，以安全、不評價的方式討論其「想被看見的樣子」③鼓勵其練習在適當場合逐步放下完美形象，讓真實狀態也有被看見的空間。", "dont": "禁止：①直接貼上「不誠實」標籤②忽略測驗情境本身帶來的壓力與不安全感③在回饋時用戳破或羞辱的語氣談其防衛④只靠此指標判斷其人格。"}', 'ANI', '你在回答時可能常會想「這樣寫感覺比較好」，而不是單純寫平常真正的反應。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (242, 'ANI_23', 'B', 50, 74, '形象真實混合', '多數時回應真實，但在敏感題或想留下好印象時可能偏理想化回答，呈現部分防衛。', '用情境題、行為例證追問與無評價訪談氛圍提高資訊準確度。', '作答時會在真實與形象之間拿捏，多數情況仍偏向說真話，但在少部分問題上可能略為修飾。', '{"do": "可用於：①說明其整體資料仍具參考價值，但需理解少部分題目可能受形象考量影響②建議在回饋時，同步邀請其分享對測驗的感受，增加開放度③鼓勵其把測驗視為自我了解工具，而不是面試考卷。", "dont": "禁止：①因為略有形象考量就說「在騙人」②忽略測驗情境（如是否與錄用掛鉤）③只從社會期望指標單點推論其誠實程度④在回饋時用指責口吻談此結果。"}', 'ANI', '你大部分會照實回答，但有些題目可能會稍微想一下「這樣寫會不會比較好」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (243, 'ANI_23', 'C', 0, 49, '回應較真實', '較能如實呈現自身想法與狀態，不會為了形象或討好而大幅扭曲答案，回覆可信度較高。', '在評鑑解讀與面談追問時可更直接使用其結果；適合用開放問題深化洞察。', '作答時傾向如實呈現自己，即使某些回答可能不那麼「好看」，也較少刻意修飾以迎合期待。', '{"do": "可用於：①說明其報告內容可信度相對較高②建議在解讀其他量表分數時，可以較少保留地相信其自陳資訊③鼓勵其持續維持真實表達，同時也學會在敏感情境中保護自己。", "dont": "禁止：①把其低社會期望反應當成「不在意別人看法」的負面標籤②忽略情境與關係對其表達方式的影響③在高風險場合鼓勵其完全不設防④把真實等同於不需任何界線。"}', 'ANI', '你比較不會特別去想「這樣寫會不會比較好看」，而是照自己的真實情況回答。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (69, 'CIA_01', 'A', 75, 100, '高度自律', '做事有一致的自我要求，能主動掌握進度、顧品質與收尾，較少需要外部催促也能維持可靠輸出。', '可交付需要穩定產出、長期追蹤、責任界線清楚的任務；適合擔任流程 owner、專案控管與交付把關角色。', '整體呈現高度自律與責任感，做事會主動掌握進度、照顧品質與收尾細節，即使沒有外在催促也能維持穩定輸出。', '{"do": "可用於：①說明其在自我管理、品質控管與長期專案追蹤上的穩定度②建議安排需要穩定產出、責任邊界清楚的任務或流程 owner 角色③鼓勵在維持高標準的同時，也留意工作量與身心負荷，避免過度投入。", "dont": "禁止：①把其盡責當成理所當然，不斷加派任務而不調整資源②將偶爾的延宕或失誤放大成「不負責」③以此分數假設其永遠不需要督導或回饋④把對細節的在意誤解為「愛挑別人毛病」。"}', 'CIA', '你習慣把事情安排好、跟進好、收尾也做好，別人把任務交給你，大多會覺得放心。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (70, 'CIA_01', 'B', 50, 74, '任務可靠', '在目標、範圍與時程清楚時表現穩定；遇到優先序頻繁變動或責任邊界不清時，效率與投入度可能波動。', '以明確分工與里程碑提升穩定度；適合在既定流程內承擔主力執行與回報節點。', '面對目標、範圍與時程清楚的任務時，多能穩定完成並維持基本品質；當優先順序頻繁變動或權責模糊時，節奏與細緻度會跟著起伏。', '{"do": "可用於：①說明其表現高度仰賴任務清晰度與外部結構②建議透過明確分工、里程碑與定期 check-in，協助其穩定輸出③鼓勵其學會主動釐清優先順序與需求，而不是悶著做。", "dont": "禁止：①在目標本身就模糊的前提下，將所有落差歸因於個人「不夠負責」②用零星案例貼上「時好時壞」的標籤③忽略管理與流程設計的責任，把結構問題丟給個人扛④期待其在混亂環境中依然維持完全同樣的表現。"}', 'CIA', '只要知道要做什麼、什麼時候要完成，你通常都能把事情處理好；但如果規則常改、任務一直變，就會比較難穩住步調。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (75, 'CIA_03', 'A', 75, 100, '先思後行', '行動前會評估風險、假設與後果，較少因一時判斷造成返工；在不確定情境能維持判斷品質。', '適合風險控管、決策審查、流程把關與合規情境；可擔任決策前最後一道檢核。', '做決定前習慣先思考情境、風險與可能結果，面對不確定時也能維持判斷品質，不會輕易被一時情緒帶走。', '{"do": "可用於：①說明其在風險評估、策略討論與重要決策上的價值②建議投入錯誤成本高、需要深思熟慮的議題（如人事、合約、長期投資）③鼓勵在已充分思考的情況下，為行動設下明確時限，避免過度拉長決策。", "dont": "禁止：①將其審慎誤解為優柔寡斷②要求在資訊高度不足又風險極高時，仍「秒回決定」③忽略議題複雜度與資訊量，只用決策速度評論其能力④把多問幾句當成「找麻煩」。"}', 'CIA', '你比較像是「先想一圈再出手」的類型，會先評估可能的後果，再決定要怎麼做。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (76, 'CIA_03', 'B', 50, 74, '情境權衡', '在重要決策會拉高審慎程度，但在時間壓力或熟悉任務可能簡化評估；品質受情境影響較大。', '提供決策模板（選項/風險/影響/備案）穩定發揮；適合在快慢要切換的團隊中。', '重要事情會刻意拉慢節奏、多想一下；對熟悉或看似小事的議題，則傾向簡化評估、快速做決定，實際謹慎程度會依情境調整。', '{"do": "可用於：①說明其會依照「重要性」調整審慎程度②建議針對關鍵領域（如人員、預算）設定最基本的思考檢核點③鼓勵在「看似日常但影響深遠」的議題上，也保留一些審慎空間。", "dont": "禁止：①因為個別錯誤就說「都想不清楚」②忽略時間壓力、資訊不足等外因③用完美主義標準要求其所有決策都零失誤④把一兩次的疏忽視為長期固定問題。"}', 'CIA', '遇到大事你會謹慎一點，平常的小決定就會比較順手、直覺地做，沒有每件事都想很久。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (78, 'CIA_04', 'A', 75, 100, '規範堅守', '高度重視承諾、規則與責任邊界，遇到灰色地帶也傾向選擇可被交代、可被信任的做法。', '適合合規、資安、機敏資料等高度信任情境；可放在制度與文化的穩定器位置。', '對承諾、規則和職責界線有強烈重視，遇到灰色地帶時，也會傾向選擇站得住腳、講得清楚的做法。', '{"do": "可用於：①說明其在守信、合規與高度信任情境中的重要性②建議安排需高度可靠與可追溯性的任務（如合約控管、稽核、長期客戶關係）③鼓勵在堅守原則的同時，也學習與組織討論不合理規範。", "dont": "禁止：①把其義務感當成免費勞力，不斷追加責任②用「你有責任」掩蓋制度或資源問題③期待其為了組織利益長期犧牲個人健康與生活④在其提出合理界線時，批評為「不夠有責任感」。"}', 'CIA', '你會很在意「答應過的事要做到」以及「事情要交代得過去」，對規則和責任界線也比較敏感。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (81, 'CIA_04', 'C', 0, 49, '彈性取捨', '較容易把規範視為可調整的工具，遇到目標壓力可能優先選擇結果導向做法，需要較強的底線提醒。', '以雙人覆核、紀錄透明、權限控管等制度降低風險；適合創新但需控風險。', '面對規範時較常以「工具」而非「原則」來看待，遇到壓力或目標強烈時，容易優先選擇對結果有利的做法，需要更清楚的底線提醒與制度控管。', '{"do": "可用於：①指出其在需要彈性、突破與實作導向的情境中具優勢，但需設好界線②建議透過權限控管、雙人覆核與紀錄透明來降低風險③鼓勵在追求結果的同時，也思考長期信任與風險成本。", "dont": "禁止：①直接標籤為「沒原則」「會亂來」②忽略目標壓力與制度缺陷對其選擇的影響③完全用道德指責代替制度設計④把此分數當作預測其必然違規或不誠信。"}', 'CIA', '你比較容易把規則當成可以調整的東西，如果壓力很大、目標很硬，就會先想「怎麼做比較有效」，而不是完全照規定。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (84, 'CIA_05', 'C', 0, 49, '衝動風險', '較容易被情緒推著走，出現衝動回應、倉促承諾或行為過頭；事後常需要修補或解釋。', '降低高衝突暴露、提供情緒停損流程（先暫停/先寫後說/第三方介入）；用規範保護本人與團隊。', '當情緒被挑起或短期誘惑出現時，較容易順著當下感覺行動，事後才意識到後果或產生懊惱，需要更多「多一拍思考」的協助與設計。', '{"do": "可用於：①指出其在衝動管理上需要具體的環境與流程輔助（例如預設等待時間、找人商量）②建議設計簡單的自問機制，如「這樣做之後一週後我會怎麼看？」③鼓勵用負責但不自我否定的方式看待過去失誤，從中練習新的反應模式。", "dont": "禁止：①貼上「沒自制力」「不成熟」的標籤②忽略壓力、情緒與環境刺激對行為的影響③單靠責罵或羞辱要求其改變④將此分數與任何臨床診斷畫上等號。"}', 'CIA', '你有時會先照當下的情緒或直覺做了，過一陣子才覺得「好像有點太快」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (87, 'CIA_06', 'B', 50, 74, '重點整理', '會整理重點與基本秩序，但不一定每件事都系統化；在多工時需要工具或提醒來維持條理。', '提供共用看板、固定回報節點與簡單模板即可顯著提升；適合兼顧彈性與秩序的型態。', '在重要事情上會維持基本的規畫與整理，但不會追求所有事物都高度結構化，會依情境在「順手」與「有系統」之間調整。', '{"do": "可用於：①說明其在條理與彈性間具有一定平衡感②建議透過簡單工具（行事曆、任務清單）維持必要結構③鼓勵在多人協作或關鍵專案時，稍微提高條理程度以避免資訊遺漏。", "dont": "禁止：①因為不「極度整齊」就認定其沒有組織能力②忽略系統與工具本身的限制③用單次檔案找不到的狀況否定其整體工作風格④在未提供任何支援的情況下要求高度紀律整理。"}', 'CIA', '對你來說，重要的東西會整理好，其他部分只要自己找得到、用起來順就可以，不一定要全部都非常整齊。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (92, 'CIA_08', 'B', 50, 74, '需要確認', '能力多半足夠，但在新領域或高風險任務會希望獲得確認；得到支持後能穩定輸出並逐步建立信心。', '提供可求助窗口、階段性肯定與清楚成功標準能快速拉升；適合導師制或同儕合作下成長。', '面對熟悉或曾經成功過的任務時，普遍有一定把握；遇到全新、複雜或風險較高的挑戰時，會在意資源、支援與方向是否明確。', '{"do": "可用於：①說明其勝任感與經驗、準備程度及環境支持高度連動②建議在新任務前提供清楚目標、學習資源與可詢問對象③鼓勵回顧自己過去克服困難的經驗，讓信心不只綁在熟悉領域。", "dont": "禁止：①把謹慎與確認解讀為「沒信心」②忽略制度、資訊與支援不足對其心理狀態的影響③只用「你要相信自己」簡化問題④用單一挫敗經驗否定其能力。"}', 'CIA', '對你做過、熟悉的事情會覺得「這個可以」，但遇到完全陌生的挑戰，就會想先搞清楚「有人可以問嗎？資源夠嗎？」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (95, 'CIA_09', 'B', 50, 74, '情境自控', '在目標清楚或環境支持下能維持自律，但在壓力大、干擾多或缺乏回饋時，容易出現鬆動與拖延。', '用短週期里程碑與外部承諾機制（回報、共學、檢核點）提升持續性。', '在有期限、有人一起推進或會被檢核的任務上，多能穩定完成；對完全自訂、沒人關心的長期目標，則較容易被日常瑣事打斷。', '{"do": "可用於：①說明其自律表現與外在結構（時程、檢核、他人參與）高度相關②建議透過結伴、定期回顧或公開承諾來支援長期目標③鼓勵將大目標拆小步驟，減少拖延與中斷。", "dont": "禁止：①把需要外在結構的特性簡化為「沒意志力」②忽略制度與工作設計對行為的影響③只用指責回應延誤，而不協助重整計畫④用短期狀態推論其長期人格特質。"}', 'CIA', '如果有交件時間、或有人一起跟進進度，你會比較穩；但是對那種「沒人管、很長期」的計畫，就容易被其他事情插隊。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (100, 'CIA_10', 'C', 0, 49, '利益傾斜', '較容易重視利益、地位或外在象徵，可能合理化先拿到再說的做法，對公平與謙遜的自我要求較弱。', '在規範清楚、權限可追溯的環境運作；加強監督、審核與利益衝突管理。', '對財富、特權與自身利益的重視度較高，在作決定時容易優先考量「對自己是否划算」，對利用規則邊界或強調自身地位的接受度較高。', '{"do": "可用於：①指出其在強競爭、高獎酬環境中可能具有推進成果的動力，但需要明確的倫理與合規框架②建議透過制度設計與監督機制，界定可接受與不可跨越的行為界線③鼓勵其思考長期信任與聲譽對自身利益的影響。", "dont": "禁止：①直接將其等同於「不誠實」「會做壞事」②忽略組織獎勵結構對價值偏移的影響③以羞辱方式處理價值議題，而不提供具體標準與討論空間④把此分數視為其必然會違法或嚴重失當的預測。"}', 'CIA', '你會比較在意自己有沒有得到應得甚至更多的好處，對於運用關係、資源或規則邊邊角角，會覺得只要不太過就是合理手段。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (103, 'CIA_11', 'C', 0, 49, '目的導向', '較容易把包裝或操弄視為達成目標的工具，可能選擇性揭露或用話術影響他人判斷。', '需在透明流程與稽核機制下運作；在客戶/治理領域需更嚴格行為規範。', '對於「只說對自己有利的一部分」或美化資訊的接受度較高，溝通常被視為推進目標的工具，而非單純交換真實狀態的管道。', '{"do": "可用於：①指出其在談判、銷售與需要強勢說服的場域可能具優勢，但須留意長期信任與誠信風險②建議透過明確規範與例外情境說明，界定不能被犧牲的誠信底線③鼓勵其思考「短期成交」與「長期信任」之間的取捨。", "dont": "禁止：①直接等同於「騙人」「不可信」②忽略組織本身對短期成效的高度壓力③只用道德批判要求其改變，而不提供具體示例與學習資源④用此分數斷言其一定會嚴重違反誠信。"}', 'CIA', '你可能會覺得強調優點、淡化缺點是很正常的做法，重點是事情要推得動。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (105, 'CIA_12', 'C', 0, 49, '高度物質導向', '較重視財富、地位或外在象徵，對回報敏感，可能把物質激勵視為投入與忠誠的主要交換條件。', '適合獎酬明確、成果可量化角色；避免模糊承諾，並以公平制度降低比較摩擦。', '對薪酬、福利、頭銜與外在認可的敏感度較高，容易把這些視為「有沒有被重視」的重要訊號，物質與地位在決策中占較大比例。', '{"do": "可用於：①指出其在獎酬明確、競爭導向的環境中可能動機強勁②建議清楚解釋薪酬架構、升遷條件與獎勵機制，減少不確定感③鼓勵其同時培養對內在成就與專業成長的重視，讓滿足來源更穩定。", "dont": "禁止：①直接貼上「拜金」「很勢利」的標籤②忽略其過往可能被低估或不公平對待的經驗③用道德批評否定其對物質條件的要求④把此分數當作預測其一定會為利益犧牲原則的依據。"}', 'CIA', '你會很在意待遇好不好、頭銜夠不夠看，以及別人怎麼看待你的位置，覺得這些都代表你有沒有被好好對待。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (108, 'CIA_13', 'C', 0, 49, '手段傾向', '較容易把領先視為第一順位，可能合理化不公平手段或利用他人換取優勢。', '高風險領域需加強權限控管、雙人覆核與稽核；角色配置宜更謹慎。', '對「世界本來就不會完全公平」這件事接受度較高，傾向優先確保自己不吃虧，對制度或利益分配不均的敏感度相對較低。', '{"do": "可用於：①指出其在高度競爭或差異報酬環境中可能較能適應，但也存在關係與文化風險②建議明確說清楚組織不可違反的公平底線③鼓勵其思考長期合作、信任與團隊士氣對結果的影響。", "dont": "禁止：①直接貼上「沒良心」「沒是非」標籤②忽略其可能曾經歷長期不公平而產生的防衛③只用指責要求其「要有正義感」④以此分數推論其一定會做出嚴重不公行為。"}', 'CIA', '你可能會覺得，只要不要自己吃太大的虧，有些不那麼公平的事也還能接受，重點是顧好自己。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (111, 'CIA_14', 'C', 0, 49, '自我凸顯', '較傾向強調自身貢獻與地位，可能把被看見視為重要需求，對他人表現的接受度較敏感。', '以透明功勞分配與評價制度降低衝突；安排在對外代表或競爭型任務可能更合適。', '較常覺得自己的付出與能力應該獲得更多關注與禮遇，習慣主動凸顯自身貢獻與重要性，期待被特別看見。', '{"do": "可用於：①指出其在爭取資源、機會與可見度時的主動性優勢，但須留意團隊感受②建議透過具體回饋幫助其調整表達方式，讓自我肯定不至於壓過他人③鼓勵其在展現自己之外，也刻意練習看見與肯定周遭成員。", "dont": "禁止：①直接標籤為「自大」「目中無人」②忽略其過去可能長期被低估而需要用力爭取③用羞辱方式壓抑其自我肯定④以此分數推論其無法良好合作。"}', 'CIA', '你可能會覺得「我做了這麼多，應該要被好好看見」，也會比較常主動提到自己的成果。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (116, 'CIA_16', 'C', 0, 49, '路徑不足', '可能有想達成的目標，但較難把動機與策略化路徑連結；遇到阻礙時容易停滯或轉向。', '先建立短期可達成目標與清晰下一步，搭配教練式提問與資源支持，逐步建立路徑思考能力。', '目前較難具體描述長期想追求的目標，對未來多半停留在模糊或「先顧好眼前再說」的狀態，較少主動規劃遠期方向。', '{"do": "可用於：①指出其可能正處於「優先處理當下」的階段②建議透過探索活動、不同嘗試與陪談，一點一點幫助其長出較有個人感的目標③鼓勵從短期小目標開始，讓「未來可以被塑造」的感覺慢慢變清楚。", "dont": "禁止：①標籤為「沒未來性」「沒理想」②忽略其現實壓力、資源或資訊限制③用批判或嘲諷逼其立即說出長期藍圖④把此分數視為固定且不可改變。"}', 'CIA', '你現在可能比較多在處理眼前的事，要說很清楚的長期目標，會覺得有點遙遠或抽象。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (119, 'CIA_17', 'C', 0, 49, '容易自我懷疑', '對能否完成目標缺乏把握，面對挑戰可能遲疑、過度求證或依賴他人決策，影響推進節奏。', '用小步成功累積、降低啟動門檻並提供明確指引與正向回饋；避免一開始就丟高不確定責任。', '對「即使努力也未必成功」的感受較強烈，面對較大的目標時容易預期失敗，因而降低投入意願或傾向選擇風險較低的選項。', '{"do": "可用於：①指出其效能感可能受過往「努力與結果落差」經驗影響，需要透過小成功經驗重新建立②建議設計可控性較高、步驟清楚的目標，減少徒勞感③鼓勵其記錄具體的進步與做到的事情，而不是只放大失敗。", "dont": "禁止：①把其保守選擇簡化為「不努力」②忽略機會不均、資源限制與系統問題③用嘲諷或比較方式施壓「你要有自信」④把此分數視為無法恢復的信心問題。"}', 'CIA', '你可能常會想「就算我很努力，也不一定有用」，所以會選擇比較安全、不會太冒險的做法。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (122, 'CIA_18', 'C', 0, 49, '耗損累積快', '在長期高壓或連續變動下容易出現能量耗竭，補救與恢復較吃力，表現波動可能增大。', '設計緩衝與分工、避免長期獨撐；用復盤與支持資源提升挽救能力。', '長期或高強度壓力較容易累積成耗損感，一旦被壓垮，恢復需要較多時間與資源，情緒與表現波動也相對明顯。', '{"do": "可用於：①指出其在長期高壓環境中的風險，需要特別留意工作設計與負荷管理②建議建立穩定的支持系統（如信任的人、專業資源、自我照顧習慣）③鼓勵用溫和、不評價自己的態度面對脆弱，從中練習新的調適方式。", "dont": "禁止：①把其狀態標籤為「玻璃心」「不抗壓」②忽略組織在壓力管理與資源配置上的責任③用比較與羞辱逼其「硬起來」④以此分數作為不適合培養或信任的理由。"}', 'CIA', '你在壓力很大或變動很多的時候，會感覺自己很快就被用完電，要花很久才補得回來。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (125, 'CIA_19', 'C', 0, 49, '容易悲觀解釋', '傾向把不如意視為長期且普遍，可能降低嘗試意願與抗挫力，遇阻礙容易預期失敗。', '從可控小目標建立成功經驗，搭配教練式提問與資源支持；避免長期無回饋任務。', '在面對壓力、變動或不確定時，較容易先想到可能的風險與失敗結果，對「事情會變好」的想像較不自然。', '{"do": "可用於：①指出其在風險覺察上具敏感度，但也較容易陷入悲觀循環②建議引導其平衡「最壞情境」與「可行對策」，從可控部分著手③鼓勵透過具體行動與小成果，慢慢修正「事情都不會變好」的內在腳本。", "dont": "禁止：①直接貼上「負面」「愛抱怨」標籤②忽略其過往挫折或資源不足對世界觀的影響③用雞湯式鼓勵要其立刻變樂觀④把此分數當作不適合承擔重要任務的單一依據。"}', 'CIA', '你可能常會往壞的方向先想，對「一切會順利」這種說法會抱持懷疑，覺得還是要準備最壞的打算。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (128, 'CIA_20', 'C', 0, 49, '慣例優先', '較偏好沿用成熟做法，面對新方法可能先觀望；創新動機較低但穩定性較高。', '適合標準化與高一致性作業；推動創新可先小規模試點降低不確定。', '做事風格較偏向沿用既有作法與慣例，面對「完全沒做過的嘗試」會感到遲疑或擔心風險，對創新本身不一定感到興奮。', '{"do": "可用於：①指出其在需要穩定執行、流程遵循的工作上可提供穩定度②建議若希望其參與創新，先從「微調現有流程」而非大幅顛覆開始③鼓勵用逐步嘗試與明確風險控管，降低對創新的不安感。", "dont": "禁止：①貼上「保守」「沒創意」的單一標籤②在未提供資訊與支援下強迫其快速接受大變革③忽略其對穩定與可預測性的合理需求④用此分數否定其在改善與優化上的貢獻可能。"}', 'CIA', '你比較習慣照既有方式把事情做好，對那種完全沒試過的新做法，會先想到風險和麻煩。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (131, 'CIA_21', 'B', 50, 74, '效率規範平衡', '能在規範內追求效率，必要時提出簡化建議，但仍保留關鍵程序以降低錯誤。', '以分級規則（哪些必做、哪些可省）最有效；適合流程微調與落地執行。', '在明顯拖沓或浪費的情況下會感到不耐，願意調整做法，但若現況尚可接受，通常不會刻意追求極致效率。', '{"do": "可用於：①說明其在效率與實際付出之間會權衡成本效益②建議在關鍵流程上與其一起定義「值得優化的地方」，提高參與感③鼓勵用小步改善而非一次大改，讓效率提升更貼近實務。", "dont": "禁止：①因不「追求每一秒都被最佳化」而貼上「不重效率」標籤②忽略改善本身需要時間與心力③在沒有參與的情況下只要求其配合新流程④用單一事件評價其長期工作風格。"}', 'CIA', '遇到很明顯很浪費時間的流程，你會想改一改，但如果只是「還可以」，就會覺得沒必要搞得太緊。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (133, 'CIA_22', 'A', 75, 100, '自在於無規則', '不依賴傳統或被接受的方法，面對缺乏規則的情境仍能找到做法並推進。', '適合新創、0→1、策略探索或規則尚未建立的任務；可放在開荒位置。', '在清楚的規則、流程與架構下工作會感到安心，傾向尊重制度、依循既有規範來處理事情。', '{"do": "可用於：①說明其在合規、風險控管與制度落實上的重要性②建議安排在需要嚴謹遵守標準作業的任務或角色③鼓勵在面對不合時宜規範時，嘗試用建設性方式提出調整建議。", "dont": "禁止：①把其對規則的尊重當成可以塞所有行政雜事的理由②忽略制度本身的不合理，只要求其「要照做」③將其質疑視為「不服從」而不討論內容④把高紀律遵循度當作缺乏彈性的同義詞。"}', 'CIA', '當規則清楚、流程明確時，你會覺得比較放心，也會習慣「照制度走」來處理事情。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (138, 'CIA_23', 'B', 50, 74, '情境催化原創', '在刺激足夠或問題設計得好時能產出新想法；若限制不清或缺乏材料，容易回到常規解法。', '用工作坊、對比案例與明確限制條件提升原創品質；適合被題目引導的創意輸出。', '在適合的題目與氛圍下，能提出一些與眾不同的想法；平常多半還是以實務可行與現有做法為主。', '{"do": "可用於：①說明其原創性會受主題興趣與心理安全感影響②建議創造低風險、可試錯的場域，邀請其分享不同看法③鼓勵其將偶爾的靈感記錄下來，累積成可被討論與應用的素材。", "dont": "禁止：①因為平時較務實就認定其「沒創意」②忽略團隊文化對發言勇氣的影響③只在會議最後壓時間時才請其「提想法」④用一次沉默評價其創造力。"}', 'CIA', '如果話題讓你感興趣，或氣氛允許，你也會丟出一些不一樣的點子；但平常做事還是以實際為主。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (141, 'CIA_25', 'A', 75, 100, '團隊優先', '重視凝聚力與共同目標，傾向把集體利益放在個人之前，願意為團隊付出與協調。', '適合跨部門協作、共同 KPI 與共享資源團隊；可擔任凝聚與協調角色。', '自然會把「我們」放在「我」之前，重視團隊凝聚與共同目標，願意在合理範圍內為集體利益調整個人安排。', '{"do": "可用於：①說明其在團隊合作、跨部門協作與文化建構上的關鍵角色②建議在溝通中清楚說明決策如何影響「整體」，能更激發其投入③鼓勵其同時照顧自己的界線，避免長期只顧團隊忽略自我需求。", "dont": "禁止：①把其集體導向當成理所當然，不斷要求多做犧牲②忽略其在團隊衝突與不公情境中的壓力③以「團隊為重」否定其個人合理訴求④將不同意見視為「不團隊」。"}', 'CIA', '你會很在意團隊好不好、大家合不合，遇到取捨時也比較願意先顧整體。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (145, 'CIA_26', 'B', 50, 74, '理解為主', '能理解他人觀點，但情緒共感表達較偏理性；在任務型對話中表現穩定。', '提供回饋技巧與提問框架可提升同理回應的可見度；適合專業導向協作。', '在關係重要、對象熟悉或情境明顯時，多能感受到他人情緒並做出恰當回應；在距離較遠或訊號較弱時，理解度會下降。', '{"do": "可用於：①說明其同理表現與關係親近度、訊息清晰度高度相關②建議在跨部門或陌生對象互動時，提供更多背景資訊與情境說明③鼓勵其用提問而非猜測來了解他人。", "dont": "禁止：①把在陌生場景下的判斷失誤解讀為「沒同理心」②忽略文化差異與溝通習慣對表達的影響③只要求「要設身處地想」卻不提供資訊④用單一案例否定其關懷能力。"}', 'CIA', '對你在乎的人，你會很希望對方覺得被理解；但對很不熟、或表情很隱晦的人，就比較難猜到在想什麼。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (149, 'CIA_27', 'C', 0, 49, '回報敏感', '對付出與回報對等性較敏感，容易在意自己是否吃虧；互惠不明確時可能降低投入或轉為保守合作。', '適合權責清楚、回報機制透明環境；需明確界定投入範圍與回饋，避免累積不滿。', '對額外付出較為保留，傾向先確認是否與自身責任、回報或目標明確連結，才會考慮投入更多時間與心力。', '{"do": "可用於：①指出其在付出時較強調界線與資源運用效率，適合在角色與責任清楚的環境中工作②建議若希望其多一些投入，需說明付出與目標、回報或專業成長的連結③鼓勵其在維護自身界線的同時，也思考關係與團隊長期合作的效益。", "dont": "禁止：①簡單貼上「自私」「不肯幫忙」的標籤②忽略其過往可能因過度付出而感到被利用的經驗③用道德控訴要求其無條件犧牲④把此分數當成無法合作或不適合團隊工作的直接證據。"}', 'CIA', '你會先想清楚「這跟我有沒有直接關係」或「值得不值得」，才決定要不要多花力氣幫忙。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (153, 'CIA_29', 'B', 50, 74, '熟悉圈內更順', '在熟悉或風格相近的場域表現良好；遇到差異很大的對象需要時間摸索互動節奏。', '提供對象背景、互動目的與界線可縮短磨合期；適合在穩定合作網絡中擴張。', '在熟悉或相對類似的人際環境中互動順暢；面對風格差異較大或權力距離較大的對象時，需要一些時間摸索相處方式。', '{"do": "可用於：①說明其人際適應與情境熟悉度高度相關②建議在新環境或新對象互動初期給予明確指引與範例③鼓勵透過觀察與適度試探，逐步找到合適的相處節奏。", "dont": "禁止：①因在陌生情境中略顯拘謹就說「人際能力不好」②忽略組織氛圍與權力結構對其互動表現的影響③只在出現衝突時才檢討其人際，而不提供教練式支持④將單次不順視為無法代表公司對外。"}', 'CIA', '跟風格接近或熟悉的人，你相處起來很自然；但對很不一樣或位階差很多的人，就會先觀察一陣子。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (155, 'CIA_30', 'A', 75, 100, '對結果負全責', '對把事情做好有強烈決心，遇到問題會主動承擔、補救與追根究柢，而非推給情境或他人。', '適合主責角色、交付導向任務；可降低管理追催成本。', '對自己承諾過或該負責的事情會主動扛起來，不容易把錯怪罪在環境或他人身上，而是先思考自己能做什麼調整。', '{"do": "可用於：①說明其在責任感與自我要求上的成熟度②建議在授權與關鍵任務上信任其承擔能力，同時避免過度堆疊責任③鼓勵其在負責的同時，也適度界定「自己不能控制的範圍」。", "dont": "禁止：①把其責任感當成無限制加派任務的理由②忽略制度或資源問題，只期待其「自己想辦法」③鼓勵其為所有問題自責而不尋求支援④將其願意承擔視為可長期濫用的條件。"}', 'CIA', '事情沒做好時，你比較會先想「我這邊可以怎麼改」，而不是第一時間怪別人或怪環境。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (157, 'CIA_30', 'C', 0, 49, '責任外移傾向', '遇到失誤或延誤較容易歸因外部，補救動作相對被動，可能降低學習與改進速度。', '以復盤流程、行為導向回饋與明確後果機制；先從可控小任務建立承擔習慣。', '在事情出現問題時，較容易優先想到外在原因或他人角色，對於自己能影響或調整的部分較少主動檢視。', '{"do": "可用於：①指出其在壓力情境下容易以防衛性方式看待責任議題②建議透過結構化檢討工具（如：我能調整什麼、可控/不可控）協助其建立新習慣③鼓勵在安全、非責備的環境中談錯誤，降低防禦需求。", "dont": "禁止：①直接貼上「愛推卸責任」標籤②在高度責備文化下只批評其防衛，而不處理環境③用羞辱方式要求其「坦承錯誤」④把此分數當成無法信任的永久標記。"}', 'CIA', '一出狀況時，你可能會先想到「是誰沒做好」或「環境太爛」，比較少一開始就檢查自己哪裡能調整。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (161, 'CIA_32', 'B', 50, 74, '情境性期待', '在投入高或自覺貢獻大時會期待相應待遇；回報不足可能不滿，但仍願意用制度途徑溝通。', '建立可追溯評價與回饋機制，避免不滿轉為消極或抱怨。', '基本認同應依貢獻與表現獲得相應對待，但在自認付出較多或能力較強時，也會期待某種程度的額外肯定與資源。', '{"do": "可用於：①說明其在「合理期待」與「特別待遇」之間可能有灰色地帶②建議清楚說明評估標準與差異對待的理由，降低被忽略或被放大的感受③鼓勵其在溝通時聚焦事實與貢獻，而不是情緒化表達。", "dont": "禁止：①把其合理期待誤解為「愛耍特權」②忽略透明制度與雙向溝通的重要③在沒有解釋下用「大家都一樣」一概帶過④用單次爭取否定其整體專業。"}', 'CIA', '你會覺得「有付出就該有相對應的待遇」，如果覺得自己做得比別人多，也會希望能被多看見一點。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (163, 'CIA_33', 'A', 75, 100, '高度形象管理', '明顯傾向以社會期待方式作答，可能歪曲信念與答案以取得認可，導致評鑑可用性下降。', '更依賴行為證據、工作樣本與多方資料交叉驗證；避免只靠自述決策。', '作答時高度考量「別人會怎麼看」，較可能以理想化的自我形象作為回答依據，而非完全依照日常真實狀態。', '{"do": "可用於：①指出其他量表分數可能受到形象管理影響，需要搭配他評、行為觀察與面談綜合判斷②建議在回饋過程中，以安全、不評價的方式討論其「想被看見的樣子」③鼓勵其練習在適當場合逐步放下完美形象，讓真實狀態也有被看見的空間。", "dont": "禁止：①直接貼上「不誠實」標籤②忽略測驗情境本身帶來的壓力與不安全感③在回饋時用戳破或羞辱的語氣談其防衛④只靠此指標判斷其人格。"}', 'CIA', '你在回答時可能常會想「這樣寫感覺比較好」，而不是單純寫平常真正的反應。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (165, 'CIA_33', 'C', 0, 49, '回應較真實', '較能如實呈現自身想法與狀態，不會為了形象或討好而大幅扭曲答案，回覆可信度較高。', '在評鑑解讀與面談追問時可更直接使用其結果；適合用開放問題深化洞察。', '作答時傾向如實呈現自己，即使某些回答可能不那麼「好看」，也較少刻意修飾以迎合期待。', '{"do": "可用於：①說明其報告內容可信度相對較高②建議在解讀其他量表分數時，可以較少保留地相信其自陳資訊③鼓勵其持續維持真實表達，同時也學會在敏感情境中保護自己。", "dont": "禁止：①把其低社會期望反應當成「不在意別人看法」的負面標籤②忽略情境與關係對其表達方式的影響③在高風險場合鼓勵其完全不設防④把真實等同於不需任何界線。"}', 'CIA', '你比較不會特別去想「這樣寫會不會比較好看」，而是照自己的真實情況回答。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (168, 'CIA_34', 'C', 0, 49, '工作僅是責任', '對工作熱情較低，多以責任或收入角度看待；投入度較依賴外部要求與制度。', '適合流程明確、成果可衡量任務；提升投入需釐清其關心價值與誘因。', '對工作本身較少產生強烈熱情，多以完成責任、維持穩定為主，較不會把工作視為自我實現的主要場域。', '{"do": "可用於：①指出其可能更重視工作以外的生活面向，或過往工作經驗較少帶來熱忱感②建議在職務設計上，不必強迫其展現高度激情，而是聚焦於清楚的目標與穩定表現③鼓勵其探索哪一部分工作內容對自己比較有意義，作為提升滿意度的起點。", "dont": "禁止：①貼上「沒熱情」「只為薪水」的道德化標籤②忽略組織文化與職務本身缺乏成就感③用激情作為唯一評價標準④把此分數視為不負責或不可靠的證明。"}', 'CIA', '你比較把工作看成「需要做好的責任」，但不一定會覺得它是人生的熱愛或主要成就來源。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (352, 'SPA_01', 'A', 75, 100, '具備足夠心理資本', '希望、效能感、韌性與樂觀四項心理資本相對充足，遇到挑戰時更能維持信心與行動力，並把壓力轉成可處理的任務。', '適合承擔需要自我驅動與長期推進的工作（開發客群、目標管理、陌生市場）；可給較大自主權與更高挑戰。', '心理資源整體偏充足，希望感、效能感、韌性與樂觀之間能維持良好平衡，壓力來時較能先穩住狀態再推進。可觀察行為包含：面對挑戰仍願意採取行動、把壓力拆成可處理的任務、在挫折後能調整策略續航。需留意的是，高分不等於不會累；若長期高負荷或缺少補能，仍可能出現耗損累積而影響穩定輸出。', '{"do": "• 配置在需要自我驅動、長期推進與反覆試錯的任務（陌生市場開發、關鍵案推進、談判收尾），讓穩定續航發揮價值<br>• 給清楚目標與決策空間，允許自行調整節奏與做法，同時安排定期復盤把學到的打法沉澱成方法<br>• 同步設計恢復節奏與支援資源（交付後緩衝、輪值分擔），避免把心理資源視為永遠用不完", "dont": "• 不因高分就推論永遠扛得住或不需要支持；長期超載仍會造成耗損與績效波動<br>• 不把測評分數當作心理健康或臨床狀態判定；需結合近期事件與可觀察行為再解讀<br>• 不以單一分數做『一定會/一定不會』式決策；忽略角色、環境與資源差異會導致錯配"}', 'SPA', '遇到變動或壓力時，通常能先把自己穩住，不太會一下子被情緒拖走，接著會把問題拆小、找出能做的下一步，慢慢把事情推回可控。你也比較能在不順後調整做法再上路。不過心理底盤再厚也會耗電，長期高壓時還是需要補能與節奏，才不會硬撐到後面掉速。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (353, 'SPA_01', 'B', 50, 74, '心理資本可用但需補給', '具備一定心理資本，平時能維持表現；在連續挫折、目標模糊或支援不足時，動能可能下滑，回穩後仍能再推進。', '用清楚目標、里程碑與回饋機制可穩定輸出；搭配同儕支持與教練式提問能拉高續航。', '心理資源大致可用，日常多能維持表現，但在連續挫折、目標模糊或支援不足時，動能較容易下滑。可觀察行為是：在有明確方向與回饋時能穩定推進；當規則不清或缺少回饋，可能出現停滯、效率下降或信心動搖。管理重點在用目標、里程碑與回饋機制把條件做齊；否則容易被情境拖著走，表現波動放大。', '{"do": "• 用清楚目標與里程碑建立可預期節奏，搭配短週期回饋（週檢核/1on1）穩定續航與信心<br>• 在挫折期提供同儕支持或教練式提問，把卡點外顯並轉成可行下一步，避免陷入模糊與停滯<br>• 把任務條件做齊（資源、權限、成功標準），讓表現不被情境拉扯，並用復盤強化可複製打法", "dont": "• 不以單次狀態就判定長期潛力；此區間很吃情境與管理清晰度，需看一段時間的行為證據<br>• 不在規則模糊或支援不足時加壓催促；會直接消耗心理資源並放大焦慮與拖延<br>• 不把分數當作診斷或人格貼標；錯把情境波動當成固定特質會造成不必要的錯配與誤判"}', 'SPA', '平常心理資源是夠用的，事情正常推進時你能把該做的做完；但如果一直挫折、目標又不清楚，或旁邊支援跟不上，動能就會比較容易掉。你在有方向、有回饋的狀況下會明顯更穩，反之就容易卡住。把目標、里程碑和回饋節奏對齊清楚，通常就能把狀態拉回來並持續往前。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (354, 'SPA_01', 'C', 0, 49, '心理資本偏緊', '希望感、效能感或復原力相對不足，遇到壓力時較容易感到無助或停滯，需要更多外部結構與支持才好重新啟動。', '先從可控的小步成功建立信心，提供明確優先順序與資源；避免長期高壓、無回饋的任務配置。', '心理資源相對偏緊，希望感、效能感或復原力較難在壓力下同時維持，遇到高壓時容易出現無助或停滯感。可觀察行為包含：啟動行動門檻變高、遇阻礙容易卡住、需要外部結構與回饋才較能重新前進。若環境長期高壓、缺乏回饋或任務過大過模糊，受限感會更明顯。需強調的是，低分不等於能力差，常反映近期耗損與環境壓力，應結合近況與行為證據解讀。', '{"do": "• 先用小步成功建立可控感：把任務拆小、提供明確下一步與短迴圈回饋，逐步拉回行動動能<br>• 提供清楚優先序與資源支援（陪同、工具、範本），降低啟動門檻，避免長期獨戰高壓前線<br>• 觀察近期事件與行為證據，再決定配置與培訓；必要時先調整負荷與節奏，讓狀態回到可發揮", "dont": "• 不把低分直接等同能力差或不適任；需先排除近期耗損、環境壓力與制度不清造成的影響<br>• 不配置長期高壓、無回饋且目標模糊的任務；會放大停滯與無助感，造成更大耗損<br>• 不以測評結果做臨床或心理健康判定；應以工作情境與可觀察行為為主，避免錯誤標籤"}', 'SPA', '最近心理資源可能比較緊，壓力一來會更容易覺得卡住、沒力，想開始做也比較難啟動。你需要更清楚的優先順序、有人一起把下一步拆小，才比較能重新走起來。如果環境又高壓、又沒回饋，這種無助感會更被放大。這不代表能力不好，很多時候是近期太耗、條件沒做齊；先把環境與節奏調整好，再談表現會更公平。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (355, 'SPA_02', 'A', 75, 100, '目標路徑清楚', '能把目標具體化，並設計可行的路徑與替代方案；遇到阻礙時仍會想辦法找路而非停在挫折裡。', '適合擔任目標拆解與行動計畫主導者（銷售計畫、BD節奏、專案推進）；給挑戰型KPI能拉出成果。', '目標感清楚，能把想達成的結果具體化，並設計可行路徑與替代方案；遇到阻礙時會轉而找路，而非停在挫折裡。可觀察行為包含：把KPI拆成行動清單、主動準備備案、卡關時迅速調整策略或尋找資源。需留意的是，目標與路徑規劃若過度飽和，可能低估資源限制或同時推太多線；因此仍需搭配資源評估與優先序管理，避免計畫過滿。', '{"do": "• 讓其主導目標拆解與行動計畫（銷售節奏、BD管線、專案推進），並給挑戰型KPI以拉出成果<br>• 把路徑規劃搭配資源盤點（時間、人力、工具）與優先序，避免同時推太多導致分散<br>• 鼓勵建立備案庫（替代客群、替代話術、替代渠道），並在週期性檢核中快速更新與調整", "dont": "• 不把高希望感誤解成盲目樂觀；仍需用數據與資源限制校準，避免計畫過滿造成失速<br>• 不在需求頻繁變更時放任目標漂移；目標不穩會讓路徑規劃失效並增加挫折成本<br>• 不以單次規劃就判定永遠能達成；需看執行與回饋迴路是否到位，避免『想得好但做不出來』"}', 'SPA', '你通常能把目標想得很具體，也比較能規劃出怎麼走、卡住時要怎麼繞路。遇到阻礙，你不太會只停在挫折，而是會換個方式找下一條路。所以在需要拆KPI、排節奏、做行動計畫時，你常能扛起主導。不過也要提醒：路徑想得越多越容易排太滿，把資源和優先順序算清楚，成果會更穩。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (356, 'SPA_02', 'B', 50, 74, '需要方向才更穩', '有目標感與動機，但對路徑規劃較依賴外部資訊或經驗；在框架清楚時能穩定執行。', '先對齊成功標準與行動節點，提供可參考的打法與案例；用週期性檢核提升節奏感。', '具備目標感與動機，但路徑規劃較依賴外部資訊、案例或經驗；在框架清楚時能穩定執行。可觀察行為是：當有人提供打法、模板或成功案例，能迅速跟上節奏並把任務推進；若目標模糊或缺乏參考，容易卡在「怎麼做」而延後啟動。管理上宜先對齊成功標準與行動節點，再用週期性檢核讓路徑逐步成形，避免把企圖誤讀成不足。', '{"do": "• 先對齊成功標準與行動節點（每週要做什麼、做到什麼算過關），提供可參考的打法與案例<br>• 用週期性檢核（週會/看板）把路徑逐步具體化，讓其在清晰框架下穩定推進與累積信心<br>• 安排陪同演練或同儕示範，縮短摸索期，讓動機能快速轉為可複製的行動步驟", "dont": "• 不把需要框架誤讀成沒企圖或不願意衝；此區間的關鍵是清晰度，而不是意願不足<br>• 不在缺乏資源與案例時要求自行想出完整路徑；會放大卡關與延後啟動<br>• 不只丟口號式目標而缺少節點與回饋；目標越抽象，越難轉成具體策略與持續行動"}', 'SPA', '你不是沒有目標，而是更需要把「怎麼做」看清楚：有框架、有案例、有節點時，你通常能穩穩照節奏走；但如果目標很模糊、也沒人給參考打法，你會比較容易卡在起步階段。只要先把成功標準、行動節點和檢核節奏對齊，你就更能把動機轉成可落地的路徑，表現也會變穩。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (357, 'SPA_02', 'C', 0, 49, '目標感較鬆散', '較難把目標轉成具體策略與步驟，遇到卡關時容易停在原地或改走短線選擇。', '用短週期目標、明確下一步與外部督導，逐步建立路徑規劃能力；避免一次丟太大的模糊目標。', '目標感較鬆散，較難把目標轉成具體策略與步驟，卡關時容易停在原地或改走短線選擇。可觀察行為包含：面對長期KPI較難持續規劃、遇到阻礙時缺乏替代路徑、容易因不確定而延後行動。若任務一開始就很大且模糊，會更難啟動。管理上宜用短週期目標、明確下一步與外部督導，逐步建立路徑規劃能力，並檢視是否為方向或資源不足所致。', '{"do": "• 把大目標拆成短週期可達成任務，明確指定下一步與期限，並用固定檢核提供外部結構與回饋<br>• 提供具體方法與範本（行動清單、話術、客群分層），降低規劃門檻，逐步培養路徑設計能力<br>• 先確認方向與資源是否到位；若缺乏資源或目標不合理，先調整任務設計再談行動表現", "dont": "• 不一次丟很大的模糊KPI並期待自行規劃；會放大延後啟動與短線逃避<br>• 不把低希望感直接等同『沒動機』；可能是方向不清或資源不足，需要先把條件做齊<br>• 不只用催促或責備要求更積極；缺乏路徑與回饋時，情緒加壓只會讓行動更難開始"}', 'SPA', '你可能比較容易有「想達成」的心情，但要把它變成清楚的步驟和計畫時，常會覺得卡卡的；一遇到阻礙，就容易停住或乾脆改走比較短線的選擇。這種狀況在目標很大又很模糊時特別明顯。把目標拆成短週期、把下一步講得很清楚，再加上固定督導與回饋，你會更容易把路徑建起來，也更敢持續前進。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (380, 'SPA_10', 'B', 50, 74, '有衝勁但會起伏', '多數時有活力，但在連續高壓或缺乏成就感時能量會下降；補充資源與回饋後可回穩。', '用可見進度、短週期成果與合理休息節奏維持動能；適合穩健推進配置。', '多數時有活力，但在連續高壓或缺乏成就感時能量會下降；補充資源與回饋後可回穩。重點在能量管理與節奏設計，而非單純加壓。', '{"do": "用「短週期成果/可見進度」維持動能；安排合理休息節奏與資源補給；以節奏管理取代純加壓。", "dont": "不要用持續催促取代方法；不要忽略成就感與回饋機制；不要把能量起伏誤判成不積極或態度問題。"}', 'SPA', '你平常是有衝勁的，但如果一直高壓、又看不到成果，能量會掉。相反地，只要進度變得可見、回饋到位，你又能很快回來。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (358, 'SPA_03', 'A', 75, 100, '自信推進', '對自己能靠努力達成目標有明確信心，敢承擔結果並持續投入，遇到困難也較不容易退縮。', '適合需要主動開發、陌生拜訪、談判與高拒絕率的銷售情境；可給較高自主與成果責任。', '對自己能靠努力達成目標有明確信心，敢承擔結果並持續投入，遇到困難也較不容易退縮。可觀察行為包含：主動開發陌生客戶、在被拒絕後仍願意再嘗試、願意承擔業績與交付責任。需要注意的是，自信若缺乏數據校準，可能在判斷上過度堅持原路；因此仍需透過復盤與指標檢核，讓信心與方法一起迭代，避免盲點累積。', '{"do": "• 配置需要主動開發、談判與承擔成果責任的任務，並給足決策空間讓其用行動推進結果<br>• 建立數據與復盤節奏（漏斗指標、案例檢討），讓信心與方法一起校準，持續提升命中率<br>• 用更高階挑戰（更難客群、更複雜案型）搭配資源支援，讓其把自信轉成可複製的成熟打法", "dont": "• 不把自信等同永遠正確；缺少數據校準容易走偏，需保留檢核與調整機制<br>• 不在缺乏資源或規則不清時只靠其硬扛；會消耗信心並造成不必要的挫折成本<br>• 不把短期成功當成唯一證據；仍需看其是否能在挫折後維持行動與修正，而非只看一兩次結果"}', 'SPA', '你通常相信自己靠努力是做得到的，所以遇到困難不太會馬上縮手，反而比較願意再試、再修正，甚至願意把成果責任扛起來。這在需要陌生開發、談判或高拒絕率的情境很有優勢。不過自信也需要校準：定期用數據和復盤檢查方向，能讓你不只衝得快，也衝得準，避免因太相信原做法而忽略新訊號。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (359, 'SPA_03', 'B', 50, 74, '確認後加速', '多數情境能相信自己，但在新產品、新市場或高風險時會更想先確認做法；理解後可穩定輸出。', '給明確成功案例、話術框架與陪同演練能迅速拉升；適合在教練制團隊中成長。', '多數情境能相信自己，但在新產品、新市場或高風險任務時，會更想先確認做法與成功機率；理解後可穩定輸出。可觀察行為包含：先詢問話術、流程或案例，再投入執行；在有教練或同儕支援時表現提升明顯。若缺乏清晰方法或早期回饋，可能延後啟動或反覆確認。管理重點在提供成功案例、框架與演練，把風險感轉成更穩的準備，而不是被誤讀為不自信。', '{"do": "• 提供清楚成功案例、話術框架與流程步驟，搭配陪同演練，縮短確認期並加速啟動<br>• 用教練制與同儕支持建立安全試錯環境，讓其把風險感轉成更扎實的準備與復盤<br>• 在新市場/新產品採用分段目標與早期回饋，讓每一步都有驗證點，信心會隨證據快速拉升", "dont": "• 不把反覆確認簡化成不自信或拖延；多半是風險感較強，需要清晰度與證據支持<br>• 不只丟高風險目標而缺乏示範與資源；會讓啟動門檻變高並拉長磨合期<br>• 不在早期失利就否定能力；此區間很看訓練與框架，給到方法後常能迅速穩定輸出"}', 'SPA', '你其實不是沒信心，而是遇到新東西或風險高的任務時，會想先弄清楚：怎麼做比較會成功、哪些坑要避開。當你拿到清楚的做法、看到案例、甚至有人陪你演練一下，你就能很穩地把事情做起來。如果只丟目標卻不給方法，你就會比較容易一直確認、起步變慢。把清晰度補上，你的輸出會很快回到穩定。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (360, 'SPA_03', 'C', 0, 49, '容易自我懷疑', '對自己能否達成目標較沒把握，容易因挫折而縮手或拖延，行動啟動門檻較高。', '先安排低風險可達成任務累積成功經驗，搭配正向回饋與明確步驟；避免長期獨戰高壓線。', '對自己能否達成目標較沒把握，遇到挫折容易縮手或拖延，行動啟動門檻偏高。可觀察行為包含：在陌生開發或被拒絕後較難快速回到行動、需要更多確認與鼓勵才敢投入。若近期連續挫敗或缺乏正向回饋，這種自我懷疑會被放大。管理上宜先安排低風險可達成任務累積成功經驗，提供明確步驟與陪跑，逐步重建效能感；並強調低分不等於能力低，需結合近三個月表現解讀。', '{"do": "• 先配置低風險、可達成且回饋快的任務，累積成功經驗，把效能感從『做得到』的證據建立起來<br>• 提供明確步驟、話術與陪跑（同行拜訪/角色扮演/逐案復盤），降低啟動門檻並加速學習<br>• 解讀時結合近三個月事件與表現；若是近期挫敗造成，先調整節奏與支持，再談長期配置", "dont": "• 不把低分等同能力差或不適任；可能只是近期連續挫折或環境支持不足，需先排除情境因素<br>• 不長期安排獨戰高壓前線且缺乏回饋；會加深自我懷疑並讓行動更難啟動<br>• 不只用責備或比較激勵；需要的是可操作方法與可見成功，而不是情緒壓力"}', 'SPA', '你可能比較容易懷疑自己做不做得到，遇到不順就會想先縮一下、拖一下，尤其是需要陌生開發或被拒絕很多的工作，啟動會更難。這種狀況常跟近期連續挫敗、回饋太少有關，不一定是能力問題。先從可達成的小任務開始，給你清楚步驟、陪你跑幾輪，看到成果後效能感會回來，你也會更敢主動出手。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (361, 'SPA_04', 'A', 75, 100, '抗壓復原快', '遭遇拒絕、衝突或目標落空後能快速回穩，重新調整策略並保持輸出，不容易被一次挫折打亂節奏。', '適合高壓業務、目標波動大或需長期耕耘的客戶線；也可在團隊低潮時提供穩定力量。', '面對拒絕、衝突或目標落空後，回穩速度快，能重新調整策略並保持輸出，不容易被一次挫折打亂節奏。可觀察行為包含：失利後能迅速復盤、改話術再上、把情緒影響控制在短時間內。需要留意的是，高韌性容易被團隊依賴而承擔過多壓力；若長期缺乏休息與補能，仍可能累積耗損而在後段出現突然掉速，因此管理上仍要配置恢復節奏與支援。', '{"do": "• 配置在高拒絕率、目標波動大或需要長期耕耘的客戶線，並讓其在團隊低潮時扮演穩定推進者<br>• 建立固定復盤機制，把挫折轉成策略調整與學習素材，讓韌性不只硬撐而是變成方法升級<br>• 同步安排休息與輪替，避免長期超載；在關鍵衝刺與收尾節點使用其韌性優勢最有效", "dont": "• 不把高韌性當作『不會累』的證明；長期超載仍會累積耗損，需主動管理負荷與節奏<br>• 不忽略情緒與壓力訊號只看結果；即使輸出穩，也要關心其恢復品質與補能狀態<br>• 不在挫折後只要求更快回來；需要的是復盤與資源支援，讓回穩建立在可學習的調整上"}', 'SPA', '就算遇到被拒絕、衝突或案子沒成，你通常也能比較快把自己拉回來：先整理一下、找出可改的點，然後很快又回到行動節奏。這種韌性在高壓業務很珍貴。不過也因為你撐得住，常會被大家更依賴、事情越扛越多。記得把休息和補能排進去，否則長期硬撐也會在後段一次性耗光。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (362, 'SPA_04', 'B', 50, 74, '恢復需要時間', '壓力當下會受影響，但在獲得支持、釐清下一步後能逐步回穩；韌性表現受情境與資源影響。', '用節奏管理、同儕支持與明確里程碑降低耗損；適合穩健推進型配置。', '壓力當下會受影響，但在獲得支持、釐清下一步後能逐步回穩；韌性表現受情境與資源影響較大。可觀察行為包含：遇到衝突或失利時需要一些時間消化，若有人協助對齊目標、提供方法或陪同復盤，恢復速度會明顯提升。若長期缺乏支持或節奏混亂，可能出現恢復變慢、效率下滑與情緒拖尾。管理重點在節奏管理、同儕支持與明確里程碑，並觀察恢復速度而非只看情緒反應。', '{"do": "• 用節奏管理降低耗損：里程碑清楚、任務拆解到可執行，並在關鍵點提供支持與短回饋<br>• 建立同儕支持與教練式1on1，幫助其把失利轉成下一步行動，縮短情緒拖尾與停滯時間<br>• 評估時聚焦恢復速度與自我調節方法，並提供可學的工具（復盤框架、壓力管理）來提升韌性", "dont": "• 不只看當下情緒反應就判定韌性差；此區間關鍵在恢復機制是否到位，而非完全不受影響<br>• 不在缺乏支持與節奏混亂時加壓要求立即回穩；會拉長恢復期並增加耗損<br>• 不把挫折當成個人問題；需同步檢視資源、角色與任務設計，避免情境造成的波動被誤判"}', 'SPA', '遇到壓力或失利時，你不是完全不受影響，當下可能會悶一下、卡一下；但只要有人幫你把下一步講清楚、一起復盤一下，你就能慢慢回穩，重新把事情推起來。你的韌性很吃情境：節奏清楚、有支持時就恢復快；節奏亂、一直沒回饋時就會拖比較久。把里程碑和支持系統做起來，你的狀態會穩很多。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (363, 'SPA_04', 'C', 0, 49, '耗損累積快', '在連續高壓或長期不確定下容易出現疲乏與挫折感，復原較慢，表現波動可能增大。', '避免長期高密度前線，增加支援資源與分工；建立固定復盤與情緒釋壓機制。', '在連續高壓或長期不確定下，疲乏與挫折感較容易累積，復原速度偏慢，表現波動可能增大。可觀察行為包含：失利後需要較長時間才能回到行動、對新挑戰的耐受度下降、容易出現撤退或情緒耗竭。若工作前線密度高、缺乏分工支援或回饋機制，耗損會更快累積。需強調的是，低分不等於抗壓差，常是目前負荷過重；管理上宜先調整環境與支援，再談能力與配置。', '{"do": "• 避免長期高密度前線配置，增加分工與支援資源；先穩住負荷，再逐步拉升挑戰強度<br>• 建立固定復盤與情緒釋壓機制（結案檢討、支持對話、喘息安排），縮短恢復期並降低耗損累積<br>• 觀察近期壓力來源與事件脈絡；若是負荷過重造成，先調整環境與節奏，再安排能力訓練", "dont": "• 不把低韌性分數直接等同『抗壓差』；需要先排除超載與長期不確定造成的耗損<br>• 不在缺乏回饋與支援時要求持續衝刺；會加速耗竭並放大波動，甚至影響留任<br>• 不忽略恢復期就加新任務；在尚未回穩前再加壓，只會讓挫折感堆疊並降低後續可塑性"}', 'SPA', '如果壓力是一直來、又看不到結束，你可能會比較快累積疲乏：事情不順時要花更久才回得來，甚至會開始不太想再接新的挑戰。這很常是『負荷太重』而不是你不行。先把前線密度降下來、分工支援補上、回饋節奏變穩，你就比較能慢慢恢復，也更有機會把韌性拉回來。環境先修好，才公平談表現。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (364, 'SPA_05', 'A', 75, 100, '偏正向解讀', '傾向把不順視為暫時且可改善，較能維持希望感與行動力，在不確定下仍願意嘗試與修正。', '適合需要帶動士氣、推進變革或長期開發的銷售情境；可作為團隊動能來源。', '把不順利解讀為「暫時、可修正」的傾向較強，即使結果未定或環境變動，仍能維持希望感與行動動機。常見表現是：遇到拒絕或失敗會先找可控因素、快速調整話術或策略，再回到行動。需要留意的是，若只看正向而忽略風險訊號，可能低估阻力或備案不足，導致後段返工。', '{"do": "• 把不確定任務拆成短週期試驗（如兩週一個話術/渠道測試），用數據回饋維持動能與校準方向<br>• 在衝刺或變革期安排其帶頭推進士氣，但同時加上「風險清單＋備案」的固定檢核，避免只往前衝<br>• 把成功案例沉澱成可複用腳本（開場、異議處理、收尾），讓正向解讀能轉成可落地的行動節奏", "dont": "• 不把正向解讀當作『永遠不會低潮』的保證；當連續失利時仍要提供資源、陪同復盤與情緒緩衝<br>• 不以『你很樂觀所以不需要備案』的方式配置任務；缺乏風險檢核會放大後段返工成本<br>• 不把短期的好心情或一句鼓勵當作管理手段；需要的是可見進度、具體回饋與可調整的策略選項"}', 'SPA', '面對不順時，通常不會直接認定「完了」，而是比較容易把它當成暫時卡關，先找哪裡能改、下一步怎麼做。你常會用修正策略或換打法把事情推回軌道。不過也要記得：保持正向很好，但還是要把風險點列清楚，避免因為太相信會變好而少做備案。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (365, 'SPA_05', 'B', 50, 74, '現實中保有期待', '多數時能保持正向，但在連續挫折或高壓時會短暫消沉；看見進展與資源後能恢復。', '用可視化進度、明確下一步與支持系統維持動能；適合穩健節奏的KPI設計。', '多數情境能保持正向期待，但在連續挫折、被否定或高壓拉長時，情緒與動能可能短暫下滑，對未來結果的想像也會變保守。常見行為是：需要看到進度、資源或可行路徑後，才更容易回到投入與嘗試。若缺少可見改善線索，可能出現拖延、降低嘗試或把目標下修的傾向。', '{"do": "• 把進度做成可視化（里程碑、漏斗、週成果），讓改善路徑可被看見，避免只靠口頭鼓勵<br>• 用固定節奏的1on1/週檢核，聚焦「下一步最小可行行動」與資源缺口，幫助快速回到可控感<br>• 在挫折期安排小勝利任務（可達成、可回饋），用連續正向回饋把動能接回來", "dont": "• 不在挫折期用空泛激勵或比較式壓力（例如拿別人績效刺激）；容易讓動能更低、甚至轉防守<br>• 不把一次消沉解讀成長期消極；需要結合近期事件與可見進度判讀，而非貼標<br>• 不讓目標長期模糊或規則一直變；資訊不清會直接消耗樂觀感並放大拖延與退縮"}', 'SPA', '平常你其實是能正向看待事情的，只是如果連續幾次不順、又看不到改善方向，心裡會比較容易「先冷掉」。一旦看到進度、拿到資源或有人把下一步對齊清楚，你又能把狀態拉回來。重點不是打氣，而是讓你看得見「事情正在往更好的方向走」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (366, 'SPA_05', 'C', 0, 49, '悲觀預期偏高', '容易把失利解釋成長期且難改變，降低嘗試與冒險意願；遇阻礙可能提前放棄或轉為防守。', '先用小目標建立成功經驗，提供具體資源與教練式回饋；避免長期無回饋的任務配置。', '傾向把失利解釋成「長期、普遍、難改變」，因此在面對不確定或連續受挫時，嘗試與冒險意願較容易下降。常見表現是：遇到阻礙會先保守收縮、降低投入，或提前判定努力無效而退出。若環境回饋稀薄、資源不足或目標過大過模糊，這種防守解讀會更明顯，可能影響持續開發與抗拒絕能力。', '{"do": "• 先設計「小步成功」：把任務拆成可控且可驗證的短目標，讓回饋密度變高、重建嘗試意願<br>• 提供具體資源與方法（話術範本、陪同演練、成功案例），降低『不知道怎麼改』造成的無力感<br>• 避免長期高壓與無回饋配置；用固定復盤把卡點外顯，讓改善路徑變清楚而不是靠硬撐", "dont": "• 不把保守解讀當成『天生消極』或『不適任』；需先排除近期耗損、制度不清與資源缺口<br>• 不一次丟大型、模糊、成敗不明的目標；會放大無助感並讓行動更難啟動<br>• 不在低潮期用責備或羞辱式激勵；會強化防守與撤退，反而更難回到可嘗試的狀態"}', 'SPA', '遇到不順時，你比較容易先想到「是不是一直都會這樣」，所以會自然地想縮回來、先保守一點，免得再受傷。這不代表沒能力，而是需要讓你重新看到：努力能帶來改變。只要把目標拆小、回饋變密、支援到位，你會比較願意再試一次，也更能把步伐走穩。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (367, 'SPA_06', 'A', 75, 100, '工作即核心', '對工作高度投入，優先把時間與心力放在職責與成果上，容易把工作表現視為自我重要來源。', '適合需要長期耕耘、深度專注與持續追蹤的銷售/客戶經營；可給長線客戶與關鍵案。', '工作在生活中佔比很高，容易把職責與成果視為自我價值的重要來源，因此會主動加碼投入時間與心力。可觀察行為包含：主動追進度、願意長線跟案、對交付品質與結果有責任感。需要留意的是，若長期高負荷或缺乏恢復節奏，可能出現過勞、對他人投入度不耐，或忽略生活面支持而導致耗損累積。', '{"do": "• 配置長線客戶經營、關鍵專案或需要深度追蹤的任務，讓投入能轉成可累積的成果與關係資產<br>• 建立可預期的恢復節奏（週期性喘口氣、交付後緩衝），避免把高投入當成無限資源使用<br>• 用明確成果定義與授權範圍，讓投入集中在高價值行動，降低無效加班與不必要的耗能", "dont": "• 不因投入高就持續堆任務或默認『一定扛得住』；長期超載會以績效波動或情緒耗竭反噬<br>• 不把工作當作唯一評價尺度；忽略生活面支持會降低續航，甚至影響長期留任與健康<br>• 不讓目標與優先序模糊；投入型在不清楚時容易越做越多卻不一定更有效，反而加速耗損"}', 'SPA', '你通常會把工作放在很核心的位置，事情一來會很自然地想把它做完整、做到有結果，所以也更願意花時間追進度、跟細節、把案子收好。這個投入度在業務或專案很有價值，但也要小心：如果一直把油門踩到底，電量會被透支。把休息節奏排進去，反而能讓你更穩。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (368, 'SPA_06', 'B', 50, 74, '投入隨情境變動', '在目標清楚、回饋可見時投入度高；若任務意義不明或成就感不足，投入可能下降。', '用清楚目標、可見成就與合理授權提升投入；適合以階段成果驅動的管理方式。', '投入度會隨情境而起伏：當目標清楚、意義感強或回饋可見時，能投入並維持表現；若任務意義不明、回饋稀薄或成就感不足，投入可能下降而轉向完成最低要求。常見行為是：在有明確節奏與里程碑的工作上表現穩定，但在模糊、重複或缺乏被看見的任務上較難自發加碼。管理重點在於把『為何重要』與『怎麼算做到』講清楚。', '{"do": "• 先把成功標準與里程碑說清楚，讓投入有方向；用階段成果回饋取代只看期末結果<br>• 把任務意義連到客戶價值或團隊目標，並提供可見成就（排行榜、案例分享、獎勵）提升投入感<br>• 採用階段授權：先給可控範圍讓其做出成果，再逐步放大責任與自主權，讓投入自然加碼", "dont": "• 不把投入起伏解讀成不敬業；多半是工作設計缺乏清晰度或回饋機制，而非態度問題<br>• 不長期安排重複且無回饋的雜務；會快速耗損投入感，並讓表現落到最低線<br>• 不只用口號式激勵要求『更投入』；缺少目標、節奏與回饋時，情緒催促只會增加抗拒"}', 'SPA', '你的投入不是一直固定在同一格。當目標清楚、事情有意義、做了能看到成果時，你會很願意投入，也做得穩；但如果工作一直很模糊、做了看不到回饋，你就比較容易把它當成「完成就好」。只要把成功標準、里程碑和回饋節奏拉清楚，你的投入感通常會跟著回來。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (369, 'SPA_06', 'C', 0, 49, '工作與生活分隔', '較傾向把工作視為一部分責任，投入度受外部要求影響，可能較少自發加碼或長線耕耘。', '適合流程清楚、成果可量化的任務；若要提升投入，需連結其在乎的價值與誘因。', '較傾向把工作視為生活的一部分責任，投入度多受外部要求與制度規範影響，較少自發加碼或長線耕耘。可觀察行為包含：偏好完成明確交付、按規則做事，對於需要自我驅動或長期追蹤的任務可能較不主動。需要留意的是，若角色與誘因設計不匹配，可能被誤解為不努力；但在流程清楚、成果可量化的任務上，反而能穩定交付。', '{"do": "• 配置流程清楚、交付可量化的任務，並把期待寫清楚（輸出標準、期限、責任邊界）以提高穩定度<br>• 若希望提升投入，先連結其在乎的價值與誘因（學習、成就、獎酬、工作彈性），再逐步擴大任務半徑<br>• 用固定追蹤節奏與明確回饋，讓投入從『被要求』轉為『看得見好處』，避免靠情緒催促", "dont": "• 不以『投入低＝能力差』做結論；可能是角色不匹配、已耗損或制度不清，需先排除情境因素<br>• 不把長期、模糊、需要高度自我驅動的前線任務直接丟上去不管；容易造成拖延或低承諾<br>• 不忽略績效行為證據，只用主觀印象評價；在適配任務上可能交付很好，需看任務條件"}', 'SPA', '你比較像是把工作放在『該做就做好』的位置：規則清楚、交付明確時，你能按步驟穩穩完成；但如果要你自己一路加碼、長期追著一個模糊目標跑，你可能不會自動把油門踩到底。這不代表做不好，而是需要更清楚的成果定義、誘因與節奏，才能讓投入往上走。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (370, 'SPA_07', 'A', 75, 100, '高標準自我要求', '傾向遵守規範並維持專業品質，做事不只達標而是追求更好，對外代表公司時重視形象與一致性。', '適合客戶面高、需要信任與長期合作的角色；可作為服務品質與流程的示範者。', '對既定標準與專業品質的堅持度高，不只想『做完』，更傾向把交付做得一致、可被信任。可觀察行為包含：重視流程與合規、對外溝通有分寸、文件與承諾較少失誤，能代表團隊維持形象。需要注意的是，若把完美當成唯一標準，可能在多工或緊急情境中降低速度，或對他人品質要求過高而產生摩擦。', '{"do": "• 安排在客戶面、合規敏感或需要信任累積的任務（提案、合約前置、重大客訴處理），放大專業一致性的價值<br>• 建立交付標準與檢核表，讓其成為流程示範者，同時把高標準沉澱成團隊可複用的方法<br>• 在趕件情境加上優先級與『足夠好』門檻，避免完美主義拖慢進度；必要時提供協作分工支援", "dont": "• 不把高標準解讀成『愛挑剔』就壓制；需要的是把標準轉成可執行規則，而不是否定其要求<br>• 不讓其獨自承擔所有品質把關；過度集中會造成瓶頸與耗損，應設計分層審核與授權<br>• 不忽略速度需求與情境限制；在緊急任務仍需明確交付優先序，避免品質與時程兩頭落空"}', 'SPA', '你做事通常不是只求交差，而是會在意專業度和一致性：該有的流程、該確認的細節，你會想把它守好，對外也比較能維持形象與可信度。這在客戶經營很加分。不過也要留意：如果每件事都追到最完美，遇到多工或趕時間時可能會卡住。把優先級分清楚，品質和速度才好兼得。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (371, 'SPA_07', 'B', 50, 74, '標準可維持', '通常能維持基本專業與規範，但在高壓或多工情境可能出現品質波動；有清楚標準時更穩。', '用檢核清單、交付標準與回饋迴路提升一致性；適合穩健型客戶經營。', '多數情境能維持基本專業與規範，但在高壓、多工或資訊不完整時，品質一致性可能出現波動。可觀察行為是：有清楚標準、模板或檢核點時交付較穩；若標準模糊或需求頻繁變更，容易出現遺漏、延後確認或品質起伏。管理重點在把『交付標準』與『驗收方式』事先定義，並提供回饋迴路以穩定表現。', '{"do": "• 提供清楚交付標準（模板、檢核清單、驗收條件），並在關鍵節點做短回饋，降低品質波動<br>• 用固定節奏的復盤把失誤點轉成流程改進（例如常見漏項清單），讓專業表現更可預期<br>• 在高壓多工期協助排優先序、減少臨時變更，讓其把力氣用在最重要的品質點上", "dont": "• 不把品質起伏簡化成態度問題；多數時是標準不清或變更過多造成，需先修系統再談人<br>• 不在需求模糊時要求『一次到位』；應先對齊驗收條件，避免返工與責任模糊<br>• 不只給抽象評語（如更專業一點）；需要具體例子與可操作的改進點，否則難以穩定提升"}', 'SPA', '你通常能把基本專業守住，但如果事情一下子變很多、又很趕或需求不清楚，品質就可能忽上忽下。當你手上有明確的標準、範本或檢核清單時，交付會穩很多；反過來，如果規則一直改、驗收也不明確，就容易漏東漏西。把標準講清楚、回饋做固定，你就更能維持一致性。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (372, 'SPA_07', 'C', 0, 49, '標準感較鬆', '對流程與規範的敏感度較低，可能以完成為主而忽略一致性與細節，對外互動時風險較高。', '需要更明確的規範、示範與檢核；先安排可控任務，逐步提升專業一致性。', '對流程、規範與專業細節的敏感度較低，傾向以『完成任務』為主，可能忽略一致性、合規或對外形象風險。可觀察行為包含：交付前較少自我檢核、文件與承諾容易漏細節、對標準差異不太在意。若放在高客戶曝光或合規要求高的情境，失誤代價會放大；但在任務可控、規則清楚且有示範的環境下，透過制度與訓練能逐步拉升一致性。', '{"do": "• 先提供明確規範與示範案例（什麼叫達標、哪些細節必檢），再用檢核表把標準固化成流程<br>• 安排可控任務逐步練習：先低風險交付→回饋→再提高曝光度，避免一次丟到高風險前線<br>• 把合規/品牌風險點做成「必查清單」與交付前的最後關卡，降低因疏忽造成的外部代價", "dont": "• 不把低敏感度直接等同『不專業人格』；需要用制度、訓練與回饋把標準建立起來，再觀察變化<br>• 不在沒有規則與驗收條件下要求高品質；標準不清只會讓錯誤重複發生並難以追責<br>• 不把高曝光、合規敏感任務直接交付而缺乏審核；應先設置把關與陪跑，避免品牌/法務風險"}', 'SPA', '你比較容易把重點放在「事情做完」而不是「做到同一個標準」，所以在流程、規範或細節上，可能不會自動去多想一步。這在要求不高的任務可能沒問題，但如果要對外代表公司、或牽涉合規，漏一個細節就可能變成大成本。把規則寫清楚、示範一次、再用檢核表輔助，你的專業一致性會更容易拉上來。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (373, 'SPA_08', 'A', 75, 100, '主動要回饋', '會主動向主管、同儕或客戶確認表現與改進點，把回饋當成加速成長的工具，調整速度快。', '適合快速迭代的銷售團隊與教練文化；給即時回饋與數據看板能放大效果。', '主動向主管、同儕或客戶確認表現與改進點，把回饋視為加速學習與提升績效的工具。可觀察行為包含：結案後主動復盤、願意要求具體建議、收到回饋後能快速調整話術或流程。需要注意的是，若回饋來源品質不一，可能被單一聲音牽著走或過度迎合；因此更適合搭配數據、行為證據與多來源校驗，讓調整更穩。', '{"do": "• 建立快速回饋迴路：結案復盤＋即時數據看板，讓其把回饋轉成可追蹤的改進動作<br>• 鼓勵多來源回饋（主管/同儕/客戶/數據），並協助整理成優先級，避免被雜訊淹沒或失焦<br>• 把學到的改進沉澱成團隊教材（話術迭代、流程優化），放大其學習型特質對團隊的貢獻", "dont": "• 不把『很會要回饋』誤解為沒主見；需看其是否能把回饋轉成行動與成果，而非只求認同<br>• 不讓其長期暴露在低品質回饋（情緒化、片面批評）；會拉低判斷力並造成迎合式調整<br>• 不只給抽象評語或只說好/不好；需要具體例子與可操作建議，才能維持其快速迭代的優勢"}', 'SPA', '你會主動去要回饋，不太會等到出事才回頭看：做完會想知道哪裡可以更好、客戶在意什麼，然後很快把做法調整起來。這種學習速度很強，但也要小心回饋來源：如果只聽一個人或一種聲音，可能會越調越偏。把回饋和數據、實際結果一起看，會更穩也更有效。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (374, 'SPA_08', 'B', 50, 74, '被提醒才回頭看', '願意接受回饋，但多在遇到問題、績效波動或被要求時才會去確認；回饋頻率較情境性。', '建立固定檢核節奏（週會/1on1/復盤）最有效；提供具體例子比抽象評語更能促進改進。', '願意接受回饋，但多在遇到問題、績效波動或被提醒時才會去確認，回饋習慣偏情境性。可觀察行為是：當有人指出明確問題或提供具體例子時能修正，但平常較少主動蒐集外部觀點。若團隊缺乏固定檢核節奏，容易錯過早期修正窗口；若建立週會、1on1或例行復盤，反而能把改進變成習慣並穩定提升。', '{"do": "• 設計固定檢核節奏（週會/1on1/結案復盤），把回饋變成例行流程而不是等出事才補救<br>• 回饋要具體可行：用案例、錄音、對話片段或數據指標，讓其知道「哪裡改、怎麼改」<br>• 用短週期目標＋回饋迴路讓改進可被看見，逐步建立『主動回饋』的習慣與安全感", "dont": "• 不用抽象批評或模糊指令（例如更積極一點）；缺少例子時很難轉成行動，反而降低回饋意願<br>• 不把被動回饋習慣貼成『不想學』；多半是缺少機制與習慣，不是能力或態度問題<br>• 不只在出錯時才給回饋；若回饋只和負面事件綁在一起，會讓其更抗拒確認與對話"}', 'SPA', '你不是排斥回饋的人，只是通常會在遇到卡關、成績起伏或被提醒時，才比較會回頭確認哪裡要改。當回饋很具體、有人跟你一起看例子，你修正其實很快。重點是把回饋變成習慣：固定的1on1、週檢核或復盤一做起來，你就比較不會等到問題變大才回頭看。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (375, 'SPA_08', 'C', 0, 49, '回饋距離感', '較少主動尋求回饋，可能擔心被否定或覺得沒必要，容易錯過修正與學習的窗口。', '用低威脅、具體且可行的回饋方式建立安全感；先從小改進與可見成效開始。', '較少主動尋求回饋，可能擔心被否定、覺得麻煩，或過往經驗讓回饋被視為壓力來源，因此容易錯過修正與學習窗口。可觀察行為包含：不太主動問「我可以怎麼更好」、遇到問題先自己撐或迴避討論。若團隊文化偏指責或回饋方式帶威脅感，這種距離感會更強。管理上宜先建立安全氛圍與低威脅回饋，再逐步導入具體改進與可見成果。', '{"do": "• 用低威脅回饋方式建立安全感：先描述觀察到的行為與影響，再提供可選擇的改善方案與支持資源<br>• 先從小改進與短週期成果開始，讓回饋和『可行、有效』連結起來，而不是和否定感綁在一起<br>• 建立固定但溫和的回饋流程（例如每週一題：本週最想改進的一件事），逐步拉近回饋距離", "dont": "• 不在公開場合或情緒化狀態下給回饋；會放大威脅感，讓其更迴避確認與討論<br>• 不把不問回饋解讀成『抗拒學習』；需先檢視文化氛圍、過往經驗與回饋方式是否造成壓力<br>• 不只給結論不給方法（例如你做得不好）；缺少可操作下一步只會加深防衛與逃避"}', 'SPA', '你比較不會主動去要回饋，可能是怕被否定、也可能覺得問了反而壓力更大，所以遇到狀況會先自己撐、或乾脆不太想談。這不代表你不想進步，而是需要一種比較安全、比較具體的回饋方式：先從小改進開始、給你可做的下一步，看到成效後，你會更願意開口確認。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (376, 'SPA_09', 'A', 75, 100, '共益付出', '較不以付出回報作為主要衡量，對不對等的容忍度較高，可能更看重關係或任務本身。', '適合彈性制度或使命導向情境；但要避免長期吃虧而累積耗損或隱性不滿。', '較不以付出/回報作為主要衡量，對短期不對等的容忍度較高，可能更看重關係、任務本身與長期互惠。此傾向有助於在彈性制度或使命導向情境中維持投入，但需留意長期吃虧造成耗損或隱性不滿。', '{"do": "以「長期互惠/整體結果」角度解讀；提醒管理端定期關心負荷與資源；遇到不對等情境用「補償機制/回補安排」來保護個體。", "dont": "不要把高分解讀成「可以一直多做/不用回報」；不要鼓勵無止境加碼或情緒勒索式的使命感；不要忽略其累積耗損的風險訊號。"}', 'SPA', '你對公平不是不在乎，而是更看長期互惠、整體結果；短期吃點虧你可能還能扛。但如果一直被壓榨，你也可能默默累積疲憊或不爽。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (377, 'SPA_09', 'B', 50, 74, '互惠平衡', '會在意對等，但若能理解背景、看到補償或改善機制，多能接受差異並維持合作。', '用理由說明、補償方案與清楚流程可穩定合作；適合擔任制度溝通橋樑。', '會在意互惠與對等，但若能理解背景、看見補償或改善機制，多能接受差異並維持合作。此區間對資訊透明度高度敏感，透明化可顯著降低摩擦。', '{"do": "強調「理由說明＋可見補償」；提供清楚流程、評價標準與可申訴管道；把互惠證據具體化（時程、回補、資源）。", "dont": "不要用「先做再說」或空泛打氣帶過；不要資訊不對稱、臨時改規則；不要把其合理在意解讀成愛計較或不配合。"}', 'SPA', '你會在意公平，但只要理由說得清楚、補償或改善看得到，你通常願意一起往前走。最怕的是資訊不透明、只講口頭承諾。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (378, 'SPA_09', 'C', 0, 49, '回報敏感', '對付出與回報的公平性非常敏感，會注意資源分配、制度一致性與被對待方式，遇到不對等易產生不滿。', '需要透明制度與清楚評價標準；適合在獎酬、分工規則明確的團隊，避免模糊功勞分配。', '對付出與回報的公平性高度敏感，會特別注意資源分配、制度一致性與被對待方式；遇到不對等易產生不滿。適合在獎酬、分工規則與功勞歸屬清楚的環境中發揮。', '{"do": "用「透明制度/一致標準」作為管理重點；先建立互信與規則再談共益合作；提供可申訴、可追溯的機制與明確功勞歸屬。", "dont": "不要貼標籤成自私或難搞；不要用模糊分工、模糊獎酬與功勞不清；不要用「你就先吞一下」方式處理不對等，會快速破壞信任。"}', 'SPA', '你對公平非常敏感：規則、資源怎麼分、功勞怎麼算，你都會看得很清楚。只要制度透明，你會很穩；但如果模糊或不一致，你很容易覺得不被尊重。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (379, 'SPA_10', 'A', 75, 100, '高能量快節奏', '生活與工作步調偏快，做事積極、反應迅速，喜歡把事情往前推，容易帶動團隊速度。', '適合外勤開發、快節奏銷售與需要主動出擊的任務；可給多線並行但要控管優先序。', '步調快、行事積極、反應迅速，喜歡把事情往前推，並可能帶動團隊速度。適合快節奏開發與主動出擊任務；但需留意節奏過快造成他人壓力或忽略細節，建議搭配檢核機制。', '{"do": "配置外勤開發/快節奏任務；同步設「優先序＋檢核點」避免返工；提醒在合作情境放慢溝通節奏、補齊細節。", "dont": "不要把高能量等同於永遠不累；不要放任多線並行無收斂；不要忽略細節/品質檢核或團隊壓力累積。"}', 'SPA', '你做事很有衝勁、節奏快，常常會想把事情立刻推進，也容易帶起整個團隊的速度。但有時候太快會讓別人喘不過氣，或細節沒顧到。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (381, 'SPA_10', 'C', 0, 49, '節奏偏穩慢', '做事較不追求快，傾向按部就班；在高節奏環境可能感到耗損或被推著走。', '適合需要耐心、細緻跟進與長線耕耘的任務；若要提速，先優化流程與工具支援。', '做事不追求快，傾向按部就班、節奏較穩；在高節奏環境可能感到耗損或被推著走。適合耐心跟進、細緻執行與長線耕耘型任務；若需提速，宜先優化流程與工具支援。', '{"do": "配置長線耕耘/細緻跟進任務；若要提速先給工具、流程與緩衝；以清楚期限＋回饋節點協助節奏對齊。", "dont": "不要把低分解讀成懶散；不要用純「加速」要求硬推；不要把其放在高多工高催促環境卻不提供資源與方法。"}', 'SPA', '你屬於穩穩做、一步一步推進的型，未必追求快，但重視可控與穩定。如果環境節奏太急，你可能會很耗；但在需要耐心與細緻的任務，你反而很能扛。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (382, 'SPA_11', 'A', 75, 100, '相信可變可學', '更相信特質、能力與表現能透過努力改善，願意嘗試新方法並持續調整，學習動機與參與度較高。', '適合導入新打法、新工具或轉型訓練；給挑戰與成長回饋能快速升級。', '更相信特質、能力與表現可透過努力改善，願意嘗試新方法並持續調整，學習動機與參與度高。適合導入新打法、新工具或轉型訓練；但仍需合理目標與資源，避免過度承諾。', '{"do": "用挑戰＋成長回饋驅動；安排新工具/新打法導入角色；把目標拆成可達成的里程碑並配資源。", "dont": "不要把高分當成「什麼都能改、無限加碼」；不要只給口號不給方法/資源；不要鼓勵過度承諾導致挫折。"}', 'SPA', '你很相信「可以變得更好」，也願意試新方法、做調整，學習動機通常很強。只要給你方向和資源，你升級速度會很快；但也要避免目標喊太大變成壓力。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (383, 'SPA_11', 'B', 50, 74, '部分可塑', '相信某些能力可以提升，但對改變幅度與速度較務實；看見成效才會更投入。', '用可驗證的小步改進與案例支持，能提升投入；適合循序培訓與教練制。', '相信部分能力可以提升，但對改變幅度與速度較務實；看見成效才會更投入。有效做法是以可驗證的小步改進與案例支持，逐步拉高投入。', '{"do": "用「小步改進＋可驗證成果」設計培訓；提供案例與同儕示範；採循序教練制提升投入。", "dont": "不要用空泛理念硬推；不要一次要求大轉變；不要在沒有成效回饋時長期施壓，會讓投入下降。"}', 'SPA', '你覺得有些能力是能練的，但你會比較務實：要看到成果、才會更願意加大投入。用小步試驗、快速驗證，對你最有效。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (384, 'SPA_11', 'C', 0, 49, '較固定心態', '較傾向認為能力與特質相對固定，面對改變可能先觀望或覺得徒勞，學習投入度容易受挫折影響。', '先讓其在安全範圍內獲得小成功，逐步建立成長經驗；提供清楚方法與同儕示範。', '較傾向認為能力與特質相對固定，面對改變易先觀望或覺得徒勞，學習投入度可能受挫折影響。建議先在安全範圍創造小成功，提供清楚方法與示範，逐步建立成長經驗與安全感。', '{"do": "先創造小成功與安全感；提供清楚方法、步驟與同儕示範；用支持式回饋取代批評。", "dont": "不要用批評/羞辱式激勵；不要直接貼「抗拒改變/不想學」標籤；不要一口氣丟大改造且缺乏方法與支持。"}', 'SPA', '你可能比較不相信「人可以很快被改變」，遇到變革時會先觀望，甚至覺得努力也沒用。但只要先讓你在安全範圍內嘗到小成功、看到方法，你其實是能慢慢跟上的。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (52, 'ANI_17', 'B', 50, 74, '重點把關', '能在重要環節把關細節，但在多工或時間壓力下容易忽略次要細節。', '以清單化、同儕檢核與分段交付可降低漏失。', '在關鍵環節與主要輸出上能注意到重要細節，但在多工、高壓或時間緊迫時，對次要細節的掌握度較容易下降。', '{"do": "可用於：①說明其能在重點環節發揮把關作用②建議透過清單、雙重檢核或分工，協助在忙碌時維持細節品質③鼓勵事先釐清「哪些地方一定要很精準、哪些可簡化」來分配注意力。", "dont": "禁止：①將偶爾的細節疏漏放大成「不嚴謹」的長期標籤②忽略組織在工時、排程與資源配置上的責任③在要求高精度時，卻不給予足夠時間與工具④以個別錯誤否定其整體專業度。"}', 'ANI', '對你來說，重要的數字、合約或正式文件，你會特別小心；但如果事情很多、時間又很趕，一些較小的細節比較容易被略過。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (385, 'SPA_12', 'A', 75, 100, '高度形象管理', '答題或表達時傾向以社會期待的方式呈現，可能為了看起來更正向而淡化真實狀態，資訊可信度需交叉驗證。', '在面談/管理上多用情境題、行為例證與工作樣本確認；建立低威脅氛圍可提升真實回饋。', '答題或表達時傾向以社會期待的方式呈現，可能為了維持正向形象而淡化真實狀態；因此資訊可信度需交叉驗證。建議在面談/管理上使用情境題、行為例證與工作樣本，並建立低威脅氛圍以提升真實回饋。', '{"do": "提醒需交叉驗證（情境題/行為證據/工作樣本）；用中性提問與低威脅氛圍提高真實度；避免讓對方覺得被審判。", "dont": "不要直接判定「不誠實」或用指責式追問；不要只依賴單次自陳分數做重大決策；不要用高壓盤問逼出更大的包裝。"}', 'SPA', '你可能比較會「把自己講得更好一些」：不是一定在說謊，而是怕被否定、想留下好印象，所以會偏向說得正向。要更準確理解你，會需要用例子、情境題、或工作樣本來對照。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (386, 'SPA_12', 'B', 50, 74, '部分包裝', '多數時回應真實，但在敏感議題或想留下好印象時會偏理想化；整體仍可用，但要注意偏差。', '用中性提問、要求舉例與第三方佐證，可提高判讀準確度；固定回饋節奏也有幫助。', '多數回應真實，但在敏感議題或想留下好印象時會偏理想化；整體仍可用，但需留意偏差。適合搭配中性提問、要求舉例與第三方佐證，提高判讀準確度。', '{"do": "採中性提問＋要求舉例；必要時加第三方佐證；建立固定回饋節奏，降低臨場包裝需求。", "dont": "不要把表面正向當成全部真相；不要忽略敏感議題的包裝偏差；不要用二分法（真/假）評斷，改用證據校正。"}', 'SPA', '你大致是講真的，但遇到敏感題目、或很想留下好印象時，可能會稍微「講得更漂亮」。這很常見，不需要過度解讀；只要搭配舉例和佐證，判讀就會很準。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (387, 'SPA_12', 'C', 0, 49, '較真實直白', '較少為迎合他人而扭曲答案，回應更貼近真實狀態；優點是資訊品質高，但表達可能較不修飾。', '可用開放問題深入挖掘動機與行為；在客戶情境則可加強溝通包裝與同理表達。', '較少為迎合他人而扭曲答案，回應更貼近真實狀態，資訊品質高；但表達可能較不修飾。管理上可用開放問題深入挖掘；在客戶情境可加強溝通包裝與同理表達。', '{"do": "肯定其真實資訊價值；用開放問題深入動機/行為；在對外互動提供溝通包裝與同理技巧。", "dont": "不要把直白解讀成沒情商；不要要求其為了迎合而扭曲事實；不要忽略其在客戶/協作情境的表達風險（需教方法而非批評）。"}', 'SPA', '你比較直白、講話偏真實，不太會為了迎合而包裝，所以資訊可信度高。但有時也可能因為太直接，讓人覺得不夠圓滑；如果是面對客戶或協作場景，稍微加一點同理和包裝會更加分。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (388, 'SPA_13', 'A', 75, 100, '高度競速型', '行為上明顯進取、重視掌控與效率，容易被競爭與時間感驅動；壓力下可能出現急躁或敵意反應。', '適合目標明確、節奏快的銷售環境；需搭配情緒管理與衝突停損機制，避免內耗。', '行為明顯進取、重視掌控與效率，容易受競爭與時間感驅動；壓力下可能出現急躁或敵意反應。適合目標清楚、節奏快的銷售環境，但需搭配情緒管理與衝突停損機制，避免內耗。', '{"do": "配置目標明確/節奏快任務；同步建立情緒調節、衝突停損與溝通規範；用復盤把衝勁轉成穩定產出。", "dont": "不要把高分直接等同高績效；不要放任衝突升級或用「硬碰硬」管理；不要忽略其壓力下的敵意/急躁風險與團隊內耗。"}', 'SPA', '你屬於典型「衝很快、很拚」的風格：目標感強、效率導向、想掌控節奏。這能帶來速度與推進力，但一旦卡關或壓力大，你也更容易急躁、火氣上來。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (389, 'SPA_13', 'B', 50, 74, '目標導向但可調節', '有一定競爭與掌控需求，但多數時可維持理性合作；在高壓或受阻時才較明顯急躁。', '用清楚目標與可控節奏可放大優勢；提供復盤與壓力管理工具可降低副作用。', '具一定競爭與掌控需求，多數時可維持理性合作；在高壓或受阻時較易急躁。管理重點在提前對齊期待、釐清節奏與提供壓力管理工具，以降低觸發摩擦。', '{"do": "找出觸發點（被拖慢/被否定/受阻）；提前對齊期待與節奏；提供復盤與壓力管理工具，維持合作品質。", "dont": "不要等爆點才處理；不要用模糊指令、臨時變更拖垮節奏；不要把短暫急躁上綱成「難相處」，而忽略情境觸發。"}', 'SPA', '你有目標感，也在意效率，但大多時你能合作、能理性溝通。只是當你被拖慢、被否定或壓力很大時，急躁會比較容易被點燃；只要先對齊節奏和期待，就能很穩。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (390, 'SPA_13', 'C', 0, 49, '相對平衡型', '較不以競速與掌控作為主要驅動，重視合作與步調穩定；在高競爭環境可能較不亢奮。', '適合需要耐心、關係經營與長線耕耘的銷售模式；可用明確成就回饋提升動能。', '較不以競速與掌控作為主要驅動，重視合作與步調穩定；在高競爭環境可能較不亢奮。適合耐心、關係經營與長線耕耘的銷售模式，並可用明確成就回饋提升動能。', '{"do": "配置關係經營/長線耕耘任務；用清楚成果回饋與里程碑維持動能；避免用純競賽/高壓方式驅動。", "dont": "不要把低分當成沒企圖；不要硬套競速文化造成不適配；不要忽略其穩健持續性與合作價值（用對場景才會發光）。"}', 'SPA', '你比較像「穩健合作型」：不一定喜歡搶快或掌控一切，反而更重視關係和穩定步調。在需要耐心經營、長線跟進的情境，你會很吃香；只是如果環境太競速，你可能看起來不那麼亢奮。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (391, 'SPA_14', 'A', 75, 100, '強烈求勝', '對勝負與優越感高度在意，傾向把每個任務當成競賽，會想拿第一或主導局面。', '適合競賽型銷售、排行榜、短期衝刺活動；需要明確規則與公平機制避免內耗。', '面對目標時傾向以「勝負／排名」作為主要驅動，衝刺力強、企圖心明顯，適合短期拉升績效與攻堅任務；但若規則不清或回饋不透明，較可能引發內耗。', '{"do": "設定明確、可量化、公開的競賽規則；把「個人戰」改成「團隊共同戰績」避免互踩；定期做輸贏復盤把情緒導回策略", "dont": "不要用模糊口號煽動或臨時改規則；不要放任零和文化導致資訊封鎖；不要把所有任務都設成比賽導致疲乏"}', 'SPA', '你很吃「想贏」的感覺，衝起來很快很猛；只要把規則、獎勵和公平講清楚，你會更容易一路把成果推上去。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (392, 'SPA_14', 'B', 50, 74, '有競爭心但務實', '在關鍵任務會想贏，但不會把所有情境都視為競賽；能在合作與競爭間切換。', '用階段性挑戰賽與清楚獎勵能提升動能；同時保留協作機制維持團隊氣氛。', '在關鍵任務上具有競爭動機，但能在合作與競爭之間切換；若提供階段性挑戰與合理獎勵，可有效提升動能並維持團隊氛圍。', '{"do": "用「階段目標＋小型挑戰」帶動節奏；獎勵與評分透明化；同時設計協作機制（共享名單/共同行動）讓競爭不傷感情", "dont": "不要把你放進長期沒有回饋的環境；不要只用排名刺激卻不給資源；不要讓競爭變成互相拆台的默許文化"}', 'SPA', '你會在該拚的時候很想拚，但也能跟大家一起做事；給你一個清楚的挑戰賽，你通常會自己加速。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (393, 'SPA_14', 'C', 0, 49, '較少求勝驅動', '對競爭與排名的興奮度較低，更重視穩定表現或關係品質；不一定追求壓倒性勝利。', '適合顧問式銷售、客戶信任建立與長期服務；用客戶成功與品質指標替代單純排名。', '對排名與勝負的興奮度相對低，更重視穩定表現與關係品質；在顧問式、信任建立與長期服務情境中，往往能持續產出，但不一定被「比賽」激起動能。', '{"do": "用「客戶成功／續約／滿意度」等指標取代純排名；給長線耕耘任務與清楚期程；把成就回饋做得具體可見", "dont": "不要用高壓競賽逼動能；不要把不愛競爭解讀成沒企圖；不要用羞辱式比較刺激，容易反效果"}', 'SPA', '你不太靠「拚第一」來充電，比較在意把客戶照顧好、把事情做穩；用客戶成功或品質指標，你會更有感。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (394, 'SPA_15', 'A', 75, 100, '硬派衝刺', '企圖心強、想把成果做到最好，容易自我加碼並追求更高成就，遇到目標會想往上拉。', '適合高成長、高目標團隊；可給關鍵客戶、挑戰案與升級路徑，並提供資源支援。', '目標感強、傾向自我加碼並追求更高成就，能在高目標環境中快速推進；但若缺乏界線與節奏管理，可能出現過度衝刺、耗損或忽略協作。', '{"do": "給具挑戰但可落地的升級路徑；提供資源/權限讓你真正能達成；建立節奏（週檢核＋補能）並明確協作規則", "dont": "不要只加目標不給資源；不要讓你長期超載卻沒有停損；不要默許「只要結果」而忽略合作成本"}', 'SPA', '你很容易自己把標準拉更高、越做越想做到最好；只要資源到位、路徑清楚，你會跑得非常快。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (395, 'SPA_15', 'B', 50, 74, '有企圖但看回饋', '想變更好，但投入強度會隨資源、回饋與勝算評估調整；在看見成效時會明顯加速。', '用清楚成長路徑、里程碑與獎勵設計能提高企圖心；適合循序挑戰。', '具備上進心，但投入強度會依資源、回饋與勝算評估調整；若能看到清楚的成長路徑與可驗證成果，通常會明顯加速。', '{"do": "用里程碑與獎勵設計讓成果可見；提供方法/腳本/案例降低不確定；把成長路徑說清楚並固定回饋節奏", "dont": "不要丟一個很大很空的目標；不要只有口頭鼓勵卻沒有衡量方式；不要在成效未現前就貼上「不夠拚」標籤"}', 'SPA', '你想變更好，但你也很務實：看得到方法、看得到回報，你就會更願意投入、跑更快。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (396, 'SPA_15', 'C', 0, 49, '企圖感較保守', '較少把「往上衝」放在第一順位，偏向把事情做好但不一定追求極致突破；可能更重生活平衡。', '適合穩健型業績盤、既有客戶維繫或流程型工作；若要提升企圖心，需連結其在乎的價值與誘因。', '較少以「往上衝」作為第一順位，傾向穩健完成、重視平衡；在既有客戶維繫、流程型或長期可預期的任務中可穩定交付，但不一定會主動加碼。', '{"do": "設定清楚的最低標準與期待；把誘因連到你在意的價值（生活品質/成就感/穩定）；給可預期的任務盤與固定回饋", "dont": "不要用「拼命文化」當唯一激勵；不要把不加碼誤解成不努力；不要讓角色長期模糊，容易更收斂"}', 'SPA', '你比較偏向把事情做穩、做長久，不太會自己無限加碼；把期待講清楚、誘因對齊，你會更好發揮。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (53, 'ANI_17', 'C', 0, 49, '細節落差', '對細節敏感度較低，容易漏掉規格或小錯誤，需要更多檢核機制。', '適合搭配模板、標準作業與品質檢查流程。', '目前在細節覺察與檢核上較不敏銳，若缺乏標準化流程或檢查機制，較容易遺漏小錯誤或規格要求。', '{"do": "可用於：①指出其適合在標準作業清楚、已有檢核機制的情境下工作②建議導入模板、檢查清單與工具來降低錯誤率③鼓勵在關鍵文件或成果上安排同儕審閱，而非單獨承擔所有細節。", "dont": "禁止：①將此結果等同於「不在意品質」②用羞辱或嘲笑方式指出細節錯誤③忽略職務設計中對精確度的不合理期待④據此推斷其在其他能力面向上的價值。"}', 'ANI', '你在做事時會先顧大方向，對一些較細的格式、標點或規格細節，不一定會第一時間注意到；如果有明確的檢查表或別人一起幫忙看，會比較安心。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (397, 'SPA_16', 'A', 75, 100, '同時做很多', '做事節奏急、偏好多工並行，容易同時推多件事以追求速度與成果；在切換間可能忽略收尾與細節。', '適合需要快速反應的開發與前線，但要配合優先級與收斂機制（週清單/結案標準）。', '做事節奏快、傾向多線並行以追求速度與成果；能快速推動進度，但若缺乏收斂與結案標準，易出現分心、漏尾或品質波動。', '{"do": "建立優先序（本週三件最重要）與看板；要求每件事有結案標準；用固定節奏做收斂（週清單/日結）", "dont": "不要同時塞過多臨時任務；不要只要求快卻不給整理時間；不要讓你一直切換而沒有收尾機制"}', 'SPA', '你習慣同時推很多件事，速度很快；只要把優先順序和結案標準訂好，你會更像「推進引擎」而不是「到處救火」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (398, 'SPA_16', 'B', 50, 74, '多工視情境', '能在必要時多工，但也知道需要收斂；在任務明確與工具支援下可維持品質。', '提供工作拆解、看板與時間區塊管理能提升效率；適合彈性但有節奏的團隊。', '能在必要時多工，也知道需要收斂；若任務拆解清楚且工具到位，多數情況能維持品質與節奏，是「可控的多工」型態。', '{"do": "提供任務拆解與期限；用時間盒與看板工具；定期回顧哪些多工是必要、哪些要砍掉", "dont": "不要用混亂當成常態；不要頻繁插單破壞節奏；不要只看忙不忙而不看完成度"}', 'SPA', '你不是一定要多工，但需要時做得到；給你清楚的拆解和工具，你通常可以快又不亂。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (399, 'SPA_16', 'C', 0, 49, '偏好一次一件', '較習慣專注完成一件事再切換，節奏較穩；在高多工環境可能感到壓力或效率下降。', '適合深度跟進、關係經營或需要精準交付的任務；若需多工，先給工具與緩衝。', '較偏好一次專注完成一件事再切換，節奏穩定、品質導向；在高多工環境可能感到壓力或效率下降，但在深度跟進與精準交付任務上具優勢。', '{"do": "用明確期限＋充足緩衝；安排深度跟進/關係經營/精準交付任務；若需要多工，先給工具與清楚切換規則", "dont": "不要硬塞高頻切換工作；不要把穩健解讀成慢；不要臨時改需求又要求同樣交期"}', 'SPA', '你比較像「一件一件做完做漂亮」的類型；給你更穩的節奏與緩衝，你反而能交付得更可靠。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (400, 'SPA_17', 'A', 75, 100, '強烈時間緊迫', '常感到時間不夠用，做事像在追趕時程，對延誤特別敏感，容易出現急躁或催促行為。', '需要清楚排程、緩衝與升級機制；適合短週期衝刺，但要避免長期高壓造成耗損與人際摩擦。', '經常處於時間緊迫感，對延誤高度敏感，能推快節奏與短期衝刺；但也容易因催促與急躁提高耗損與人際摩擦，需要更清楚的排程與升級機制。', '{"do": "提供清楚排程與緩衝；建立卡點升級流程（誰決策/多久回覆）；用短週期衝刺＋固定復盤降低焦慮", "dont": "不要讓你長期在不確定與等待中；不要用含糊指令或頻繁變更；不要放任催促文化傷害合作關係"}', 'SPA', '你很容易感到時間不夠用，會想把事情趕快推完；只要排程清楚、卡點有處理流程，你就能把急迫感用在推進而不是內耗。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (401, 'SPA_17', 'B', 50, 74, '會緊張但可調整', '在重要交付或多任務時會有時間壓力感，但在規劃清楚、資源到位時能回到穩定節奏。', '用里程碑、優先序與時間盒管理能有效；適合有節奏的KPI與追蹤方式。', '在重要交付或多任務時會有壓力感，但在規劃清楚、資源到位時可回到穩定節奏；對「清楚優先序」與「可預期交付」反應最好。', '{"do": "用里程碑＋時間盒管理；提前對齊交付標準；減少臨時插單並確保資源到位", "dont": "不要讓需求反覆變更又不調整時程；不要只丟一句「快點」；不要把壓力全交給個人承擔"}', 'SPA', '你會緊張，但不是不能穩；把優先順序講清楚、把期限切成里程碑，你就會比較安心也做得更順。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (402, 'SPA_17', 'C', 0, 49, '時間壓力感較低', '較少被時間追著跑，對延誤的焦慮較低，步調偏穩；在快節奏團隊可能被誤解為不急。', '適合長線耕耘、品質控管與需要耐心的任務；若要提速，需更明確期限與回饋節點。', '較少被時間追著跑，對延誤焦慮低、步調偏穩；在長線耕耘、品質控管與需要耐心的任務更能發揮，但在快節奏團隊可能被誤解為不急。', '{"do": "設定明確期限與檢核節點；用可視化進度避免被誤解；安排長線或品質導向任務並給足資訊", "dont": "不要用恐嚇式催促；不要把「不焦慮」解讀成拖延；不要缺乏期限與回饋，容易失去節奏感"}', 'SPA', '你不太會被時間逼著跑，節奏比較穩；只要把期限、節點和回饋講清楚，你通常能穩穩交付。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (403, 'SPA_18', 'A', 75, 100, '情緒反應快', '面對煩惱或挫折時較容易衝動、情緒升溫快，可能出現急躁、語氣變硬、當場對抗或做出高代價回應。', '需設計降刺激工作方式、建立冷卻機制與溝通規範（先暫停、先書面、先換人），並降低高衝突暴露，衝突場景第三方介入；必要時安排情緒調節訓練。', '面對挫折時情緒升溫快、衝動反應機率高，可能在高衝突場景做出高代價回應；需透過降刺激工作設計、冷卻流程與溝通規範降低風險。', '{"do": "建立冷卻機制（先暫停/先書面/先換人）；降低高衝突暴露並用第三方介入；教練式訓練情緒調節與回應腳本", "dont": "不要當場硬碰硬；不要在情緒高點做重大決策；不要用羞辱/否定式管理加劇爆點"}', 'SPA', '你在被惹到或壓力很高時，反應會來得很快；如果先把「怎麼停損、怎麼冷卻」設好，你其實可以更好地把力氣用在解決問題。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (404, 'SPA_18', 'B', 50, 74, '會被觸發但可回穩', '一般情況能維持理性，但在被否定、受委屈、被誤解、連續失敗或壓力高時反應會上升；事後多能恢復並修正。', '先辨識觸發情境，建立停損與復盤流程；給提前提醒與支持能顯著降低爆點。', '多數情況能維持理性，但在被否定、受委屈、被誤解或連續失敗時反應會上升；事後通常可回穩並修正，差異在於是否具備自我覺察與停損方法。', '{"do": "辨識觸發情境並預先約定停損；用復盤把情緒轉成改善點；給提前提醒與支持（1on1/同儕）降低爆點", "dont": "不要把情緒反應直接貼成「難搞」；不要在高壓時用硬壓/指責；不要忽略觸發點而只要求忍耐"}', 'SPA', '你平常是穩的，但踩到特定地雷就會上來；如果先抓到觸發點，再配一套停損流程，你會更快回到可解決的狀態。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (405, 'SPA_18', 'C', 0, 49, '情緒穩定', '情緒反應門檻較高，遇到煩惱或衝突多能保持冷靜與理性處理，較少因一時情緒影響判斷、做出高代價決定。', '適合客訴、談判與高壓場景；可作為衝突情境的穩定支點。', '情緒反應門檻高，面對衝突多能冷靜理性處理，適合高壓、談判與客訴場景；但也可能較不外顯，需要確保有正常表達與釋壓管道，避免悶燒。', '{"do": "安排在談判/客訴/高壓協調任務；建立正常回饋與表達機制；提供規律釋壓與復盤節奏", "dont": "不要把冷靜誤解成沒有感受；不要長期讓你承接所有高壓；不要缺乏表達管道導致累積到臨界點"}', 'SPA', '你在壓力下通常很冷靜，很多人會覺得你很可靠；同時也要記得把壓力有地方說、有地方放，不要都自己吞。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (1, 'ANI_02', 'A', 75, 100, '壓力調適', '面對挫折與壓力能快速復原並維持穩定表現，較能把困難轉化為調整與學習。', '適合高壓、變動或需要長期推進的任務；可作為穩定軍心的角色配置。', '表現較高韌性傾向，面對壓力、挫折或變動情境時，通常能在合理時間內回復到穩定狀態，並從經驗中整理出調整方向與學習重點。', '{"do": "可用於：①說明其在「壓力復原、長期任務持續度、情緒穩定度」上的相對優勢②提供適合任務建議，如長期專案、高變動環境或需要安定團隊情緒的角色③提醒仍需安排休息與資源，而非將其視為可以無限加壓的對象。", "dont": "禁止：①描述為「不會有壓力」「什麼都壓不垮」等誇大說法②鼓勵在缺乏資源或不合理條件下持續硬撐③以韌性高分作為要求其「犧牲健康或私人生活」的理由④推論任何心理診斷或身心狀態。"}', 'ANI', '遇到壓力或挫折時，你雖然也會受影響，但通常能在不久之後重新站穩腳步，從中找出下一步要怎麼調整。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (2, 'ANI_02', 'B', 50, 74, '恢復中', '遇到壓力時需要時間調整，通常在獲得支持或釐清方向後能回到穩定狀態。', '安排合理節奏、階段性里程碑與支持資源，有助於維持續航。', '在面對壓力或重大變化時，通常需要一段時間消化與調整；當獲得適當支持、釐清方向與步驟後，多數情況能回到較為穩定的表現並持續前進。', '{"do": "可用於：①說明其在有支援與清晰方向下，仍具備良好續航與恢復力②建議主管或情境安排，如提供階段性里程碑、情境說明與情緒支持③引導個人覺察「什麼樣的壓力、資源或節奏」有助於自己恢復。", "dont": "禁止：①把需要時間調整解讀為「脆弱」「不可靠」②用貶抑或責備語氣描述其反應（例如「太玻璃心」）③推論其適不適合留任或升遷④將一時的狀態當成永久標籤。"}', 'ANI', '遇到壓力或不確定變化時，你可能需要先花點時間消化、弄清楚狀況，在有人討論或給你方向之後，會比較容易回到穩定步調。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (3, 'ANI_02', 'C', 0, 49, '能量耗損', '長期高強度或高度不確定環境下，較容易出現情緒耗竭或表現波動。', '避免長期高壓獨撐；可搭配同儕支持、分工與恢復機制。', '在長期高壓、持續不確定或資源不足的情境下，較容易出現能量耗損、情緒起伏或表現不穩，需要在負荷、支持與恢復之間有更刻意的管理與設計。', '{"do": "可用於：①協助釐清壓力來源與能量消耗模式，並給出具體的恢復與資源使用建議②建議組織在工作量、排程與支援上做調整（如分工、彈性安排、心理安全）③強調這反映的是「能量管理需求」而非價值或意志力問題。", "dont": "禁止：①將此解讀為「抗壓性差」「不適任關鍵職位」等負面標籤②鼓勵忽略身心狀態或繼續長期過勞③推論任何身心疾病或使用驚悚語言（如崩潰、撐不住）④把短期表現波動放大為個人缺陷。"}', 'ANI', '當壓力拉得太長、變化太多或資源不夠時，你可能會很快覺得耗損或疲憊；如果能調整工作節奏、清楚界線並安排恢復時間，狀態會比較好。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (4, 'CIA_28', 'B', 50, 74, '有感但不常說', '內心知道他人幫助重要但表達較保留，通常在重要事件或被提醒時才明確致謝。', '提供具體表達方式（回饋模板、公開致謝場域）可提升社會連結效果。', '對明顯的幫助或支持會覺得需要表示感謝，但對日常小協助或制度性資源未必都會特別放在心上。', '{"do": "可用於：①說明其感謝表現與事件顯著程度有關②建議透過團隊活動或反思機制，增加對日常支持的覺察③鼓勵在覺得被幫助時，適時做出簡單肯定，強化合作關係。", "dont": "禁止：①把沒立即表達感謝等同於「不懂感恩」②忽略文化差異對感謝表達形式的影響③用道德壓力要求其「凡事都要感謝」④不分情境地將其行為解讀為冷漠。"}', 'CIA', '遇到明顯的幫忙你會說謝謝，但有些日常小事，可能就覺得是互相幫忙或制度本來就該給的。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (5, 'ANI_03', 'A', 75, 100, '快速轉換', '能在不同觀點、策略與方法間切換，快速吸收新資訊並調整做法。', '適合跨領域協作、探索性任務或轉型期的快速迭代工作。', '表現較為突出的認知彈性，能在不同觀點、策略或方法之間切換，面對新資訊或情境變化時，較容易調整思考路徑並嘗試替代方案。', '{"do": "可用於：①說明其在觀點切換、策略調整與跨領域理解上的相對優勢②建議適合投入的任務，例如探索性專案、創新構想討論或轉型期的協作角色③提醒在多方案並行時仍需設立決策標準，避免過度變動方向。", "dont": "禁止：①將其描述為「三心二意」「沒定性」②鼓勵在缺乏共識或評估下頻繁變更策略③把認知彈性與「必然創意十足」畫上等號④推論任何注意力或衝動控制問題。"}', 'ANI', '你很擅長換角度看問題，面對新情況時能很快找到不同做法或新的切入點，而不是只卡在原本的想法裡。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (7, 'ANI_03', 'C', 0, 49, '思維慣性', '面對改變時傾向維持既有做法，對新方法需要更清楚的必要性與步驟。', '適合變動幅度較小或流程穩定的任務；導入改變時需分段推進。', '在思考方式上較容易維持既有路徑與慣用做法，面對改變時，通常需要更明確的必要性說明、具體步驟與足夠時間，才比較容易嘗試與內化新的方式。', '{"do": "可用於：①協助釐清其對穩定結構與既有流程的依賴，並建議在導入改變時採取分段、漸進的方式②鼓勵以「小幅試驗」「雙軌並行」來降低不安全感③提醒主管在溝通變革時增加說明、觀察期與回饋機制。", "dont": "禁止：①直接貼上「守舊」「抗拒學習」等標籤②忽略其在穩定環境中的價值與貢獻③用威脅或恐嚇的方式推動改變④把這個分數當作衡量學習能力或智力的指標。"}', 'ANI', '你比較習慣用熟悉的方式做事，遇到改變時，如果知道為什麼要改、怎麼做、會帶來什麼好處，就會比較願意配合和調整。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (11, 'ANI_04', 'A', 75, 100, '主動因應', '能快速覺察環境變化並調整優先順序，面對新要求通常能積極回應。', '適合高不確定、節奏快或需頻繁調整資源的情境。', '具備適應敏捷度的明確表現，能較早覺察環境或需求的變化，並主動調整優先順序與資源配置，對新的任務要求通常能以積極、開放的態度面對。', '{"do": "可用於：①說明其在變動情境下的「主動調整、重新排序、快速起跑」的傾向②建議適合投入在轉型專案、變革推動或需要頻繁調整方向的角色③提醒在反應快速的同時，仍需留意與利害關係人對齊，避免超前過多造成落差。", "dont": "禁止：①將其描述為「什麼都接、永遠有彈性」而忽略邊界②鼓勵在資訊不足時貿然大幅改變方向③以此分數合理化過度工作負荷或持續加壓④推論其一定適合所有高變動職務。"}', 'ANI', '當周遭情況或目標改變時，你通常能很快察覺、調整做事順序，主動尋找新的作法，而不是被動等待指示。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (8, 'ANI_04', 'B', 50, 74, '觀察後行動', '通常在理解變化背景與影響後才投入調整，行動較審慎但可持續。', '先給方向與期望，再給可行選項與期限，有助於加速反應。', '在面對變化時傾向先觀察與理解，再進入行動調整階段；通常在掌握變化的背景、影響與期待後，能做出較穩健且可持續的調整。', '{"do": "可用於：①強調其「理解後穩健行動」的風格，適合需要權衡利弊與長期影響的情境②建議主管在調整時先說明原因、預期與界線，有助於加快其決策與跟進速度③鼓勵個人在觀察與行動之間抓到平衡，不必過度延後調整。", "dont": "禁止：①把先觀察的習慣解讀為「反應慢」「沒企圖心」②在尚未說明清楚前，要求立刻承諾或大幅調整③否定其在穩定推進上的價值④將此分數視為對未來發展潛力的限制。"}', 'ANI', '遇到變化時，你會先觀察、問清楚來龍去脈，再決定怎麼調整；一旦想清楚之後，行動通常是穩穩往前的。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (9, 'CIA_31', 'B', 50, 74, '被引導就成長', '對成長開放，但多在看見清楚路徑、有人引導或制度推動下才積極投入。', '以學習地圖、導師制與可衡量成長目標最有效；適合穩健培育策略。', '認同持續成長的重要，也願意在有合適機會時投入學習；但在工作繁忙或看不到實質回報時，動力會明顯下降。', '{"do": "可用於：①說明其成長動機與資源、時間與回報期待高度連動②建議在安排訓練時，清楚連結到實際工作與發展機會③鼓勵將學習拆成小步驟，降低啟動成本。", "dont": "禁止：①將其在忙碌時學得少解讀為「不重視成長」②忽略工作量與心理負荷③只用口號式「要終身學習」施壓④在未說明意義下要求參與大量培訓。"}', 'CIA', '你知道學習對未來有幫助，也願意投入，但如果工作太忙或看不出學了會有什麼差別，就會很難擠出力氣。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (14, 'ANI_01', 'B', 50, 74, '情境分析', '在結構明確或熟悉情境中能有效分析，但在高度模糊或快速變動狀態下需要更多脈絡與引導。', '提供清楚問題框架與資料脈絡，有助於發揮分析能力。', '在情境脈絡較清楚或熟悉時能有效分析與判斷；面對高度模糊或快速變動議題時，較需要補充資訊、問題框架或引導以維持分析效率。', '{"do": "可用於：①建議先澄清目標/範圍/成功標準②提供框架（輸入-處理-輸出、假設清單、比較表）③說明此區間反映「對情境清晰度的依賴」，並給出提升分析品質的支援做法。", "dont": "禁止：①把需要框架解讀為「能力不足」或「不適任」②使用絕對化說法（如「壓力下就完全無法思考」）③將其描述成不負責/不主動④推論任何醫療或心理診斷。"}', 'ANI', '有清楚目標和資料時，你的分析很到位；如果狀況很模糊或變化太快，先把問題框起來、補齊脈絡，會更順更快。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (16, 'ANI_05', 'A', 75, 100, '自我驅動', '能自主設定目標、管理進度並調整行動，對成果與承諾有明確自我要求。', '適合高度自主、遠距或需要自我管理的角色與任務。', '展現明確的自主領導狀態，能主動設定目標、規劃步驟並追蹤進度，對承諾與成果有明確的自我要求，較少需要他人頻繁提醒。', '{"do": "可用於：①說明其在自我管理、時間規劃與任務推進上的主動性與可靠度②建議適合投入高度自主、遠距或需要自我規劃的任務與角色③提醒組織仍須提供方向對齊與資源支持，而非完全放任自行承擔所有壓力。", "dont": "禁止：①把高自主等同於「不需要管理、不需支持」②鼓勵長期過度自我要求而忽略休息與健康③以此作為理所當然加重負荷或指派所有「難搞任務」的理由④推論其人格價值或道德優劣。"}', 'ANI', '你習慣自己訂目標、自己抓進度，對「說出口要做到」這件事會特別在意，不太需要別人一直盯。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (18, 'ANI_05', 'C', 0, 49, '外部引導', '需要較明確的指示、節奏與回饋，否則容易分散或延宕。', '適合結構清楚的工作安排；管理上需更明確的分工與追蹤。', '在沒有明確指示、步驟與回饋時，較容易出現分心或延宕，傾向需要清楚的任務拆解、角色分工與追蹤機制，才能較穩定地推進工作。', '{"do": "可用於：①協助界定其在「需要結構與引導」上的特性，並建議具體管理做法（SOP、任務拆解、固定檢核）②強調這反映的是自我調節需求，而非能力或意願缺乏③鼓勵逐步練習小範圍的自我規劃，以累積自主經驗。", "dont": "禁止：①將其標記為「懶惰」「沒有責任感」②忽略環境設計與管理方式對表現的巨大影響③以羞辱或威脅方式要求其「自己想辦法」④推論其不適合任何關鍵任務或長期培養。"}', 'ANI', '如果事情只說一個大方向、沒有細節和步驟，你可能會比較不知道從哪裡開始；有清楚的分工、待辦清單和回饋時，會比較做得下去。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (19, 'ANI_06', 'A', 75, 100, '自然帶動', '能以溝通、信任與說服影響他人，並能在互動中建立支持與共識。', '適合協調資源、跨部門推進與帶動改變的角色。', '展現高人際影響力，能透過溝通、信任與說服自然帶動他人，容易在團隊中形成意見凝聚或推進變革的關鍵角色。', '{"do": "可用於：①說明其在建立共識、帶動氣氛與推進跨部門協作上的優勢②建議投入在需要對齊多方利害關係人、推動改變或代表團隊發聲的情境③提醒需注意溝通透明與一致性，避免因影響力大而讓他人感到被壓迫或資訊不對稱。", "dont": "禁止：①將其影響力等同於權威或否定他人觀點的正當性②鼓勵以操控、情緒勒索或過度包裝來說服他人③忽略組織在權責設計與決策機制上的界線④把高人際影響力當作必然適合所有管理職的唯一判準。"}', 'ANI', '你很擅長跟人互動、溝通想法，別人也比較容易因為信任你、被你說服，而願意一起往前走。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (20, 'ANI_06', 'B', 50, 74, '任務影響', '在職責或專業範圍內具影響力，遇到超出角色邊界時影響力較弱。', '給予清楚角色定位與授權範圍，有助於穩定發揮。', '在人際互動中，在自身職責或專業範圍內具有一定影響力，當角色定位與授權邊界清楚時，能有效說明觀點並帶動相關對象；超出範圍時影響力較受限制。', '{"do": "可用於：①說明其在人際影響上與「角色清晰度、權責範圍」的連動關係②建議透過清楚賦權與角色說明，提高其在組織內適當發聲的空間③鼓勵在符合職責的前提下，主動提出觀點並練習橫向影響，而非只在被動被詢問時表達。", "dont": "禁止：①將其描述為「沒有影響力」「存在感低」②忽略組織結構與文化對其影響表現的限制③以此分數推論其不適合與人合作或不善溝通④要求在完全沒有授權或支持下承擔高度政治性的影響任務。"}', 'ANI', '在你熟悉或負責的範圍內，你說話的份量和影響力會比較大；但如果是權責之外的事情，會比較看重角色邊界，不一定主動去帶風向。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (22, 'ANI_07', 'A', 75, 100, '多元發想', '能提出不同觀點與新穎解法，善於跳脫既有框架思考問題。', '適合創新、概念發想與解法探索階段。', '具備創造性思考的突出表現，能從多元角度觀看議題，提出新穎觀點與解法，較容易跳脫既有框架，為問題帶來不同的可能性。', '{"do": "可用於：①說明其在點子發想、概念設計與問題重新定義上的優勢②建議參與創新專案、策略構想或需要打破慣例的工作階段③提醒仍需搭配可行性評估與落地規畫，避免讓團隊感到變動過多或難以執行。", "dont": "禁止：①將「創意多」簡化成「一定好用」或「一定適合所有情境」②以此作為忽略流程、風險或資源限制的藉口③把他人較保守的反應解讀為阻礙或保守者的錯④鼓勵在完全沒有評估下頻繁更換方向。"}', 'ANI', '你很擅長換角度想事情，常常可以想到別人還沒想到的做法或點子，幫問題打開新的可能。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (23, 'ANI_07', 'B', 50, 74, '改良導向', '能在既有方案上進行優化與調整，創意多來自實務經驗與限制條件。', '提供清楚限制與目標，有助於產出可落地的改良方案。', '在既有框架與實務條件下，擅長對現有方案做調整或優化，創意多與實際需求、限制與經驗結合，傾向尋找「更好但可行」的改良路徑。', '{"do": "可用於：①說明其創造力偏向「改良與優化」而非完全顛覆式創新②建議投入在流程改善、產品優化或營運調整等需要務實創意的任務③鼓勵與偏概念型創意者合作，由其負責把想法轉化為可落地方案。", "dont": "禁止：①把這種風格解讀為「缺乏創意」②要求其在完全沒有參考與以往經驗時，獨立提出大膽顛覆方案③忽略實務限制，期待其產出與A區間相同型態的創新輸出④用分數去否定其在改善與精進上的價值。"}', 'ANI', '你比較擅長在「原本的做法」上動腦，調整流程、細節或組合，讓事情更順、更有效，而不是完全推翻重來。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (25, 'ANI_08', 'A', 75, 100, '卓越驅動', '對成果品質與表現標準有高度要求，主動追求突破與精進。', '適合高挑戰、高標準或需要拉高團隊門檻的任務。', '表現明顯卓越追求動機，對成果品質與個人表現標準有較高要求，傾向主動設定具挑戰性的目標並持續投入，以追求突破與精進。', '{"do": "可用於：①說明其在自我驅動、目標拉高與持續精進上的優勢②建議安排可見成效與成長空間的任務，以善用其高動機③提醒需留意過度完美或目標過高可能帶來的壓力，並協助建立健康的成就觀。", "dont": "禁止：①將其視為可以無限加壓、不需照顧的對象②鼓勵以過勞或犧牲私人生活換取成就③用分數合理化不平衡的工作分配④把偶爾狀態下滑解讀為「不夠用力」。"}', 'ANI', '你對自己的要求通常比較高，會主動拉高標準、訂比較有挑戰性的目標，希望把事情做到更好。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (27, 'ANI_08', 'C', 0, 49, '需求回應', '能完成基本要求，但較少主動追求更高標準或自我加碼。', '適合職責明確、節奏穩定的工作安排。', '在滿足基本要求與完成指定任務方面能維持一定水準，但較少主動追求更高標準或額外挑戰，動機多與外在要求、制度或環境壓力連動。', '{"do": "可用於：①說明其傾向以「達成既定要求」為主要目標，適合在職責明確、流程穩定的情境下工作②建議透過清楚說明升遷、獎酬或成長機會，逐步建立內在動機連結③鼓勵探索個人有興趣的領域，從小範圍開始嘗試更高標準的挑戰。", "dont": "禁止：①將其標籤為「不上進」「沒企圖心」②忽略組織在激勵設計、職涯路徑與文化上的影響③以比較或羞辱方式逼迫其追求高標準④推論其未來必然缺乏成長或貢獻。"}', 'ANI', '你可以把交辦的事情做完，但不一定會特別想要「再多做一點」或自動把標準拉得很高，通常會看公司的要求或情況再決定。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (28, 'ANI_09', 'A', 75, 100, '自我覺察', '能清楚覺察自身情緒與行為模式，理解其對他人與結果的影響並能調整。', '適合需要反思、回饋吸收與自我調節的角色。', '有高自我覺察，能較清楚地察覺自身情緒、想法與行為模式，理解其對他人與結果的影響，並較有能力在需要時調整表現與互動方式。', '{"do": "可用於：①說明其在情緒管理、反思與行為調整上的潛在優勢②建議投入需要回饋吸收、角色榜樣或教練性質較強的工作脈絡③提醒高覺察不代表永遠狀態穩定，也需要適當支持與休息。", "dont": "禁止：①將高自我覺察解讀為「不會情緒失衡」或「不需要支持」②要求其在任何情境下都必須完美調整自己③利用其覺察能力作為加重情緒與責任負擔的理由④推論其必然適合所有輔導或教練角色。"}', 'ANI', '你通常看得出來自己現在在想什麼、感受如何，也大概知道這樣的狀態會怎麼影響別人，必要時會調整自己的說話或做事方式。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (31, 'ANI_09', 'C', 0, 49, '覺察較少', '較少主動覺察自身狀態或對他人的影響，需要更具體的回饋才會調整。', '適合搭配明確行為指引、即時回饋與檢核機制。', '在日常情境中較少主動檢視自身情緒、行為或其對他人的影響，通常需要較具體、明確的回饋或事件，才會啟動覺察與調整的過程。', '{"do": "可用於：①說明其在覺察啟動上較仰賴外部回饋與具體事件②建議主管或同事提供明確、具體且建設性的回饋，而非抽象評價③協助設計簡單的自我檢核工具或提問，引導其在重要時刻多一點停頓與思考。", "dont": "禁止：①將其定義為「完全沒有自覺」「不會成長」②以指責或羞辱方式提供回饋，造成防衛而非學習③忽略組織在回饋品質與文化上的責任④過度解讀單次行為為固定且不可改變的特質。"}', 'ANI', '你平常不一定會一直想「我剛剛的反應怎麼樣」，但如果有人具體跟你說明、或事情影響比較大，你會開始注意並思考要不要調整。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (32, 'ANI_10', 'A', 75, 100, '應用理解', '能理解 AI 概念、應用情境與限制，並能評估實務價值與風險。', '適合參與數位轉型、工具導入與流程再設計。', '具備較成熟AI 科技素養，能理解 AI 的核心概念、常見應用情境與限制，並在實務中評估其帶來的價值與風險，協助組織做出較穩健的導入決策。', '{"do": "可用於：①說明其在 AI 概念理解、應用評估與風險意識上的相對優勢②建議投入在數位轉型、工具選型或流程再設計等需要判斷 AI 適用性的任務③提醒 AI 能力主要聚焦在「理解與應用判斷」，並非代表具備模型開發或工程實作能力。", "dont": "禁止：①將其 AI 素養等同於「可以獨立開發模型或架構系統」②以高分作為安排不合理技術責任或額外隱性工作負擔的理由③用「你最懂 AI，所以錯都是你」這類方式推卸組織決策責任④把 AI 素養與個人整體價值或智力高低直接畫上等號。"}', 'ANI', '你對 AI 的基本原理、能做什麼／不能做什麼有一定掌握，也大致看得出來哪裡適合用、可能會踩雷的地方。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (34, 'ANI_10', 'C', 0, 49, '起步階段', '對 AI 概念與應用仍在熟悉階段，需要具體示範與情境說明。', '適合循序導入；先從低風險工具與任務開始。', '目前仍在熟悉 AI 相關概念與應用的初始階段，對名詞與工具可能感到陌生或零散，需要透過具體示範、情境案例與循序練習，逐步建立基本理解與信心。', '{"do": "可用於：①說明其處在「基礎建立期」，適合先從低風險、操作簡單的工具與具體情境開始②建議提供循序漸進的教學、練習任務與問答機會，讓其在安全環境中探索③強調這不代表抗拒或跟不上，而是需要時間與合適資源來累積經驗。", "dont": "禁止：①把此區間標籤為「不懂科技」「抗拒改變」②在沒有給予足夠資源與示範前，就以成效不彰作為責備依據③用貶抑語氣嘲諷其數位能力或世代差異④推論其未來無法適應數位轉型或缺乏學習能力。"}', 'ANI', '現在你對 AI 的感覺比較像「還在摸索」，很多名詞或應用聽過但不一定很熟，需要有人示範、一起試著用幾次，會比較知道怎麼上手。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (29, 'ANI_12', 'B', 50, 74, '任務傾聽', '在目標明確時能有效傾聽，但在多工或高壓下易出現分心或漏聽。', '用會議結構、重點提示與摘要確認可提升表現。', '在傾聽過程中能維持一定專注，對重要內容與關鍵訊息有不錯掌握；在關係較重要或議題較敏感時，會有意識地多問幾句、確認自己有聽懂，但在其他時候，尤其多工或壓力較大時，較容易回到偏「選擇性傾聽」。', '{"do": "可用於：①說明其具備從「選擇性傾聽」往「積極同理心傾聽」移動的能力，差別多在情境與心力分配②建議在關鍵溝通時刻刻意關閉干擾、放慢節奏，用複述與簡短總結提高理解深度③鼓勵透過練習開放式提問與情緒確認（如「聽起來你有點…？」）來提升同理層次。", "dont": "禁止：①把在高壓或分心情境下的表現簡化為「你不願意聽」②忽視工作環境中的多工要求與資訊轟炸，單純用態度來解讀傾聽品質③以單一互動情境貼上「不會傾聽」的長期標籤④要求其在所有場景都維持高強度傾聽而不考量負荷。"}', 'ANI', '當情境重要、你在意對方時，你會比較專心聽，也會用追問或重複重點來確認理解；但若同時在忙其他事，或資訊很多時，可能就只會先抓住自己覺得重點的那一部分。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (39, 'ANI_12', 'C', 0, 49, '資訊遺漏', '容易錯過細節或誤解對方重點，需要更頻繁的確認與書面化。', '適合搭配紀錄、摘要與確認流程降低落差。', '在對話中較容易落在「選擇性傾聽」或表面回應的模式，可能只接收到自己感興趣或立刻有關的部分，較少主動複述、總結或確認對方真正的感受與需求。', '{"do": "可用於：①指出其目前傾聽多停在「聽到部分內容」的層次，適合透過簡單技巧（如多問一句、多重述一句）逐步往積極傾聽靠近②建議在重要對話中刻意放慢回應，不急著表達立場，先確認「我剛剛聽到的是…對嗎？」③鼓勵觀察語氣與表情等非語言訊號，幫助自己看見內容背後的情緒與需求。", "dont": "禁止：①將此區間直接標記為「不在乎別人」「完全不會聽」②用道德批判或羞辱的方式要求改變傾聽方式③忽略組織文化、會議節奏與發言空間設計對傾聽行為的影響④據此推斷其不適合所有與人互動或服務相關職務。"}', 'ANI', '你在聊天或開會時，容易先注意到自己在意的那一段，對於其他內容或對方背後的感受，不一定會特別停下來確認，有時會讓對方覺得「好像被部分聽到，但不完全」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (40, 'ANI_13', 'A', 75, 100, '主動探索', '對新知與新情境保持高度興趣，主動發問、嘗試並擴展理解。', '適合創新、學習、研究與實驗性任務。', '在好奇心上表現強烈，對新知、新情境與不同觀點保持高度興趣，會主動發問、查資料與嘗試新作法，傾向持續拓展自己的理解範圍。', '{"do": "可用於：①說明其在探索、研究與創新情境中的優勢，適合參與新題目或實驗性任務②建議搭配聚焦與優先順序設定，避免能量分散在過多議題③鼓勵將好奇心延伸到「如何落地」與「如何創造實際價值」，讓探索成果更容易被應用。", "dont": "禁止：①將高度好奇視為理所當然，卻不提供時間與空間來探索②忽略其探索需要，僅要求執行重複、單調的任務③把「還在探索」詮釋為「不穩定」或「不務實」④期待其對每個主題都同樣投入，忽視個人興趣差異。"}', 'ANI', '你對很多新東西都會想「這是怎麼回事？」會主動找資訊、問問題或試試看，不太只滿足於現有的做法。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (41, 'ANI_13', 'B', 50, 74, '回應式探索', '在需求或引導下能展現探索動機，問題越清楚越容易投入。', '提供明確問題與探索方向，有助於啟動好奇。', '在已有需求、清楚問題或外在引導下，能展現一定程度的探索動機，對與工作或生活相關的議題會主動多問一點，但較少對完全無關的主題投入大量精力。', '{"do": "可用於：①說明其好奇心較偏向「情境觸發型」，在相關性高或問題清楚時較易啟動②建議在任務設計上清楚說明探索的目的與可能收穫，有助於提升參與度③鼓勵個人針對有興趣或與發展相關的領域，設定小型探索目標，而非被動等待外在刺激。", "dont": "禁止：①把此區間解讀為「缺乏好奇心」②在任務缺乏意義感時，單純以壓力或命令要求其投入探索③忽略工作設計與回饋對探索動機的影響④用分數作為評論其人格開放度或價值的依據。"}', 'ANI', '如果有明確的問題、任務或有人邀請你一起討論，你會願意多了解一些；但不一定會對所有新東西都主動鑽研。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (42, 'ANI_13', 'C', 0, 49, '焦點保守', '偏好既有知識範圍，較少主動延伸探索或嘗試新作法。', '適合穩定、重複性或標準化程度高的任務。', '在學習與工作中傾向聚焦在已知領域與熟悉作法，對額外探索新主題或新工具的優先度較低，較偏好在穩定框架中持續精進既有能力。', '{"do": "可用於：①說明其在穩定、標準化或重複性較高的任務中，能以既有經驗維持品質②建議透過小幅度、低風險的探索（例如每次多嘗試一個不同做法）來逐步擴展彈性③強調此分數反映的是探索優先順序，而非學習能力或意願的否定。", "dont": "禁止：①貼上「沒好奇心」「不求進步」等標籤②忽視其在穩定執行與知識深化上的價值③要求在缺乏支持與說明下，快速接受大量變化或新工具④將此結果解讀為未來無法成長或轉型。"}', 'ANI', '你比較習慣把心力放在已經熟悉的事情上，會希望先把這些做穩、做好，而不是同時跑去摸太多新的題目。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (38, 'ANI_15', 'B', 50, 74, '局部整合', '能掌握主要關聯，但遇到高度複雜系統時需要視覺化或說明輔助。', '用流程圖、關聯圖與假設檢核可提升整體掌握。', '在系統性思考上具備一定能力，能掌握主要關聯與脈絡，但面對高度複雜或資訊龐大的議題時，較需要透過視覺化工具或結構化說明輔助整理全貌。', '{"do": "可用於：①說明其在有框架、有圖像輔助時能有效理解系統運作②建議透過流程圖、關聯圖與假設檢核表來支援思考③鼓勵在面對複雜問題時，先主動要求或自己建立整體圖像再往下分析。", "dont": "禁止：①把對工具與說明的需求視為理解力不足②在資訊高度破碎情境下，仍期待其快速做出全面判斷③以單次混亂經驗評斷其不適合處理複雜議題④用貶抑方式形容其為「只懂一點皮毛」。"}', 'ANI', '在一般情況下，你看得出事情之間的大關聯；如果牽涉單位太多、資訊太雜，只要有人幫忙畫圖、整理架構，你就能比較快釐清。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (44, 'ANI_14', 'B', 50, 74, '需求導向', '在工作或角色需求出現時投入學習，學習節奏與外在需求連動。', '設定明確目標與應用場景，有助於提升成效。', '在有明確需求、角色轉換或環境變化時，會投入學習來補足所需能力，學習節奏多與工作要求或外在機會緊密連動。', '{"do": "可用於：①說明其學習傾向偏向「需求驅動型」，在看到用途與必要性時較易啟動②建議在制度上清楚連結學習與角色發展、績效或機會，以提升學習誘因③鼓勵在需求出現前，針對關鍵能力預做一些基本鋪陳，以降低未來壓力。", "dont": "禁止：①將此區間簡化為「不愛學習」②在沒有說明學習意義與用途的情況下，只要求完成訓練時數③忽略組織在設計學習機會與發展路徑上的責任④以分數評斷其未來發展上限。"}', 'ANI', '當工作有新要求、或你看到某個能力真的會影響到成果時，你會開始找資料或學習，但平常不一定會主動去多學很多東西。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (91, 'CIA_08', 'A', 75, 100, '勝任自信', '對自身能力與掌控感較有信心，遇到挑戰願意承擔並主動找方法；較少因不確定而退縮。', '適合需要自主判斷、獨立推進與對外代表的角色；可賦予較高授權與主責範圍。', '普遍對自己的能力與影響力抱持信心，相信只要有時間與資源，大多數挑戰都能找到解法並處理好。', '{"do": "可用於：①說明其在承接新任務、面對變動與帶頭嘗試方面的優勢②建議提供具挑戰但可達成的機會，讓其把勝任感轉化為實際成果③提醒在高自信下仍要留意資源與現實限制，避免壓力累積。", "dont": "禁止：①把其自信當成不需支援的理由②在結果不理想時，用更高標準回頭指責「你不是很有能力嗎」③期待其一個人扛起所有困難專案④將自信與自負簡化為同一件事。"}', 'CIA', '你多半會覺得「給我一點時間，我可以搞定」，面對新挑戰比較容易採取「先試試看」的態度。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (45, 'ANI_14', 'C', 0, 49, '維持現況', '較少主動追求新技能，偏好以既有能力完成任務。', '適合技能穩定、變動較少的角色。', '在現階段較傾向以既有知識與技能應對工作需求，較少主動投入長期或額外的學習計畫，更偏好在熟悉範圍內維持穩定表現。', '{"do": "可用於：①說明其目前重點在穩定運作與運用既有能力，適合在變動較低、技能要求較固定的情境②建議透過短小、明確且與現有工作高度相關的學習活動，降低進入門檻③強調此分數代表學習投入的優先順序，而不是否定其學習能力或未來發展可能。", "dont": "禁止：①貼上「不思長進」「不上進」等價值評斷②忽略組織在提供有吸引力的學習資源與清楚發展誘因上的角色③以比較或羞辱方式強迫參與學習，導致更高抗拒④用這個結果斷言其無法成長或不適合被培養。"}', 'ANI', '你會比較偏向「用現在會的東西，把工作做好就好」，不一定會主動去規劃很多新的學習或進修。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (46, 'ANI_15', 'A', 75, 100, '整體連結', '能理解系統間相互影響，從整體角度看問題並預判連動效果。', '適合流程設計、跨部門協作與複雜議題盤點。', '在系統性思考上表現突出，能從整體結構與關聯角度審視議題，預先意識到一項決策對不同環節可能產生的連動影響。', '{"do": "可用於：①說明其在跨流程、跨部門或長期議題盤點上的優勢②建議投入於需要整體規劃、政策設計或路徑模擬的任務③提醒仍需搭配細節檢核，避免只停留在概念層次。", "dont": "禁止：①將其解讀為一定精通所有專業細節②僅因具整體觀就期待其獨自承擔複雜變革所有決策③以此作為忽略現場實務限制或基層聲音的理由④推論其必然適合所有策略職位。"}', 'ANI', '你不太只看單一點，而是會一起想：「這樣改會影響到哪些人、哪些流程？」所以在看事情時視野會比較全。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (49, 'ANI_16', 'B', 50, 74, '條件可靠', '在目標清楚或流程明確時表現可靠，遇到模糊或變動時易波動。', '提供清楚優先序、時程與檢核節點可提升穩定性。', '在目標、流程與期望清楚時，多數情況能維持可靠的交付；但在需求模糊、變動頻繁或優先順序不明時，交付穩定度較容易受到影響。', '{"do": "可用於：①說明其可靠性與目標明確度、流程清晰度高度相關②建議透過優先順序、檢核節點與書面確認支援其穩定交付③鼓勵在不確定時主動詢問與確認，而非自己猜測。", "dont": "禁止：①把在混亂情境下的波動視為「個人不可靠」②忽視管理與流程問題，單純責怪個人③用分數評斷其不適合承擔關鍵任務④忽略其在結構良好環境中的穩定表現。"}', 'ANI', '只要事情的期限、標準和流程都交代清楚，你通常可以準時、穩定地交付；如果前提常常改、或指示很模糊，就會比較難掌握。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (51, 'ANI_17', 'A', 75, 100, '精準嚴謹', '能維持高度專注與準確度，主動發現錯誤並確保品質一致。', '適合品質控管、資料處理、合規與高精度交付任務。', '在準確嚴謹度上表現優異，能長時間維持對細節的專注，主動發現錯誤或不一致之處，確保成果的品質與一致性。', '{"do": "可用於：①說明其在品質控管、審核與精細作業上的優勢②建議投入在資料處理、合規檢查或高精度要求的工作③提醒在追求精準的同時，也需與時程與效率做平衡。", "dont": "禁止：①以此期待其在任何情境下都零失誤②忽視工作量與時間壓力對細節品質的影響③將其嚴謹解讀為「挑剔」或人際問題④把注意細節等同於創意或大局思考不足。"}', 'ANI', '你對細節很敏感，常常可以在別人沒注意到的地方抓出錯字、數字或流程上的小問題，讓成果更穩。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (55, 'ANI_18', 'B', 50, 74, '任務溝通', '在工作需求明確時能有效溝通，但高壓或多工時需留意資訊遺漏。', '用議程、摘要與回覆確認可提升溝通品質。', '在任務明確、角色清楚的情境下，能有效傳遞資訊與回應需求；但在高壓、多工或議題較模糊時，資訊的完整度與一致性較容易產生落差。', '{"do": "可用於：①說明其溝通品質與情境條件的關聯②建議透過會議議程、會後紀錄與關鍵訊息重複確認來支援③鼓勵在不確定時多問一句、再複述一次對方的重點，以減少落差。", "dont": "禁止：①把情境造成的誤解一概歸因為「你溝通不好」②在資訊本身就不清楚的前提下，責怪個人沒有講清楚③忽略溝通管道過多、訊息碎片化等結構性問題④以一次溝通失誤否定其長期表現。"}', 'ANI', '當事情的目標、分工都講清楚時，你的溝通其實蠻順；但如果一次要處理很多事、或討論的主題很模糊，就比較容易漏講、或跟別人理解的不太一樣。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (57, 'ANI_19', 'A', 75, 100, '策略協商', '能平衡利益、尋求雙贏並調整策略，面對衝突仍能維持合作。', '適合對外合作、關鍵協議與資源交換情境。', '在協商談判上表現成熟，能兼顧自身與對方利益，清楚表達立場與底線，同時維持合作關係，擅長尋找雙贏或折衷方案。', '{"do": "可用於：①說明其在價格、條件或資源協調上的優勢②建議投入對外合作、合約協調或內部資源分配等需要談判的情境③提醒談判仍需事前準備與資料支持，而非完全依賴臨場反應。", "dont": "禁止：①將其視為必須在所有衝突情境中出面處理的人②以此為由，把高度風險或壓力談判全數交給其負責③忽略團隊或組織在談判策略與立場設定上的責任④以短期結果評價其全部談判能力。"}', 'ANI', '你談事情時，既會顧到自己這邊要守住的重點，也會注意到對方能接受的空間，常常可以談出雙方都可以接受、關係也維持得不錯的結果。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (59, 'ANI_19', 'C', 0, 49, '讓步傾向', '衝突情境中較易退讓或避免對抗，可能錯失保護己方利益的機會。', '適合先設定底線與說法，並安排練習與支援。', '在衝突或利益拉鋸的情境中，可能傾向避免對立、選擇讓步以維持關係或降低場面壓力；或是可能以強勢進逼想贏過對方、沒有保留雙贏空間，，因此談判結果對己方在短期或長期可能遭受損失。', '{"do": "可用於：①說明其偏好低衝突與關係維持的談判風格②建議在進入協商前先設定清楚的底線、可讓步與不可讓步項目，並安排必要時可請他人協助發聲③鼓勵透過角色扮演或模擬練習，逐步提升在安全範圍內堅持立場或思考雙贏的能力。", "dont": "禁止：①將其描述為「沒有立場」「不敢發聲」②忽略其維持關係與降低衝突的正面價值③在完全沒有支持的情況下要求其獨自面對高風險談判④用結果指責其個性有問題或推論其不適合承擔責任。"}', 'ANI', '一進入比較緊張或有衝突感的談判場景，你可能會傾向先讓一步、先求氣氛不要太僵，結果有時會把對自己比較有利的條件讓出去。另一方面，也可能發生只顧己方利益單純想贏，忽略雙贏的長期利益。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (60, 'ANI_20', 'A', 75, 100, '審慎評估', '能檢視資訊可信度、比較不同觀點並避免過度直覺判斷。', '適合參與風險評估、決策審查與品質把關。', '在批判性思考上表現成熟，能檢視資訊來源與證據品質，對不同觀點進行比較，不會只依靠直覺或單一說法做決定。', '{"do": "可用於：①說明其在資料驗證、風險評估與決策審查上的優勢②建議投入需要檢視假設、看反例、拆解論點的任務，如專案審查、政策討論、風險委員會③鼓勵搭配清晰的評估標準與多元資料來源，讓其批判性思考轉化為具體決策建議。", "dont": "禁止：①將其批判能力解讀為「挑剔」「唱反調」②期待其在毫無資料的情況下仍能做出絕對正確判斷③用這個分數合理化過度否定他人或持續拖延決策④把質疑與提問視為不服從或負面態度。"}', 'ANI', '你會先看資訊靠不可靠、理由是否站得住腳，不會只因為「聽起來合理」或「大家都這樣說」就接受。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (61, 'ANI_20', 'B', 50, 74, '選擇性檢視', '在關注重點明確時能進行判斷，但時間壓力下可能簡化評估流程。', '保留討論空間與反例檢核，有助避免單一觀點。', '具備一定批判性思考，當議題與重點清楚時，能針對關鍵資訊提出疑問與判斷；但在時間壓力大或資訊量過多時，較容易簡化評估流程。', '{"do": "可用於：①說明其批判深度會受時間與情境影響，在結構較清楚時表現較佳②建議透過簡化的檢核清單（如幾個固定問題）協助在壓力下維持基本評估品質③鼓勵在重大決策前預留短暫「停頓時間」，專門檢查假設與風險。", "dont": "禁止：①因為少數情境下評估不足，就簡化為「沒有批判能力」②在完全沒有時間與資訊支援的情況下要求其做深度風險分析③忽略議題複雜度與資訊品質，把所有判斷結果都歸因於個人能力④用一次錯誤推論其長期判斷力。"}', 'ANI', '如果主題明確、時間允許，你會挑重點去想「哪裡說得不夠完整」；但在很趕或資訊太雜時，會傾向先抓大方向，細部就不會檢查太多。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (63, 'ANI_21', 'A', 75, 100, '情境洞察', '能讀懂社交線索與關係動態，並調整互動策略以促進合作。', '適合跨部門協作、客戶互動與橋樑型角色。', '在社交智商上表現良好，能讀懂場合氛圍與人際動態，敏感察覺權力關係與微妙變化，並調整溝通方式以維持合作與信任。', '{"do": "可用於：①說明其在關係經營、跨部門協作與客戶互動上的情境判讀優勢②建議擔任橋樑型角色，如專案協調、利害關係人管理或對外窗口③鼓勵在維持關係的同時，也適度表達真實立場，以避免過度迎合。", "dont": "禁止：①將其社交敏感度視為理所當然的隱形勞務②要求其在任何情境都優先照顧他人情緒而忽略自身界線③把「看得懂氣氛」等同於必須處理所有人際問題④用此分數推論其一定外向或喜歡高社交強度。"}', 'ANI', '你對場合氣氛和人跟人之間的關係很敏感，通常看得出誰在意什麼、現場氛圍如何，會調整說話方式，讓互動順得多。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (64, 'ANI_21', 'B', 50, 74, '基本互動', '能在一般情境維持良好互動，但在複雜權力或衝突情境需要時間適應。', '清楚角色與關係結構、有助於提升互動穩定度。', '在一般職場互動中能維持良好關係，理解基本社交線索與角色分際；但在權力結構複雜、衝突較高或情緒張力大的情境中，較需要時間適應與額外資訊來判讀局勢。', '{"do": "可用於：①說明其社交智商多在「一般情境」表現穩定，在高複雜度場域需要更多脈絡支援②建議在重要會議或政治敏感議題前，提供關係地圖、角色說明與溝通重點③鼓勵在不確定時，採取多聽、多觀察與詢問建議的策略，而非急於表態。", "dont": "禁止：①因在少數複雜情境中不夠靈活，就貼上「社交遲鈍」標籤②忽略組織文化與權力關係對社交壓力的影響③期待其在沒有資訊與支持的情況下獨自處理高度政治性的互動④將社交表現與人格價值直接綁定。"}', 'ANI', '在日常合作、一般會議或熟悉的同事之間，你的互動通常蠻順；但遇到牽涉權責或氣氛比較僵的場合，就會需要多觀察一下，或事先有人幫忙說明背景，才比較知道如何應對。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (65, 'ANI_21', 'C', 0, 49, '線索不敏感', '對社交暗示或關係變化較不敏感，互動策略較固定，易產生落差。', '適合互動規則明確的環境；可用明確回饋降低誤解。', '在社交情境的細微線索（例如眼神、語氣、關係張力）上較不敏銳，互動風格偏固定，容易與他人對情境的解讀產生落差，需要更明確的規則、回饋與說明。', '{"do": "可用於：①指出其在「讀空氣」上需要更多明確線索與回饋，適合在互動規則清晰、期望透明的環境工作②建議同事與主管用直接、具體的方式說明期待，而不是依賴暗示③鼓勵個人透過詢問（例如「現在大家的顧慮是什麼？」）來補足情境理解。", "dont": "禁止：①將此結果簡化為「不懂人情世故」「情商低」②用嘲笑或排斥的方式回應其社交錯位③忽略組織在建立清楚規則與開放溝通文化上的責任④據此否定其在專業貢獻或工作成果上的價值。"}', 'ANI', '你在和人互動時，會比較專注在話裡「字面上」的內容，對氣氛變化或潛台詞不一定會第一時間察覺，有時會跟別人對當下情況的感受不太一致。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (67, 'ANI_22', 'B', 50, 74, '審慎選擇', '傾向蒐集足夠資訊後再決策，決策品質穩定但速度受資訊完整度影響。', '設定時程與決策門檻，有助兼顧效率與品質。', '在有足夠資訊與時間時，能做出穩健的決策；傾向先蒐集資料、聽取意見再定案，決策品質通常不錯，但速度會受到資訊完整度與不確定程度影響。', '{"do": "可用於：①說明其傾向審慎決策、重視風險與證據，在穩定環境中特別適合負責重要判斷②建議在時程敏感的情境下，事先設定「資料夠多就要決定」的門檻與期限③鼓勵在資訊難以完全掌握的情況下，運用情境假設與試行方案，而非無限延後決策。", "dont": "禁止：①將審慎與遲疑混為一談，簡化為「反應慢」②忽視議題複雜度與風險，要求其在資訊不足時硬性加快決策③以單次決策延宕評價其整體工作效率④用壓力或羞辱方式逼迫其「快點決定」。"}', 'ANI', '如果時間允許、資料找得到，你會希望先弄清楚來龍去脈再做決定，所以做出的決策通常蠻穩，但在資訊很模糊時就會多想一下才敢定案。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (71, 'CIA_01', 'C', 0, 49, '節奏支援', '較容易受情境或情緒影響而出現拖延、鬆散或收尾不足；不是做不到，而是自我監控與維持節奏較吃力。', '搭配短週期拆解、檢核清單、同儕回報機制；先讓完成穩定，再逐步拉高品質。', '執行節奏容易受情緒、環境或干擾影響，偶爾會出現拖延、鬆散或收尾不足的情況，能力並非不足，而是在自我監控與維持節奏上較吃力。', '{"do": "可用於：①指出其需要更多外部化工具（如任務拆解、檢核清單、固定回報節點）來穩定輸出②建議先把「準時完成」與「不漏掉」當成第一優先，再逐步拉高品質標準③鼓勵與主管或同事一起設計適合自己的節奏，而不是單靠意志力撐。", "dont": "禁止：①直接標籤為「懶散」「不可靠」②忽略工作量、干擾度與專注環境對其表現的影響③用羞辱或比較的方式要求「要自律一點」④將此分數視為否定其能力或潛力的理由。"}', 'CIA', '你不是做不到，只是很容易被當下狀態、雜事或心情打斷，要自己撐住步調會比較累。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (72, 'CIA_02', 'A', 75, 100, '卓越進取', '對表現與成果有明顯企圖心，願意多投入以達到更高標準，遇到挑戰傾向主動升級方法與目標。', '適合高挑戰、高成長、需要拉高標準的任務；可作為衝刺型角色。', '對表現與成果抱持強烈企圖，會主動拉高標準、尋找挑戰，願意投入額外心力追求更出色的成績。', '{"do": "可用於：①說明其在目標導向與追求成就上的動能，可作為衝刺型或關鍵任務的主力②建議搭配清楚的成長與回饋機制，把努力和成果連結清楚③提醒在高成就傾向下，也要留意休息與界線，避免過勞或過度自責。", "dont": "禁止：①以其成就動機為由，不斷加壓或延長工時③忽略資源不足、流程問題，只用「你應該更努力」回應落差③將短暫倦怠解讀為「不再上進」④把個人績效完全與人格價值綁在一起。"}', 'CIA', '你不太滿足於「剛好過關」，比較習慣問自己「能不能再更好一點」，所以常會多做一些。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (73, 'CIA_02', 'B', 50, 74, '目標驅動', '在目標清楚、回饋可見時會穩定投入；若缺乏指標或看不到進展，動能容易下降。', '以 KPI/OKR、里程碑與可視化進度維持續航；適合中長期專案的穩定推進者。', '對達成目標有穩定重視，當目標具體且看得到成果時，會願意投入努力；若缺乏指標或看不到成效，動能就比較容易下降。', '{"do": "可用於：①說明其動機多與「目標清晰度、意義感與回饋」連動②建議在專案初期一起定義具體指標與節奏，並提供可見的進展回饋③鼓勵其主動提出自己在成就與發展上的期待，避免陷入被動。", "dont": "禁止：①將此區間簡化為「不上進」或「沒企圖心」②在缺乏方向與資源時，用壓力或比較逼其多做③忽略職務設計與獎酬機制對動機的影響④用單一時期的低動力推論其長期表現。"}', 'CIA', '如果知道「做到這裡代表有進步」，你會願意出力；但如果目標很空或看不出差別，就會覺得再拼也不一定有用。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (74, 'CIA_02', 'C', 0, 49, '穩定達標', '傾向把工作完成在合理範圍，不一定追求更高難度或額外突破；動機更受環境支持與要求牽動。', '適合明確職責、節奏固定的工作；若期待突破，需提供動機意義與可達成的成長路徑。', '整體行事風格偏向穩穩完成要求，對「超標」「突破」的追求較弱，更傾向在合理範圍內把事情做完即可。', '{"do": "可用於：①說明其適合在穩定執行與支持性角色中貢獻，而不宜期待高度競賽式表現②建議將其放在需要穩定完成、而非持續衝高指標的工作內容③鼓勵透過探索「自己覺得有成就感的事」來建立屬於自己的成就定義。", "dont": "禁止：①貼上「不求上進」「躺平」等道德化標籤②忽略職務匹配與成就感來源差異③用高壓業績文化要求其表現出強烈競爭性④將此分數當作否定其職涯發展可能的依據。"}', 'CIA', '你會希望把分內的工作處理好，但不一定會為了拿第一名或打破紀錄，再多推自己好幾步。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (121, 'CIA_18', 'B', 50, 74, '恢復需要時間', '受到壓力時會有明顯影響，但在獲得支持、釐清方向後能逐步回穩；表現受情境差異影響。', '以合理節奏、同儕支持與階段里程碑降低負荷；適合穩健推進配置。', '面對壓力與打擊時會明顯受影響，需要時間與支持才能恢復，但在方向釐清、支持到位後，多能逐步回穩。', '{"do": "可用於：①說明其恢復速度與壓力強度、持續時間及支持程度高度相關②建議在高壓階段預先安排緩衝與支援機制③鼓勵其把需要幫助視為正常反應，而不是弱點。", "dont": "禁止：①把在高壓下恢復較慢解讀為「抗壓性差」②忽略工作與生活中長期壓力來源③只用「要想開」而不處理結構問題④把一次的低潮視為不能再被信任。"}', 'CIA', '壓力大或事情不順時，你會真的累、真的被影響，但如果有人陪你理一理、環境調整一下，慢慢就能再起來。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (77, 'CIA_03', 'C', 0, 49, '行動先行', '傾向先做再調整，評估常在行動後補上；在快速節奏下能衝刺，但也較容易忽略隱性風險。', '搭配快速檢核點與同儕 review 降低返工與踩雷；適合需要速度的工作。', '做事風格偏向「先做再說」，經常先行動再在過程中修正，對事前評估風險與前提的時間相對較少，在快速環境能推進，但也較容易忽略隱藏問題。', '{"do": "可用於：①指出其在需要快速試錯、敏捷調整的情境中具行動優勢②建議在高風險或一次性決策前，設置簡單的「停一下先想」流程③鼓勵與較審慎的同事搭配，在速度與風險之間互相補位。", "dont": "禁止：①直接貼上「莽撞」「沒在想」的標籤②忽略制度、時程與壓力對其行動風格的影響③只用事後責備處理錯誤，而不提供前期支援④把此分數當作否定其判斷力的理由。"}', 'CIA', '你很多時候會先去做、邊做邊調整，不太會在一開始就把所有細節想透。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (79, 'CIA_04', 'B', 50, 74, '規則導向', '大多遵守規範，但在資源不足或目標衝突時會尋求折衷；通常需要明確指示什麼不能動。', '把不可妥協底線講清楚，其餘留彈性可提升效率與配合度。', '大多數情況會遵守規範與承諾，但在資源不足、規則矛盾或多重目標拉扯時，會尋找折衷作法，希望在「守規矩」與「把事情做成」之間取得平衡。', '{"do": "可用於：①說明其在實務現場會同時顧及原則與效率②建議清楚界定「真的不能動的底線」，其他部分保留彈性空間③鼓勵當規範與目標衝突時，用對話尋找更好的做法，而非悶著承擔。", "dont": "禁止：①把情境下的權衡解讀為「沒有責任感」②忽略制度設計與資源條件對行為的限制③用單一事件批評其立場不堅定④要求其在沒有任何空間與支援下，仍獨自扛起所有義務。"}', 'CIA', '你基本上會照規則來，但如果資源不夠、規定有矛盾，或這樣做會讓事情完全卡住，你也會想辦法找折衷。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (82, 'CIA_05', 'A', 75, 100, '自制穩定', '能管理情緒與衝動反應，在壓力下仍維持一致行為與判斷，不易因一時情緒做出高代價決定。', '適合高壓、客訴、談判等需要穩定情緒輸出的角色；可作為團隊情緒穩定器。', '衝動與情緒來時，多半能先踩煞車、評估一下後果，再決定要不要說或要不要做，短期誘惑不容易完全蓋過長期考量。', '{"do": "可用於：①說明其在情緒管理、風險行為與重要承諾上的穩定度②建議在需要冷靜判斷與高自制的角色中善用此特質③鼓勵在自我壓抑與健康表達之間找到平衡，不必永遠當「情緒黑洞」。", "dont": "禁止：①把其穩定當成無限承受情緒與壓力的理由②忽略其內在耗損，只期待「你一定撐得住」③批評偶發情緒失控為「不應該」而不看長期表現④把高自制等同於不需要支持。"}', 'CIA', '就算一瞬間很想發作或很想立刻答應，你通常還拉得住自己一下，先想一下「這樣做之後會怎樣」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (83, 'CIA_05', 'B', 50, 74, '情境波動', '一般狀態自制力良好，但在連續高壓、衝突或睡眠不足時，反應可能變快、語氣變硬或耐心下降。', '建立高壓期節奏（輪班、緩衝、降噪）與復盤機制；在有支持系統下承擔前線任務。', '平時多能控制自己的反應與衝動，但在長期壓力、嚴重疲勞或連續挫折的情況下，情緒與行為有時會一時失衡。', '{"do": "可用於：①說明其衝動管理與壓力、體力高度連動②建議建立壓力預警機制（例如自覺快爆時先暫停決定）③鼓勵在事後檢討時，把重點放在調整做法，而不是單純自責。", "dont": "禁止：①只用單一事件否定其平常的自制力②忽略制度與工作負荷對其情緒穩定的影響③以「你不可以這樣」作為唯一回應，而不討論實際調整策略④把情緒反應視為人格缺陷。"}', 'CIA', '你大部分時候都還撐得住，但當很多事疊在一起、又很累的時候，也可能會突然說重話或做了之後覺得太快的決定。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (80, 'CIA_07', 'B', 50, 74, '品質平衡', '在重要任務會提高標準，但能在時間/資源限制下做取捨；品質與效率之間較能取得平衡。', '採分級品質策略（關鍵件高標、一般件可接受）能發揮最大效益；適合專案推進。', '在重要任務上會希望成果好看、站得住腳，但也能在時程或資源有限時接受「足夠好」，不會在所有細節上都追求極致。', '{"do": "可用於：①說明其在品質與效率之間的彈性拿捏②建議在專案啟動時就與團隊對齊品質標準與優先順序③鼓勵維持這樣的平衡，而不是被環境推向過度完美或過度隨便。", "dont": "禁止：①因為不「事事追求極致」就說「不夠用心」②忽略限制條件（時間、人力、資訊）③用他人極端完美標準要求其配合④將小失誤解讀為態度不佳。"}', 'CIA', '你會看事情的輕重來決定要多講究：重要的東西會盡量做到好、不丟臉，其他就做到合理水準即可。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (86, 'CIA_06', 'A', 75, 100, '流程有序', '偏好清楚流程與例行節奏，能把資訊分類、把任務排程並維持一致做法，降低遺漏與混亂。', '適合流程設計、營運管理、專案行政與品質控管；可建立團隊共通作業標準。', '對秩序與結構有明顯偏好，會主動整理流程、資料與環境，讓事情有條有理地進行，以降低遺漏與混亂。', '{"do": "可用於：①說明其在流程整理、檔案管理與專案規畫上的貢獻②建議擔任需要維持秩序與結構的角色（如 PM、系統整理、SOP 設計）③鼓勵在需要彈性的情況下，也允許自己保留部分「尚待探索」空間。", "dont": "禁止：①把其對條理的堅持解讀為「龜毛」「難相處」②忽略組織本身的混亂對其壓力的影響③期待其單獨扛起全部整理和制度化工作④把偏好秩序等同於缺乏創造力。"}', 'CIA', '你喜歡把「東西放哪裡」「下一步是什麼」都弄清楚，環境太亂或流程太散會讓你不太安心。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (88, 'CIA_06', 'C', 0, 49, '彈性隨性', '較不靠固定流程工作，容易臨場處理；彈性高但也可能出現紀錄不足、交接不清或遺漏細節。', '設定最低限度的紀錄與交付格式（不求完美，求可追溯）；適合探索或外部開發。', '對固定流程、分類與整理沒有太強的內在動機，習慣依當下需求與感覺處理事物，資訊與物品較容易分散，需要「最低限度的秩序設計」來避免影響工作。', '{"do": "可用於：①指出其在創意發想或需要靈活應變的工作中可保有彈性，但在大量資訊情境需要外加結構②建議從關鍵檔案與重要流程開始，建立最基本的整理規則③鼓勵逐步加入「讓自己少找東西」的小習慣，而不是一次要求全面大改。", "dont": "禁止：①直接貼上「邋遢」「沒組織」的標籤②忽略工作環境、工具與流程本身的雜亂③在未給予任何結構支援下，要求與高度條理者一樣的標準④以此分數否定其在專業或創意上的價值。"}', 'CIA', '你比較不會特別想要把每件事都歸檔好、標好，多半是要用到的時候才去找、才處理。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (89, 'CIA_07', 'A', 75, 100, '品質苛求', '對細節與品質要求高，會反覆檢查與優化以達到無瑕疵；在高標準場景能顯著提升可靠度。', '適合品質把關、重要交付、品牌/法遵/對外文件等；可作為最後審稿者。', '對成果品質與細節有高度在意，容易把標準拉在相對嚴格的位置，會不斷微調、修正，直到接近心中理想狀態。', '{"do": "可用於：①說明其在品質控管與精緻輸出上的優勢②建議在關鍵輸出（如對外簡報、正式文件）善用其高標準③鼓勵一開始先區分「需要完美」與「夠好就好」的情境，避免耗損過多心力。", "dont": "禁止：①把其完美傾向視為無限壓榨的理由②忽略時間與資源限制，只要求結果「零失誤」③用個別小缺點否定整體努力④鼓勵長期熬夜或超時工作來維持完美表現。"}', 'CIA', '你常會一改再改，只因為覺得「還可以更好一點」，對小瑕疵也比較看得見、放不太下。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (90, 'CIA_07', 'C', 0, 49, '完成優先', '更重視推進與交付，細節品質通常做到可用即可；在快速迭代場景有效率，但可能忽略小錯累積。', '適合 MVP、試點、快速產出；需搭配檢核/測試/他人 review 避免品質風險放大。', '對小細節瑕疵的容忍度較高，做事更在意整體完成與可運作，而不會為了打磨到完美而卡住進度，偏向「先有再優化」的風格。', '{"do": "可用於：①指出其在快速迭代、原型開發或試錯情境中具有優勢②建議搭配對細節敏感的成員，共同平衡整體品質③鼓勵在重大、一次性輸出時，稍微拉高檢查標準以降低風險。", "dont": "禁止：①把這種風格直接等同於「隨便」「沒品質概念」②忽略職務本身是否真需要極高完美標準③在未說清楚品質期待前事後責怪④以單一缺失否定其整體貢獻。"}', 'CIA', '你比較在意事情有完成、能用，而不是所有細節都要無可挑剔，對不影響結果的小地方會放得比較鬆。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (85, 'CIA_16', 'A', 75, 100, '目標路徑清晰', '能把目標具體化，並同時具備推進動機與替代路徑思考；遇到阻礙時能改道而不放棄。', '適合策略化推進、拆解路徑與持續優化的任務；可負責專案規劃與排除障礙。', '對未來有相對清晰的目標感，也能思考多條可行路徑，遇到阻礙時傾向調整做法而不是放棄方向。', '{"do": "可用於：①說明其在目標設定與路徑規劃上的優勢②建議參與中長期計畫與改善專案的設計與推進③鼓勵在修正路徑時，同步檢視目標是否仍符合自身價值與現實。", "dont": "禁止：①期待其永遠保持清晰方向、從不迷惘②用「你不是很有目標嗎」壓過其目前困境③忽略資源與外部環境對達成目標的影響④將短暫失去動力視為不被允許。"}', 'CIA', '你大概知道自己要往哪裡走，也會想「那如果這條路不通，可以怎麼繞過去」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (93, 'CIA_08', 'C', 0, 49, '信心不足', '容易懷疑自己是否能做好，遇到不確定任務可能遲疑或依賴他人決定；需要更多安全感才敢推進。', '以小步成功累積並提供明確指引與正向回饋；避免一開始就丟高風險責任。', '面對挑戰時較容易先想到「我可能不行」或「別人比較適合」，對自己能否處理好事情的把握度較低，需要更多具體支持與成功經驗累積。', '{"do": "可用於：①指出其在勝任感上需要更多具體回饋與小步成就來建立自信②建議主管在分派新任務時拆小步驟、給清楚指引與即時肯定③鼓勵其將「沒做過」與「做不到」分開看，避免預先放棄。", "dont": "禁止：①貼上「沒自信」「太弱」的標籤②忽略過往負面回饋或失敗經驗對其信心的影響③用嘲諷或比較逼其「振作」④依此分數斷定其不適合作為培養對象。"}', 'CIA', '你有時會先懷疑自己「真的可以嗎？」，會覺得別人可能會做得比自己好。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (94, 'CIA_09', 'A', 75, 100, '延宕誘惑', '能為了長期目標延遲滿足，面對短期誘惑仍可維持節奏與自我約束，較少因一時舒服而偏離計畫。', '適合長期推進、重複投入與自我管理任務；可交付需要持續交付的工作。', '能長期維持自訂節奏，為了重要目標安排時間、抗拒短期干擾，即使沒有人盯，也會自己推進到位。', '{"do": "可用於：①說明其在長期專案、自我成長與習慣養成上的穩定度②建議安排需要持續投入與高度自主管理的任務③鼓勵在自律與彈性之間保留調整空間，避免把自己綁太死。", "dont": "禁止：①把其自律當成無限加工作量的理由②忽略其同樣會感到疲憊與需要休息的事實③將偶爾鬆動解讀為「變懶」④假設其完全不需要外在支持系統。"}', 'CIA', '就算沒有人催，你也會照著自己的計畫去做，一點一點往長期目標前進。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (96, 'CIA_09', 'C', 0, 49, '短期拉扯', '較容易被短期誘惑牽動，明知道長期目標重要仍可能在當下選擇立即回報；自律維持較吃力。', '拆小任務、降低啟動成本並用環境設計減少誘惑；以明確獎勵建立習慣。', '在維持固定節奏與長期計畫上較有難度，行動常受當下心情、突發事件或環境干擾影響，計畫與實際執行之間容易出現落差。', '{"do": "可用於：①指出其在需要高度自律的任務中，必須透過工具與環境設計來補強②建議採用「短時段、短目標、多次重新開始」的方式，而不是一次逼自己完美堅持③鼓勵尋找適合自己的支持系統（例如夥伴約定、提醒工具）。", "dont": "禁止：①批評為「沒自制」「不長進」②忽略心理狀態、壓力或生活變動對執行力的影響③要求一次性徹底改變而不提供漸進方案④以此分數否定其負責任或成長的可能性。"}', 'CIA', '你可能常常有計畫，但實際要照著做會覺得很容易被打斷或被別的事情帶走。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (97, 'CIA_10', 'A', 75, 100, '誠正節制', '在利益與目標可見的情境下仍能維持誠懇與公正，對財富、地位與特權不會過度執著，也較少炫耀或佔便宜。', '適合需要高度信任的工作（資源分配、敏感資訊、合規與治理）；可作為文化示範者。', '整體價值觀傾向重視誠實、公平與謙遜，對貪圖不當利益、濫用特權或炫耀地位較為排斥。', '{"do": "可用於：①說明其在信任、倫理與風險控管上的重要性②建議安排在需要高度誠信與長期信賴的職務（如金流、合約、關鍵客戶）③鼓勵組織在制度與文化上與其價值相符，減少價值衝突感。", "dont": "禁止：①以其高誠實謙遜為由，忽視公平報酬與合理待遇②在制度不公時只要求個人「要有道德」③把其視為可無限承受價值衝突的防火牆④假設其永遠不會做出錯誤判斷。"}', 'CIA', '你在意事情是不是光明正大，也不喜歡靠關係或特權撈好處，對炫耀財富或地位的行為比較不買單。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (98, 'CIA_10', 'B', 50, 74, '原則彈性', '多數時候能維持公平與誠實，但在強壓績效或利益衝突下，可能在達標與原則間做權衡。', '把不可妥協底線講清楚（利益揭露、流程透明），並提供可行達標路徑。', '整體而言重視誠實與公平，但在壓力大、競爭激烈或灰色地帶情境中，會同時在意現實與原則，試圖在兩者之間找平衡。', '{"do": "可用於：①說明其價值觀與現實考量之間的拉扯狀態②建議組織釐清倫理底線與可接受做法，減少個人單獨承擔的壓力③鼓勵在困惑情境中透過對話，而不是獨自吞下矛盾。", "dont": "禁止：①因其猶豫或折衝，就貼上「不誠實」標籤②忽略文化、獎酬與權力結構對行為的影響③用道德壓力掩蓋制度缺陷④把單一次的妥協視為長期人格問題。"}', 'CIA', '你基本不喜歡不公不義的事，但在壓力很大或大家都這樣做的情況下，也會掙扎「這樣是不是還能接受」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (99, 'CIA_12', 'A', 75, 100, '重價值不重物', '相對不把財富與地位視為主要追求，決策更看重意義、成長或關係品質，較不易被物質誘因牽動。', '適合使命導向或長期投入工作；激勵方式偏成就感、自主與成長資源。', '對金錢、頭銜與外在排場的重視度相對較低，更傾向用意義感、關係與內在成就感來衡量一份工作值不值得。', '{"do": "可用於：①說明其在追求有意義工作與內在報酬上的傾向②建議以成長機會、影響力與價值實現作為重要激勵來源③提醒組織仍須提供公平報酬，避免以「使命」為由忽略基本待遇。", "dont": "禁止：①以其低物質傾向為藉口壓低薪資或福利②用「你不是不看重錢嗎」來逼其接受不合理條件③假設其完全不在意物質生活品質④忽略其對基本安全感的正當需求。"}', 'CIA', '你當然也需要收入，但不會只用「薪水多少、頭銜多大」來決定事情好不好，更在意內容是不是有價值。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (101, 'CIA_11', 'A', 75, 100, '直率不操弄', '較少為了達成目標去操縱或欺騙他人，溝通偏直接透明，傾向用真實資訊建立合作。', '適合互信與長期合作情境（跨部門、客戶關係、治理）；可降低猜疑與內耗。', '在人際互動上偏好以真誠、直接的方式溝通，不太傾向刻意操弄、隱瞞或欺騙他人來達成目的。', '{"do": "可用於：①說明其在建立深度信任與長期關係上的優勢②建議讓其參與需要穩定、真誠互動的合作與夥伴關係管理③鼓勵在保持誠懇的同時，也學會適度保護自己，不被過度要求透明。", "dont": "禁止：①期待其在任何情境都完全坦白而不顧自身風險②忽略組織政治與權力現實③將必要的策略性表述誤解為不誠懇④把偶爾的保留視為人格反轉。"}', 'CIA', '你多半是「怎麼想就怎麼說」，不太喜歡用話術或欺騙的方式來達成目標。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (102, 'CIA_11', 'B', 50, 74, '策略拿捏', '多數時回應誠懇，但在競爭、壓力或政治情境中，可能用較策略性的表達方式保護自身立場。', '提供清楚溝通規範（哪些可保留、哪些必須公開）與協作準則，維持信任又不失彈性。', '整體不偏好欺騙或操弄，但在敏感、權力不對等或關係脆弱的情境中，會斟酌要說多少、怎麼說，以兼顧真實與關係。', '{"do": "可用於：①說明其在誠懇與情境顧慮之間維持某種平衡②建議釐清組織對資訊透明與保密的實際期待，降低個人壓力③鼓勵在不安時尋求對話，而不是一味壓抑或過度隱瞞。", "dont": "禁止：①把策略性保留一概解讀為「不老實」②忽略法律、商業機密與角色責任對發言空間的限制③用理想化標準要求其在任何情境完全透明④用單一事件否定其整體誠懇度。"}', 'CIA', '你大多數時候會說實話，但在某些場合也會想「怎麼講比較不會傷人或惹麻煩」，不一定全部攤開講。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (104, 'CIA_12', 'B', 50, 74, '務實平衡', '能理解物質與地位的重要性，但不會完全被其主導；會在價值、生活需求與回報之間做合理取捨。', '清楚薪酬制度與可見成長路徑最有效；也能接受績效激勵但需要公平透明。', '既重視合理薪酬與生活品質，也會把工作內容、成長空間與環境氛圍納入考量，在物質與非物質報酬之間尋求平衡。', '{"do": "可用於：①說明其在評估機會時會綜合考慮多面向②建議在職涯溝通時，同時談報酬、發展與意義感③鼓勵其清楚表達對薪資與環境的期待，而不是壓抑需求。", "dont": "禁止：①將對合理報酬的要求貼上「現實」「勢利」標籤②忽略市場行情與貢獻價值③只用理想或使命感要求其忽略物質條件④用此分數評價其人格高低。"}', 'CIA', '你會希望薪水合理、生活過得去，但也知道「只看錢」不一定會快樂，會一起看內容、學習機會跟團隊氛圍。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (106, 'CIA_13', 'A', 75, 100, '原則守公平', '即使想領先或達成目標，仍傾向拒絕欺騙、偷竊、貪污或利用他人的手段，重視對等與規則一致。', '適合資源分配、制度設計、採購與治理等角色，提升信任與長期穩定。', '對公平與正義有強烈敏感度，對欺負弱勢、作弊或佔他人便宜的行為常會感到不舒服，傾向維護制度與互動中的公正。', '{"do": "可用於：①說明其在維護制度正當性與團隊公信上的重要性②建議在流程設計、規則檢討與倫理議題中納入其觀點③提醒在高度不公情境下，其挫折與憤怒感可能更強，需要支持與對話空間。", "dont": "禁止：①把其對公平的堅持視為「不識相」或「太理想」②忽略組織結構與決策不透明對其壓力的影響③期待其單獨扛起對抗不公的任務④因其提出質疑就標籤為「麻煩人物」。"}', 'CIA', '你看到明顯不公平的事情，會特別在意，覺得「這樣不太對」，也比較希望事情可以講求公道。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (107, 'CIA_13', 'B', 50, 74, '情境權衡', '大多願意遵守公平規則，但在強烈競爭或目標壓力下可能出現擦邊球心態，視環境容忍度調整行為。', '明確規則與後果（紅線、稽核、透明），並提供可行達標方法避免手段化。', '原則上不贊同不公平的作法，但在權力不對等、風險較高或氛圍緊繃的情境中，有時會選擇觀望、沉默或有限度表達。', '{"do": "可用於：①說明其在價值與安全感之間的拉扯②建議建立安全管道（如匿名回饋、正式申訴流程），降低其發聲成本③鼓勵其在可掌握的範圍內練習表達，逐步累積為公平發聲的經驗。", "dont": "禁止：①把沉默直接解讀為「贊同不公」②忽略權力結構與心理安全感不足③用「你怎麼不早說」責怪其沒出聲④將一次沉默視為長期價值觀問題。"}', 'CIA', '你會覺得公平很重要，但在現實複雜或講了可能對自己不利時，也會猶豫要不要出聲。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (109, 'CIA_14', 'A', 75, 100, '低自我中心', '對自身與他人的相對位置看法較平衡，不太需要透過炫耀或壓過他人來證明價值，較能接受他人貢獻。', '適合團隊協作、共同署名與跨部門合作，降低內耗與功勞爭奪。', '較自然地把自己視為團隊的一員，而非特別應該被優待的人，習慣低調表達貢獻，不會刻意凸顯自己。', '{"do": "可用於：①說明其在團隊合作、學習與接納回饋上的優勢②建議在需要降低階級距離、建立信任氛圍的情境中善用此特質③鼓勵在合適場合也能清楚說出自己的貢獻，避免長期被低估。", "dont": "禁止：①因為其謙虛就忽略或壓低其成果與待遇②用「你很謙虛」包裝客觀上的不公平③期待其永遠把他人放在自己前面④用文化期待壓抑其合理的自我主張。"}', 'CIA', '你不太會主動強調「我有多厲害」，也不太習慣要求特別待遇，比較傾向讓成果自己說話。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (110, 'CIA_14', 'B', 50, 74, '自信含蓄', '能肯定自己但表達較保留；在需要展現影響力或爭取資源時，可能猶豫如何拿捏分寸。', '給明確發聲場域與表達框架（成果呈現、角色授權），提升影響力而不違背風格。', '整體能保持不誇大、不自我膨脹的態度，但在需要爭取機會或介紹自己的場合，也有能力適度呈現個人成果。', '{"do": "可用於：①說明其在謙虛與自我行銷間較能拿捏分寸②建議在重要場合協助其更具體呈現亮點，以免低估自己③鼓勵持續維持這種彈性，不因環境壓力走向過度自貶或過度自誇。", "dont": "禁止：①因其在某些場合展現自信就批評為「不謙虛」②忽略角色本身對曝光與表現的要求③用單一互動經驗判斷其整體人格④要求其完全抹去自我存在感。"}', 'CIA', '你平常不會特別炫耀自己，但如果需要投履歷、簡報或爭取機會，也能把自己做過的事講清楚。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (112, 'CIA_15', 'A', 75, 100, '正向資源充沛', '具備較高的希望、效能感、韌性與樂觀傾向，面對挑戰能維持動能與信心，並把挫折視為可處理的問題。', '適合承擔轉型、開創、逆風推進與需要帶動士氣的角色；可作為團隊動能來源。', '整體心理資源相對充足，面對壓力與挑戰時，多半能帶著希望感、自信與韌性前進，把挫折視為可以調整與學習的機會。', '{"do": "可用於：①說明其在變動環境與高壓任務中的心理支撐作用②建議擔任需要帶動士氣、面對不確定性的角色③提醒在照顧他人、當大家精神支柱的同時，也要有人照顧他。", "dont": "禁止：①把其心理資本視為可以無限加壓的本錢②用「你撐得住」忽略其困難或疲憊③期待其永遠保持樂觀不准低潮④視求助或疲倦為「不應該」。"}', 'CIA', '你通常會覺得「雖然不一定順利，但總有辦法想出路」，對未來大多保有可以努力的感覺。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (113, 'CIA_15', 'B', 50, 74, '可被激發', '一般狀態能保持正向，但在長期壓力或不確定下動能可能下降；獲得支持與看見進展後會回升。', '以清楚目標、可見進度、支持系統與正向回饋拉升狀態；適合穩健推進型任務。', '在一般情況下能保持一定程度的樂觀與復原，但遇到長期壓力、連續挫敗或高度不確定時，心理動能會明顯下降，需要外在支持與時間恢復。', '{"do": "可用於：①說明其心理狀態與壓力總量與時間長度高度相關②建議安排合理恢復期與支持資源，避免長期處在高壓而不調整③鼓勵建立自己的紓壓與支持系統，在動能下降時有地方補充。", "dont": "禁止：①把在高壓之下的疲憊解讀為「不堅強」②忽略工作量、角色衝突與生活事件③只用「想開一點」簡化其困境④將偶爾低潮視為無法信任的理由。"}', 'CIA', '多數時候你覺得還行，但如果壓力堆太久、事情一直不順，就會開始懷疑自己、覺得很累。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (114, 'CIA_15', 'C', 0, 49, '資源不足', '較容易感到無力或悲觀，遇到挫折時動能下降較明顯，對未來期待感相對薄弱。', '先從可達成小目標建立成功經驗，搭配支持、教練式管理與壓力源盤點；避免一開始丟高不確定任務。', '對未來與自身影響力較容易抱持保留或悲觀態度，遇到壓力與挫折時，容易覺得「事情不會變好」或「自己也改變不了太多」。', '{"do": "可用於：①指出其在面對壓力與變動時需要更多支持與成功經驗累積②建議透過小而具體的目標與逐步成就感，慢慢擴大心理資源③鼓勵組織提供安全嘗試與允許失敗的空間，而非只要求「要正向」。", "dont": "禁止：①將其標籤為「負面」「難帶」②忽略過往挫折、資源不足或系統問題對其心理狀態的影響③用雞湯或責備要求其立刻樂觀④以此分數判定其不適合承擔重要任務。"}', 'CIA', '你可能比較常先看到困難或風險，對「事情會好轉」「我辦得到」這類想法沒有那麼自然。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (115, 'CIA_16', 'B', 50, 74, '動機可續航', '有目標動機，但路徑規劃有時需要外部引導；當方法不順時可能卡住，重新對齊後能再推進。', '用路徑拆解、選項清單與障礙排除會議提升連續性；適合在有策略框架的團隊成長。', '對未來大致有想像或方向，但在具體步驟與策略上仍在摸索，遇到環境變化或挫折時，較容易感到卡住，需要更多討論與陪伴釐清。', '{"do": "可用於：①說明其在願景與路徑之間存在過渡期②建議提供職涯諮詢、導師制度或教練式對話，協助把方向拆成可行步驟③鼓勵從短期可實踐的小目標開始，降低不確定感。", "dont": "禁止：①將其猶豫解讀為「沒目標」「沒企圖心」②忽略機會結構與資訊不對稱③只用「自己要想清楚」回應其困惑④以此分數否定其長期發展。"}', 'CIA', '你大概知道想成為什麼樣的人，但「要怎麼走到那裡」有時還不太確定，遇到變化就會更猶豫。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (117, 'CIA_17', 'A', 75, 100, '敢承擔會達成', '對努力能換來結果有明確信心，遇到高標目標傾向主動拆解與推進，較不容易因不確定而退縮。', '適合推進型任務與需要自我驅動的角色；可給較高自主權並期待自我解題。', '面對具有挑戰的目標時，多半相信「只要我願意投入，就有機會做到」，傾向主動拆解目標並推進，而不是因不確定而退縮。', '{"do": "可用於：①說明其在承接挑戰性任務與帶頭推進方面的潛力②建議提供明確標準與資源，讓其效能感轉成具體成果③提醒在失敗時，不要把所有責任全往自己身上扛，以免效能感反向受損。", "dont": "禁止：①把其高效能感視為可以忽略支援與環境條件的理由②在結果不佳時，以更重的道德壓力批評「你本來就做得到」③期待其一人填補所有制度缺口④用短暫挫折推論其信心已崩壞。"}', 'CIA', '你看到高標目標時，比較容易想「可以怎麼做」而不是「這太難」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (118, 'CIA_17', 'B', 50, 74, '需要確認再加速', '能力感多半足夠，但在新領域或高風險情境會希望先確認方向；一旦標準清楚就能穩定輸出。', '以成功標準、階段檢核與教練式回饋拉升信心與速度；適合在導師制團隊中成長。', '對熟悉或曾經成功的類型較有把握，遇到全新領域或高風險任務時，會先關注方向是否正確、支援是否足夠，再決定要投入多少。', '{"do": "可用於：①說明其效能感與「掌握度」高度相關②建議在新任務上提供導入說明、示範與可詢問對象，縮短不確定期③鼓勵其把過去克服困難的經驗帶到新的情境中，協助建立信心。", "dont": "禁止：①將謹慎視為「沒自信」或「不敢扛責」②忽略資源與資訊不足對投入意願的影響③只用「你要勇敢試」而不調整外在條件④以此分數否定其接新角色的可能性。"}', 'CIA', '對你有經驗的事情會覺得「OK，這可以試」，但對完全沒碰過的，你會先觀察、確認再全力衝。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (120, 'CIA_18', 'A', 75, 100, '逆境復原快', '遇到壓力、衝突或失敗後能快速回到可工作狀態，並把打擊轉成修正與補救行動。', '適合高壓前線、轉型推進、責任變更頻繁角色；可作為續航與穩定支點。', '面對壓力、挫折或變化時，雖然會受影響，但多能在合理時間內調整心態、找到因應方式並回到可運作狀態。', '{"do": "可用於：①說明其在變動環境與高壓任務中的復原能力②建議在變革或關鍵專案中安排其扮演穩定力量的角色③提醒組織不要因其韌性而忽略資源、人力與休息配置。", "dont": "禁止：①把其韌性當成可以無限加壓的理由②用「你撐得住」忽略其耗損③假設其永遠不會出現耗竭或低潮④在其提出需要幫忙時感到「意外」並責怪。"}', 'CIA', '你遇到打擊時也會難過或累，但通常可以慢慢整理好，再站起來繼續往前。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (123, 'CIA_19', 'A', 75, 100, '把不順視為暫時', '對挫折的解釋偏向可改善、可轉機，較能維持希望感與行動力，不易被單次失敗打垮。', '適合帶動士氣、在不確定中推進的任務；可作為團隊動能來源。', '看事情時比較容易先看到可能性與希望，面對挫折也傾向解讀為暫時的阻礙，而不是全面否定自己或未來。', '{"do": "可用於：①說明其在壓力與變動中維持希望感與行動動能的能力②建議在變革、轉型或高不確定專案中，善用其穩定團隊士氣的特質③鼓勵把樂觀轉化為行動計畫，而不是只停留在「應該會好」的想像。", "dont": "禁止：①把其樂觀看成「什麼都不怕」而不討論風險②用樂觀掩蓋現實問題或資源不足③在對方感到沮喪時，用「你不是很樂觀嗎」否定其當下感受④暗示只要樂觀就不需要制度與支援。"}', 'CIA', '你通常會覺得「雖然不順，但應該還有辦法」，比較少因一次挫折就對一切失去信心。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (124, 'CIA_19', 'B', 50, 74, '現實中保有期待', '多半能保持正向，但在連續不順或高壓時會短暫消沉；看見進展與資源後能恢復。', '以可視化進度、明確下一步與支持系統維持動能；適合穩健節奏。', '面對多數情況時能維持基本正向看法，但在連續挫折或高度不確定時，心情與信心會隨情境明顯波動。', '{"do": "可用於：①說明其樂觀程度與事件頻率、壓力強度高度連動②建議在關鍵階段提供資訊透明與具體進展，減少不必要的悲觀解讀③鼓勵透過記錄小成功、與他人對話來調整看事情的角度。", "dont": "禁止：①把偶爾的低落解讀為「很負面」②忽略環境與事件累積對其心態的影響③只用「想開一點」要求其振作，而不處理問題本身④把樂觀程度簡化為個人意志力強弱。"}', 'CIA', '一般情況下你還算樂觀，但如果連續遇到不順或變化太多，就會比較容易懷疑「真的會好轉嗎」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (126, 'CIA_20', 'A', 75, 100, '主動挑戰框架', '喜歡用新方法做事，會主動發現問題、提出替代解法並挑戰主流規則，不易被既有慣例限制。', '適合探索、轉型、產品/流程革新；放在發想與實驗段落發揮。', '遇到問題時自然會往新方法、新角度思考，不太滿足於「一向都這樣」，喜歡在限制中找到創新的突破口。', '{"do": "可用於：①說明其在創新專案、流程改善與新服務設計上的潛力②建議安排有空間試驗與迭代的任務，讓其創意能真正落地③鼓勵同時學會評估風險與成本，讓創新不只好玩也具可行性。", "dont": "禁止：①把其創新力當成無限「幫忙發想」的資源，而不給實驗空間②把所有守規或穩定作法都貶低為「不創新」③忽略其創意實作所需時間與支援④要求其在高度僵化環境下仍源源不絕產出新點子。"}', 'CIA', '你很少只照舊做，看到問題會想「有沒有更好的做法」，也樂於試試不同的點子。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (127, 'CIA_20', 'B', 50, 74, '改良式創新', '願意提出新點子，但多從現有流程中找改良機會；限制明確時更容易產出可落地方案。', '給清楚目標與限制條件並搭配原型驗證，提升落地率；適合改善型任務。', '在熟悉範圍內遇到問題時，偶爾會提出不同作法；但若風險較高或規則限制較多時，會傾向先確認安全做法再談創新。', '{"do": "可用於：①說明其創新傾向受情境安全感與資源影響②建議提供明確框架（哪些可試、哪些是底線），讓其較敢提出改進想法③鼓勵在小範圍試驗、A/B 測試中練習把點子變成具體行動。", "dont": "禁止：①把不主動「顛覆一切」解讀為「沒創意」②忽略文化氣氛與主管態度對其創新意願的影響③只在出問題時要求其「想點新招」④以少數不成功的嘗試否定其創新能力。"}', 'CIA', '你有靈感時也會想試試新方式，但會看場合、對象與風險，通常不會貿然大改。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (130, 'CIA_21', 'A', 75, 100, '跳脫程序求快', '高度在意更快更省更有效，不喜歡被程序綁住，會用不同角度簡化流程以達成結果。', '適合快速迭代、流程優化與降本增效；可主導改善與自動化提案。', '對提升流程效率、縮短等待與減少浪費特別敏感，會主動思考「怎樣更快、更準、更省力」。', '{"do": "可用於：①說明其在流程優化、標準化與自動化上的優勢②建議讓其參與或主導效率改善專案，將觀察轉化為具體機制③鼓勵在追求效率時，兼顧品質、人際感受與必要的思考空間。", "dont": "禁止：①把效率視為唯一價值，鼓勵其忽略人與品質②在制度與工具落後的前提下要求其獨自扛起所有改善責任③將對低效率的敏感誤解為「愛抱怨」④忽略某些議題需要「慢下來」才能做出好決定。"}', 'CIA', '你很容易注意到哪裡在浪費時間或資源，也習慣問自己「有沒有更順、更有效率的做法」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (132, 'CIA_21', 'C', 0, 49, '精準依程序', '做事偏向遵循規範與既定步驟，重視精確與條理；效率提升多透過穩定流程而非破格捷徑。', '適合高精度、合規、品質把關或需要穩定一致輸出的任務。', '對效率或流程優化的敏感度較低，只要事情能完成，就不太在意是否有更快或更省力的方式。', '{"do": "可用於：①指出其在節奏穩定、壓力較低的環境中較能自在工作②建議在需要效率的關鍵流程，提供清楚指標與具體做法，而不是只喊「要快」③鼓勵透過簡單工具（範本、捷徑）讓效率自然提升，而非完全依賴個人自覺。", "dont": "禁止：①貼上「拖延」「效率差」的道德化標籤②忽略任務複雜度、資訊混亂度對節奏的影響③期待其在沒有任何工具與教學下，自行達到高效率標準④把此分數視為無法勝任高要求工作的絕對指標。"}', 'CIA', '你比較不會主動去想「能不能再快一點、省一點」，只要事情做得完、大家能接受就可以。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (129, 'CIA_24', 'B', 50, 74, '顧自己也顧關係', '通常能維持自我一致，但在高社會壓力或權威情境會調整表達以保留合作空間。', '提供安全表達空間與明確決策流程，有助兼顧真實與合作；適合協調角色。', '重視真實與一致性，但也會考量場合、角色與關係，在誠實表達與維持和諧之間尋找平衡。', '{"do": "可用於：①說明其在真實自我與社會期待之間有彈性調整能力②建議釐清哪些情境可以更做自己、哪些需更策略表達③鼓勵其在長期壓抑時，找到安全場域說真話，減少耗損。", "dont": "禁止：①將必要的修飾一概視為「不真誠」②忽略角色責任與關係風險對其表達選擇的影響③用理想化標準要求其「永遠說真話不計代價」④以一次不完全坦白否定其整體真實性。"}', 'CIA', '你在意真誠，但也會看場合調整表達方式，有些話不一定會直接全部說白。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (135, 'CIA_22', 'B', 50, 74, '可切換模式', '在有規則時能配合，在無規則時也願意嘗試；但需要明確目標與邊界才能穩定輸出。', '給方向與原則（目的/底線/驗收）讓其在框架內自由發揮；適合跨情境角色。', '基本會遵守重要規範與流程，但在規則與現實衝突時，會評估情境與風險，尋找可行折衷，而非一味僵硬或完全忽略。', '{"do": "可用於：①說明其在「守規」與「務實」之間具有一定彈性②建議與其一起界定哪些是不能碰的底線，哪些可以討論與調整③鼓勵在遇到衝突情境時，把思考過程說出來，增加透明度與信任。", "dont": "禁止：①因為有彈性就說「不守規矩」②忽略制度矛盾、時間壓力對行為選擇的影響③只看結果是否完美符合流程，而不看其評估過程④用單一事件給出「不可靠」的定義。"}', 'CIA', '你會照規則做，但如果規則和現況真的完全對不上，也會評估狀況，找比較合理的做法。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (136, 'CIA_22', 'C', 0, 49, '規則清楚最好', '偏好依循既有且被接受的方法，規則越清楚越能發揮；面對模糊規則容易卡住或降低效率。', '適合制度化、作業明確、合規高的環境；對變更管理需更完整溝通。', '對既有規則與流程的依附度較低，面對限制時較容易想著「有沒有別的方法」，對高度制式、僵化的環境較難長期適應。', '{"do": "可用於：①指出其在需要突破僵化流程、面對未定義問題時具優勢②建議在高風險領域設立清楚界線，讓其明白哪些地方不能逾越③鼓勵其將挑戰規則的能量用在提出具體改善方案，而不是只是否定。", "dont": "禁止：①直接貼上「叛逆」「不聽話」的標籤②忽略規則本身是否合理③完全用個人意願取代制度設計的討論④在沒有說明風險的前提下，單純要求其「不要亂動流程」。"}', 'CIA', '你比較不喜歡被很多規定綁住，遇到一堆流程時，容易想「真的有必要這樣嗎」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (137, 'CIA_23', 'A', 75, 100, '原創解題者', '常能以另類觀點重新定義問題，並提出非既定路徑做法；原創想法輸出頻率高。', '適合概念發想、策略破題與需要差異化的任務；在早期探索階段發揮。', '思考與表達時常能跳脫既有框架，提出與主流不同但具啟發性的觀點或解法。', '{"do": "可用於：①說明其在策略討論、產品構想與問題定義上的創意資產②建議在早期構想階段讓其多參與發想，再搭配他人評估可行性③鼓勵在維持獨特觀點的同時，也學會用對方聽得懂的語言表達。", "dont": "禁止：①把其與眾不同的想法視為「不切實際」而直接否定②只在有問題時才臨時要其「給點創意」③忽略其在落地執行上可能需要支援④把創意等同於必須承擔所有變革責任。"}', 'CIA', '你常會想到別人沒想到的角度，看事情也不太只照慣性路線走。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (139, 'CIA_23', 'C', 0, 49, '常規解法偏好', '傾向在規範或既定程序內思考，較少自發產出原創解法；重視可行與穩定。', '適合落地、標準化、維運與品質一致性工作；創新需求可由他人提供再負責執行。', '多半偏好沿用已證實可行的作法，對太跳躍或過於另類的觀點較難產生共鳴，原創性表現相對內斂。', '{"do": "可用於：①指出其在維持穩定、落實既有最佳實務上具可靠性②建議若希望其參與創意思考，可從「現有做法的微調」入手，而不是要求大幅顛覆③鼓勵其在聽到新點子時，先詢問邏輯與目的，再決定是否採納。", "dont": "禁止：①貼上「墨守成規」「沒想像力」標籤②忽略其在風險敏感與實務可行性上的價值③強迫其接受沒有說清楚的劇烈變革④以此分數否定其在優化、標準化工作中的重要性。"}', 'CIA', '你比較傾向用已經證明可行的方式處理事情，對那種很跳躍、很新奇的想法會比較保留。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (134, 'CIA_24', 'A', 75, 100, '價值一致', '行為與自身價值觀、欲望較一致，即使面臨從眾壓力仍能維持立場與一致性表現。', '適合誠信、文化示範與長期信任角色；在價值衝突場景提供穩定判準。', '言行多半能與內在價值與真實感受保持一致，即使環境有壓力，也比較難長期違背自己真正相信的事。', '{"do": "可用於：①說明其在信任建立與角色正直上的重要性②建議安排在需要高可信度與價值導向的任務（如顧問、關係管理）③鼓勵其在價值衝突情境中尋求對話與支持，而不是一個人硬撐。", "dont": "禁止：①把其真實性當成可以要求「完全透明」的理由②忽略文化與權力現實對表達空間的限制③在其提出價值質疑時視為「不配合」④鼓勵其長期犧牲自我以換取組織穩定。"}', 'CIA', '你不太喜歡「表裡不一」，會盡量讓自己做的事、說的話跟心裡認同的價值接近。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (140, 'CIA_24', 'C', 0, 49, '易受從眾牽引', '較容易因外界期待而調整言行，內外一致性較弱；可能避免衝突而壓抑真實想法。', '適合規則清楚、壓力較低環境；管理上降低懲罰式文化並鼓勵回饋。', '在強烈外在期待或壓力下，較容易優先配合情境需要，而壓抑或暫時擱置自己的真實想法與感受。', '{"do": "可用於：①指出其可能長期處在高社會期待或關係壓力之中②建議提供安全、非評價性的對話空間，讓其練習逐步表達真實自己③鼓勵分辨「為了關係調整」與「完全犧牲自我」之間的界線。", "dont": "禁止：①直接貼上「假」「雙面」標籤②忽略權力不對等與文化壓力③要求其立刻完全做自己而不顧現實風險④將此分數視為無法信任的絕對指標。"}', 'CIA', '你有時會先選擇「先配合環境」，把自己的真實感受收起來，覺得硬說出來可能會更麻煩。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (142, 'CIA_25', 'B', 50, 74, '合作務實', '願意合作，但會視任務與回報做取捨；在公平制度下能維持良好協作。', '以清楚分工與共同目標對齊最有效；適合合作＋個人責任並存制度。', '重視團隊合作與關係，但在個人利益或發展受到明顯影響時，也會思考如何取得平衡。', '{"do": "可用於：①說明其會在團隊與個人之間做現實權衡②建議在任務分配與獎酬上說清楚彼此的得失，避免其長期感到吃虧③鼓勵其以理性表達而非壓抑來處理衝突。", "dont": "禁止：①因為提出個人需求就認定其「不顧團隊」②忽略制度設計與分配機制對其感受的影響③用道德壓力要求其無條件付出④把一次保留視為不適合團隊。"}', 'CIA', '你願意配合團隊，但如果對自己傷害太大，也會開始評估「這樣值不值得」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (143, 'CIA_25', 'C', 0, 49, '個人導向', '更重視個人目標與自主性，對集體要求投入度較低；偏好清楚個人責任與回報。', '適合個人貢獻型角色；若需合作，說明互賴關係與利益對齊。', '思考時較常以個人目標與利益為優先，對「為團隊多做一些」的動機較依賴具體回饋或明確交換。', '{"do": "可用於：①指出其在個人績效導向情境中可能動機較強，但在高度團隊導向文化中需要更多對齊與說明②建議清楚界定合作帶來的具體好處（學習、資源、評價），提升合作意願③鼓勵其在爭取自我利益的同時，也思考長期關係與名聲。", "dont": "禁止：①直接貼上「自私」「不合群」標籤②忽略其過往可能被濫用或吃虧的經驗③只用道德批評要求其「要為團隊著想」④把此分數視為無法參與任何團隊工作的證明。"}', 'CIA', '你會先想「對自己有沒有幫助」，對那種需要多付出但看不太到回報的團隊要求，比較少熱情。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (144, 'CIA_26', 'A', 75, 100, '能進入他人框架', '能以他人的參考架構理解其處境與感受，互動時會調整語氣與回應方式以貼近對方需要。', '適合客戶溝通、帶人管理、衝突調解與需要情緒敏感度的角色。', '容易從他人立場出發理解對方的感受與處境，能聽出話語背後的情緒與需求，並給出相對貼近的回應。', '{"do": "可用於：①說明其在輔導、溝通協調與客戶關係中的價值②建議在衝突情境中善用其橋樑角色，協助彼此被理解③鼓勵其建立自我界線與自我照顧，避免長期承擔過多情緒負荷。", "dont": "禁止：①把其同理心當成情緒垃圾桶，凡事都請他吸收②忽略其自身的情緒需求③在制度不公時只要求其「多體諒」④將其情緒耗竭視為「不專業」。"}', 'CIA', '你常會不自覺地想到「如果我是他，會怎麼感受」，對別人的情緒變化也蠻敏感。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (146, 'CIA_26', 'C', 0, 49, '線索較少', '不容易捕捉他人情緒或隱含需求，互動多以事情推進為主，可能無意中造成距離感。', '適合互動需求較低角色；在服務/帶人場景建議搭配溝通訓練與回饋機制。', '自然注意力較多放在自己當下的任務、感受與想法上，不太會自發地揣摩他人心情，需要比較明確的訊號才容易察覺。', '{"do": "可用於：①指出其在專注任務上的優勢，同時在人際情境需刻意練習「多看一眼、多問一句」②建議提供清楚的人際線索與反饋，幫助其理解互動影響③鼓勵其把「想問清楚」當作一種尊重，而不是多此一舉。", "dont": "禁止：①直接貼上「冷漠」「沒感覺」標籤②忽略其成長背景與文化對表達情感方式的影響③在沒說明期待的情況下責怪其「不懂人情世故」④以此分數判定其不適合任何關係導向工作。"}', 'CIA', '你比較容易專注在自己眼前要處理的事，不一定會立刻意識到別人其實已經不太舒服或在意。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (147, 'CIA_27', 'A', 75, 100, '共益付出', '在合作中更重視整體成果與長期互惠，願意先付出、讓利或承擔額外責任，以促成共同完成目標。', '適合共創與跨部門協作、短期回報不明但長期價值高的任務；可放在需要先扛先推的角色位置。', '對他人與團隊相當願意投入時間與心力，即便不一定有立即回報，也樂於主動幫忙與支援。', '{"do": "可用於：①說明其在團隊合作、支援同事與承接額外任務上的高度意願②建議在重要專案或關鍵時刻善用其願意多走一里路的特質③鼓勵組織在接受其付出的同時，給予合理感謝與資源，避免長期過勞或被視為理所當然。", "dont": "禁止：①把其願意付出當成無限制增加工作量的理由②忽略其也有疲累與界線，只期待「有事找他就對了」③用道德壓力強調「你那麼願意幫忙就再多撐一點」④在制度設計上假設有人會永遠自願補洞，不處理結構問題。"}', 'CIA', '你常會先問「我能幫上什麼忙」，不一定要有明確回報才願意多付出一些。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (148, 'CIA_27', 'B', 50, 74, '互惠平衡', '願意付出，但也會留意互惠是否合理；當看到對方回應與制度公平時，投入度與合作意願會提升。', '以透明分工、可見回饋與資源對齊穩定投入；適合制度清楚的團隊協作。', '願意在合理範圍內為他人與團隊付出，但會衡量情境與自身狀態，選擇在合適的時候伸出援手。', '{"do": "可用於：①說明其付出傾向會隨工作量、公平感與關係重要性而調整②建議與其清楚談期待與分工，讓付出與回報相對平衡③鼓勵其在自己願意幫忙的前提下，也能適時說明目前的負荷狀況，避免內心累積壓力。", "dont": "禁止：①因為不「每次都答應」就貼上「不願付出」的標籤②忽略其實在多數情況下仍願意支援他人③只在忙碌時臨時請求幫忙，卻沒有長期在制度上照顧④用比較的方式指責「別人都願意，你怎麼不行」。"}', 'CIA', '你會幫忙，也願意多做一點，但會看狀況和自己最近的負荷，不會每件事都一肩扛起。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (150, 'CIA_28', 'A', 75, 100, '經常表達感激', '容易看見他人付出並主動表達感謝，強化互惠與人際正向循環。', '適合文化建立、團隊氛圍與客戶關係經營；可作為正向回饋示範者。', '對他人的幫助與資源供給比較容易感到感激，會主動表達謝意並記得他人的好。', '{"do": "可用於：①說明其在建立互信與正向互動氛圍上的貢獻②建議讓其在團隊中成為正向回饋與感謝文化的帶動者③鼓勵其在表達感謝時也具體說明「哪裡幫助到自己」，增加互動品質。", "dont": "禁止：①把其願意感謝視為理所當然、反而加重負擔②以「你應該更感恩」來壓抑其合理不滿③忽略制度與實質待遇問題，只期待情緒上的感恩④把感恩當成避免改變的不成文要求。"}', 'CIA', '別人對你好的地方，你通常會放在心上，也不吝於說聲謝謝或回應對方。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (151, 'CIA_28', 'C', 0, 49, '較少注意感謝', '較不容易察覺或表達感謝，互動多聚焦在任務完成；可能忽略他人投入的情感需求。', '可加入回饋儀式與互相肯定機制；適合任務導向角色但需補足情感回饋。', '對他人提供的協助或制度支援較少產生明顯的感激情緒，可能更傾向視為「應該的」或互利交換的一部分。', '{"do": "可用於：①指出其在強調權責與交換的互動中較感自在，但在關係經營上可能少了些溫度②建議透過具體例子協助其理解感謝對關係的正向影響③鼓勵其在重要時刻試著用簡短話語表達肯定，不需誇張也能拉近距離。", "dont": "禁止：①直接貼上「忘恩負義」標籤②忽略其價值觀中對「互惠、權責分明」的重視③用羞辱方式強迫其表達感謝④將此分數視為無法建立良好人際的必然結果。"}', 'CIA', '你比較少特別去想「要感謝誰」，會覺得很多事本來就是互相、或制度本來就該提供。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (152, 'CIA_29', 'A', 75, 100, '能與各型人合作', '能適應不同性格與風格的人，懂得管理互動張力並建立互利的合作關係。', '適合跨部門、客戶多元與橋接衝突角色（PM、顧問、BD、HR）。', '在人際互動中能快速調整說話方式與互動風格，面對不同性格與背景的人，都有機會建立合作或信任關係。', '{"do": "可用於：①說明其在跨部門協作、客戶應對與關係經營上的靈活度②建議安排在需要橋接多方利害關係人的角色③鼓勵在調整自己迎合他人時，也要留意不過度消耗自我。", "dont": "禁止：①把其適應力誤解為「沒有立場」「到處討好」②忽略其在人際壓力下的疲憊感③期待其一手處理所有人際問題，而不調整制度④將偶發的誤判視為長期失職。"}', 'CIA', '你蠻會看場合、看對象調整自己的溝通方式，跟各種類型的人相處都比較容易找到頻率。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (154, 'CIA_29', 'C', 0, 49, '互動張力較高', '面對不同類型的人容易緊繃或不知拿捏，互動策略較固定，合作建立成本較高。', '適合互動規則清楚環境；可用情境腳本、角色演練與回饋提升。', '在人際情境中的調整彈性相對有限，面對不同風格與期待的對象時，較容易感到尷尬、不知如何應對或乾脆選擇少互動。', '{"do": "可用於：①指出其在人際多樣性高的環境中可能需要較多支持與指引②建議提供具體對話範例、情境演練或觀摩機會，讓其建立安全感③鼓勵其從少數關係開始練習，而不是要求自己對每個人都能自在自如。", "dont": "禁止：①貼上「不會做人」「EQ 低」標籤②忽略其內向、焦慮或過去人際經驗帶來的影響③在未提供任何訓練或支持下，要求其立刻處理複雜關係④以此分數否定其在專業或技術面上的價值。"}', 'CIA', '你可能常覺得「要看人說話」很累，遇到跟自己差很多的人，也會比較不確定怎麼相處才好。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (156, 'CIA_30', 'B', 50, 74, '責任隨界線而定', '在責任範圍清楚時能承擔並完成；若分工模糊或權責不對等，承擔度會受影響。', '先定義權責、交付標準與升級機制；適合制度清楚的專案體系。', '在合理範圍內會承認自己該負的責任；但當情境明顯不合理或自己影響力有限時，也會指出外在因素的影響。', '{"do": "可用於：①說明其對責任的看法較貼近現實，能區分個人與系統因素②建議在檢討時，同時討論可控部分與制度層面調整③鼓勵其維持這種「不推責也不全扛」的健康平衡。", "dont": "禁止：①把其提到環境因素解讀為「在找藉口」②忽略實際權限與資源限制③只要求「要負責任」而不談如何賦權④用單一事件評價其是否具責任感。"}', 'CIA', '該負的你會認，但如果很多事情明顯超出自己能控制的範圍，你也會說明不是全都在你身上。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (158, 'CIA_31', 'A', 75, 100, '主動自我升級', '會主動尋找成長機會，願意參與改變、學新方法並發展自我，不需要外部推動也會持續進步。', '適合高成長路徑、輪調與培訓、創新任務；給探索資源與更大挑戰。', '對自我成長與能力提升有明確主動性，會自己找資源、設定學習目標並安排行動，而不只是等公司安排訓練。', '{"do": "可用於：①說明其在學習敏捷與自我發展上的優勢②建議提供更具挑戰性的發展機會與清楚的職涯路徑③鼓勵其在追求成長時，也平衡休息與當下生活品質。", "dont": "禁止：①把其成長動機視為理所當然，不給資源只給期待②忽略學習需要時間，仍塞滿日常工作③以「你那麼愛學」為由，把所有新任務都丟給他④把發展責任完全推給個人。"}', 'CIA', '你常會主動找課、找資料，思考「接下來可以學什麼」，不太只等別人來安排。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (159, 'CIA_31', 'C', 0, 49, '維持現狀取向', '較少主動追求自我改變，傾向用既有能力完成任務；成長渴望不高或動機不明確。', '適合技能穩定、流程固定角色；若期待提升，先連結其關心利益點與小步目標。', '目前對主動追求自我成長的內在驅動較弱，多半以完成當前工作要求為主，對額外學習較缺乏明確動機。', '{"do": "可用於：①指出其可能處在高壓或疲累階段，較難額外挪出資源給成長②建議從與現職高度相關、負擔較小的學習機會開始，逐步建立成就感③鼓勵透過職涯對談探索「為什麼要學」而不只是「要學什麼」。", "dont": "禁止：①貼上「不上進」標籤②忽略其現實壓力與資源限制③用比較與羞辱方式要求其「要有企圖心」④把此分數視為不能培養的定論。"}', 'CIA', '你現在可能比較偏向「先把眼前工作做好」，對另外再花時間學新東西，會覺得動機沒那麼強。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (160, 'CIA_32', 'A', 75, 100, '高特權感', '較容易認為自己應得到特殊待遇且不一定以努力或績效為前提；期待落空可能強烈不滿或對抗。', '清楚制度邊界、權限與後果，避免模糊承諾；在治理與文化面需更嚴格管理。', '對自己應享有特別待遇、資源或彈性的期待較高，若感到未被特別對待，容易出現強烈不滿或被低估的感覺。', '{"do": "可用於：①指出其在自我價值與外在對待之間連結緊密，容易因差距產生情緒②建議透過清楚標準、數據與實際貢獻來對齊期待③鼓勵其將部分精力放在提升影響力與成果，而不只聚焦在待遇比較上。", "dont": "禁止：①直接貼上「公主病」「王子病」標籤②只用道德批評壓抑其不滿③在未討論事實與數據前否定其感受④把此分數當成其必然難以合作的定論。"}', 'CIA', '你可能常會覺得「以我的條件應該要更好待遇」，如果覺得沒有被這樣對待，就會很不甘心。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (162, 'CIA_32', 'C', 0, 49, '低特權感', '較少認為自己應獲特殊待遇，對資源分配與規則較能接受，以實際貢獻而非身份要求回報。', '適合共享資源與合作情境；較能接受公平制度與透明流程。', '對「自己應被特別對待」的期待相對較低，比較能接受與他人在相近標準下被評估與對待。', '{"do": "可用於：①說明其在團隊中較少因特權議題造成摩擦②建議在獎酬與機會分配上，仍清楚說明其貢獻，以避免被低估③鼓勵其在明顯不合理待遇時勇於表達，而不是全部吞下。", "dont": "禁止：①因其不要求特權就忽略或壓低其應得回報②把其低特權期待當成可以任意加工作量的理由③鼓勵其「多委屈一點」以維持表面和諧④將不爭取視為理所當然。"}', 'CIA', '你不太會覺得自己一定要被特別優待，反而比較能接受跟大家差不多的標準。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (164, 'CIA_33', 'B', 50, 74, '形象真實混合', '多數時回應真實，但在敏感題或想留下好印象時可能偏理想化回答，呈現部分防衛。', '用情境題、行為例證追問與無評價訪談氛圍提高資訊準確度。', '作答時會在真實與形象之間拿捏，多數情況仍偏向說真話，但在少部分問題上可能略為修飾。', '{"do": "可用於：①說明其整體資料仍具參考價值，但需理解少部分題目可能受形象考量影響②建議在回饋時，同步邀請其分享對測驗的感受，增加開放度③鼓勵其把測驗視為自我了解工具，而不是面試考卷。", "dont": "禁止：①因為略有形象考量就說「在騙人」②忽略測驗情境（如是否與錄用掛鉤）③只從社會期望指標單點推論其誠實程度④在回饋時用指責口吻談此結果。"}', 'CIA', '你大部分會照實回答，但有些題目可能會稍微想一下「這樣寫會不會比較好」。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (166, 'CIA_34', 'A', 75, 100, '投入感強', '對工作本身有明顯熱情與投入，願意多付出以追求成果與成長，工作能量較充足。', '適合需要自我驅動、主動推進與帶動氛圍職務；給挑戰題與舞台。', '對工作本身具有高度熱情與投入感，常願意花時間精進、思考與主動承擔與工作相關的挑戰。', '{"do": "可用於：①說明其在工作動機與投入度上的優勢，適合作為關鍵任務推動者②建議提供與其熱情方向一致的專案與成長機會③提醒在高度投入下，亦需留意過勞與界線，避免工作熱忱轉為耗竭。", "dont": "禁止：①把其熱情當成無上限加班的理由②忽略其在挫折時同樣需要支持③以「反正你喜歡」合理化不合理工作量④把工作熱忱視為可以犧牲其他生活面向的藉口。"}', 'CIA', '你對自己的工作多半是有感覺的，會想把它做好、做深，也願意多花一些心力在上面。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (167, 'CIA_34', 'B', 50, 74, '熱度受情境影響', '在任務有意義、回饋可見或氛圍好時熱忱提高；反之容易變成只是完成工作。', '以目標意義連結、可見成就與支持系統維持熱度；適合穩健推進配置。', '若工作內容具意義感、挑戰性或與興趣契合時，會願意投入較多心力；若過於例行或看不到價值，熱情就會下滑。', '{"do": "可用於：①說明其工作熱忱與工作設計、意義感高度連動②建議在可能範圍內調整任務組合，增加與其興趣與強項連結③鼓勵其在低熱情時思考可以創造什麼新價值，而不是只悶著做。", "dont": "禁止：①把低熱情全歸因於個人態度②忽略職務內容長期單調或缺乏自主性的影響③只用「要有使命感」要求其打起精神④在未調整結構前批評其投入不足。"}', 'CIA', '遇到有意思、有挑戰的工作，你會很有動力；但如果內容很制式、看不到意義，就比較容易只把它當成一份工作。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (169, 'CIA_35', 'A', 75, 100, '活力充沛', '在日常工作與生活中多以積極、充滿熱情與活力方式行事，對未來抱持期待與動能。', '適合帶動氛圍、對外互動與高節奏推進任務；可作為正向能量來源。', '日常行事風格多半充滿活力與期待感，願意主動探索新體驗，並將熱情帶入生活與工作中。', '{"do": "可用於：①說明其在團隊氣氛與活動帶動方面的正向影響②建議讓其在需要活絡氣氛、鼓舞士氣的場合發揮所長③提醒在照亮他人的同時，也要照顧自己的休息與情緒需求。", "dont": "禁止：①把其熱情視為理所當然的「氣氛製造機」②忽略其也會有低潮的時候③在其需要安靜或暫時退後時批評「怎麼變了」④只看外顯活力而忽略內在壓力。"}', 'CIA', '你多半是那種會主動揪活動、安排有趣事情的人，生活節奏比較有動能。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (170, 'CIA_35', 'B', 50, 74, '能量隨情境起伏', '平時有一定活力，但在壓力、睡眠不足或連續挫折時動能會下降；恢復後可回穩。', '提供節奏管理、適度休息與可見成果，有助維持動能。', '在心情不錯或有感興趣的事情時，會展現活力與參與感；但在疲累或壓力較大時，會明顯收斂熱情。', '{"do": "可用於：①說明其生活熱情與身心狀態高度連動②建議透過合理工時與休息安排，維持其能量水位③鼓勵其接受自己熱情有起伏是正常的，不必勉強一直「很 high」。", "dont": "禁止：①在其低潮時貼上「變冷淡」標籤②忽略組織節奏與壓力對其能量的消耗③只在需要活絡氣氛時才想到找他④用單次狀態判斷其個性。"}', 'CIA', '如果最近狀態好，你會很願意參與各種活動；但一累或煩的時候，就會比較安靜、保留。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (171, 'CIA_35', 'C', 0, 49, '動能偏低', '較少以熱情與活力驅動行動，對未來期待感薄弱時容易被動或拖延，需要更多外部刺激才啟動。', '從小步可達成目標建立動能，搭配支持與節奏安排；避免長期高壓無回饋。', '在日常生活中較少展現外顯的熱情或興奮感，行事節奏偏穩、偏內斂，對活動與變化的主動性相對有限。', '{"do": "可用於：①指出其在穩定、需要長期堅持的任務中可能更為合適②建議不要強迫其扮演外向帶動角色，而是尊重其節奏與風格③鼓勵其在自己覺得安全與舒適的範圍內，嘗試少量新體驗。", "dont": "禁止：①貼上「沒活力」「很冷漠」的簡化標籤②忽略其內在可能有屬於自己的熱情只是不外顯③用外向標準扣分其表現④在團隊中排除較安靜成員的重要性。"}', 'CIA', '你比較習慣過穩穩的節奏，不一定會對很多新活動感到特別興奮，也不太會主動當氣氛帶動者。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (172, 'CIA_36', 'A', 75, 100, '容易被點燃', '對挫折、否定、壓力或不公平刺激反應門檻低，情緒升溫快，可能出現語氣變衝、衝動回應或當場對抗。', '需設計降刺激工作方式：明確溝通規範、冷卻流程、衝突場景第三方介入；高衝突前線配置需更謹慎。', '情緒對外在刺激相當敏感，遇到不順或被觸怒的情況時，反應容易快速且強烈，需要更多自我調節與環境支持。', '{"do": "可用於：①說明其情緒反應速度快、強度高，需在壓力管理與情緒調節上給予具體工具與協助②建議在重要溝通或衝突場合，預留冷卻時間與中立第三方，降低當下失控風險③鼓勵其練習暫停、換位思考或離開現場等方法，幫助自己先穩住情緒再做決定。", "dont": "禁止：①直接貼上「暴躁」「情緒化」的標籤②忽略長期壓力、工作環境或過往經驗對其情緒狀態的影響③用羞辱或嘲諷的方式要求其「冷靜一點」④只看爆發當下的畫面而完全不檢視前期累積的壓力來源。"}', 'CIA', '你很容易因為一件事立刻覺得不爽、生氣或緊張，要壓住不表現出來對你來說是需要用力的。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (173, 'CIA_36', 'B', 50, 74, '可控但會被觸發', '平常多可維持穩定，但遇到特定觸發點（被誤解、時間壓力、連續失敗）時反應會上升；事後多能回穩並修正。', '辨識觸發點並建立停損機制（暫停、書面回覆、換人處理），再用復盤降低再發。', '多數情況下能保持基本穩定，但在壓力累積、被反覆踩到地雷或身心狀態不佳時，情緒起伏會明顯放大。', '{"do": "可用於：①說明其情緒穩定度與壓力總量、睡眠與支持系統高度相關②建議與其一起找出個人的「情緒警訊」與舒壓方式，在快到臨界點前就先調整③鼓勵其在覺得快受不了時，提前提出需求，而不是一路硬撐到爆發。", "dont": "禁止：①只在情緒失控時檢討其個人，而不處理制度或人際問題②忽略工作負荷、時間壓力與資源不足的影響③用「你怎麼這麼誇張」否定其累積已久的感受④把一次情緒爆發當成永久標記，忽略其多數時間的穩定表現。"}', 'CIA', '平常你還撐得住，但如果同樣的事一再發生、又剛好很累或很煩，就會比較容易一次反應比較大。', NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (174, 'CIA_36', 'C', 0, 49, '情緒穩定', '情緒反應門檻較高，遇到煩惱或衝突多能保持冷靜與理性處理，較少因一時情緒做出高代價決定。', '適合高壓、客訴、談判與需要穩定輸出的工作；可作為衝突情境的穩定支點。', '在面對壓力、衝突或突發狀況時，多半能維持相對平穩的情緒，不容易因單一事件立刻被點燃或失控。', '{"do": "可用於：①說明其在高壓情境與危機處理場合中具備情緒穩定優勢②建議在團隊容易緊張或慌亂時，讓其協助穩住節奏與理性討論③鼓勵其在維持冷靜的同時，也適度表達自己的不滿與界線，避免長期只扮演「穩定器」。", "dont": "禁止：①因其外表冷靜就忽略其實際壓力與情緒累積②把其穩定視為可以承接所有負面情緒的理由③在其偶爾情緒外露時，以「你平常不是很穩嗎」否定其感受④把高穩定度誤解為完全不需要情緒支持。"}', 'CIA', '遇到惹人不快的事，你雖然會有感覺，但比較少一瞬間就情緒爆掉，通常還能先穩住自己再看怎麼處理。', NULL, NULL, NULL);
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2, 'CIA_01', 'A', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「魯莽的勤奮者」。雖有極強執行力但行動前缺乏思考，易努力執行錯誤決策，需加強前置覆核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3, 'CIA_01', 'A', 'CIA_04', 'A', '與 CIA_04 (義務感) 高分聯動：典型的「組織基石」。對規範高度尊重且極度自律，是非常可靠的合規型人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4, 'CIA_01', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) 低分聯動：表現為「焦慮補償者」。雖渴望做好但易受情緒干擾，壞事後會花加倍力氣彌補，效率波動較大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (5, 'CIA_01', 'A', 'CIA_06', 'A', '與 CIA_06 (條理性) 高分聯動：卓越的流程管理者。能將複雜工作系統化，產出極其穩定且精確。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (6, 'CIA_01', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) 高分聯動：品質的絕對守門員。標準極高，但需警惕因過度鑽研細節導致進度延宕或造成團隊壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (7, 'CIA_01', 'A', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) 低分聯動：表現為「自省型執行者」。雖然表現優異但對自己缺乏信心，易產生職業燃盡，需主管頻繁給予正向回饋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (8, 'CIA_01', 'A', 'CIA_09', 'A', '與 CIA_09 (自律性) 高分聯動：長期目標的長跑者。具備極強的抗誘惑能力與延遲滿足感，能自主完成長期艱難任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (9, 'CIA_01', 'A', 'CIA_11', 'C', '與 CIA_11 (誠懇) 低分聯動：表現為「權謀執行者」。極度自律但可能具備操縱傾向，需注意其工作產出背後的動機與誠信風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (11, 'CIA_01', 'A', 'CIA_13', 'A', '與 CIA_13 (公正性) 高分聯動：組織的倫理標竿。做事盡責且絕不作弊，適合擔任稽核、財務或高誠信要求的崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (12, 'CIA_01', 'A', 'CIA_14', 'C', '與 CIA_14 (謙虛) 低分聯動：表現為「傲慢的優等生」。因自身高標準而自覺高人一等，易在團隊中製造階級感並忽視他人意見。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (13, 'CIA_01', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) 低分聯動：表現為「脆弱的完美者」。這是關鍵預警項，一旦失敗會因無法忍受瑕疵而崩潰，難以從挫折中恢復。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (14, 'CIA_01', 'A', 'CIA_19', 'C', '與 CIA_19 (樂觀) 低分聯動：表現為「憂患意識者」。凡事滴水不漏但缺乏活力，總在防範最壞情況，雖可信賴但會帶給團隊沉重氛圍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (15, 'CIA_01', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) 高分聯動：表現為「實踐型天才」。能將創新點子轉化為具體的 SOP 與執行計畫，是推動體制內變革的核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (16, 'CIA_01', 'A', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) 高分聯動：傳統規則的捍衛者。在既定架構內表現極佳，但在無規則或模糊情境下會感到極度焦慮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (17, 'CIA_01', 'A', 'CIA_25', 'C', '與 CIA_25 (集體意識) 低分聯動：表現為「孤傲型強人」。個人產出強但無視團隊節奏，對不認同的團體活動展現消極。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (18, 'CIA_01', 'A', 'CIA_26', 'C', '與 CIA_26 (同理心) 低分聯動：表現為「冷酷執行者」。只看目標不看人情，適合推行硬性政策，但長期可能造成組織氣氛僵化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (19, 'CIA_01', 'A', 'CIA_27', 'A', '與 CIA_27 (權益公平感) 高分聯動：精確的對等者。對付出與回報的比例極度敏感，若感到不公，其「盡責」程度會迅速下降。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (20, 'CIA_01', 'A', 'CIA_30', 'A', '與 CIA_30 (個人責任感) 高分聯動：卓越的自主管理者。不需要外界監督也能達成高標，管理上應給予充分授權而非微觀管理。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (21, 'CIA_01', 'A', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) 高分聯動：自我進步型人才。不僅把事做好，還渴望優化自身能力，是組織極具價值的儲備幹部。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (22, 'CIA_01', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) 高分聯動：表現為「精英心態者」。認為自己的高績效應換取特殊的優先待遇，若未獲特權會產生不平。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (23, 'CIA_01', 'A', 'CIA_34', 'C', '與 CIA_34 (工作熱忱) 低分聯動：表現為「機器人型執行」。雖依循規範完成任務，但內心缺乏熱情，僅視工作為義務，長期發展動力有限。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (24, 'CIA_01', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) 高分聯動：表現為「暴躁的工頭」。對工作要求轉化為對人的怒氣，當他人未達標時會產生強烈情緒反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (25, 'CIA_02', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「高效能明星」。具備極強的成功欲望與自我要求，是組織績效的穩定貢獻者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (26, 'CIA_02', 'A', 'CIA_03', 'C', '與 CIA_03 (審慎) C聯動：表現為「冒進的擴張者」。渴望快速達成目標但行動前缺乏深思，易忽略潛在風險，需加強風險控管提示。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (27, 'CIA_02', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「情緒化衝刺者」。雖極想贏但易受當下情緒干擾，表現起伏大，需建立標準作業程序以穩定產出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (28, 'CIA_02', 'A', 'CIA_06', 'C', '與 CIA_06 (條理性) C聯動：表現為「混亂的衝鋒者」。專注於大目標但細節混亂，雖有產出但常伴隨行政錯誤，需行政資源輔助。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (29, 'CIA_02', 'A', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「利益導向者」。成功至上且可能不惜犧牲倫理，需注意其達成目標的手段是否符合合規要求。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (30, 'CIA_02', 'A', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) C聯動：表現為「高度物質動機」。對金錢與地位有強烈需求。若獎酬機制不具競爭力，此類員工離職風險極高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (31, 'CIA_02', 'A', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「炫耀型成功者」。達成目標後傾向於彰顯功勞，易在團隊中造成他人心理壓力，需引導其分享成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (32, 'CIA_02', 'A', 'CIA_17', 'A', '與 CIA_17 (目標效能感) A聯動：表現為「自信的開拓者」。不僅想贏且相信自己能贏，面對挑戰不退縮，是組織攻堅時的首選先鋒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (33, 'CIA_02', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「脆弱的攀登者」。極度渴望成功但心理緩衝空間小，一旦專案失敗易陷入長期低潮，需主管即時介入輔導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (34, 'CIA_02', 'A', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「焦慮的追求者」。雖然努力達成目標，但內心總預見壞結果，工作動能雖強但情緒緊繃感極重。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (35, 'CIA_02', 'A', 'CIA_23', 'A', '與 CIA_23 (獨創性) A聯動：表現為「創新實踐者」。會不斷尋找更聰明的方法來達成業績，不滿足於現狀，是推動流程變革的核心人物。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (36, 'CIA_02', 'A', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「計較回報的戰士」。對付出與獲得的公平性極度敏感，若獎勵未達其預期，會迅速轉向消極反抗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (39, 'CIA_02', 'A', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「全心投入者」。工作本身即是快樂來源，具備極強的長期戰鬥力與忠誠度，是組織文化的核心支柱。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (40, 'CIA_03', 'A', 'CIA_01', 'C', '與 CIA_01 (盡責) C聯動：表現為「想得多做得少」。雖能洞察風險但執行力不足，容易陷入「過度分析而無行動」的狀態，需搭配強力的執行窗口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (41, 'CIA_03', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「精確的戰略家」。追求成功的同時具備高度理性，能規劃出具備高可行性的路徑，是高品質決策的核心人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (42, 'CIA_03', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「理性的內耗者」。雖然腦中知道該審慎思考，但行為上易受衝動誘惑而破功，事後常感到後悔，心理壓力較大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (43, 'CIA_03', 'A', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「決策癱瘓者」。因過度考慮風險且對自己能力缺乏信心，在需要快速反應時會因焦慮而無法做決定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (44, 'CIA_03', 'A', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「深沉的操縱者」。行動極其謹慎且具備隱藏真實動機的傾向，在職場政治中較難被看透，需留意其長期誠信表現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (45, 'CIA_03', 'A', 'CIA_15', 'C', '與 CIA_15 (心理資本) C聯動：表現為「悲觀的風險控管者」。審慎變成了對挫折的防備而非策略規劃，容易因過度看重困難點而失去前進動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (46, 'CIA_03', 'A', 'CIA_19', 'A', '與 CIA_19 (樂觀) A聯動：表現為「務實的開拓者」。對未來抱持正向期待，同時具備風險避開能力。能產出既具企圖心又經得起推敲的提案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (47, 'CIA_03', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「有紀律的創新者」。不會為了不同而不同，而是能在深思熟慮後，挑戰無效規則並提出具邏輯支撐的創新方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (48, 'CIA_03', 'A', 'CIA_21', 'C', '與 CIA_21 (效率取向) C聯動：表現為「緩慢的完美主義」。極度重視邏輯嚴謹但忽視時間效率，在講求快速變動的環境中適應力較低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (49, 'CIA_03', 'A', 'CIA_24', 'A', '與 CIA_24 (真實性) A聯動：表現為「誠信的觀察家」。不僅言行一致，且在表達觀點前會經過精密考量，其給出的建議通常具備高度參考價值。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (50, 'CIA_03', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「貼心的協調者」。在人際往來中思慮周全，能顧及他人感受且說話不魯莽，適合處理複雜的人事糾紛。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (51, 'CIA_03', 'A', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「完美的防禦者」。因高度負責且凡事三思，適合處理合規、法務、審計等絕對不能出錯的高風險任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (52, 'CIA_03', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「精明的索求者」。會精密計算如何透過特殊待遇獲取最大利益，並小心保護自己的特權，需注意其與團隊利益的衝突。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (53, 'CIA_03', 'A', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「精確的人設師」。為了獲得認可會非常謹慎地篩選答案或行為，其真實特質可能被良好的社交偽裝覆蓋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (54, 'CIA_03', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「冷靜的引信」。雖易被激怒，但因具備高度審慎，會刻意壓抑或精確計算反擊時機，展現出具攻擊性的嚴謹。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (55, 'CIA_04', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「極致的守法者」。將規範視為個人信仰，執行任務不打折扣。管理警示：容易對不守規矩的同事產生強烈偏見，導致團隊氣氛緊繃。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (56, 'CIA_04', 'A', 'CIA_02', 'C', '與 CIA_02 (成就動機) C聯動：表現為「安分的執行員」。極度負責且聽話，但缺乏向上突破的動力。管理預測：適合擔任穩定崗位，但不宜放在需要「不計代價達成業績」的開拓職位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (57, 'CIA_04', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「深思熟慮的守護者」。在執行規範前會思考其合理性與影響，能為組織提供具建設性的法律或合規建議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (58, 'CIA_04', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「自責的失控者」。內心極度想遵循規範，但行為常受衝動驅使而違規。心理風險：事後會產生巨大的罪惡感與焦慮，長期易導致自尊受損。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (59, 'CIA_04', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「教條主義者」。不僅要遵守規則，更要追求流程的完美無瑕。警示：容易在繁文縟節中迷失，造成行政效率低下，甚至阻礙緊急決策。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (60, 'CIA_04', 'A', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「形式主義的利己者」。外在極力表現出合規的樣子，實則內在缺乏誠信，僅是為了避免受罰而守規，需防範隱蔽性舞弊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (61, 'CIA_04', 'A', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「正義使者」。對職場不公平現象極度敏感，會為了維護正義而舉報或反抗，是組織清廉的指標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (62, 'CIA_04', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「易碎的樑柱」。承擔過多責任卻缺乏抗壓彈性，一旦組織規則劇烈變動或面臨衝突，容易出現情緒崩潰或迅速離職。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (63, 'CIA_04', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「建設性變革者」。遵循更高層級的「良知」而非「死板規定」。會為了優化組織而勇敢提出挑戰舊規的創新方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (64, 'CIA_04', 'A', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) A聯動：表現為「傳統捍衛者」。絕對服從現有體系，缺乏應變彈性。在轉型期可能成為組織阻力，因為他們認為挑戰規則是不忠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (65, 'CIA_04', 'A', 'CIA_24', 'A', '與 CIA_24 (真實性) A聯動：表現為「言行合一的楷模」。行為高度契合價值觀。管理預測：極具誠信魅力，適合擔任組織文化傳播者或內部導師。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (66, 'CIA_04', 'A', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「重視承諾的夥伴」。對「勞資契約」有神聖感。警示：一旦感受到付出回報不對等，會認為組織「不講信義」而徹底心碎並轉身離開。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (67, 'CIA_04', 'A', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「自主責責任者」。不僅守規矩，還會主動承擔任務。預測：是最不需要監督的員工，給予明確目標後即可高度放心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (68, 'CIA_04', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「傲慢的苦難者」。一邊為了組織義務辛苦付出，一邊覺得自己理應獲得特殊優待，容易在背後抱怨他人偷懶而自己受苦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (70, 'CIA_04', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「效率至上的冷酷者」。雖然做事有紀律能達成目標，但缺乏道德感或對規範的尊重，容易為了達成任務而遊走灰色地帶。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (72, 'CIA_05', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「冷靜的狩獵者」。能為了最終成就而忍受長期的枯燥與誘惑。管理建議：適合擔任需要高度專注力且具備延遲滿足特性的高階開拓職位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (73, 'CIA_05', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「極致的理性派」。行動前深思熟慮且行為受控，絕不輕率表態。警示：在需要「快速試錯」的環境中可能顯得過於保守或反應遲鈍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (74, 'CIA_05', 'A', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「高階操縱者」。行為高度受控但動機不純，能冷靜且有計畫地為了目標欺騙或操縱他人，是組織中最高層級的誠信風險，需加強合規監督。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (75, 'CIA_05', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「靜默的受難者」。雖然能管住行為不爆發，但內心缺乏緩衝能力。管理風險：容易將壓力內化導致身心崩潰或突然「無預警離職」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (76, 'CIA_05', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「高度修養的壓力鍋」。極易被激怒但能展現極強的職業素養予以壓制。警示：外表冷靜但內心消耗巨大，需適度給予情緒宣洩空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (77, 'CIA_05', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「焦慮的追求者」。內心極想做好（盡責）但行為卻常失控違規。行為預測：工作成果起伏巨大，常在「失誤」與「拼命補救」之間循環。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (78, 'CIA_05', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「挫敗的完美主義」。雖對品質有極高要求，但因行為魯莽常在細節出錯。管理建議：容易因自己的失誤而陷入極大的自我責備，需他人協助檢查細節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (79, 'CIA_05', 'C', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「投機冒險者」。不僅管不住衝動，且缺乏誠信底線，極易為了短期利益而觸犯規則或法律，需嚴格限制其權限。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (80, 'CIA_05', 'C', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「失控的發明家」。點子多且行動極快，但常在未經測試前就推翻現有流程。管理警示：適合發想階段，但不宜讓其主導專案落地。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (81, 'CIA_05', 'C', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「情緒敏感的協調者」。雖能感同身受，但易因一時激動而做出過度的情感承諾。預測：容易在職場衝突中因一時同情而壞了規矩。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (82, 'CIA_05', 'C', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「社交變色龍（負面型）」。雖能適應人際關係，但常因衝動說錯話或表錯態，導致原本建立的關係迅速崩塌。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (83, 'CIA_05', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「職場地雷」。認為自己應得特權且管不住脾氣，一旦環境不如其意便會立刻爆發。管理警示：對團隊士氣殺傷力極大，需建立明確的行為底線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (84, 'CIA_05', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「人設崩塌者」。極度渴望獲得認可但卻管不住負面衝動，常在失控後花極大心力進行公關式彌補。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (85, 'CIA_05', 'C', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「三分鐘熱度者」。熱情時極其投入，但一旦遇到挫折或新誘惑，興趣會迅速轉移，長期穩定性存疑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (86, 'CIA_05', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「典型的火藥桶」。極易生氣且會立刻表現於行為。預測：頻繁引發人際衝突，不適合團隊協作崗位，需獨立作戰空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (87, 'CIA_06', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「系統化的執行者」。不僅想把事做好，還能建立標準作業程序 (SOP) 並嚴格執行。預測：極其穩定且精確的產出，是流程優化的理想人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (88, 'CIA_06', 'A', 'CIA_02', 'C', '與 CIA_02 (成就動機) C聯動：表現為「行政管家」。雖然極度細心且愛好程序，但缺乏突破目標的野心。管理建議：適合擔任穩定運營的幕後支援，不宜賦予高競爭性的開拓任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (89, 'CIA_06', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「精密規劃者」。在行動前會細節性地推敲每一個步驟，確保流程無死角。警示：應變速度極慢，在混亂或緊急環境下會感到極大壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (90, 'CIA_06', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「細節偏執者」。對排列、程序與成果無瑕疵有極強渴望。管理風險：容易因瑣碎細節而耽誤核心進度，需主管適時定義「何謂完成」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (91, 'CIA_06', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「實務改良家」。能將天馬行空的創意整理成邏輯通順的實施方案。預測：能讓創新成果落地的關鍵橋樑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (92, 'CIA_06', 'A', 'CIA_21', 'C', '與 CIA_21 (效率取向) C聯動：表現為「繁文縟節的愛好者」。雖然愛好程序，但卻過於精確 methodical 導致喪失效率，適合稽核崗位，但不適合敏捷團隊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (93, 'CIA_06', 'A', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) C聯動：表現為「自創系統者」。喜歡有條理，但不喜歡「別人的」條條框框，會傾向於重新建立一套自己覺得更高效的程序。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (94, 'CIA_06', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「程序守門員的怒火」。當環境被弄亂或他人不按 SOP 執行時，會瞬間被激發情緒反應，對混亂有極低的容忍度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (95, 'CIA_06', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「隨興的苦幹者」。雖然非常盡責想把事做好，但做事雜亂無章、缺乏次序。行為預測：努力但效率低，需行政輔助工具協助管理進度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (96, 'CIA_06', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「混亂的獵人」。極想達成業績目標，但過程中容易丟三落四、遺漏細節。警示：業績好但售後或行政手尾極多，需配備助理協助控管。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (97, 'CIA_06', 'C', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「職場混亂製造者」。既沒條理又容易衝動行事。管理風險：行為極度隨機且不可控，會造成團隊協作上的巨大困擾。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (98, 'CIA_09', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「有紀律的發明者」。能克制「只發點子不做事」的傾向，強迫自己將創新概念進入繁瑣的研發與測試階段。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (100, 'CIA_06', 'C', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「非典型的快速執行者」。雖然不重視程序與整潔，但對獲取結果的效率有極強渴望。會用跳躍式的路徑達成目的。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (101, 'CIA_06', 'C', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「負責任的散漫者」。對結果負責，但過程極其跳躍。管理預測：只要給他最終成果的期限，不要管他過程怎麼排列。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (102, 'CIA_07', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「高品質保證者」。強大的自制力支撐其對完美的追求。行為預測：產出極其精緻且合規，是處理精密任務或核心資產的關鍵人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (103, 'CIA_07', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「精密的防禦者」。行動前反覆推敲以確保無誤。管理警示：極度畏懼錯誤，在面對高時效要求的專案時，可能因過度檢查而錯失良機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (105, 'CIA_07', 'A', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「挑剔的管理者」。對自己要求完美，且認為自己理應獲得最高尊重，易對下屬或同僚表現出不耐與輕視，造成人際摩擦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (106, 'CIA_07', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「脆性完美主義」。一旦專案出現無法控制的瑕疵，其自我認同會崩解。預測：在逆境下恢復緩慢，甚至可能因一次失敗而選擇徹底逃避。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (107, 'CIA_07', 'A', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「卓越的工匠」。不僅追求完美，更渴望用最快、最精確的方式達成。預測：這是效率與品質兼備的極佳組合，是高階專業技術職的核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (108, 'CIA_07', 'A', 'CIA_26', 'C', '與 CIA_26 (同理心) C聯動：表現為「冷酷的工作狂」。對細節的執著凌駕於對他人感受的關注。警示：容易為了成果無瑕疵而過度逼迫團隊，導致團隊流失率增高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (109, 'CIA_07', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「易爆的檢查者」。對任何不完美的行為（如垃圾沒丟好、簡報格式跑掉）會產生即時且強烈的情緒反應，容忍度極低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (110, 'CIA_07', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「務實的執行者」。雖然自律且盡責，但不糾結細節，以完成任務為首要。管理預測：產出速度快且及格，適合高週轉率、容許微小誤差的工作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (111, 'CIA_07', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「擴張型獵人」。極想贏但不在意過程是否無瑕疵。管理警示：容易達成業績但「售後」問題多，需安排「條理性高」的人員協助收尾。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (112, 'CIA_07', 'C', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「豁達的進取者」。容許失敗與瑕疵，並對未來保持樂觀。預測：心理彈性極佳，非常適合變動劇烈、不確定性高的創業型環境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (113, 'CIA_07', 'C', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) C聯動：表現為「自由散漫者」。既不追求完美，也不想遵循規則。管理風險：除非有強大的熱忱支持，否則其產出品質往往難以維持組織基本水準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (114, 'CIA_08', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「高產能開拓者」。不僅渴望成功，且深信自己具備達標的能力。預測：在面對困難專案時具備極強的心理優勢，是帶領團隊突破困境的靈魂人物。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (115, 'CIA_08', 'A', 'CIA_05', 'A', '與 CIA_05 (衝動管理) A聯動：表現為「穩健的掌控者」。相信自己能應付局面，且行為高度自律。管理預測：在危機時刻能保持冷靜，不因恐慌而失控，是極佳的危機處理人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (116, 'CIA_08', 'A', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「膨脹的權威」。具備能力自信但缺乏謙遜。警示：容易變得剛愎自用，不願聽取他人建議，甚至在團隊中形成獨裁風格，需注意其人際關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (117, 'CIA_08', 'A', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) A聯動：表現為「體制內的專家」。在熟悉的規則架構下感覺極度自信且高效。預測：是組織 SOP 的最佳執行者，能完美維護既有系統的運作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (118, 'CIA_08', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「自負的精英」。深信自己的卓越能力應換取特殊優待。管理風險：對一般行政要求配合度低，認為瑣事應由他人代勞。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (119, 'CIA_08', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「焦慮的耕耘者」。雖然做事盡責努力，但內心始終擔心自己能力不足。行為預測：會花過多時間反覆檢查，雖然產出品質高，但心理內耗極大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (120, 'CIA_08', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「癱瘓的完美主義」。因追求無瑕疵但又不信自己能達成，導致嚴重的拖延症。管理建議：需主管協助拆解小目標，累積成功的「微體驗」以重建信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (121, 'CIA_08', 'C', 'CIA_17', 'C', '與 CIA_17 (目標效能感) C聯動：表現為「習得性無助者」。完全不相信努力能改變結果。警示：在高壓環境下極易放棄，是組織績效的重大隱憂，需關注其身心健康與職務契合度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (122, 'CIA_08', 'C', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「韌性支撐的求存者」。雖然目前對自己信心不足，但遭遇打擊時能迅速站起並從頭再來。管理建議：屬於大器晚成型，適合長期培養以建立信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (123, 'CIA_08', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「討好型偽裝者」。因對能力沒信心，會過度觀察他人臉色並迎合期望以獲取安全感。其專業觀點可能因恐懼而不誠實。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (124, 'CIA_09', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「卓越的馬拉松跑者」。具備強大的目標導向與執行意志，能為了長遠成功忍受現階段的艱辛。預測：在長期轉型專案中展現極佳的穩定性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (125, 'CIA_09', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「冷靜的戰術執行家」。在深思熟慮後，能嚴格控制行為不偏離既定策略，絕不因外部干擾而打亂節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (126, 'CIA_09', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「意志力與情緒的拉鋸」。雖然內在有強烈長期目標（自律），但外在行為易受誘惑干擾（衝動）。管理警示：此組合會造成巨大的心理內耗，需建立環境隔離誘惑以輔助。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (127, 'CIA_09', 'A', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) C聯動：表現為「高度務實的奮鬥者」。其自律源於對物質回報的強烈渴望，能為了高額獎酬或地位晉升展現出極致的禁慾與努力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (129, 'CIA_09', 'A', 'CIA_34', 'C', '與 CIA_34 (工作熱忱) C聯動：表現為「專業的苦行僧」。雖然對工作缺乏熱情，但憑藉強大的意志力（自律）依然能高品質完成任務，行為表現極其職業化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (131, 'CIA_09', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「眼高手低的焦慮者」。對成果有無瑕疵的要求，卻管不住自己去落實細節。警示：容易產生「想得美、做不到」的落差，需主管介入監督進度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (132, 'CIA_09', 'C', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「隨性的樂天派」。雖然不夠自律且易分心，但對未來保持積極期待，即便進度延遲也能自我排解壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (133, 'CIA_09', 'C', 'CIA_23', 'A', '與 CIA_23 (獨創性) A聯動：表現為「多產但不落地的創意家」。有極多創新的原創想法，但因缺乏自律將其細緻化，成果往往流於草稿階段。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (134, 'CIA_09', 'C', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「救火式執行者」。雖然缺乏日常紀律，但一旦事情迫在眉睫，會基於強烈的責任感爆發性能量完成工作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (135, 'CIA_09', 'C', 'CIA_35', 'A', '與 CIA_35 (生活熱情) A聯動：表現為「熱情四射的散漫者」。對生活充滿活力與興趣，但工作上難以專注於單一目標，容易被新奇事物吸引而轉向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (136, 'CIA_10', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「正派的領袖」。追求成功但絕不走捷徑。預測：能建立具備長期信任感的團隊，即便在高度競爭下也能維持組織聲譽。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (137, 'CIA_10', 'A', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「清廉的高效能者」。在追求效率的過程中極其精確且誠實，適合處理採購、預算控管等涉及龐大利益的崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (138, 'CIA_10', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「自覺的內耗者」。內心覺得自己應得特權，但道德感強迫自己謙虛。管理警示：容易累積隱性不滿，需注意其情緒平衡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (139, 'CIA_10', 'A', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「純粹的誠信者」。不在乎他人評價或包裝形象，真實地展現正直。預測：是組織內部舉報或倫理風險查核的最佳守門員。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (140, 'CIA_10', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「精明的權謀家」。利用高度的自律與細心來實現個人私利，行為極難被察覺。警示：若缺乏外部稽核，容易造成系統性損害。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (141, 'CIA_10', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「深沉的政治家」。行為極其謹慎且不擇手段。管理警示：在職場競爭中擅長佈局且不留痕跡，需注意其對團隊互信的破壞力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (142, 'CIA_10', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「極端利己者」。完全以目標為導向且具備操縱傾向。風險預測：高頻率出現職場政治操弄，需嚴格控管其決策權限。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (143, 'CIA_10', 'C', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) C聯動：表現為「貪婪的追求者」。對財富、地位有極度渴望且不排除用非正式手段獲取。警示：是職場舞弊的高風險群組。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (144, 'CIA_10', 'C', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「狂傲的擴張者」。自視甚高且追求財富。管理建議：其強大的自信雖能帶來業績，但極易引發團隊衝突與流失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (145, 'CIA_10', 'C', 'CIA_24', 'C', '與 CIA_24 (真實性) C聯動：表現為「虛偽的表演者」。為了利益可以隨時調整價值觀或行為，表裡不一。預測：人際關係起伏大，誠信基礎薄弱。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (146, 'CIA_10', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「計較的利己主義」。對付出回報極其敏感，且會為了爭取更多私利而挑戰公平規則，屬於難以滿足的員工。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (147, 'CIA_10', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「職場變色龍」。表面極度謙虛、誠懇以獲取認可，實則內在逐利。警示：是最難識別的風險對象，需透過第三方反饋來驗證。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (148, 'CIA_11', 'A', 'CIA_05', 'A', '與 CIA_05 (衝動管理) A聯動：表現為「正直的穩定者」。不僅不屑於欺騙，且能冷靜克制誘惑。預測：在金錢或權力誘惑面前具備極強的抵抗力，是組織信任的定海神針。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (149, 'CIA_11', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「透明的關懷者」。對人的關心發自內心，不帶目的性。預測：極易建立深厚的人際信任，適合擔任團隊黏著劑或心理諮詢角色。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (150, 'CIA_11', 'A', 'CIA_29', 'C', '與 CIA_29 (人際適應力) C聯動：表現為「拙於包裝的正直者」。為人誠懇但不懂圓滑，說話過於直白。管理警示：雖值得信任，但易在不經意間得罪人，需注意其溝通技巧。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (151, 'CIA_11', 'A', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「純粹的真我」。完全不掩飾缺點，也不刻意塑造形象。管理預測：其測評結果信效度極高，是職場中最透明、最好管理的類型。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (152, 'CIA_11', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「目的導向的野心家」。為了業績或晉升，不惜美化事實或誤導他人。警示：短期績效雖好，但長期會嚴重損害團隊的互信基礎。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (153, 'CIA_11', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「精密的政治玩家」。操縱行為經過精密計算，且不會輕易留下把柄。風險預測：擅長推卸責任或竊取功勞，是組織內部的潛在負面變數。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (154, 'CIA_11', 'C', 'CIA_14', 'A', '與 CIA_14 (謙虛) A聯動：表現為「偽善者」。表面表現得極度謙遜，實則內在充滿操縱動機。警示：最難防範的類型，常利用「弱者姿態」來獲取資源或同情。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (155, 'CIA_11', 'C', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「具備欺騙性的創意者」。可能利用創新的點子來包裝個人私利，或將他人的創意占為己有並進行改良。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (156, 'CIA_11', 'C', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「派系操作者」。極力維護小團體利益，但過程充滿政治操弄，容易在組織內形成「小圈子」文化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (157, 'CIA_11', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「權利的計較者」。會利用操縱手段來確保自己獲得「超額回報」，並對任何微小的不公平進行政治化的反擊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (158, 'CIA_27', 'C', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「情緒化的計較者」。一旦感到分配不公，會立刻表現出憤怒或消極怠工，情緒反應極大且難以安撫。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (160, 'CIA_12', 'A', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「純粹的修煉者」。比起加薪，更看重學習機會與自我實現。管理建議：應提供具挑戰性的專案或進修機會作為主要獎酬。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (161, 'CIA_12', 'A', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「使命感驅動者」。對工作充滿熱愛且不計酬勞多寡。預測：在組織面臨寒冬或薪資凍結時，這類員工的留任意願最高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (162, 'CIA_12', 'A', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「無私的貢獻者」。願意為了團隊共榮而放棄個人獎金或特權。預測：是建立高凝聚力文化的核心成員。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (163, 'CIA_12', 'A', 'CIA_14', 'A', '與 CIA_14 (謙虛) A聯動：表現為「淡泊名利的隱士」。既不追求財富也不渴求他人尊重，這類人極難被外在名利收買，適合擔任高度保密或敏感職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (165, 'CIA_12', 'C', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「貪婪的職場投機者」。高度重視利益且可能忽視倫理。警示：是職場舞弊、收受回扣的高風險群組，需建立嚴格的財務審核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (166, 'CIA_12', 'C', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「利益至上的不公者」。為了獲取個人物質優勢，不惜破壞組織公平規則。風險預測：極易為了私利而損害團隊或客戶利益。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (167, 'CIA_12', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「特權索求者」。認為自己應享有最高薪資與專屬待遇。管理警示：若組織無法給予「優越感」，其工作動能會迅速崩潰且產生負面抱怨。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (168, 'CIA_12', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「高度現實的勞動者」。對每一分付出的金錢回報都斤斤計較。管理預測：是標準的「金錢驅動型」，管理方式應簡單直接，以獎金說話。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (232, 'CIA_18', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「快速冷靜者」。雖然容易受到挫折激怒（易激度高），但能迅速從情緒中復原並重回理性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (169, 'CIA_12', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「職場鍍金者」。為了塑造成功形象（高社會地位）而過度包裝自己。警示：其表面展現的價值觀可能與內在逐利心態不符，需長期觀察。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (170, 'CIA_13', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「正道成功者」。對成功有渴望但絕不跨越道德底線。預測：其成就具備極高的透明度與可複製性，是組織內部良性競爭的標竿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (171, 'CIA_13', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「失控但正直者」。雖然行為魯莽易出錯，但出發點通常是誠實的，不會為了掩蓋錯誤而撒謊。管理建議：應包容其無心之過，引導其修正行為而非懲罰其動機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (172, 'CIA_13', 'A', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) A聯動：表現為「廉潔守護神」。具備極高的道德標準且不貪婪。預測：極其適合擔任高價值資產管理、法務、稽核或涉及高度信任的職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (173, 'CIA_13', 'A', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「體制公平的捍衛者」。不僅要求自己公正，也極度在意組織的公平。管理警示：若組織出現不公平競爭，他會是第一個站出來發聲或選擇離職的人。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (174, 'CIA_13', 'A', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「剛正不阿者」。不在乎社交形象，即使在同儕壓力下也會堅持說出真相，是預防集體作惡的關鍵防線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (175, 'CIA_13', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「不擇手段的擴張者」。為了達成業績或領先同儕，會利用資訊不對稱或規則漏洞。管理風險：高業績可能掩蓋其合規風險，需加強第三方稽核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (176, 'CIA_13', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「深思熟慮的投機家」。其不誠實行為通常經過精心佈局，難以察覺。警示：是高階商業犯罪潛在對象，需建立分權制衡機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (177, 'CIA_13', 'C', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「職場慣竊或投機者」。管不住慾望且缺乏公正底線。行為預測：容易出現偷工減料、虛報開支或侵占公物等低階舞弊行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (178, 'CIA_13', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「偽裝的利用家」。透過操縱手段獲取他人信任後再進行剝削。風險預測：在團隊中容易造成信任感瓦解，是組織文化中的「劇毒」成分。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (179, 'CIA_13', 'C', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「走捷徑的高效能」。為了快而省去必要的安全或倫理程序。管理警示：雖能快速達標，但可能留下巨大的法律或安全後患。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (180, 'CIA_13', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「貪婪的特權者」。認為自己的「特殊」地位應換取超越規則的利益，且不會對利用他人感到愧疚。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (181, 'CIA_13', 'C', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「熱情的利己者」。雖熱愛工作，但其動機可能源於工作帶來的灰色利益獲取機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (182, 'CIA_14', 'A', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「內斂的高手」。具備極強能力卻不張揚。預測：在團隊中極受尊敬且具備高影響力，是理想的導師（Mentor）型人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (183, 'CIA_14', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「僕人式領導」。真心平視他人並感同身受。預測：能創造極高的心理安全感，非常適合帶領高知識產能或需要創意協作的團隊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (184, 'CIA_14', 'A', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「低調的協調者」。能身處不同階層而不顯突兀。管理建議：在跨部門溝通中具備極強的潤滑作用，能有效降低組織摩擦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (185, 'CIA_14', 'A', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「終身學習者」。因謙虛而自覺不足，能持續吸收新知。管理預測：具備極佳的受教性（Coachability），是組織持續進化的核心力量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (186, 'CIA_14', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「狂妄的野心家」。成功後傾向於擴張自我，排斥他人功勞。警示：容易造成「一將功成萬骨枯」的情形，需注意優秀部屬的流失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (187, 'CIA_14', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「權勢型操縱者」。自視甚高且擅長權術。風險預測：會利用職位或資訊不對稱來打壓異己，對組織文化透明度有強烈破壞性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (188, 'CIA_27', 'C', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「利己主義者」。不僅計較獲得，還可能為了獲取更多而犧牲他人或組織利益。風險預測：是潛在的誠信風險對象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (190, 'CIA_14', 'C', 'CIA_24', 'C', '與 CIA_24 (真實性) C聯動：表現為「虛飾的名利徒」。為了維持高人一等的形象而不斷包裝或誇大事實。行為預測：在面對錯誤時會全力推諉，以保護其自傲的形象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (191, 'CIA_14', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「職場獨裁傾向者」。自認優越且理應享有特權。管理警示：會強烈要求特殊化管理，破壞組織的制度統一性，挑戰管理權威。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (192, 'CIA_14', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「偽裝的菁英」。內心傲慢但外在包裝得很得體。警示：這種「隱性傲慢」會在長期合作或高壓下暴露，需注意其對團隊長期信任的損害。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (193, 'CIA_14', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「自尊極度敏感者」。因自視甚高，任何輕微的指正或異議都會被其視為嚴重的冒犯，引發劇烈的情緒反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (194, 'CIA_15', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「無敵的開路者」。具備強大成功慾望且擁有充足心理資源支持。預測：面對高難度挑戰時不會輕言放棄，是組織推動艱鉅任務的最佳人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (195, 'CIA_15', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「務實的樂觀主義者」。既對未來抱持正向期待，又能冷靜分析潛在風險。預測：能制定出具備激勵性且紮實可行的計畫。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (196, 'CIA_15', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「韌性十足的變革者」。創新過程中失敗率極高，高心理資本提供了失敗後的快速復原力。預測：能帶領團隊在反覆試錯中找到新路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (197, 'CIA_15', 'A', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「正向能量傳播者」。能以自身的樂觀與韌性感染團隊，在逆境中穩定軍心。管理建議：適合作為組織文化大使或危機應變核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (198, 'CIA_15', 'A', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「天生贏家型員工」。對工作充滿熱情且心態極其健康，離職風險與燃盡風險極低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (199, 'CIA_15', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「焦慮的耕耘者」。雖極其努力工作，但內心缺乏支撐資源。警示：一旦遇到無法控制的挫折，極易陷入自我否定，需高度關注其心理健康。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (200, 'CIA_15', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「崩潰邊緣的完美者」。追求完美但心理資源不足以承載失敗。風險預測：只要成果有一點瑕疵，其崩潰感會比一般人強烈數倍，易出現逃避行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (201, 'CIA_15', 'C', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「清高的受害者」。堅持正直但在不公環境中缺乏韌性與樂觀。預測：容易因職場政治感到灰心喪志，轉向消極應對。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (202, 'CIA_15', 'C', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「苦命的承擔者」。責任感強迫其接下工作，但內心深感無力與悲觀。警示：是「職場過勞」的高風險群組。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (203, 'CIA_15', 'C', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「渴望成長但自卑者」。想變好但總擔心自己做不到。管理建議：需提供明確的成長路徑與頻繁的小成功（Small Wins）來補足信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (204, 'CIA_15', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「易碎的火藥桶」。對逆境耐受力差且易被激怒。風險預測：在壓力下不僅容易放棄，還會伴隨激烈的情緒宣洩，對團隊穩定性極大傷害。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (205, 'CIA_16', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「目標導向的戰略家」。不僅想把事做對（盡責），且腦中總有多套達成目標的路徑。預測：在遇到阻礙時會迅速切換執行策略，而非死守一條死路。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (206, 'CIA_16', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「周密的夢想家」。具備宏大的目標動機，但每一步都經過精確計算。管理預測：能提出既具備野心又能避開風險的長遠計畫。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (207, 'CIA_16', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「急躁的開拓者」。對達成目標充滿渴望與策略，但執行時易因情緒波動而偏離軌道。管理警示：雖有點子且想贏，但需他人協助維持執行節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (208, 'CIA_16', 'A', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) A聯動：表現為「正派的願景家」。其規劃的達成路徑完全符合倫理，不屑於透過損人利己的方式達成目標，是組織誠信文化的好榜樣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (209, 'CIA_16', 'A', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「不屈的導航員」。遭遇重大挫折（韌性）後，能迅速產生新的目標動機與執行方案（希望）。預測：是組織度過經營危機的靈魂人物。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (210, 'CIA_16', 'A', 'CIA_23', 'A', '與 CIA_23 (獨創性) A聯動：表現為「創新的策略師」。善於用非傳統的方法達成目標，能看見別人看不見的替代方案。預測：適合解決結構性難題或處理複雜的商業併購。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (211, 'CIA_16', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「鼓舞人心的領導者」。不僅自己有希望，還能站在他人立場設計出讓團隊成員都有共鳴的達成路徑，大幅提升團隊動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (213, 'CIA_16', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「絕望的苛求者」。對結果要求完美，但對「如何達成」缺乏信心。風險預測：常因看不見完美的達成路徑而陷入極度悲觀，並出現嚴重拖延。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (214, 'CIA_16', 'C', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「習得性無助的典型」。對未來不抱期待，也不相信自己能找到出路。管理警示：動能完全熄火，若持續在高壓職位，極易引發嚴重的心理健康問題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (215, 'CIA_16', 'C', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「空有願望的成長者」。想變好但找不到具體方法。管理建議：應提供結構化的培訓與導師指導（Mentorship），幫他畫出成長路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (216, 'CIA_17', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「強效執行者」。具備極高的達成信心且配合嚴明的紀律。預測：對承諾的目標有極高的達成率，且過程穩定不需督促。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (217, 'CIA_17', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「深思熟慮的自信者」。其信心建立在充分的準備與分析之上，而非盲目自信。預測：能承擔高風險決策，因為他已看清路徑並相信自己能控場。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (219, 'CIA_17', 'A', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「信念堅定的專家」。對能力（08）與努力達成目標（17）都有極高信心。預測：展現出強大的氣場與說服力，適合帶領變革或開拓性任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (220, 'CIA_17', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「脆性自信者」。在順境中信心爆棚，但一旦努力後仍失敗，自信會迅速崩塌。管理建議：需在失敗初期即時介入，防止其陷入自我懷疑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (221, 'CIA_17', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「敢於突破的發明者」。相信非傳統的方法可行且自己能推動它。預測：能打破僵化的 SOP，透過創新的手段達成他人認為不可能的目標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (222, 'CIA_17', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「傲慢的精英」。相信自己能力出眾且理應獲得特殊回報。警示：容易低估團隊貢獻，認為成功全是個人努力的結果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (223, 'CIA_17', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「強勢的專家」。對自己極度自信，因此對「不專業」或「進度慢」的同事容忍度極低，易因恨鐵不成鋼而爆發脾氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (225, 'CIA_17', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「冒名頂替症候群」。要求無暇疵但深怕被看穿能力不足。風險預測：常因恐懼失敗而導致嚴重的任務拖延或過度準備（Over-preparing）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (226, 'CIA_17', 'C', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「習得性無助者」。不相信未來會變好，也不相信自己有能力改變。管理警示：動能趨近於零，在變動環境中容易率先放棄，需透過小目標建立信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (227, 'CIA_17', 'C', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「求知若渴的學徒」。強烈想變好但現在沒信心。管理建議：是極佳的培訓對象，適合給予結構化的技能引導與正向回饋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (228, 'CIA_18', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「長線抗壓執行者」。即便計畫出錯，也能在修復情緒後迅速回歸紀律。預測：在高度不確定且高壓的專案中，產出品質最為持久。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (229, 'CIA_18', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「愈挫愈勇的開拓者」。失敗被其視為達成最終成功的養分。預測：是組織進攻困難市場、開發新客戶時最穩定的先鋒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (230, 'CIA_18', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「健康的完美主義」。追求高品質但能容忍過程中的挫折，並從瑕疵中學習。預測：具備極強的自我優化能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (231, 'CIA_18', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「無畏的實驗家」。創新即代表不斷失敗，高韌性確保其在實驗重重受阻時，仍能維持探索的動力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (233, 'CIA_18', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「易碎的樑柱」。做事盡責但抗壓性極差。警示：一旦遭遇重大失敗，其「盡責」會轉化為強烈的自我否定，需高度防範燃盡（Burnout）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (234, 'CIA_18', 'C', 'CIA_05', 'A', '與 CIA_05 (衝動管理) A聯動：表現為「沉默的受難者」。雖能管住行為不爆發，但內心緩衝能力極低。管理風險：壓力會持續累積而非排解，易導致無預警離職。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (235, 'CIA_18', 'C', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「习得性無助者」。既不信自己有能力，也無法承受壓力。管理預測：在變動環境中會最先喪失功能，需安排在穩定、低壓職位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (236, 'CIA_18', 'C', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「悲觀的受災戶」。對未來不抱期待，且遭受打擊後一蹶不振。警示：會擴大團隊的負面氛圍，需注意其對士氣的殺傷力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (237, 'CIA_18', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「心碎的公平追求者」。對不公平現象極度在意，且一旦受到不公對待，修復心理創傷的速度極慢，易產生長期怨懟。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (238, 'CIA_18', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「玻璃心的巨嬰」。認為應受特權對待，一旦被指責或遭遇普通挫折，會感到嚴重的心理受傷與憤怒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (239, 'CIA_19', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「務實的樂觀者」。對未來充滿期待，但每一步都經過精確計算以避險。預測：能提出具備野心且高度可行性的商業提案，不會盲目衝動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (240, 'CIA_19', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「進取的完美主義」。追求極致品質，且相信透過努力必能達成。管理建議：其正向心態能緩解完美主義帶來的焦慮，是高品質產出的核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (241, 'CIA_19', 'A', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「投機的冒險家」。相信「壞事不會發生在自己身上」，因此更敢於走捷徑或忽視規則。警示：高樂觀掩蓋了道德風險，需加強合規稽核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (242, 'CIA_19', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「變革的傳教士」。相信創新必能改變現狀，且不畏懼初期的挫折。預測：在組織轉型中是極佳的動員者與願景傳播者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (243, 'CIA_19', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「陽光的火藥桶」。雖然容易被激怒，但因具備正向歸因，怒氣消散極快，不會記恨或長期陷入負面情緒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (244, 'CIA_19', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「防禦性的勤奮者」。因不相信未來會自然變好，所以靠極度努力來對抗焦慮。警示：雖產出穩定但心理壓力極大，需適時給予紓壓支援。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (245, 'CIA_19', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「焦慮的攀登者」。極想成功但總預感會失敗。預測：行為上雖衝刺，但內耗嚴重。成功後常感如釋重負而非喜悅，需關注其身心健康。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (246, 'CIA_19', 'C', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「抑鬱的放棄者」。既不信自己有能力，也不信環境會好轉。管理風險：極易陷入「習得性無助」，在變動中完全喪失動能，需優先輔導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (247, 'CIA_19', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「陰鬱的操縱者」。因對人性悲觀，更傾向於使用權術或欺騙來保護個人利益。預測：職場防禦心極強，難以建立深度夥伴關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (249, 'CIA_19', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「戴著面具的悲觀者」。內心充滿不安，但為了獲得認可而表現出正向樂觀的樣子。警示：這類員工最難察覺其真實壓力水準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (250, 'CIA_20', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「實踐型變革者」。不僅有點子，且能透過自律將創意標準化、流程化。預測：能產出既具新意又具備極高完工度的成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (251, 'CIA_20', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「策略型創新者」。在挑戰現狀前會先進行縝密的風險評估。預測：其提出的變革方案通常具備高度可行性，容易獲得高層支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (252, 'CIA_20', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「不穩定的發明家」。雖有大量創新構思但缺乏行為剎車，容易在未經驗證下頻繁更動流程。警示：會對團隊造成執行上的混亂，需專人負責收尾。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (253, 'CIA_20', 'A', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「游走灰色地帶的破壞者」。利用創新力來鑽規則漏洞或損人利己。管理警示：其創意可能帶來合規風險，需嚴格控管其變革權限。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (254, 'CIA_20', 'A', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「無畏的變革推手」。對創新充滿樂觀與韌性，即便方案被否決也能迅速修正再出發。預測：是推動企業文化轉型的重要火車頭。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (255, 'CIA_20', 'A', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「精實創業家」。創新是為了極大化效率，追求用更聰明的方法解決問題。管理建議：非常適合負責自動化、數位轉型或流程優化專案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (256, 'CIA_20', 'A', 'CIA_26', 'C', '與 CIA_26 (同理心) C聯動：表現為「冷酷的顛覆者」。為了推動創新方案而無視團隊成員的情緒壓力。風險預測：雖能達成變革，但過程中可能引發強烈的人際衝突與流失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (257, 'CIA_20', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「卓越的守成者」。對現有規則極度忠誠且執行到位，但不具備優化意識。管理建議：適合維護既有成熟系統，但不宜指派其負責開發期專案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (258, 'CIA_20', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「努力的跟隨者」。極想成功但缺乏原創思維，傾向於複製已證明的成功模式。預測：在成熟市場的執行力強，但難以應對藍海市場。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (259, 'CIA_20', 'C', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) A聯動：表現為「傳統捍衛者」。對變革有天然的抗拒感，認為穩定勝於一切。警示：在組織面臨轉型時，可能是最難被說服的人群，需給予充足的過渡期。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (260, 'CIA_20', 'C', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「渴望成長的模仿者」。雖想自我進步，但傾向於吸收外部現成知識而非自己創造新路徑。管理建議：適合透過外部培訓來引導其技能更新。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (261, 'CIA_21', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「高效產能機器」。不僅想做好，還要做得快。預測：能在最短時間內產出高品質結果，是組織中標準的「高潛力人才（HiPo）」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (262, 'CIA_21', 'A', 'CIA_03', 'C', '與 CIA_03 (審慎) C聯動：表現為「速食決策者」。為了趕進度而犧牲思考深度。警示：容易因追求快而遺漏關鍵風險，需他人協助進行最終審核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (263, 'CIA_21', 'A', 'CIA_06', 'C', '與 CIA_06 (條理性) C聯動：表現為「混亂的高效者」。不拘泥於辦公桌整潔或 SOP，只要能最快拿到結果，過程混亂也無所謂。管理建議：適合作為突擊隊員處理緊急任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (264, 'CIA_21', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「精實大師」。在追求無瑕疵的同時不斷優化動作，達成「一次就做對且最快」。預測：具備卓越的自我優化與流程設計能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (265, 'CIA_21', 'A', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「捷徑尋找者」。為了提升效率不惜損害他人利益或遊走道德邊緣。警示：其效率可能建立在合規風險之上，需嚴格監控手段合法性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (266, 'CIA_21', 'A', 'CIA_26', 'C', '與 CIA_26 (同理心) C聯動：表現為「冷酷的數據者」。視人為資源，為求團隊總產出極大化而忽略個別成員的身心狀況。風險：短期績效極高，但長期團隊流失率大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (267, 'CIA_21', 'A', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「快樂的生產者」。對優化流程充滿熱情。預測：具備極強的抗燃盡能力，因為他們總能找到更輕鬆且高效的方式完成工作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (268, 'CIA_21', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「傳統苦幹者」。非常努力且負責任，但往往使用舊方法、笨方法。管理建議：應指派其參加工作坊學習新工具，提升其數位化能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (269, 'CIA_21', 'C', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「耗時的工匠」。為了細節極限而嚴重拖慢進度。警示：容易在非核心細節上投入過多資源，需主管定義任務的「停損點」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (270, 'CIA_21', 'C', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「步調緩慢的樂天派」。做事節奏慢但不感到壓力。管理預測：在高度競爭、節奏極快的環境（如電商、金融）中，會顯得格格不入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (271, 'CIA_21', 'C', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) A聯動：表現為「僵化的官僚執行者」。嚴格遵守流程即使該流程已明顯不合時宜。警示：是組織冗長流程的維護者，缺乏變革動機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (272, 'CIA_21', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「拖延的焦慮者」。因效率低導致任務堆積，進而引發焦慮與負面情緒。預測：在高壓截止日期前極易情緒失控。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (273, 'CIA_22', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「組織的鋼鐵基石」。具備極高的可靠性與服從度。預測：在嚴謹、高壓且需精確執行的環境（如航太、軍事、醫療）中表現最卓越。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (274, 'CIA_22', 'A', 'CIA_20', 'C', '與 CIA_20 (創新力) C聯動：表現為「守舊的官僚者」。過度依賴舊規，對任何改變都有天然抗拒。管理建議：不宜指派其負責開發期專案，但在維護既有成熟系統時極其稱職。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (275, 'CIA_22', 'A', 'CIA_05', 'A', '與 CIA_05 (衝動管理) A聯動：表現為「冷靜的制度執行者」。即便面對極大情緒壓力，也能管住行為不做出任何違規舉動。預測：適合處理敏感、保密且流程僵化的行政事務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (278, 'CIA_22', 'A', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「忠誠的受命者」。一旦認同指令，會不計代價地落實。預測：是主管最放心的「交辦對象」，通常不需要二次確認進度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (279, 'CIA_22', 'C', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「破壞式創新者」。視規則為絆腳石，傾向於「先做再說，被抓到再道歉」。管理建議：適合研發或前線開拓，但必須配備一名行政助手協助合規收尾。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (280, 'CIA_22', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「自律的獨行俠」。對工作品質有高要求（盡責），但非常討厭形式化的規矩。預測：會產出高品質結果，但常因不填日報或不按流程申請而遭行政單位投訴。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (281, 'CIA_22', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「精明的規避者」。在不遵循規則前會精密計算過後果，確保自己不會受到懲罰。警示：其違規行為通常具備「戰略性」，難以透過簡單管理糾正。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (282, 'CIA_22', 'C', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「俠義的破局者」。會為了團隊利益或夥伴情誼而勇敢挑戰公司「不合理」的制度。管理預測：是潛在的基層意見領袖，若管理不當易形成對立。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (283, 'CIA_22', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「反叛的刺頭」。認為規則是用來約束平庸者的，自己應享有例外權。風險：極易公開挑戰主管權威，對組織紀律的殺傷力極大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (284, 'CIA_22', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「易爆的刺客」。對規範有強烈排斥感，一旦被要求遵守規則，極易產生對抗性的負面情緒反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (285, 'CIA_23', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「多產的原創大師」。能將獨特的點子轉化為具體的作品或提案，而非流於空想。預測：能穩定產出具有高度辨識度的專業成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (286, 'CIA_23', 'A', 'CIA_06', 'A', '與 CIA_06 (條理性) A聯動：表現為「結構化的創意者」。能將天馬行空的想法整理成極具邏輯的體系。管理建議：適合作為產品架構師或內容策略開發者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (287, 'CIA_23', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「極致美學追求者」。對原創內容的細節有近乎病態的要求。預測：能創造出具備極高品牌價值的巔峰之作，但開發週期可能較長。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (288, 'CIA_23', 'A', 'CIA_12', 'A', '與 CIA_12 (低物質傾向) A聯動：表現為「純粹的藝術家靈魂」。創作不為名利，只為表達獨特的自我。管理建議：難以用金錢激勵，應給予高度的自主權與創作空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (289, 'CIA_23', 'A', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) C聯動：表現為「反傳統的奇才」。其原創性往往建立在對舊有規定的否定之上。風險：可能在團隊中顯得格格不入，甚至挑釁現有流程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (290, 'CIA_23', 'A', 'CIA_24', 'A', '與 CIA_24 (真實性) A聯動：表現為「忠於自我的創作者」。其點子不僅獨特，且反映其真實內在。預測：具備強大的個人魅力與品牌原創性，適合品牌代言或核心價值詮釋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (291, 'CIA_23', 'A', 'CIA_35', 'A', '與 CIA_35 (生活熱情) A聯動：表現為「靈感不斷的發電機」。對生活充滿好奇，能從跨領域的體驗中汲取養分。預測：在腦力激盪（Brainstorming）會議中是不可或缺的點子來源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (292, 'CIA_23', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「高產出的複刻者」。雖有強大成功渴望，但傾向於走已驗證的「安全牌」。管理警示：在需要顛覆式設計的環境中會顯得靈魂不足。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (293, 'CIA_23', 'C', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「務實的執行專家」。對處理已知領域的任務非常有信心，但對「無前例可循」的創意任務感到不安。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (294, 'CIA_23', 'C', 'CIA_20', 'A', '與 CIA_23 (獨創性) C 與 CIA_20 (創新力) A：表現為「改良型工程師」。擅長優化現有流程，但較難產出顛覆性的新概念。預測：是組織進行漸進式改進（Kaizen）的優選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (295, 'CIA_23', 'C', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「圓滑的從眾者」。為人好相處，思維大眾化，不具威脅性。管理建議：適合作為前線服務或需要大量人際協作的標準化職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (296, 'CIA_23', 'C', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「勤奮的學習機器」。能快速吸收現有的知識體系，但較難發展出個人風格的見解。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (298, 'CIA_24', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「真誠的人道主義者」。對人的關懷不具政治目的，能建立極高質量的深度信任。管理建議：適合作為高階教練或員工關係調解者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (299, 'CIA_24', 'A', 'CIA_29', 'C', '與 CIA_29 (人際適應力) C聯動：表現為「頑固的真誠者」。不願為了場面圓滑而掩飾想法，說話過於直接。警示：雖值得信任但易在社交中受挫，需主管保護其直言不諱的勇氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (300, 'CIA_24', 'A', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「純粹的自我」。完全不在乎社會評價，僅追求對得起自己。預測：測評結果極具參考價值，其反饋通常是未經修飾的真相。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (301, 'CIA_24', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「情緒透明者」。高興或憤怒都寫在臉上，絕不隱藏。管理建議：雖有情緒但因透明而好預測，主管能輕易判讀其當下的心理狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (302, 'CIA_24', 'C', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「盲從的組織人」。為了融入群體可以隨時修改自己的立場與偏好。管理警示：缺乏獨立見解，容易在團隊中形成集體盲思（Groupthink）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (303, 'CIA_24', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「精明的合約者」。表面表現得不在意，實則內心精密計算每一分回報。警示：一旦感到不公，會使用非直接的方式進行報復或怠工。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (304, 'CIA_24', 'C', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「圓滑的變色龍」。擅長在不同場合展現不同的人格面具以獲取利益。預測：適合業務開發或公共關係，但內部管理時需警惕其承諾的真實度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (305, 'CIA_24', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「隱性特權索求者」。內心認為自己高人一等，但在外表上會包裝成平易近人的樣子。管理風險：當其特權未獲滿足時，會展現出劇烈的被動攻擊（Passive-aggressive）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (307, 'CIA_25', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「組織的榮譽戰士」。將個人成功與團隊勝敗深度綁定。預測：在競爭激烈的市場中，會為了團隊達標而爆發驚人鬥志，是優質的部門主管人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (308, 'CIA_25', 'A', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「公平的守護者」。追求集體利益的同時堅持公正不阿，防止團隊內部的分配不均。預測：在管理崗位上能極大化團隊信任感，降低內耗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (309, 'CIA_25', 'A', 'CIA_14', 'A', '與 CIA_14 (謙虛) A聯動：表現為「無私的貢獻者」。願意默默付出不搶功，將光環留給團隊。管理建議：是建立高凝聚力文化的靈魂人物，需適時公開表揚其貢獻，以免其被忽視。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (310, 'CIA_25', 'A', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「逆境中的黏著劑」。在團隊面臨危機時，其強大的歸屬感會轉化為支撐同僚的韌性。預測：能有效防止團隊在壓力下瓦解。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (311, 'CIA_25', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「排外的護城河」。雖對團隊忠誠，但認為自己的小圈子應享有優於其他部門的特權。警示：易引發跨部門協作的衝突。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (312, 'CIA_25', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「專業的獨行俠」。工作極度負責，但只管好自己的事，不參與團隊事務。管理建議：適合獨立研究或專家職位，不宜強迫其負責團建。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (313, 'CIA_25', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「職場僱傭兵」。僅視組織為跳板，缺乏忠誠度。警示：隨時可能為了更高待遇離職，甚至帶走核心資源，需加強競業條款與資安控管。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (314, 'CIA_25', 'C', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「孤傲的顛覆者」。點子極多但常挑戰既有團隊共識。預測：其創新可能因缺乏群體支持而難以落地，需配備溝通力強的搭檔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (315, 'CIA_25', 'C', 'CIA_26', 'A', '與 CIA_25 (集體意識) C 與 CIA_26 (同理心) A：表現為「選擇性關懷者」。同情個體，但對抽象的組織利益無感。行為預測：會為了下屬的私事而違反公司規章。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (316, 'CIA_25', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「計較的交易者」。對個人利益分毫不讓，完全依照合約行事。管理建議：以明確的獎酬與關鍵績效指標（KPI）來對話，勿談願景。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (317, 'CIA_25', 'C', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「圓滑的投機客」。表面人緣極佳，實則內心與組織極度疏離。警示：具備強大的帶風向能力，若對公司不滿，會成為潛在的輿論隱憂。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (318, 'CIA_25', 'C', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「自嗨的工作狂」。對工作本身充滿熱愛，但對團隊合作或組織規範感到煩躁。預測：是高產出的個人工作者，但不具備管理潛質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (319, 'CIA_26', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「溫暖的執行者」。在追求工作產出的同時，會極力避免對他人造成困擾或負擔。預測：是極佳的團隊導師，能以身作則且耐心引導後進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (320, 'CIA_26', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「周全的協調家」。在做決定前會細膩評估對相關人員的心理影響。管理建議：適合處理組織內複雜的人事異動或高難度的客戶關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (321, 'CIA_26', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「情感起伏大的照顧者」。雖極具愛心但情緒容易受他人影響。警示：容易因為過度同情而做出不理智的承諾，需注意心理邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (323, 'CIA_26', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「情感敏感者」。對外界情緒極度敏銳，容易感同身受但也容易被他人負能量引燃。風險：在高壓負面環境中極易產生情緒倦怠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (324, 'CIA_26', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「冷酷的攀登者」。目標感極強且無視他人痛苦，視團隊成員為達成目標的工具。警示：高產出但伴隨高流失，需注意其對組織氛圍的破壞。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (325, 'CIA_26', 'C', 'CIA_06', 'A', '與 CIA_06 (條理性) A聯動：表現為「無情的標準作業機器」。凡事講究程序與邏輯，對他人的情緒訴求感到不耐與困惑。管理建議：適合處理冷冰冰的數據與流程，不宜負責第一線客服。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (326, 'CIA_26', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「掠奪型操縱者」。了解他人弱點（認知同理強）但不在乎其感受（情感同理弱），並藉此進行社交操弄。風險：職場霸凌的高潛在對象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (327, 'CIA_26', 'C', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「鐵石心腸的倖存者」。能在混亂中保持冷靜，不被哀兵政策所動。預測：在執行裁員或重大改革等痛苦決策時，能展現出極強的心理剛性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (328, 'CIA_26', 'C', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「精確的會計師人格」。只看數據與對等回報，不談人情。管理建議：以事實與契約為對話基礎，任何情感訴求對其皆無效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (329, 'CIA_26', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「自我中心的特權者」。認為全世界應繞著他轉，完全無視他人需求。警示：對團隊合作極具毀滅性，需建立明確的人際邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (330, 'CIA_27', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「無私的耕耘者」。不僅做事負責，且不計較短期得失。預測：在初創期或資源匱乏的專案中，是最穩定的戰力，不會因獎金遲發而輕易動搖。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (331, 'CIA_27', 'A', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「組織奉獻者」。願意為了團隊成功而超時工作或共體時艱。管理建議：應定期給予精神激勵與長期承諾，防止其因長期被「佔便宜」而最終崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (332, 'CIA_27', 'A', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「熱情的志工心態」。工作本身就是回報，對薪酬以外的價值（如成就感）極度重視，是企業文化的穩定核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (333, 'CIA_27', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「精明的績效導向者」。追求成功，但每一步都要求相對應的報酬。管理警示：若制度無法提供「即時且優渥」的反饋，其動能會迅速消失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (334, 'CIA_27', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「風險與收益的精算師」。在投入任何心力前會先精密估算 ROI。預測：極少做白工，但也可能因此錯失需要先行投入的創新機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (336, 'CIA_27', 'C', 'CIA_32', 'A', '與 CIA_27 (權益公平感) C 與 CIA_32 (心理特權) A：表現為「職場霸凌或特權索求者」。認為付出是應得的，但回報必須遠超常人。管理風險：會破壞團隊的和諧與公平認知。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (337, 'CIA_27', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「戴著面具的交易者」。表面客氣，實則內心精密計算每一分得失。警示：通常在離職那天主管才發現其對薪資或福利積怨已久。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (338, 'CIA_27', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「易怒的維權者」。對微小的不公（如午餐津貼少了十元）會有極大的負面情緒反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (339, 'CIA_28', 'A', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「團隊的向心力來源」。不僅認同團體，且會公開表達對同事協助的感激。預測：能極大化團隊成員的心理回報感，降低離職意願。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (340, 'CIA_28', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「真誠的共感者」。能敏銳感知他人的付出並給予溫暖回饋。管理建議：適合作為團隊領導者或 HR，能營造極佳的工作氛圍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (341, 'CIA_28', 'A', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「良性循環的發動機」。樂於付出且感激所得，不會斤斤計較。預測：在資源有限的環境下，仍能保持正向積極的心態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (342, 'CIA_28', 'A', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「純粹的感恩者」。其感激是發自內心的珍惜，而非社交辭令。預測：其建立的人際關係極為穩固且深厚，具備高度信任度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (343, 'CIA_28', 'A', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「高韌性的樂觀派」。習慣從挑戰中看見學習的機會與他人的幫助。行為預測：面對挫折時復原極快，且能帶動團隊維持士氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (344, 'CIA_28', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「理所當然的索求者」。認為他人的幫助是應得的，極少表達謝意。警示：會迅速消磨團隊的合作熱情，導致周遭同事產生被剝削感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (345, 'CIA_28', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「功利的表演者」。僅在對自己有利時才表現出感謝。風險預測：其人際關係往往是短暫且具備目的性的交易關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (346, 'CIA_28', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「自我中心的攀登者」。極度關注個人目標與成功，容易忽略過程中他人的支援與貢獻。管理警示：容易造成「收割成果」的負面印象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (347, 'CIA_28', 'C', 'CIA_27', 'C', '與 CIA_27 (權益公平感) C聯動：表現為「計較的分配者」。更在意自己「沒得到什麼」而非「得到了什麼」，容易對現狀感到不滿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (348, 'CIA_28', 'C', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「傲慢的專家」。將成功完全歸功於個人能力，忽視環境因素與同儕協助。管理風險：難以聽取他人建議，協作難度高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (349, 'CIA_29', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「目標導向的社交家」。能為了達成商業目標而精準調整與不同利害關係人的溝通風格。預測：極具商務談判潛力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (350, 'CIA_29', 'A', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「圓滑的談判專家」。在社交適應的同時保持警覺與風險意識。管理建議：適合作為高階採購或涉及重大利益的外部對接人。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (351, 'CIA_29', 'A', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「變色龍般的操縱者」。具備極高的適應力但動機不純。警示：能輕易贏得各方信任，但需警惕其利用社交技巧進行政治操弄。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (352, 'CIA_29', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「變革的推客」。能向不同部門的保守者推銷創新的點子，透過調整語境降低變革阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (354, 'CIA_29', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「優雅的權利追求者」。雖然內心自負，但懂得透過社交手段（偽裝適應）來獲得其想要的特權待遇。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (355, 'CIA_29', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「耿直的模範生」。做事極其到位但做人缺乏彈性，容易在與「風格不合」的同事協作時產生嚴重摩擦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (356, 'CIA_29', 'C', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) A聯動：表現為「木訥的正人君子」。堅持原則且不屑於社交包裝，這類人值得信賴但可能在複雜的職場政治中被邊緣化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (357, 'CIA_29', 'C', 'CIA_14', 'A', '與 CIA_14 (謙虛) A聯動：表現為「隱形的技術專家」。不愛社交也不愛表現，傾向於窩在自己的舒適圈。管理建議：適合獨立技術鑽研，不宜負責外務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (358, 'CIA_29', 'C', 'CIA_28', 'A', '與 CIA_28 (感謝) A聯動：表現為「內斂的知恩者」。內心感激他人但不知如何適當地表達或與人互動，導致其社交意圖常被誤解。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (359, 'CIA_29', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「人際火藥桶」。社交適應度低且情緒控制差，易因他人的行為不符預期而直接爆發衝突。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (360, 'CIA_30', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「終極執行者」。不僅做事細心，且對結果負百分之百的責任。預測：是組織中最不需要追蹤進度的員工，其承諾即等於結果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (361, 'CIA_30', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「熱血的救火隊」。雖行為易衝動出錯，但出錯後會第一時間承擔並拼命補救。管理建議：應肯定其擔當，同時輔導其降低出錯率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (362, 'CIA_30', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「零瑕疵的承諾者」。對自己要求極高，且決不容許因個人疏忽導致計畫失敗。預測：產出品質極高，但心理壓力極大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (363, 'CIA_30', 'A', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「職場清流」。堅持正道且對行為後果負責。預測：在面對利益誘惑或灰色地帶時，能基於強烈的責任感與道德感守住底線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (364, 'CIA_30', 'A', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「不倒的基石」。在逆境中不僅能自保，還會因為自覺有責任「把事做好」而撐起團隊。管理建議：適合擔任關鍵專案的負責人（Owner）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (365, 'CIA_30', 'A', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) C聯動：表現為「結果導向的破局者」。不在乎死板流程，甚至會為了確保「事情做好」而微調規則。預測：雖有違規風險，但其初衷是為了達成最終目標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (367, 'CIA_30', 'C', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「滑頭的操縱者」。擅長透過文字遊戲或社交技巧規避責任，發生問題時總是第一個「消失」或「撇清」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (368, 'CIA_30', 'C', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「樂天的甩鍋者」。遇到問題不覺得是大事，樂觀地認為「船到橋頭自然直」，導致問題持續擴大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (369, 'CIA_30', 'C', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「依賴團體的成員」。認同團隊但缺乏個人當責感，習慣躲在集體決策背後，缺乏獨立承擔的勇氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (370, 'CIA_30', 'C', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「職場巨嬰」。認為自己應得一切，但不願為任何失敗負責。警示：極度破壞團隊士氣，需建立明確的 KPI 責任制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (371, 'CIA_31', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「進取型精英」。追求成功的同時，將自我提升視為達成目標的必要路徑。預測：會主動尋求回饋並迅速修正弱點，成長速度極快。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (372, 'CIA_31', 'A', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「謙遜的求知者」。雖對目前能力缺乏信心，但具備強烈變強的渴望。管理建議：是最佳培訓對象，只要給予資源，其回報率極高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (373, 'CIA_31', 'A', 'CIA_16', 'A', '與 CIA_16 (希望) A聯動：表現為「願景實踐者」。不僅渴望成長（31），且具備設計成長路徑的能力（16）。預測：能自我規劃職涯路徑，不需要組織過多干涉。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (374, 'CIA_31', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「終身進化的變革者」。將創新視為一種學習與成長的機會。預測：在技術更迭極快的產業中，能始終保持競爭力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (375, 'CIA_31', 'A', 'CIA_23', 'A', '與 CIA_23 (獨創性) A聯動：表現為「尋求獨特發展的創意人」。渴望發展出具備高度個人特色與原創性的技能體系。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (376, 'CIA_31', 'A', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「自律的修煉者」。基於責任感認為自己有義務「變得更好」以應對工作。預測：是組織內部轉型、接班人計畫的首選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (377, 'CIA_31', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「穩定的守成勞動者」。做事負責但拒絕改變。警示：雖能處理現有工作，但若職責範疇發生質變，其適應困難度會極高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (378, 'CIA_31', 'C', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「停滯的自負者」。認為現有能力已足夠，缺乏進一步發展的動力。管理風險：容易產生職場僵化，甚至抗拒新的數位工具或流程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (379, 'CIA_31', 'C', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) C聯動：表現為「利潤導向的現狀者」。對成長本身無感，成長的動力僅來自於金錢激勵。管理建議：需將培訓與獎金掛鉤，否則其學習意願極低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (380, 'CIA_31', 'C', 'CIA_15', 'C', '與 CIA_15 (心理資本) C聯動：表現為「心灰意冷的被動者」。對自我發展持悲觀態度，不相信努力可以改變現狀。警示：是組織中典型的「負資產」，需注意其消極情緒擴散。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (381, 'CIA_31', 'C', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「單一技能的狂熱者」。對目前的工作很有熱情，但不願意跳出舒適圈去學習跨領域技能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (382, 'CIA_32', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「自負的野心家」。追求高成就，但認為組織必須先給予資源或特權作為前提，若不符合其「高標待過」則拒絕投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (383, 'CIA_32', 'A', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「精英主義者」。極度自信且認為自己應高人一等。管理風險：容易挑戰主管權威，認為既有規範不適用於自己。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (384, 'CIA_32', 'A', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「掠奪型員工」。不僅追求特權（32），且缺乏謙遜與誠實（10），可能為了獲取特殊利益而損人利己。警示：職場舞弊的高潛在群組。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (385, 'CIA_32', 'A', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「權力操縱者」。擅長透過政治手段或欺騙來維持其特權地位。風險預測：會破壞團隊的公平競爭環境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (386, 'CIA_32', 'A', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「傲慢的索求者」。完全不隱藏自己的優越感，對其他「平庸」的同事缺乏尊重。行為預測：極易引發人際衝突，團隊凝聚力殺手。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (387, 'CIA_32', 'A', 'CIA_27', 'C', '與 CIA_27 (權益公平感) C聯動：表現為「不滿足的貪婪者」。對回報極度敏感，且永遠覺得自己拿得不夠多。管理建議：需建立明確的法制化契約，限制其特權索求。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (388, 'CIA_32', 'A', 'CIA_28', 'C', '與 CIA_28 (感謝) C聯動：表現為「忘恩負義的受益者」。視他人的幫助與公司的獎勵為理所當然，完全缺乏感激之心。預測：難以建立長期的情感連結，員工忠誠度低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (389, 'CIA_32', 'A', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「職場火藥桶」。一旦未獲得預期的優待，會立刻產生劇烈的挫折感與憤怒情緒，出現被動攻擊行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (390, 'CIA_32', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「默默耕耘的典範」。不求特權，只求將事情做好。管理預測：是組織中最穩定、最可靠的「樑柱」，通常具備高滿意度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (391, 'CIA_32', 'C', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「無私的團隊成員」。願意為了群體利益隱藏自我需求。管理建議：應主動給予這類人應有的獎酬，以免其被高特權者「吃掉」資源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (392, 'CIA_32', 'C', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「高當責的勞動者」。相信回報源於責任與努力（30），而非身分或特權（32）。預測：具備最健康的績效觀念。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (393, 'CIA_33', 'A', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) A聯動：表現為「極度在意形象的正直者」。雖然內在誠實，但會過度修飾言辭以符合社會規範。管理預測：其測評結果可能比真實情況更「完美」，需結合面談觀察。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (394, 'CIA_33', 'A', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「高階偽裝者」。具備操縱傾向（11C）且極度在意正面形象（33A）。風險預測：極擅長職場政治，會精準提供主管「想聽的內容」，真實動機難以察覺。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (395, 'CIA_33', 'A', 'CIA_24', 'C', '與 CIA_24 (真實性) C聯動：表現為「人設經營者」。其展現的自我高度符合組織期望，但與內在價值觀可能嚴重脫節。警示：離職風險極具隱蔽性，往往在崩潰前一刻都表現得非常配合。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (397, 'CIA_33', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「隱性自負者」。內心認為應享特權，但為了維持良好形象（33A）會掩飾這種索求。管理風險：當其優越感未獲滿足時，會產生嚴重的被動攻擊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (398, 'CIA_33', 'C', 'CIA_24', 'A', '與 CIA_24 (真實性) A聯動：表現為「坦蕩的求真者」。完全不在乎包裝，即便缺點也直白坦露。預測：此人的測評結果信效度極高，其呈現的數據即為真實的自我。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (399, 'CIA_33', 'C', 'CIA_29', 'C', '與 CIA_29 (人際適應力) C聯動：表現為「耿直的刺頭」。不在乎他人認可，也不願調整溝通方式以適應環境。管理建議：溝通成本高，但其反饋通常是最真實的「防腐劑」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (400, 'CIA_33', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「真實的火藥桶」。對不滿情緒毫不掩飾，不會為了維持社交和諧而壓抑怒氣。警示：衝突強度高，需注意其對團隊氛圍的直接衝擊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (401, 'CIA_33', 'C', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「鐵面無私者」。即便做法會得罪所有人，也會堅持正確的原則，因為他完全不被「社會期望」所左右。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (402, 'CIA_34', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「充滿激情的攀登者」。不僅想贏，且熱愛競爭與達標的過程。預測：在組織中能產生極大的正面渲染力，是帶動士氣的天然領袖。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (403, 'CIA_34', 'A', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「卓越的工匠」。對細節的苛求源於對工作的熱愛。預測：能產出具備「靈魂」的高品質成果，但在情緒過度投入時需注意燃盡風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (404, 'CIA_34', 'A', 'CIA_12', 'A', '與 CIA_12 (低物質傾向) A聯動：表現為「純粹的職人」。工作動機完全來自內在喜悅而非金錢回報。管理建議：應提供其高度的專業自主權，而非僅靠薪資激勵。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (405, 'CIA_34', 'A', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「韌性十足的熱愛者」。對工作的熱情使其能以樂觀心態看待挫折。預測：即便在組織動盪期，也能靠著內心對工作的喜愛而維持產能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (406, 'CIA_34', 'A', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「高效的玩家」。熱愛優化流程，將解決問題視為一種樂趣。預測：會不斷自發性地尋找「更聰明的工作方式」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (407, 'CIA_34', 'A', 'CIA_35', 'C', '與 CIA_35 (生活熱情) C聯動：表現為「典型的工作狂 (Workaholic)」。生活重心極度向工作傾斜。管理警示：雖短期產能極高，但需強制其休息以避免長期健康受損。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (408, 'CIA_34', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「枯燥的紀律執行者」。不愛工作但因盡責而完成任務。管理預測：產出穩定但缺乏創意與主動進取的能量，容易出現職業倦怠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (409, 'CIA_34', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「消極的防禦者」。對工作無感且過於謹慎，傾向於推諉變革。管理風險：容易成為組織轉型中的隱形阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (410, 'CIA_34', 'C', 'CIA_11', 'C', '與 CIA_11 (誠誠) C聯動：表現為「職場僱傭兵」。僅視工作為謀生工具，不惜透過操縱手段獲取最大利益。警示：對組織毫無忠誠度可言，隨時可能跳槽。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (411, 'CIA_34', 'C', 'CIA_27', 'C', '與 CIA_27 (權益公平感) C聯動：表現為「計較的打工仔」。不愛工作且對回報極度敏感。管理預測：稍有不公便會立刻消極怠工，管理成本極高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (412, 'CIA_34', 'C', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「迷惘的求學者」。渴望成長但目前的工作並非其所愛。管理建議：應評估其崗位適配性（Job Fit），考慮內部調動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (413, 'CIA_35', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「充滿生命力的開拓者」。不僅想贏，且過程中充滿感染力，能讓追隨者感到振奮。預測：極佳的業務與團隊領袖。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (414, 'CIA_35', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「熱情的火藥桶」。雖然活潑積極，但因活力過盛且缺乏控制力，容易在人際互動中顯得過於突兀。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (415, 'CIA_35', 'A', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「陽光的韌性者」。即使在逆境中也能靠著天生的熱情找到樂趣。預測：復原力極強，是組織內部最不容易心理受挫的群體。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (416, 'CIA_35', 'A', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「變革的發電機」。對新想法展現出純粹的熱愛，能以強大的動能推動從未嘗試過的專案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (417, 'CIA_35', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「溫暖的能量散播者」。其熱情是利他的，能帶動同僚共同追求更美好的生活與工作目標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (418, 'CIA_35', 'A', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「職業與生活高度融合的快樂者」。生命中的每一分鐘都在燃燒能量，離職風險與過勞感極低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (419, 'CIA_35', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「嚴肅的工蜂」。做事一絲不苟但缺乏活力與笑容。管理建議：應肯定其品質，但避免其負責需要大量感染力、公關或團隊動員的任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (420, 'CIA_35', 'C', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「頹廢的自我懷疑者」。既不信自己能做好，也對周遭事物缺乏熱情。警示：易產生憂鬱情緒，需高度關注心理健康。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (421, 'CIA_35', 'C', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「陰沉的防禦者」。對未來不抱期待，且行事風格暮氣沉沉。管理風險：容易成為團隊中負能量的擴散點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (422, 'CIA_35', 'C', 'CIA_28', 'C', '與 CIA_28 (感謝) C聯動：表現為「情感乾涸者」。對生活缺乏熱力，且對他人的好意也表現得冷淡、無感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (423, 'CIA_35', 'C', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「焦慮的厭世者」。生活熱情低且易受刺激。預測：在組織中常以抱怨者的身分出現，難以建立和諧關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (424, 'CIA_36', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「焦慮的完美主義執行者」。雖然做事細緻，但一旦進度受阻或出現錯誤，情緒會迅速波動，產生巨大的心理內耗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (425, 'CIA_36', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「職場火藥桶」。情緒燃點低且缺乏行為剎車，容易在衝突中脫口而出傷人的話或做出衝動決策。風險：人際關係高度緊張。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (426, 'CIA_36', 'A', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「自尊極度敏感者」。因自視甚高，任何指正或不同意見都會被其解讀為冒犯，引發強烈的防衛性憤怒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1, 'CIA_01', 'A', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：展現極強的紀律與成功慾望，是高產出的明星員工。管理上需注意其可能為了目標忽略身心平衡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (10, 'CIA_01', 'A', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) 低分聯動：表現為「高度功利驅動」。自律是為了換取物質回報或地位，若獎酬制度不明確，其穩定性會下降。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (37, 'CIA_02', 'A', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「自我進化者」。將工作成就視為個人成長的一部分，極度看重培訓與發展空間，是優質的儲備幹部。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (38, 'CIA_02', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「權利索求者」。認為自己的努力應換取特殊優待與特權。若管理上無法給予特殊感，其工作配合度會降低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (69, 'CIA_04', 'A', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「模範生人設」。高度社會化，會刻意表現出符合主流價值期待的樣子，需觀察其私下是否能維持一致。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (71, 'CIA_05', 'A', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「鋼鐵般的穩定者」。具備極高的自律性與自我控制力，是高難度長線專案的最佳負責人。管理預測：產出極其穩定，極少因個人情緒影響工作進度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (99, 'CIA_06', 'C', 'CIA_07', 'A', '與 CIA_06 (條理性) C 與 CIA_07 (完美主義) A：表現為「內在衝突的完美者」。渴望完美但缺乏建立次序的能力。預測：會因環境混亂而焦慮，卻又不知如何整理，需他人協助建立架構。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (104, 'CIA_07', 'A', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「冒名頂替症候群 (Imposter Syndrome)」。設定了極高標準卻不相信自己能達成。管理風險：極度焦慮，即使表現優異仍深感挫折，需頻繁情感支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (128, 'CIA_09', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「自負的修煉者」。因具備極強自律能力而認為自己應獲得特殊优待，並容易對不自律的下屬展現出缺乏同理心的批判。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (130, 'CIA_09', 'C', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「受罪惡感驅動者」。內心極想做好（盡責）但行為上卻難以抵抗誘惑（低自律）。預測：常在最後一刻趕工，並在工作過程中伴隨高度焦慮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (159, 'CIA_11', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「完美的社交包裝師」。擅長透過塑造樂觀形象來獲得認可，實則行為充滿目的性。其測評結果可能存在高度偽飾，需多方查核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (164, 'CIA_12', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「目標明確的掠奪者」。其成就動機源於對財富與地位的渴望。管理警示：只要有更高薪的對手招手，離職風險極高，需建立績效獎金掛鉤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (189, 'CIA_14', 'C', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「過度自負的樂觀」。相信自己無所不能且未來必勝。警示：容易忽略客觀風險警訊，導致組織在重大決策上出現盲目的毀滅性策略。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (212, 'CIA_16', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「盲目的攀登者」。極想成功（成就動機）但缺乏達成目標的路徑規劃能力（低希望）。管理警示：容易像無頭蒼蠅般瞎忙，需主管協助給予明確的操作指引。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (218, 'CIA_17', 'A', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「過度擴張的冒險家」。相信自己能搞定一切但行為容易失控。警示：容易承諾超過自身負荷的任務，需主管協助控管承諾邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (224, 'CIA_17', 'C', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「焦慮的攀登者」。非常想成功（成就動機）但內心不信自己做得到。行為預測：工作中伴隨高度壓力與自我懷疑，需頻繁獲得成功經驗來補足信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (248, 'CIA_19', 'C', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「韌性支撐的求存者」。雖然對未來不樂觀，但遭受打擊時能硬撐並站起來。管理建議：屬於「實戰型」人才，雖然口頭消極，但行為上極其堅韌。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (276, 'CIA_22', 'A', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「表面服從者」。口頭高度配合公司規則，實則利用規則死角謀求私利。警示：此組合最具隱蔽性，需透過非正式溝通管道瞭解其真實動向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (277, 'CIA_22', 'A', 'CIA_26', 'C', '與 CIA_26 (同理心) C聯動：表現為「死板的鐵面人」。執行制度時毫不留情，無視他人苦衷。管理風險：極易在基層引發反感，需留意其與團隊成員的磨合狀況。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (297, 'CIA_24', 'A', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「組織的道德羅盤」。其正直源於深層的內在信念而非恐懼懲罰。預測：在企業面臨倫理抉擇時，會是堅持價值觀而不妥協的關鍵力量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (306, 'CIA_24', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「完美的模範人設」。行為完全符合職場教科書要求，但缺乏靈魂與感染力。管理建議：需透過深度對話挖掘其真實需求，防止其突然的職業燃盡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (322, 'CIA_26', 'A', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「仁慈的裁判」。堅持原則的同時，能以令人舒服的方式傳達紀律。預測：在管理崗位上能將「法、理、情」完美結合，深獲下屬愛戴。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (428, 'CIA_36', 'A', 'CIA_29', 'C', '與 CIA_29 (人際適應力) C聯動：表現為「社交防禦者」。不擅長管理社交緊張關係，且情緒容易被他人激發，常導致溝通破裂。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (429, 'CIA_36', 'A', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「憤怒的特權索求者」。認為應受優待，一旦願望落空，會表現出極高的情緒激發強度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (430, 'CIA_36', 'C', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「冰冷的策略家」。情緒極度穩定且思維嚴謹，在危機時刻能保持驚人的冷靜，進行最理性的判斷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (431, 'CIA_36', 'C', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「情緒穩定的樂天派」。面對煩惱時反應淡定，能以積極且平穩的心態尋求解決方案，是團隊的定海神針。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (432, 'CIA_36', 'C', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「專注的高效機器」。不被瑣事干擾情緒，能持續維持產出動能，即使在混亂的變動中也不會自亂陣腳。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (433, 'CIA_36', 'C', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「溫和的傾聽者」。具備共情能力但自身情緒穩定，能包容他人的負面情緒而不受影響。管理建議：適合作為衝突調解人。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (434, 'CIA_36', 'C', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「得體的職場專業人士」。為了形象與本性，展現出極高的修養與情緒控制力，極少流露負面情感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (335, 'CIA_27', 'C', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「心灰意冷的離職預備軍」。在挫折中感到不公平時，修復能力極差。警示：一旦其心裡那把「秤」失衡，會很快進入安靜離職（Quiet Quitting）狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (353, 'CIA_29', 'A', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「高 EQ 的和諧大師」。既能感同身受（同理），又能靈活應對（適應）。預測：是組織中處理人際衝突、建立跨部門信任的靈魂人物。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (366, 'CIA_30', 'C', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「推諉的天才」。自認能力強，因此一旦出錯，會傾向於歸咎環境、系統或同事太笨，而非自我反省。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (396, 'CIA_33', 'A', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「社交變色龍」。適應力強且極度在意他人評價，是極佳的公共關係（PR）或服務業人選，但在內部管理時需警惕其表裡不一。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (427, 'CIA_36', 'A', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「脆性情緒反應者」。面對挫折時情緒反應劇烈且難以自我修復（18C），容易陷入長期的低落或憤怒中。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (869, 'ANI_01', 'A', 'ANI_02', 'A', '與 ANI_02 (韌性) A聯動：表現為「冷靜的危機分析官」。在高壓或挫折中，仍能維持極高的邏輯穩定性與結構化思考品質（01A）。預測：在組織混亂期是極佳的解題者，不會因情緒壓力導致決策邏輯崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (870, 'ANI_01', 'A', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A聯動：表現為「多維度的邏輯大師」。具備強大的結構拆解能力，且能根據新資訊快速切換不同的分析模型。預測：極具敏捷開發潛力，能快速修正分析偏差，而非固執於單一邏輯。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (871, 'ANI_01', 'A', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A聯動：表現為「務實的發明家」。點子具備強大的邏輯支撐與可行性結構。管理建議：其提議通常不是空談，適合負責將抽象願景轉化為可執行的產品原型或專案藍圖。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (872, 'ANI_01', 'A', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) A聯動：表現為「AI應用的戰略家」。能從邏輯層面理解 AI 模型，並有效評估其在實務中的價值與風險。預測：是組織數位轉型中的核心評估者，能精準判斷技術導入的邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (873, 'ANI_01', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A聯動：表現為「全局架構師」。不僅能拆解細節模式，還能看透各子系統間的相互依存關係。管理建議：適合擔任流程優化或中長程戰略規劃的高層幕僚。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (874, 'ANI_01', 'A', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A聯動：表現為「精密邏輯控制者」。在複雜分析中能同時確保每一環節的極高精確度。警示：容易出現過度分析（Analysis Paralysis），在追求邏輯完美時可能犧牲交付速度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (875, 'ANI_01', 'A', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A聯動：表現為「真理的檢驗者」。具備結構化分析力且能審慎評估資訊來源的可信度，極難被假訊息或單一觀點誤導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (876, 'ANI_01', 'A', 'ANI_22', 'C', '與 ANI_22 (高效決策) C聯動：表現為「猶豫的專家」。邏輯分析極強，但面對模糊情境時因追求更多數據而難以定案。管理建議：需由外部力量設定決策期限或提供權重框架。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (877, 'ANI_01', 'C', 'ANI_05', 'A', '與 ANI_05 (自主領導) A聯動：表現為「努力但盲目的執行者」。自我驅動極強，但因缺乏結構化拆解能力，常在錯誤的方向上拼命。管理建議：需主管協助定義「對的問題」，並提供明確的任務清單。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (878, 'ANI_01', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A聯動：表現為「挫折感強的高標者」。渴望卓越但苦於找不到解決複雜難題的邏輯路徑。風險：容易因產出品質達不到自我期望而陷入自我懷疑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (879, 'ANI_01', 'C', 'ANI_13', 'A', '與 ANI_13 (好奇心) A聯動：表現為「資訊的採集者而非整合者」。對新奇事物有熱情，但僅停留於表面探索，難以深入分析其內在模式或商業價值。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (880, 'ANI_01', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A聯動：表現為「穩定的守成者」。在標準化任務中極其可靠，但在面對需要複雜分析的新型任務時會感到手足無措。管理建議：應提供標準作業流程（SOP）來彌補其分析短板。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (881, 'ANI_01', 'C', 'ANI_22', 'A', '與 ANI_22 (高效決策) A聯動：表現為「直覺型決策者」。決策極快，但通常缺乏邏輯與證據支撐，屬高風險型決策風格。警示：在變動大且容錯率低的環境中極具危險性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (882, 'ANI_01', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A聯動：表現為「包裝精美的平庸者」。測評中展現高度合規形象，但在實際需要硬核分析的場景中會顯露支撐力不足。面談重點：應透過具體行為案例考察其邏輯拆解過程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (883, 'ANI_02', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A聯動：表現為「冷靜的解題戰術家」。在高度壓力和挫折中，仍能運用邏輯拆解資訊並識別模式。預測：在組織危機中能產出具備結構化邏輯的復原計畫，不因情緒壓力而導致思維癱瘓。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (884, 'ANI_02', 'A', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A聯動：表現為「動態適應的專家」。心理彈性強且能迅速切換思考策略以應對新挑戰。預測：面對突發變革時，能最快從舊框架中跳出，展現出極高的問題解決多樣性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (885, 'ANI_02', 'A', 'ANI_05', 'A', '與 ANI_05 (自主領導) A聯動：表現為「不屈的開拓領袖」。具備強烈主動性 且在不確定環境中仍能維持動能。管理建議：適合作為新業務的發起者，因為他們在遇到拒絕或瓶頸時會自發復原並引導他人前行。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (886, 'ANI_02', 'A', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A聯動：表現為「愈挫愈勇的精進者」。追求極致成果的熱情結合高復原力，將挫折視為優化的必要過程。預測：能維持長期的卓越表現而不倦怠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (887, 'ANI_02', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A聯動：表現為「宏觀的穩定者」。能從整體連動的角度理解局部挫折，並維持心理穩定。管理建議：適合作為變革管理的領導者，能穩定軍心並引導團隊看見長遠願景。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (888, 'ANI_02', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A聯動：表現為「危機指揮官」。能在變動中果斷決策並承擔風險，不因不確定性而動搖。預測：具備強大的領袖氣場，能在壓力和失敗面前維持執行效率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (889, 'ANI_02', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A聯動：表現為「焦慮的邏輯者」。分析能力強但心理防禦弱。警示：一旦遇到挫折，情緒波動會干擾其結構化推理過程，導致雖然看見問題卻無法有效行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (890, 'ANI_02', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A聯動：表現為「玻璃心的完美主義者」。渴望卓越但對失敗的容忍度極低。風險：極易因一次失敗而陷入長期的消沉與自我懷疑，需頻繁獲得肯定來支撐動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (891, 'ANI_02', 'C', 'ANI_11', 'A', '與 ANI_11 (同理心) A聯動：表現為「易碎的共感者」。具備情感連結但心理資源容易耗竭。管理警示：容易被團隊的負面情緒淹沒，面對人際衝突時復原極慢。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (892, 'ANI_02', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A聯動：表現為「防禦性的守成者」。值得信賴但極度排斥任何可能導致挫折的變革。管理建議：適合放在變動性極低的崗位，一旦面臨轉型需給予大量心理緩衝。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (893, 'ANI_02', 'C', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A聯動：表現為「脆弱的精算師」。追求細節完美，但一旦出錯便會產生劇烈的挫折反應。行為預測：出錯時可能出現逃避行為，而非積極尋求解決路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (894, 'ANI_02', 'C', 'ANI_21', 'A', '與 ANI_21 (社交智商) A聯動：表現為「社交防禦者」。雖具備社交洞察力，但若在社交場合受挫，會迅速退縮並難以再次主動建立聯繫。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (895, 'ANI_02', 'C', 'ANI_23', 'C', '與 ANI_23 (社會期望反應) C聯動：表現為「真實的消極者」。不屑偽裝且面對困難時反應消極。警示：在遭遇不順時會直接表露挫敗感，對組織氛圍具備強烈的負面擴散效應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (896, 'ANI_03', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A聯動：表現為「多維度的邏輯大師」。不僅能拆解模式，還能隨環境變動切換多種邏輯分析框架。預測：在複雜變局中能產出多套邏輯自洽的替代方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (897, 'ANI_03', 'A', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A聯動：表現為「變革的發動機」。思維切換快（03A）且行為調整即時（04A）。預測：在組織轉型期適應極快，能最先從舊模式轉入新賽道，是敏捷開發的核心人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (898, 'ANI_03', 'A', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A聯動：表現為「流變的創意者」。不僅想法新穎，且能根據回饋快速修改創意路徑。管理建議：適合負責需要高度迭代的產品開發或概念設計任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (899, 'ANI_03', 'A', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) A聯動：表現為「AI 共生者」。能快速適應 AI 工具帶來的典範轉移，主動調整工作流程以極大化科技價值。預測：是推動組織數位轉型的先鋒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (900, 'ANI_03', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A聯動：表現為「動態的策略家」。能看見全局關聯，並靈活調整局部策略以維持系統最優平衡。管理建議：適合作為高階策略幕僚，處理高複雜度的跨部門議題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (901, 'ANI_03', 'A', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A聯動：表現為「理性的修正者」。會批判性檢視證據，一旦發現既有策略有誤，能毫無偏執地立即切換思考方向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (902, 'ANI_03', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A聯動：表現為「敏捷的決策指揮」。決策快且具備應變力，能在資訊變動時果斷修正決策路徑，避免組織陷入路徑依賴（Path Dependence）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (903, 'ANI_03', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A聯動：表現為「執著的專家」。邏輯分析力強，但固守單一模型。風險：在產業環境巨變時，容易因拒絕思考替代路徑而導致邏輯優勢失效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (904, 'ANI_03', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A聯動：表現為「僵化的精進者」。追求完美，但只認同「唯一的正確方法」。警示：在標準化流程中表現優越，但在需要靈活變通的非標專案中會顯得笨拙。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (905, 'ANI_03', 'C', 'ANI_13', 'A', '與 ANI_13 (好奇心) A聯動：表現為「矛盾的收集者」。對新資訊有熱情，但實際運用時仍傾向回歸舊有習慣（03C）。管理建議：其好奇心多停留於表面，需主管引導其將新資訊內化為具體行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (906, 'ANI_03', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A聯動：表現為「穩定的守位者」。在既定規範內極其可靠，但對「不按牌理出牌」的變革感到焦慮。管理建議：適合法務、審計等需要高度穩定思考路徑的職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (907, 'ANI_03', 'C', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A聯動：表現為「細節的困獸」。對準確度要求極高，但當環境不確定時，會因無法調整規則而陷入對瑣碎細節的無效糾結。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (908, 'ANI_03', 'C', 'ANI_22', 'A', '與 ANI_22 (高效決策) A聯動：表現為「固執的快決策者」。決定下得快，但極難回頭修正方向。風險：一旦決策前提發生變化，容易因反應遲緩（03C）而導致嚴重損失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (909, 'ANI_03', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A聯動：表現為「表面服從的保守派」。口頭上配合變革（23A），但思維與實際做法仍偏好舊路（03C）。面談重點：應追問其對新策略的具體拆解與對策。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (910, 'ANI_04', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「數據驅動的變革者」。能快速拆解新環境下的邏輯與模式，並據此立即調整資源分配。預測：在組織轉型初期，能最快辨識出新舊邏輯的差異並產出具備結構化支持的行動方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (911, 'ANI_04', 'A', 'ANI_02', 'A', '與 ANI_02 (韌性) A 聯動：表現為「逆境中的生存大師」。面對變動產生的壓力與挫折能快速復原，並以積極回應代替消極抵抗。管理建議：適合作為高壓、高頻率變動專案的領軍人物。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (912, 'ANI_04', 'A', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「全方位的敏捷精英」。思維路徑與行為模式同步調整，完全不具備路徑依賴。預測：極具敏捷開發潛力，能在高度模糊與迭代的任務中維持極高的工作效能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (913, 'ANI_04', 'A', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「靈活的自我驅動者」。不需要主管頻繁指示，會自發根據變動目標調整自己的進度與目標。預測：適合遠距辦公或開拓性任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (914, 'ANI_04', 'A', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「流變的發明家」。點子新穎且能根據外部反饋立即優化創意，不固執於原始構思。管理建議：是推動產品快速原型開發（Prototyping）的核心戰力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (915, 'ANI_04', 'A', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) A 聯動：表現為「AI 共生先鋒」。能迅速掌握 AI 技術的迭代更新，並立即將其應用於調整現有工作流程，極大化產出效率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (916, 'ANI_04', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「敏捷指揮官」。在資訊有限且環境快速變遷下，能果斷定案並隨時根據最新情報修正決策路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (917, 'ANI_04', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「理論型學者」。雖然分析能力極強，但在執行層面轉向遲緩，容易陷入「分析癱瘓」，需主管推動其進入實踐階段。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (918, 'ANI_04', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「追求完美的守舊者」。極度在意外產出品質，但堅持使用熟悉的既有流程。警示：在遭遇範式轉移（Paradigm Shift）時會產生強烈的抵觸感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (919, 'ANI_04', 'C', 'ANI_13', 'A', '與 ANI_13 (好奇心) A 聯動：表現為「觀察者而非變革者」。對新資訊感興趣，但行為上仍偏好在安全、穩定的環境中進行探索，難以即時轉化為行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (920, 'ANI_04', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「穩定的守位者」。高度可靠但極度依賴 SOP。管理建議：在變革發生前需給予充分的預告與緩衝期，否則其一致性優勢會因焦慮而失效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (921, 'ANI_04', 'C', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「精確的緩慢者」。為了維持細節品質，在面臨變動時會顯得猶豫不決，不願為了速度犧牲其嚴格的準確標準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (922, 'ANI_04', 'C', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「剛性的決策者」。決策雖快但一旦定案極難轉彎，面對外部環境的動態修正能力較弱。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (923, 'ANI_04', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「表面配合的被動者」。口頭上同意改變以符合認可，但行為仍死守舊流程。面談重點：應追蹤其具體的行為調整紀錄。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (924, 'ANI_05', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「獨立的策略執行者」。不僅具備強大拆解問題的邏輯（01A），且能自發性地針對分析結果採取行動（05A）。預測：極具潛力成為專案負責人，能獨自完成從「問題發現」到「計畫實施」的全過程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (925, 'ANI_05', 'A', 'ANI_02', 'A', '與 ANI_02 (韌性) A 聯動：表現為「不屈的開拓者」。面對挫折時能自發性地尋求復原路徑（02A），且不需要他人安慰便能重新找回動能（05A）。管理建議：適合作為開拓新市場或應對高度不確定專案的先鋒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (926, 'ANI_05', 'A', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A 聯動：表現為「敏捷的自我進化者」。會根據環境變動主動調整優先順序（04A），而非等待主管告知方向（05A）。預測：在組織轉型期是極佳的活水，能迅速在混亂中找到自身定位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (927, 'ANI_05', 'A', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「高標準的自律大師」。對自我要求極高（08A），且這種動力源自內心，不因缺乏監督而降低品質（05A）。管理建議：給予高度自主權能發揮其最大效能，過度微管理（Micro-management）反而會損害其動力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (928, 'ANI_05', 'A', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) A 聯動：表現為「數位轉型自發者」。會主動探索如何將 AI 工具融入日常工作流程中（10A, 05A），不需要公司強制推行學習計畫。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (929, 'ANI_05', 'A', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「絕對可靠的獨當一面者」。不僅值得信賴（16A），且在承諾任務後能自主完成所有細節（05A）。預測：是組織中最不需要被追蹤進度的「放心指標」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (930, 'ANI_05', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果敢的執行指揮官」。具備強烈的所有權意識（05A），能果斷下達決策並對結果負全責（22A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (931, 'ANI_05', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「理論型顧問」。邏輯分析能力極強（01A），但缺乏將分析轉化為具體行動的推動力，傾向於「只說不做」（05C）。管理建議：需主管明確指派行動步驟或搭配高主動性的夥伴。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (932, 'ANI_05', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「被動的完美主義者」。渴望卓越（08A），但若缺乏外部明確的指示與目標設定，會因為猶豫不決而陷入停滯（05C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (933, 'ANI_05', 'C', 'ANI_13', 'A', '與 ANI_13 (好奇心) A 聯動：表現為「分散的探索者」。對新資訊有熱情（13A），但缺乏將其整合進具體職責的目標導向，容易在廣泛的學習中迷失主線（05C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (934, 'ANI_05', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「優秀的指令執行員」。在明確的規範下非常可靠（16A），但若任務模糊或缺乏主管督導，其產出會顯著下降（05C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (935, 'ANI_05', 'C', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「批判性的觀望者」。能看出問題所在（20A），但因為缺乏主動擔當的意識（05C），通常不會主動站出來提出解決方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (936, 'ANI_05', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「過度合規的溫順者」。在行為上高度追求認可與合規（23A），這反而削弱了其在灰色地帶進行自主決策的勇氣（05C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (937, 'ANI_06', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「邏輯說服者」。其影響力建立在嚴密的數據拆解與事實基礎上。預測：在面對高階決策者或工程技術團隊時，能以高度理性的結構贏得認可。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (938, 'ANI_06', 'A', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「靈活的遊說家」。能根據不同聽眾的需求快速調整說服策略（03A, 06A）。管理建議：適合作為跨國、跨領域專案的溝通橋樑，能克服認知隔閡建立共識。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (939, 'ANI_06', 'A', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「主動的變革推手」。具備強烈的所有權意識（05A），並會自發性地爭取資源與他人支持以達成目標（06A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (940, 'ANI_06', 'A', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「感性的共鳴領導」。說服過程極具溫度，能精準洞察對方需求並建立雙贏共識。預測：在團隊中具備極強的心理凝聚力，能推動員工自發性追隨。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (941, 'ANI_06', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「戰略架構說服者」。能從全局角度說明決策的必要性，說服他人配合整體的長遠發展。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (942, 'ANI_06', 'A', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「傑出的談判家」。能在複雜利益關係中運用影響力達成有利的協議，確保組織利益最大化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (943, 'ANI_06', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果敢的決策引導者」。決定下得快且能迅速爭取團隊認可（22A, 06A），降低決策落地時的阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (944, 'ANI_06', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「孤傲的數據專家」。邏輯分析能力極強（01A），但因缺乏說服技巧（06C），其精闢見解常因無法獲得共識而被束之高閣。管理建議：需為其配備強大的溝通介面或協助其簡化報告語言。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (945, 'ANI_06', 'C', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「懷才不遇的藝術家」。點子新穎（07A），但由於不擅長向外推銷與爭取認同（06C），其創新構思難以在組織內獲得資源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (946, 'ANI_06', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「孤軍奮戰的高標者」。自我要求極高（08A），但因無法帶動他人共同前行（06C），常導致自己過度工作而團隊卻無動於衷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (947, 'ANI_06', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「可靠的幕後工作者」。工作極度穩定且值得信任（16A），但在需要展現個人觀點或影響群體時傾向於退縮（06C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (948, 'ANI_06', 'C', 'ANI_18', 'A', '與 ANI_18 (協調溝通) A 聯動：表現為「被動的訊息傳遞者」。能清晰轉達工作指令（18A），但缺乏主動改變他人立場或化解異見的能力（06C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (949, 'ANI_06', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「合規的隨行者」。過度在意社會規範與認可（23A），使其不願在公共場合發表具衝突性或需要強力推動的觀點（06C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (950, 'ANI_07', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「務實的發明家」。不僅能產生新穎想法（07A），還能運用邏輯拆解並驗證其可行性（01A）。預測：其創新產出具備高度結構化，易於被組織轉化為具體的商業成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (951, 'ANI_07', 'A', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「多維度的創意者」。想法多樣且能根據反饋快速切換思考路徑（03A, 07A）。管理建議：適合作為產品迭代或概念驗證階段的核心人才，能不斷提供替代方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (952, 'ANI_07', 'A', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「具感染力的遠見者」。不僅有點子，且極度擅長向外推銷並說服他人認同其創新觀點（06A）。預測：能有效爭取創新資源，推動組織內的範式轉移。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (953, 'ANI_07', 'A', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「AI 賦能的藝術家」。能運用 AI 工具擴展個人創意邊界（10A），將科技視為靈感的放大器而非替代品。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (954, 'ANI_07', 'A', 'ANI_13', 'A', '與 ANI_13 (好奇心) A 聯動：表現為「廣博的探索家」。強烈的好奇心為創意提供源源不絕的異質素材。預測：擅長跨領域整合，能從看似不相關的領域提取概念應用於現有問題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (955, 'ANI_07', 'A', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「嚴謹的革新者」。在產生新想法的同時（07A），會客觀檢驗其證據支持與潛在偏誤（20A），避免流於「為創新而創新」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (956, 'ANI_07', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果敢的創意領導」。在多個新穎方案中能快速定案並承擔風險。管理建議：適合帶領需要快速突破的任務編組。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (957, 'ANI_07', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「卓越的優化者」。雖難以產生顛覆性新點子（07C），但極擅長分析現有模式並進行漸進式改良（01A）。管理建議：適合維護成熟系統，透過精確分析提升既有效率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (958, 'ANI_07', 'C', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「勤奮的既定路線執行者」。主動性高（05A），但行動高度依賴現有的 SOP 或標準規範，難以在模糊地帶自創方法（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (959, 'ANI_07', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「執著於傳統的高標者」。渴望卓越（08A），但追求方式傾向於「將舊方法做到極致」而非嘗試新途徑（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (960, 'ANI_07', 'C', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「穩健的全局守護者」。能看清系統關聯（15A），但面對系統性崩潰時，傾向於修補舊結構而非重新建構（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (961, 'ANI_07', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「組織的定時器」。極度可靠且穩定（16A），對任何偏離傳統做法、不具備預測性的點子感到排斥（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (962, 'ANI_07', 'C', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「精密的工匠」。專注於細節的精確與合規（17A），發散式思維極弱。風險：在需要破框思考的場合會顯得極度僵化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (963, 'ANI_07', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「高度社會化的傳統主義者」。行為追求社會認可與合規（23A），這進一步壓抑了其可能展現的獨特想法（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (964, 'ANI_08', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「精準的卓越者」。不僅追求高標準（08A），且具備強大的邏輯拆解能力（01A）來識別達成目標的關鍵路徑。預測：能產出具備高度結構化且品質卓越的成果，是組織中處理高難度核心任務的首選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (965, 'ANI_08', 'A', 'ANI_02', 'C', '與 ANI_02 (韌性) C 聯動：表現為「脆弱的完美主義者」。自我要求極高（08A），但面對挫折時復原緩慢（02C）。警示：容易因一時的失敗而陷入嚴重的自我否定或心理潰敗，需主管及時給予技術性支持與信心引導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (966, 'ANI_08', 'A', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「自發性精英」。主動追求突破（08A）且不需監督便能獨立推進任務（05A）。管理建議：給予高度自主權與具備成長空間的專案，是組織最核心的自我發展動力源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (967, 'ANI_08', 'A', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「顛覆式的精進者」。追求卓越的方式不侷限於舊法（08A），能跳脫框架產生新穎方案（07A）。預測：能推動組織的範式轉移（Paradigm Shift），將產出提升到全新層次。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (968, 'ANI_08', 'A', 'ANI_09', 'A', '與 ANI_09 (自我覺察) A 聯動：表現為「清醒的成長者」。追求卓越的同時（08A），能客觀評估自身能力的優劣勢與情緒影響（09A）。預測：能進行有針對性的補強，避免盲目努力，成長效率極高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (969, 'ANI_08', 'A', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) A 聯動：表現為「數位增強的高標者」。為了追求卓越（08A），會主動掌握並高效運用 AI 工具來優化產出（10A）。預測：能引領團隊進行 AI 化生產力的轉型，對新科技的實踐力極強。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (970, 'ANI_08', 'A', 'ANI_14', 'A', '與 ANI_14 (終身學習) A 聯動：表現為「知識驅動的卓越者」。將學習視為追求進精通的唯一路徑（14A, 08A）。管理建議：是組織培訓體系中的「領頭羊」，會主動將新知轉化為卓越的工作標準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (971, 'ANI_08', 'A', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「無懈可擊的交付者」。對品質要求高（08A）且承諾絕對兌現（16A）。預測：是組織中信任度最高的員工，承接的任務幾乎不會出現品質下滑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (972, 'ANI_08', 'A', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「極致工匠」。對細節精確度的執著源於對卓越的承諾（17A, 08A）。風險：可能在瑣碎細節上耗費過多精力，需協助其平衡「整體突破」與「細節完美」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (973, 'ANI_08', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「消極的分析師」。邏輯能力強（01A），但缺乏追求更高難度挑戰的慾望（08C）。管理建議：適合擔任「查核」或「顧問」角色，而非主導需要突破性的第一線開拓。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (974, 'ANI_08', 'C', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A 聯動：表現為「靈活的隨行者」。能快速適應環境變動（04A），但其動機多源於「外在環境要求」而非「內在卓越追求」（08C）。預測：配合度高，但不會主動提出具備變革性的高標準方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (975, 'ANI_08', 'C', 'ANI_13', 'A', '與 ANI_13 (好奇心) A 聯動：表現為「廣泛但淺層的學習者」。對新資訊有熱情（13A），但缺乏將其磨練至「技能精通」的決心與動能（08C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (976, 'ANI_08', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「穩定的標準化勞動力」。在明確職責內非常可靠（16A），但較少主動設定額外挑戰（08C）。管理建議：適合配置在流程穩定、不需要頻繁「超越現狀」的職位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (977, 'ANI_08', 'C', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「風險規避的決策者」。決策雖快（22A），但通常以「滿足基本要求」為底線，不願承擔追求卓越所帶來的失敗風險（08C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (978, 'ANI_08', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「完美的合規者」。行為高度追求他人認可（23A），使其更傾向於做「正確的事」而非「卓越的事」，以避免失敗帶來的負面評價。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (979, 'ANI_09', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「後設認知專家」。不僅能邏輯拆解問題（01A），還能覺察自己思考過程中的盲點與偏誤（09A）。預測：在解決複雜難題時，能主動修正個人的思維定式，確保分析結果的客觀性與正確性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (980, 'ANI_09', 'A', 'ANI_02', 'A', '與 ANI_02 (韌性) A 聯動：表現為「心理資源管理者」。在壓力下能敏銳察覺自身情緒波動與疲勞信號（09A），並運用韌性自發進行修復與能量調節（02A）。管理建議：其高穩定性來自於主動的心理維護，適合擔任高壓環境下的長期關鍵崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (981, 'ANI_09', 'A', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「高情商說服者」。能精準感知自己的社交行為對他人的影響（09A），並據此動態調整說服策略以取得共識（06A）。預測：其影響力極具策略性且不留痕跡，能建立極高質量的信任關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (982, 'ANI_09', 'A', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「深層共鳴者」。能清楚區分「自身情緒」與「他人感受」（09A, 11A）。預測：在處理人際衝突或輔導下屬時，能提供具備邊界感且深具溫度的引導，是極佳的團隊教練人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (983, 'ANI_09', 'A', 'ANI_14', 'A', '與 ANI_14 (終身學習) A 聯動：表現為「標靶式學習者」。清楚知道自己的能力短板與成長需求（09A），能針對性地投入學習資源（14A）。管理建議：其成長效率極高，能主動吸收回饋並轉化為具體的進步動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (984, 'ANI_09', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「覺醒的架構師」。能意識到「自己作為系統一環」的作用與責任（09A），並從宏觀角度調整自身行為以優化整體連動（15A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (985, 'ANI_09', 'A', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「自我監控大師」。能敏銳感知社交場合的期望（09A），並在不失真誠的前提下展現符合公認優秀標籤的行為（23A）。警示：其完美表現可能隱藏了真實壓力，需關注其職業燃盡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (986, 'ANI_09', 'C', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「盲目衝鋒的孤狼」。主動性極強（05A），但較少察覺自身行為對團隊的負面影響（09C）。風險：容易在追求目標的過程中，因無視他人反饋或過度擴張而造成組織內耗或個人口碑崩壞。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (987, 'ANI_09', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「不知疲倦的過勞者」。一心追求高標準（08A），卻難以覺察身心耗竭的訊號（09C）。管理建議：主管需強制介入其休息節奏，並透過量化數據提醒其產出效率的下滑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (988, 'ANI_09', 'C', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「技術偏執的賦能者」。擅長運用 AI 工具（10A），但難以察覺個人偏見如何滲透進 AI 的應用過程中（09C）。風險：其產出的結果可能具備邏輯硬傷或忽視了現實中的倫理與情感維度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (989, 'ANI_09', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「刻板的執行員」。雖然高度可靠（16A），但在犯錯或表現下滑時難以自發察覺（09C）。管理建議：需提供即時、具體且非抽象的負面回饋，以啟動其被動的調整機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (990, 'ANI_09', 'C', 'ANI_21', 'A', '與 ANI_21 (社交智商) A 聯動：表現為「技巧型的外交官」。具備社交洞察力（21A），但對自身「動機」或「帶給人的壓力」覺察較淺（09C）。警示：容易讓人感到圓滑但缺乏真心，需輔導其強化內在反省。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (991, 'ANI_09', 'C', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「直覺型快決策者」。決策極快（22A），但往往意識不到個人偏好或情緒如何左右了決策（09C）。預測：在決策失敗後容易歸咎於外部環境而非個人判斷偏誤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (992, 'ANI_10', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A聯動：表現為「AI應用的戰略家」。能從邏輯層面理解 AI 運作邏輯（01A），並精準評估其產出在實務中的價值與風險（10A）。預測：能引導組織做出穩健的技術導入決測，避免盲目跟風。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (993, 'ANI_10', 'A', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A聯動：表現為「數位轉型先鋒」。不僅能理解新工具（10A），還能隨技術迭代快速調整自身工作流程（04A）。管理建議：適合作為數位工具導入的種子人員（Early Adopter）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (994, 'ANI_10', 'A', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A聯動：表現為「AI賦能的發明家」。能將 AI 視為靈感的放大器（10A），利用科技產出跨越傳統框架的創新方案（07A）。預測：能大幅縮短從概念到原型的研發週期。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (995, 'ANI_10', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A聯動：表現為「數位架構師」。能從全局角度思考 AI 導入後對各部門與流程的連動影響（15A），確保科技應用與整體戰略對標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (996, 'ANI_10', 'A', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A聯動：表現為「理性的監督者」。能敏銳察覺 AI 的局限性、幻覺或偏見（10A），並批判性地審核其產出的真實性與倫理風險（20A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (997, 'ANI_10', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A聯動：表現為「數據驅動的決策者」。能快速利用 AI 產出的資訊作為佐證（10A），並在不確定性中果斷下達具備實務支撐的決策（22A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (998, 'ANI_10', 'C', 'ANI_02', 'C', '與 ANI_02 (韌性) C聯動：表現為「數位焦慮者」。對 AI 感到陌生（10C），且在面臨科技衝擊時心理復原力較弱（02C），容易產生強烈的排斥感或職業恐慌。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (999, 'ANI_10', 'C', 'ANI_05', 'A', '與 ANI_05 (自主領導) A聯動：表現為「傳統路徑的奮鬥者」。主動性高（05A），但因缺乏對 AI 工具的理解（10C），傾向於用傳統高耗能的方式完成任務。管理建議：應提供具體示範以引導其自發轉型。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1000, 'ANI_10', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A聯動：表現為「受限的精進者」。渴望卓越（08A），但因不熟悉 AI 應用（10C），其工作天花板受限於現有的人力產能，需透過培訓打破瓶頸。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1001, 'ANI_10', 'C', 'ANI_13', 'A', '與 ANI_13 (好奇心) A聯動：表現為「數位轉型的潛力股」。雖目前仍處於摸索期（10C），但強烈的好奇心（13A）將驅動其快速學習。管理建議：提供安全且具體的試點專案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1002, 'ANI_10', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A聯動：表現為「守穩傳統規範的執行員」。在既有系統中極其可靠（16A），但對缺乏 SOP 的 AI 工具持觀望態度（10C）。管理建議：將 AI 導入納入正式流程與規範。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1003, 'ANI_10', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A聯動：表現為「表面的數位配合者」。口頭認同科技重要性以獲取認可（23A），但實際操作時仍因不熟練而感到困頓（10C）。警示：應追蹤其真實的使用深度而非報告。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1004, 'ANI_11', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「理性的療癒者」。能運用邏輯拆解他人的情緒來源與需求模式。預測：在提供支持時不僅具備溫度，還能給出具備結構化與可行性的建議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1005, 'ANI_11', 'A', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「深具感染力的領導者」。能精準捕捉群體情緒並建立共識。預測：其說服力建立在「懂你」的基礎上，能大幅降低變革推行時的人際阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1006, 'ANI_11', 'A', 'ANI_09', 'A', '與 ANI_09 (自我覺察) A 聯動：表現為「高 EQ 溝通專家」。能清楚區分自身與他人的情緒邊界。管理建議：其高共鳴力不會導致個人情緒燃盡，是處理高度緊張人際議題的首選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1007, 'ANI_11', 'A', 'ANI_12', 'A', '與 ANI_12 (積極傾聽) A 聯動：表現為「全神貫注的同頻者」。不僅理解話語，更能感受弦外之音。預測：能建立極深度的信任關係，在人才導師（Mentoring）角色中表現卓越。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1008, 'ANI_11', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「人文關懷的架構師」。在思考系統優化時會優先考量對「人」的影響。管理建議：適合制定涉及大規模員工權益的組織政策。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1009, 'ANI_11', 'A', 'ANI_21', 'A', '與 ANI_21 (社交智商) A 聯動：表現為「溫暖的交際大師」。具備敏銳的社交洞察力且真心關懷他人。預測：是團隊中的核心潤滑劑，能自然地化解隱形衝突。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1010, 'ANI_11', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「仁慈的指揮官」。決策果斷但會細膩地處理受影響者的心理安撫。管理建議：適合執行需要高執行力但涉及人事情感的組織任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1011, 'ANI_11', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「無情的計算機」。邏輯極強但無視人的情感成本。風險：其優化方案雖然理論正確，但往往因忽視人心反彈而在執行階段慘遭失敗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1012, 'ANI_11', 'C', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「自負的獨行俠」。自我驅動極強但缺乏對團隊的情感連結。管理建議：適合個人貢獻型工作，不宜放入需要高度協作或輔導他人的職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1013, 'ANI_11', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「冷酷的高標者」。為達成卓越目標可以毫不猶豫地犧牲他人的感受。警示：高產出但會造成團隊的高流失率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1014, 'ANI_11', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「刻板的執行機器」。行為高度可靠但缺乏溫度。管理建議：適合與物、數據或規範打交道，而非與「人」的高頻對接。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1015, 'ANI_11', 'C', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「瑣碎的裁判者」。糾結於細節精確（17A）卻無視他人所處的困境或壓力（11C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1016, 'ANI_11', 'C', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「強悍的掠奪者」。談判技巧高（19A）但不在乎長遠關係與對方利益。預測：能贏得短暫勝利，但難以建立長期的戰略夥伴關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1017, 'ANI_11', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「虛偽的表演者」。行為符合社會禮儀以獲取認可（23A），但內心對他人需求毫無感應（11C）。面談重點：應觀察其在突發情緒衝突下的真實反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1018, 'ANI_12', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「精準的解題專家」。能完全理解對方的意圖與細節（12A），並運用強大邏輯拆解問題（01A）。預測：其產出的方案不僅符合邏輯，且能精準擊中問題核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1019, 'ANI_12', 'A', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「深具魅力的溝通領袖」。說服力建立在「聽懂對方需求」的基礎上（12A），能透過引導與共識達成目標（06A）。管理建議：適合作為高階談判或變革管理中的共識建立者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1020, 'ANI_12', 'A', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「卓越的輔導教練」。不僅理解資訊，更能覺察情緒（11A）並透過提問確認需求（12A）。預測：在團隊中具備極高的信任感，能有效提升部屬或同事的向心力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1021, 'ANI_12', 'A', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「戰略型談判者」。能精準捕捉對方隱藏的利益點與需求（12A），並在複雜利益衝突中找到共贏方案（19A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1022, 'ANI_12', 'A', 'ANI_21', 'A', '與 ANI_21 (社交智商) A 聯動：表現為「高敏銳的社交者」。在各種社交場合中，能透過傾聽快速掌握環境氛圍與他人動機，從而做出最得體的社交回應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1023, 'ANI_12', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「週全的決策指揮官」。決策雖然快速（22A），但並非魯莽，而是基於對所有利害關係人反饋的充分理解（12A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1024, 'ANI_12', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「自負的邏輯者」。分析能力強（01A），但因傾聽不佳（12C），容易在未聽完對方需求前就開始推演，導致「用正確的邏輯解決了錯誤的問題」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1025, 'ANI_12', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「急躁的追求者」。為了追求卓越績效（08A），往往忽視了他人的細節回饋（12C）。警示：雖有衝勁，但常因誤解指令而導致無效勞動，需主管頻繁確認進度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1026, 'ANI_12', 'C', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「充滿善意的誤解者」。內心關心他人感受（11A），但因傾聽不足（12C）而常錯過對方的重點需求，造成「關心不到位」的尷尬。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1027, 'ANI_12', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「需書面化的執行員」。對承諾負責（16A），但口頭領受任務時容易漏失資訊（12C）。管理建議：所有的重要溝通必須留存文字紀錄或回報確認。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1028, 'ANI_12', 'C', 'ANI_18', 'A', '與 ANI_18 (協調溝通) A 聯動：表現為「單向的傳遞者」。擅長發送訊息與資源協調（18A），但缺乏對他人的接收確認與雙向回應（12C），溝通鏈結易斷裂。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1029, 'ANI_12', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「禮貌的失神者」。表面上點頭微笑以維持形象（23A），但實際上並未處理對方的資訊細節（12C）。面談重點：需觀察其對談話內容的具體摘要能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1030, 'ANI_13', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「深度的知識探究者」。不僅有探索渴望（13A），更具備拆解與理解底層邏輯的能力（01A）。預測：在面對新技術或新市場時，能迅速建立結構化的專業認知，而非僅停留在表面興趣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1031, 'ANI_13', 'A', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「多產的創新發明家」。好奇心驅動異質資訊的採集（13A），創意則將這些碎片連接成獨特方案（07A）。管理建議：其提議往往具備破框性質，是組織研發與前瞻計畫的核心推手。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1032, 'ANI_13', 'A', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「AI 應用的無限實驗者」。強烈的好奇心驅動其不斷挖掘 AI 的應用邊界（10A, 13A）。預測：能引領團隊探索出非典型、高效率的數位工作流程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1033, 'ANI_13', 'A', 'ANI_14', 'A', '與 ANI_14 (終身學習) A 聯動：表現為「自發性的學習機器」。將好奇心轉化為長期的教育投入（14A），其知識庫會隨著職涯長度產生複合增長效應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1034, 'ANI_13', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「跨領域的關聯發現者」。對各個領域的運作方式感興趣（13A），並能識別出這些領域如何作為一個系統相互作用（15A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1035, 'ANI_13', 'A', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「審慎的真相追尋者」。不僅想知道「是什麼」，更會運用批判性思維質疑現狀（20A），找出「為什麼不是」的改進契機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1036, 'ANI_13', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「專注的局部專家」。分析力強（01A），但對超出既有職責範圍的新知興趣低落（13C）。管理建議：適合擔任成熟穩定系統的分析師，但需注意其可能錯失跨領域的創新機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1037, 'ANI_13', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「目標導向的精進者」。追求完美（08A），但路徑高度固定，傾向於「將舊有技藝磨練到極致」而非探索新技術（13C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1038, 'ANI_13', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「穩健的既定程序守護者」。高度可靠（16A），不輕易偏離熟悉的流程去嘗試未知風險（13C）。警示：在需要破舊立新的變革環境中，其阻力通常來自於對舊秩序的安全感依賴。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1039, 'ANI_13', 'C', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「細節控制的工匠」。對現有規範的精確度極高（17A），但對新規範或新知識的導入顯得被動且抗拒（13C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1040, 'ANI_13', 'C', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「基於過往經驗的快決策者」。決策雖快（22A），但因缺乏對新趨勢的好奇心（13C），容易陷入舊思維，忽視了環境已產生的重大變數。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1041, 'ANI_13', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「得體的守舊人士」。為了維持正面形象（23A），表面上可能表示接受新知，但內心缺乏真實的驅動力去學習（13C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1042, 'ANI_14', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「深度的專業建構者」。不僅投入學習（14A），且能透過邏輯拆解將零散資訊轉化為結構化的專業體系（01A）。預測：在面對複雜新領域時，能迅速建立具備商業價值的專業深度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1043, 'ANI_14', 'A', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「靈活的跨域學習者」。學習動機強且能快速切換不同領域的思維框架（03A, 14A）。預測：極具斜槓潛力，能在多樣化的任務中不斷提取並遷移知識。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1044, 'ANI_14', 'A', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「自我驅動的進化者」。不需要組織強制，會自發制定學習計畫並承擔個人成長責任（05A, 14A）。管理建議：應提供高度自主的培訓資源，鼓勵其帶動團隊學習氛圍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1045, 'ANI_14', 'A', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「精英式的技能精通者」。將學習視為追求卓越、提升標準的唯一路徑。預測：其能力成長曲線呈複合式上升，是組織中高潛力人才（HiPo）的核心指標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1046, 'ANI_14', 'A', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「數位轉型長青者」。會積極且持續地追蹤 AI 技術發展（10A），並不斷更新個人應用策略以維持生產力領先。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1047, 'ANI_14', 'A', 'ANI_13', 'A', '與 ANI_13 (好奇心) A 聯動：表現為「無限的知識探索家」。好奇心提供燃料，終身學習提供結構化的續航力。預測：知識庫廣博且更新速度極快，是組織內的知識中心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1048, 'ANI_14', 'A', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「清醒的學習家」。在吸收新知時具備極強的篩選能力（20A），確保所學資訊具備高度可信度與實務價值。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1049, 'ANI_14', 'C', 'ANI_02', 'C', '與 ANI_02 (韌性) C 聯動：表現為「變革中的焦慮守舊者」。因缺乏更新技能的動機（14C），在面臨挫折或環境劇變時容易感到無力與恐慌（02C），應對策略極其單一。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1050, 'ANI_14', 'C', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A 聯動：表現為「應激式的調整者」。能快速適應新環境（04A），但其調整多來自外在壓力而非主動內化的技能提升（14C）。警示：雖短期配合度高，但長期可能因專業能力原地踏步而掉隊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1051, 'ANI_14', 'C', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「工具型的使用者」。對現有 AI 工具具備基本掌握（10A），但缺乏持續追蹤技術迭代的熱情（14C）。管理建議：需主管主動推動技術升級資訊，否則其技術優勢會迅速過時。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1052, 'ANI_14', 'C', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「穩健的體系守護者」。能理解現有系統的運作（15A），但面對需要引入新技術或新範式的系統升級時，會因偏好舊能力（14C）而展現隱形阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1053, 'ANI_14', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「忠誠的守位執行員」。在既有職責與技能範圍內極其可靠（16A），但不願脫離舒適圈去學習新作法。管理建議：適合配置於穩定性高、知識更新需求較低的後勤部門。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1054, 'ANI_14', 'C', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「經驗導向的快決策者」。決策雖快，但決策基礎多來自過往舊經驗而非最新數據或新知（14C）。風險：在需要新知識判斷的場合容易因守舊而產生偏誤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1055, 'ANI_15', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「總體架構師」。不僅能拆解細節（01A），還能看清各組件如何相互作用形成整體（15A）。預測：能精確診斷組織深層病灶，提出的方案兼具邏輯細節與全局穩定性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1056, 'ANI_15', 'A', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「靈活的動態佈局者」。能理解全局（15A），並根據外部環境變動迅速調整系統內的關鍵權重（03A）。管理建議：適合作為複雜變革專案的總協調人。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1057, 'ANI_15', 'A', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「具備全局觀的遊說家」。說服他人時不僅靠口才，更會說明該變更對各部門的長遠連動效應，建立更穩固的跨部門共識。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1058, 'ANI_15', 'A', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「系統性創新者」。其創意並非單點突破，而是能改變整體運作模式的結構性創新。預測：能引發組織內的典範轉移。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1059, 'ANI_15', 'A', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「數位生態架構師」。能預見 AI 導入對組織整體流程、人才佈局與倫理風險的全面影響（10A, 15A），確保科技應用與企業戰略深度融合。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1060, 'ANI_15', 'A', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「嚴謹的風險預測家」。在審視全局時（15A），會主動質疑系統內的前提假設，識別出可能導致「蝴蝶效應」的隱藏偏誤（20A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1061, 'ANI_15', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果敢的全局指揮官」。決策雖快（22A），但基於對整體關聯的精確預測（15A），能有效避免決策帶來的副作用。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1062, 'ANI_15', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「專注的局部專家」。細節拆解能力極強（01A），但難以察覺該局部優化是否會損害整體利益（15C）。警示：容易出現「贏了局部，輸了全局」的狀況。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1063, 'ANI_15', 'C', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「盲目衝鋒的部門主管」。自我驅動極強（05A），但因缺乏系統觀（15C），其主動採取的行動常意外干擾其他單位的運作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1064, 'ANI_15', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「狹隘的追求者」。追求最高標準（08A），但標準往往侷限於個人或當下職責，無視長遠或跨單位的負面衝擊（15C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1065, 'ANI_15', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「穩定的守位者」。高度完成任務（16A），但僅在被告知的範圍內負責，較難預見自己的延誤會對後續流程產生的骨牌效應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1066, 'ANI_15', 'C', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「見樹不見林的精算師」。糾結於局部數據的絕對精確（17A），卻未察覺該數據在整體系統中已失去參考價值（15C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1067, 'ANI_15', 'C', 'ANI_18', 'A', '與 ANI_18 (協調溝通) A 聯動：表現為「單點式的傳令兵」。能清晰傳達訊息（18A），但缺乏對訊息背景與後續連動的理解，難以處理複雜的多方資源協調。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1068, 'ANI_15', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「迎合當下的老好人」。為了獲取即時認可（23A），可能做出讓當下滿意但對組織整體長期有害的承諾（15C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1069, 'ANI_16', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「精確的工程師」。不僅能以邏輯拆解問題（01A），且能穩定兌現分析後的執行承諾（16A）。預測：其產出高度可預期，是負責核心架構與長期專案的最佳人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1070, 'ANI_16', 'A', 'ANI_02', 'C', '與 ANI_02 (韌性) C 聯動：表現為「和平時期的模範生」。在穩定環境中極其可靠（16A），但一旦面臨變動或挫折，其一致性會因心理受創而出現短暫斷裂（02C）。管理建議：應在變動期給予其心理支持，以維持其原本的穩定輸出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1071, 'ANI_16', 'A', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「絕對獨立的推進者」。具備強烈的所有權意識（05A），且在無需監督的情況下仍能保持高標準交付（16A）。預測：這是組織中最珍稀的「自動駕駛型」人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1072, 'ANI_16', 'A', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「承諾必達的精進者」。追求卓越的標準（08A）並將其轉化為穩定的產出行為（16A）。預測：不僅做得好，且每一次都能如期交出高水準成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1073, 'ANI_16', 'A', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「穩健的數位實踐者」。能正確運用 AI 工具（10A）並確保留其產出的可靠性與合規性（16A），不會因技術過度依賴而產生風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1074, 'ANI_16', 'A', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「零失誤的執行官」。對細節的精確度（17A）與交付的時程（16A）有雙重執著。警示：容易自我加壓過重，需適時提醒其資源分配的彈性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1075, 'ANI_16', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「沉穩的指揮官」。決策果斷（22A）且對決策後的行動方案負責到底（16A），不因難度增加而推諉。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1076, 'ANI_16', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「斷續的智多星」。思維極其敏捷（01A），但交付品質不穩定，容易因狀態不佳或瑣事分心而延誤（16C）。管理建議：需為其配置明確的進度追蹤系統。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1077, 'ANI_16', 'C', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「虎頭蛇尾的發起者」。主動發起專案的能量極高（05A），但缺乏持續收尾的毅力與責任感（16C）。警示：需有人協助其處理專案後期的「落地」執行。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1078, 'ANI_16', 'C', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「不穩定的天才」。想法極具突破性（07A），但產出的時效性與行為的一致性極低（16C）。管理建議：適合短期創意激盪，但不宜負責有嚴格 Deadlines 的正式流程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1079, 'ANI_16', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「焦慮的夢想家」。渴望做出驚人成就（08A），但常因細節執行不力或一致性差（16C）導致理想無法變現，產生強烈的自我挫折。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1080, 'ANI_16', 'C', 'ANI_18', 'A', '與 ANI_18 (協調溝通) A 聯動：表現為「只說不做的傳令兵」。擅長傳遞與協調資源（18A），但當涉及需要個人親自承擔的最後一哩路交付時，往往會掉鏈子（16C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1081, 'ANI_16', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「禮貌的放鴿子者」。為了維持良好關係與認可（23A），會過度承諾自己能力以外的事，最後因無法達成（16C）而損害誠信。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1082, 'ANI_17', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「精密邏輯分析師」。不僅能運用邏輯拆解問題，且能確保分析過程中的數據與細節無懈可擊。預測：在審計、精密研發或複雜數據建模中具備極高價值，產出極度可信。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1083, 'ANI_17', 'A', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「卓越的工匠型創作者」。具備跳出框架的點子，且對實現創意的每一處細節都有極高的品質堅持。管理建議：其作品通常兼具美感與實用性，適合負責高端產品設計或關鍵技術研發。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1084, 'ANI_17', 'A', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「高品質的精進者」。對卓越的渴望 體現在對每一個小細節的極致打磨上。預測：會主動發現他人忽略的細微錯誤，是組織內部的品質標竿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1085, 'ANI_17', 'A', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「AI 產出的嚴謹監督者」。擅長運用 AI 提升效率，但會對 AI 產出的結果進行細緻的人工查核，確保不出現技術性幻覺或偏誤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1086, 'ANI_17', 'A', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「絕對零失誤的交付者」。行為穩定可靠，且交付內容永遠符合規格、無細微瑕疵。管理建議：適合擔任涉及重大合規、法務或關鍵營運流程的最後把關者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1087, 'ANI_17', 'A', 'ANI_22', 'C', '與 ANI_22 (高效決策) C 聯動：表現為「因糾結細節而猶豫的專家」。為了追求絕對準確，常因資訊不夠完美而推遲決策。警示：容易出現過度分析（Analysis Paralysis），需外部給予明確的決策期限。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1088, 'ANI_17', 'C', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A 聯動：表現為「敏捷但粗放的先遣軍」。反應與調整速度極快，但在快速轉向中容易忽視細節規範。管理建議：適合開拓期任務，但需配備嚴謹的助理或查核系統進行後續補位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1089, 'ANI_17', 'C', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「高行動力但粗心的發起者」。具備強烈主動性，但因對細節敏感度低，其產出的方案往往需要頻繁修改才能落地。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1090, 'ANI_17', 'C', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「過度依賴工具的快速使用者」。雖懂技術應用，但容易直接照搬 AI 生成內容而不加核實細節。風險：可能導致系統性的小錯誤在組織中擴散。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1091, 'ANI_17', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「雖守時但常需退件的執行員」。會如期交付任務，但成果中常伴隨規格不符或小錯誤。管理建議：應提供結構化的 Check-list 強制其進行自我檢核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1092, 'ANI_17', 'C', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「能識大體但疏於校對的評論家」。能看出邏輯偏誤或大前提錯誤，但對文書格式、具體數據的小數位數等細節缺乏耐心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1093, 'ANI_17', 'C', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果斷但高風險的指揮官」。決策速度極快，但常因忽視細微變數或關鍵細節 而導致執行階段出現意想不到的紕漏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1094, 'ANI_18', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「結構化溝通大師」。不僅能協調資源，還能運用邏輯（01A）將複雜的工作流拆解成易懂的指令。預測：在跨部門合作中，能精準對接技術與業務語言，顯著降低溝通損耗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1095, 'ANI_18', 'A', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「強大的共識建立者」。除了傳達訊息，還具備說服他人配合資源調整的能力（06A, 18A）。管理建議：適合作為大型變革專案的協調樞紐，能主動化解部門間的協作阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1096, 'ANI_18', 'A', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「高品質的同步者」。為了追求卓越成果（08A），會主動確保所有協作節點都保持高標準的資訊透明與效率（18A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1097, 'ANI_18', 'A', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「有溫度的協調者」。在分配資源或協調任務時，能理解並尊重各方的感受與困難（11A, 18A）。預測：其協調方式極具包容力，能有效凝聚團隊心理向心力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1098, 'ANI_18', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「全局協作架構師」。能看清系統各部分的連動關係（15A），並據此做出最優化的資源配置與資訊同步（18A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1099, 'ANI_18', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果斷的調度者」。決策迅速（22A）且能第一時間將決策指令準確傳達到所有執行末梢（18A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1100, 'ANI_18', 'C', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「孤軍奮戰的執行者」。自發性極強（05A），但因協調意願低（18C），常在不與他人同步的情況下超前部署，造成團隊節奏脫節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1101, 'ANI_18', 'C', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「數位孤島的使用者」。雖擅長 AI 工具（10A），但缺乏將科技產出分享給團隊或進行跨員調度的習慣（18C）。警示：其個人生產力極高，但難以轉化為團隊資產。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1102, 'ANI_18', 'C', 'ANI_12', 'A', '與 ANI_12 (積極傾聽) A 聯動：表現為「沉默的吸收者」。能聽懂所有細節（12A），但較少主動將這些資訊對外傳遞或用於協調資源（18C）。管理建議：需強制其設定定期回報機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1103, 'ANI_18', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「穩定的末端執行員」。對自身任務高度負責（16A），但不擅長與上下游環節進行協作與進度同步（18C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1104, 'ANI_18', 'C', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「沈默的細節控」。在個人範圍內極度精確（17A），但面對需要多方配合、模糊度高的資源協調時會感到手足無措並退縮（18C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1105, 'ANI_18', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「避免衝突的傳令兵」。過度在意正面認可（23A），使其在需要強力協調資源或傳遞困難訊息時，傾向於避重就輕（18C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1106, 'ANI_19', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「理性的價值挖掘者」。能運用邏輯拆解對方的利益結構（01A），並據此設計多套雙贏的替代方案。預測：在複雜的採購、併購或合約談判中，能精準找到利益交集點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1107, 'ANI_19', 'A', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「敏捷的策略家」。能根據談判桌上的動態變換思考框架，當 A 方案受阻時，能迅速切換至 B 方案（03A, 19A）。管理建議：適合處理高度模糊、非典型且需要即興發揮的談判任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1108, 'ANI_19', 'A', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「強悍的氣場掌控者」。不僅具備策略，更懂得運用心理技巧與說服力（06A）來引導對方接受自己的條件。預測：在需要爭取核心資源或改變對方既定立場時表現卓越。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1109, 'ANI_19', 'A', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「溫和的價值創造者」。能真心理解對方的痛苦與需求（11A），透過建立信任來消除防禦感。預測：能與合作夥伴建立長期、互惠的戰略關係，而非一次性掠奪。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1110, 'ANI_19', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「全局利益維護者」。談判時不只看當下利益，更能預測協議對整體組織生態的長遠影響（15A）。管理建議：適合擔任涉及公司戰略轉型的核心談判官。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1111, 'ANI_19', 'A', 'ANI_21', 'A', '與 ANI_21 (社交智商) A 聯動：表現為「外交官般的談判手」。具備極強的社交洞察力（21A），能敏銳捕捉對方的微表情或情緒變化，精準拿捏進退分寸。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1112, 'ANI_19', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果敢的協議終結者」。在談判陷入膠著時，能果斷判斷底線並做出決定（22A），避免因過度拉鋸導致機會成本喪失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1113, 'ANI_19', 'C', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「勤奮但易妥協的執行者」。主動性高且對自身任務負責（05A），但一旦需要與外部爭取資源或面對強勢對手時，容易退讓（19C）。管理建議：其身後需有強力的法務或商務輔助。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1114, 'ANI_19', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「自省但無力的完美主義者」。自我要求極高（08A），但因不擅長對外爭取支持或處理衝突（19C），常導致其高標準因資源匱乏而無法實現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1115, 'ANI_19', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「忠誠的秩序維護者」。非常可靠（16A），但在面對不合理的組織要求或外部壓力時，容易因避免衝突（19C）而承擔過多不合理的責任。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1116, 'ANI_19', 'C', 'ANI_18', 'A', '與 ANI_18 (協調溝通) A 聯動：表現為「單純的訊息傳遞者」。能清晰同步各方資訊（18A），但在協調資源分配發生衝突時，傾向於犧牲己方利益以求和諧（19C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1117, 'ANI_19', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「討好型談判者」。過度在意社會認可與形象（23A），使其在談判桌上不敢堅持立場，破壞「好人」形象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1118, 'ANI_20', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「嚴密的邏輯檢察官」。不僅能拆解問題模式（01A），還會嚴格審核數據來源與邏輯前提的可信度（20A）。預測：在組織面臨重大策略抉擇時，能提供最客觀、去偏誤的專業審核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1119, 'ANI_20', 'A', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「理性的策略切換者」。具備切換思維框架的能力（03A），且每次調整都基於對證據的冷靜評估（20A），而非盲目跟風。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1120, 'ANI_20', 'A', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「務實的革新者」。點子多樣（07A）但能自我審查創意的可行性與邏輯漏洞（20A）。管理建議：其提議往往最具備實施價值，因已預先排除不切實際的幻想。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1121, 'ANI_20', 'A', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「AI 幻覺的終結者」。理解 AI 應用（10A）但對其產出保持高度警覺，能識別出 AI 生成內容中的偏見與錯誤（20A）。預測：能確保組織在安全、合規的軌道上運用 AI 產能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1122, 'ANI_20', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「全局風險精算師」。能看清系統連動（15A），並批判性地評估系統中關鍵節點的脆弱性（20A），預防連鎖反應導致的崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1123, 'ANI_20', 'A', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「冷靜的談判專家」。能看穿對方在談判桌上的資訊誤導或心理戰術（20A），基於事實底線達成協議（19A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1124, 'ANI_20', 'A', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「精確的指揮官」。決策快速且具備深度（22A, 20A），能確保決策品質在「速度」與「準確」間取得最優平衡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1125, 'ANI_20', 'C', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「具感染力的傳聲筒」。雖具備說服他人的能力（06A），但因缺乏獨立判斷（20C），容易將錯誤的資訊或未經證實的觀點有效擴散至團隊，具備隱性誤導風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1126, 'ANI_20', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「勤奮但盲目的追求者」。極度追求高標（08A），但因不善質疑任務的前提與證據（20C），容易在錯誤的方向上投入極大心力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1127, 'ANI_20', 'C', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「AI 生成內容的順從者」。雖懂得操作 AI（10A），但傾向於無條件相信 AI 的答案（20C）。警示：容易因疏於查核而產出具備低級錯誤或誤導性的工作成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1128, 'ANI_20', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「守舊的規範執行員」。非常可靠地執行承諾（16A），即便既定流程已出現明顯邏輯漏洞，也會因為缺乏質疑意識（20C）而繼續執行。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1129, 'ANI_20', 'C', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「魯莽的快決策者」。決策極快但過於依賴直覺或他人觀點（20C），在高風險情境下極易因偏誤而導致重大失誤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1130, 'ANI_20', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「盲從社會共識的老好人」。為了獲得認可與合規感（23A），傾向於接受大多數人的觀點而不加反思（20C），缺乏獨立人格。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1131, 'ANI_21', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「人際策略分析家」。能運用邏輯拆解社交線索與利益關係（01A），並精準調整互動策略（21A）。預測：在複雜的政治環境或高階社交場合中，能迅速辨識權力核心並建立有效的聯盟。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1132, 'ANI_21', 'A', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「深具魅力的領導者」。不僅具備說服力（06A），更能讀懂對方的心理防線並適時轉換風格（21A）。管理建議：適合作為跨組織協作的對外代表，能以高度靈活的手腕達成共識。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1133, 'ANI_21', 'A', 'ANI_09', 'A', '與 ANI_09 (自我覺察) A 聯動：表現為「內外合一的社交高手」。對內能察覺自身情緒（09A），對外能讀懂關係動態（21A）。預測：互動風格真誠且具備邊界感，極少發生社交失言，是建立心理安全感的關鍵人物。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1134, 'ANI_21', 'A', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「溫暖的連結者」。能感同身受（11A）並轉化為得體的應對方式（21A）。預測：在團隊中具備極強的非職權凝聚力，是調解衝突、安撫人心的核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1135, 'ANI_21', 'A', 'ANI_12', 'A', '與 ANI_12 (積極傾聽) A 聯動：表現為「高敏銳的接收處理者」。透過傾聽吸收細微資訊（12A），並即時根據情境反饋最合適的社交語言（21A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1136, 'ANI_21', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「組織動態架構師」。能從全局看清各部門間的關係網路（15A），並透過關係管理優化整體工作流（21A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1137, 'ANI_21', 'A', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「頂尖的外交官」。談判時能讀懂對方的「潛台詞」（21A），在多方利益糾葛中游刃有餘地達成雙贏協議（19A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1138, 'ANI_21', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「木訥的天才」。邏輯推演無懈可擊（01A），但因讀不懂社交暗示（21C），常在不合時宜的場合說出「正確但傷人」的話。警示：容易與團隊產生隔閡，需專人負責其外部協作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1139, 'ANI_21', 'C', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A 聯動：表現為「尷尬的變革者」。行為調整雖快（04A），但因缺乏社交敏感度（21C），其轉向往往顯得生硬且未考量他人的情感負擔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1140, 'ANI_21', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「低 EQ 的追求者」。為了追求卓越成果（08A）會無視團隊動態與關係成本（21C）。風險：高產出但會伴隨極高的人才流失風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1141, 'ANI_21', 'C', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「耿直的執行員」。言出必行且高度可靠（16A），但在處理複雜的人際請託或跨部門博弈時，顯得過於僵化、不懂變通（21C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1142, 'ANI_21', 'C', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「專注於細節的獨行者」。在專業數據上精確（17A），但完全無視社交情境的微小變化（21C），溝通方式通常較為單向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1143, 'ANI_21', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「僵化的合規者」。為了獲取認可而死守禮儀規範（23A），但因缺乏真實的社交直覺（21C），其互動顯得刻意且無法應對非正式場合。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1144, 'ANI_22', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「精確的戰略官」。決策不僅快，且具備深厚的邏輯支撐（01A）。預測：能在短時間內處理大量數據並產出高品質決策，是處理突發營運危機的核心人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1145, 'ANI_22', 'A', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「敏捷的修正者」。決策果斷（22A），且當環境變動時能迅速切換思路（03A）做出動態調整。管理建議：適合作為高頻率迭代專案（如新產品測試）的決策主導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1146, 'ANI_22', 'A', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「獨立的指揮官」。不需要等待主管下令（05A），能在其職權範圍內迅速定案並推動執行（22A）。預測：極具所有權意識，是推動組織「扁平化、去中心化」管理的標竿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1147, 'ANI_22', 'A', 'ANI_09', 'A', '與 ANI_09 (自我覺察) A 聯動：表現為「清醒的承擔者」。清楚自己為何做此決策（09A），且對決策後的風險有心理準備。預測：不會因壓力而導致決策偏誤，能維持極高的決策穩定度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1148, 'ANI_22', 'A', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「數位增強決策者」。能快速利用 AI 分析產出作為判斷依據（10A），結合個人直覺做出高效率定案（22A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1149, 'ANI_22', 'A', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「全局指揮官」。能看清系統連動（15A），在確保整體利益不損害的前提下，迅速對局部衝突做出裁決。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1150, 'ANI_22', 'A', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「可靠的終結者」。決定下得快（22A），且對決策後的承諾與執行維持高度一致性（16A），不輕易反覆。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1151, 'ANI_22', 'C', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「分析癱瘓的專家」。邏輯能力極強（01A），但因追求資訊完備而陷入無限分析（22C）。管理建議：需為其設定強制性的決策截止時間（Deadline）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1152, 'ANI_22', 'C', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「追求完美的猶豫者」。渴望達成卓越（08A），但因擔心決策不夠完美而遲遲不敢定案（22C）。警示：容易在重要機會點前因反覆斟酌而錯失良機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1153, 'ANI_22', 'C', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「糾結細節的保守派」。過度專注於數據的精確性（17A），在不確定環境中顯得畏縮，難以在模糊資訊中做出決斷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1154, 'ANI_22', 'C', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「優柔寡斷的談判手」。具備策略概念（19A），但在談判桌上最後一刻收網時，往往猶豫不決（22C），導致談判對手掌握節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1155, 'ANI_22', 'C', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「嚴謹但被動的審核者」。能看出各種方案的漏洞（20A），但因為缺乏決斷動能（22C），最終僅停留在「批評」而非「拍板」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1156, 'ANI_22', 'C', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「隨大流的合規者」。因害怕做出錯誤決策而影響他人認可（23A），傾向於等待群體共識或上級指示後才跟進（22C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1157, 'ANI_23', 'A', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「精明的社交棋手」。能運用邏輯（01A）判斷當前環境最被期望的行為，並精準呈現符合優秀標準的產出（23A）。預測：在組織政治中游刃有餘，其專業展現往往極具策略性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1158, 'ANI_23', 'A', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「具魅力的合規領導」。擅長運用說服力（06A）來推動符合組織主流價值觀的計畫，並以此獲取廣泛的認可（23A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1159, 'ANI_23', 'A', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「模範生式的卓越者」。追求高標準（08A）的一部分動力來自於渴望被社會視為優秀精英（23A）。管理建議：其動能深受「榮譽感」與「外部肯定」影響。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1160, 'ANI_23', 'A', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「極致的貼心者」。能理解他人感受（11A），且行為上高度符合社交禮儀與期望（23A）。警示：容易因過度在意他人評價而產生心理內耗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1161, 'ANI_23', 'A', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「完美的秩序維護者」。因渴望符合期望（23A），會不遺餘力地履行每一項承諾（16A），是組織中最穩定的正面力量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1162, 'ANI_23', 'A', 'ANI_21', 'A', '與 ANI_21 (社交智商) A 聯動：表現為「得體的外交官」。具備極高的社交洞察力（21A），能精準捕捉社交規範並做出最得體的反應（23A），關係管理能力極強。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1163, 'ANI_23', 'C', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「特立獨行的開拓者」。主動性極強（05A），但完全不在意他人眼光或傳統規範（23C）。預測：能推動顛覆性變革，但常因不屑偽裝而得罪組織內的保守勢力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1164, 'ANI_23', 'C', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「反叛的創意天才」。創意不受社會期望約束（07A, 23C），其方案通常極具衝擊力，但也可能因過於前衛而難以被主流接受。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1165, 'ANI_23', 'C', 'ANI_09', 'A', '與 ANI_09 (自我覺察) A 聯動：表現為「坦率的求真者」。能看清自己的優缺點（09A），且不屑為了迎合他人而掩飾或包裝真實的自我（23C）。管理建議：其反饋極具真實參考價值。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1166, 'ANI_23', 'C', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「技術實務派」。對 AI 的應用僅看重實效（10A），不願為了符合數位轉型的「形象噱頭」而做表面功夫（23C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1167, 'ANI_23', 'C', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「硬派談判手」。在談判桌上堅持底線（19A），不會為了維持客氣或討好對方而輕易讓步（23C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1168, 'ANI_23', 'C', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「批判性的獨覺者」。具備獨立判斷能力（20A），且敢於挑戰大眾共識，不擔心發表不合群但正確的言論（23C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1169, 'ANI_23', 'C', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果敢但不討好的決策者」。決策迅速（22A），且願意做出「正確但不得人心」的艱難決定，不被社會壓力所左右（23C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1170, 'SPA_01', 'A', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「目標導向的戰士」。心理資本充足（01A）且目標路徑清晰（02A）。預測：在複雜任務中能自發找到多種解決路徑，不因暫時的挫折而放棄目標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1171, 'SPA_01', 'A', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「無懈可擊的穩定源」。心理資源充沛且復原極快。管理建議：適合作為組織危機處理的先鋒，能長時間維持高強度輸出而不斷電。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1172, 'SPA_01', 'A', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「高效的永動機」。高度投入工作（06A）且有足夠的心理資本支撐（01A）。風險預防：這類人容易因自我加壓而忽略休息，雖資源充沛仍需留意長期燃盡風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1173, 'SPA_01', 'A', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「自信的成長者」。因心理資本高（01A），能將負面回饋視為成長工具而非否定（08A）。預測：其能力提升速度極快，能主動優化自身行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1174, 'SPA_01', 'A', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「具基石的衝刺者」。強大的企圖心（15A）配合穩健的心理資本（01A）。管理建議：是組織中極佳的高潛力人才，敢於追求極致目標且具備承擔失敗的底氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1175, 'SPA_01', 'A', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「理性的守護者」。具備高心理韌性且情緒極度穩定。預測：在衝突場合中能展現出驚人的冷靜，是跨部門協調與高壓談判的理想人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1176, 'SPA_01', 'C', 'SPA_03', 'C', '與 SPA_03 (效能感) C 聯動：表現為「深度自我懷疑者」。心理資源偏緊（01C）且缺乏信心（03C）。管理建議：需主管透過「拆解小目標」來建立成功經驗，否則易陷入習得性無助。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1177, 'SPA_01', 'C', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「悲觀的預測者」。傾向將失利視為永久且無法改變。風險：在面對變革或不確定性時會率先退縮，對團隊士氣可能產生負面連鎖反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1178, 'SPA_01', 'C', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「焦慮的防禦者」。因自身心理資源不足（01C），對外部回報與公平性極度敏感（09C）。警示：容易因微小的資源分配不均而產生強烈不滿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1179, 'SPA_01', 'C', 'SPA_11', 'C', '與 SPA_11 (可塑性) C 聯動：表現為「僵化的守舊派」。不相信自己能改變（11C）且缺乏重新啟動的心理動能（01C）。管理建議：應給予極其明確的指令與外部推力，減少其面對改變的心理負荷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1180, 'SPA_01', 'C', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「高壓的自燃者」。具備強烈的競爭欲與時間緊迫感（13A），但內在心理資源卻支撐不足（01C）。風險：極度容易發生身心崩潰或職業倦怠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1181, 'SPA_01', 'C', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「情緒的易燃者」。面對挫折時心理緩衝力弱（01C）且情緒升溫極快（18A）。管理建議：絕對不宜放在需要高度人際協作或面對客戶投訴的崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1182, 'SPA_01', 'C', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「表面的堅強者」。雖然心理資源匱乏（01C），但在作答或互動中會努力維持正面形象（12A, 23A）。隱憂：可能隱藏真實的求救信號，主管需透過非正式對話觀察其真實能量狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1183, 'SPA_02', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「全能型推進者」。希望感提供的路徑規劃（02A）與強大的心理底蘊（01A）結合。預測：在資源匱乏的環境中，能主動創造條件達成目標，是開拓陌生市場的關鍵人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1184, 'SPA_02', 'A', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「深具信念的執行者」。既相信自己能做到（03A），又能找到做到的方法（02A）。管理建議：其主動性極高，適合承擔高度模糊、需要自創戰術的任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1185, 'SPA_02', 'A', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「策略型職人」。在遵循職業規範（07A）的同時，能靈活調整方法（02A）來解決客戶難題，而非死守教條。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1186, 'SPA_02', 'A', 'SPA_11', 'A', '與 SPA_11 (可塑性) A 聯動：表現為「自我進化的領航員」。因看見未來目標的路徑（02A），故極度願意學習新技能（11A）以填補路徑上的缺口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1187, 'SPA_02', 'A', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「清醒的野心家」。強大的成功欲望（15A）配合具體可行的達成路徑（02A）。預測：其成就導向極強，且不會盲目衝刺，能精準將動能轉化為結果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1188, 'SPA_02', 'A', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「多線程的策略大師」。能同時規劃多條路徑達成多項任務（16A, 02A）。警示：雖路徑規劃力強，但需留意資源分散導致每一條路徑都「淺嚐輒止」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1189, 'SPA_02', 'C', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「被動的防禦者」。能扛住壓力（04A），但不知道下一步該往哪走（02C）。管理建議：這類人具備續航力，但主管需扮演「導航儀」，為其指派明確路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1190, 'SPA_02', 'C', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「盲目的勤奮者」。極度努力工作（06A），但缺乏達成目標的有效策略或替代方案（02C）。風險：一旦現有方法失效，會因找不到出口而陷入嚴重的職業燃盡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1191, 'SPA_02', 'C', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「依賴回饋的學徒」。主動尋求建議（08A），主因是缺乏自覺的路徑規劃能力（02C）。管理建議：應給予具體的指令引導（Coach），而非僅僅給予抽象建議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1192, 'SPA_02', 'C', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高耗能的徘徊者」。體力與能量充足（10A），但行動缺乏清晰目標與導向（02C）。預測：在重複性、體力消耗型任務中表現佳，但在策略研討中參與感弱。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1193, 'SPA_02', 'C', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「受挫的競爭者」。渴望贏過他人（14A），但在競爭陷入僵局時，缺乏變通路徑以取得優勢的能力（02C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1194, 'SPA_02', 'C', 'SPA_17', 'A', '與 SPA_17 (時間壓力) A 聯動：表現為「緊迫的焦慮者」。感覺時間不夠（17A），又因找不到達成任務的路徑（02C）而加劇焦慮。管理建議：主管需介入協助排定優先順序，化解其心理僵局。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1195, 'SPA_02', 'C', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「絕望的爆發者」。面對阻礙時因找不到替代方法（02C），極易引發強烈的挫折感與情緒衝動（18A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1196, 'SPA_03', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「全能的推進者」。具備足夠的心理底蘊且對成功有明確信心。預測：在面對未知或高難度挑戰時，能將壓力完全轉化為可執行的步驟，是組織開拓新業務的最佳人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1197, 'SPA_03', 'A', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「具備導航力的戰士」。既有達成的信念（03A），又能主動規劃多種路徑（02A）。管理建議：其主動性極強，適合承擔高度模糊、需要自創戰術的任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1198, 'SPA_03', 'A', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「不屈的執行大師」。即便遭遇失敗，不僅能快速復原（04A），且仍維持對成功的信心而不退縮（03A）。行為預測：是團隊中極其穩定的輸出源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1199, 'SPA_03', 'A', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「自信的勞模」。高度投入工作且深信努力會有成果。風險：可能因過度自信而承接超出負荷的任務，需主管協助控管任務邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1200, 'SPA_03', 'A', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高能的進攻者」。充滿活力且行事果斷。管理建議：適合節奏極快、需要第一時間反應的職務（如第一線業務或公關）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1201, 'SPA_03', 'A', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「目標導向的精英」。強大的慾望配合對能力的自信，使其產出具備極強的穿透力，能持續挑戰業績天花板。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1202, 'SPA_03', 'A', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「強勢的火藥桶」。對成功有執著，但若目標受阻，其自信會轉化為強烈的衝動或對抗情緒。警示：需建立情緒降溫機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1203, 'SPA_03', 'C', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「含蓄的潛力股」。雖有心理資源，但缺乏自我肯定的「板機」。管理建議：需主管透過具體的成功經驗（Mastery Experiences）來啟動其能量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1204, 'SPA_03', 'C', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「習得性無助者」。不相信自己能行，且預期結果會持續惡化。風險：極易在挫折中徹底癱瘓，需密集的正面引導與外部結構支撐。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1205, 'SPA_03', 'C', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「尋求安心的依賴者」。主動要回饋的主因是內在信心不足，需要他人肯定才能繼續。面談重點：應多給予「過程肯定」而非僅看結果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1206, 'SPA_03', 'C', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「焦慮的競速者」。行為上急迫且想掌控，但內心極度擔心失敗（03C）。警示：其高壓行為多源於不安，容易產生極大的人際張力與身心負擔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1207, 'SPA_03', 'C', 'SPA_11', 'C', '與 SPA_11 (可塑性) C 聯動：表現為「僵化的自保者」。不相信能力可變，且對當前任務沒信心，會表現出極強的抗拒改變與學習意願低下。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1208, 'SPA_03', 'C', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「脆弱的火藥桶」。因沒把握而焦慮，一旦受挫會迅速情緒爆發以掩飾內心的自我懷疑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1209, 'SPA_04', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「強大的復原基石」。心理資源完整且抗壓性極強。預測：在組織經歷大規模轉型或市場寒冬時，能維持極高的心理穩定度並帶動團隊動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1210, 'SPA_04', 'A', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「不屈的導航者」。遭遇失敗時能快速復原（04A），且因具備希望感，能立即規劃出第二條路徑達成目標（02A）。管理建議：適合作為高難度商務開發（BD）人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1211, 'SPA_04', 'A', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「無懈可擊的推進者」。不僅對自我能力有信心（03A），且具備強大的壓力吸收能力（04A）。行為預測：這類人幾乎不被外界負面評價影響，執行力極其穩定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1212, 'SPA_04', 'A', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「可持續的高標工作者」。高度投入工作且不容易因疲勞或小挫折而退縮。預測：能維持長期的卓越表現，是部門中的穩定軍心柱。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1213, 'SPA_04', 'A', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「從失敗中獲益的成長者」。能承受負面評價帶來的衝擊（04A），並積極尋求反饋以進行自我優化（08A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1214, 'SPA_04', 'A', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「強悍的競爭對手」。強大的求勝欲（14A）結合高度的挫折容忍力（04A）。管理建議：在激烈的業績競賽中表現極佳，能在落後時展現驚人的追分能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1215, 'SPA_04', 'A', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「沉穩的防禦盾牌」。抗壓性強且情緒反應低。預測：面對客戶的無理取鬧或突發危機，能表現出極致的冷靜與專業處理能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1216, 'SPA_04', 'C', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「脆弱的悲觀主義者」。一旦受挫復原極慢（04C），且傾向將失敗視為長期不可逆的結果（05C）。風險：容易在壓力下產生習得性無助，進而導致職務流失或長期低迷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1217, 'SPA_04', 'C', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「易碎的競速者」。行為急迫、追求效率（13A），但一旦事情不順或被延誤，心理復原力跟不上，會產生巨大的心理挫折。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1218, 'SPA_04', 'C', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「高度焦慮的攀登者」。雖然目標遠大（15A），但因缺乏韌性（04C），每一次的小挫敗對他而言都是重大打擊。管理建議：需主管頻繁給予心理緩衝與支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1219, 'SPA_04', 'C', 'SPA_17', 'A', '與 SPA_17 (時間壓力) A 聯動：表現為「時間壓力下的崩潰者」。因時間緊迫感強（17A）加上抗壓韌性不足（04C），在期限將至時容易出現失誤或逃避行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1220, 'SPA_04', 'C', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「高壓下的易爆物」。受挫時心理防禦迅速潰散（04C），隨即引發強烈的情緒衝動或對抗行為（18A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1221, 'SPA_04', 'C', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「壓抑的受挫者」。心理復原緩慢（04C），但為了符合社會期望與認可（12A），會表現出「沒關係」的假象，容易累積成內在的心理疾病。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1222, 'SPA_05', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「強大的心理能量源」。樂觀的歸因（05A）能有效保護並補充心理資本（01A）。預測：在長期高難度專案中，能持續維持高士氣，並將外部壓力轉化為正向的推進力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1223, 'SPA_05', 'A', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「充滿希望的開路者」。相信事情會變好（05A）且能找出變好的多種路徑（02A）。管理建議：適合作為新市場或前瞻計畫的領導者，其信心具備極強的團隊渲染力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1224, 'SPA_05', 'A', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「自信的進攻者」。預期結果是積極的（05A）且相信自己有能力達成（03A）。行為預測：行動啟動門檻極低，能主動捕捉每一個潛在機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1225, 'SPA_05', 'A', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「不屈的彈性核心」。遭遇失敗時視其為暫時（05A），並能快速從衝擊中回穩（04A）。預測：在高度不確定的環境中，能表現出極致的心理穩定度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1226, 'SPA_05', 'A', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「開放的自我優化者」。相信改進能帶來更好的結果（05A），故會積極尋求反饋（08A）。管理建議：其成長潛力巨大，能將負面回饋轉化為具體的進步動力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1227, 'SPA_05', 'A', 'SPA_11', 'A', '與 SPA_11 (可塑性) A 聯動：表現為「深信成長的學習者」。對未來的正向預期（05A）強化了對「能力可變」的信念（11A），展現出極高的學習投入度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1228, 'SPA_05', 'A', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「理性的樂觀實踐者」。態度積極（05A）但情緒表達冷靜且受控（18C），不會因為過度樂觀而顯得浮誇，決策更具專業深度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1229, 'SPA_05', 'C', 'SPA_01', 'C', '與 SPA_01 (心理資本) C 聯動：表現為「心理脆弱的悲觀者」。傾向於災難化思考（05C），這導致其心理資源迅速枯竭（01C）。風險：在壓力環境下極易崩潰，需高度關注其心理健康。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1230, 'SPA_05', 'C', 'SPA_03', 'C', '與 SPA_03 (效能感) C 聯動：表現為「習得性無助者」。不相信未來會好轉（05C），也不相信自己有能力改變（03C）。管理建議：這類員工常處於「防禦模式」，需透過大量的外部鼓勵與成功示範來引導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1231, 'SPA_05', 'C', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「防禦性的公平追求者」。因對未來預期消極（05C），會更計較當下的付出與回報是否對等（09C），以求自保。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1232, 'SPA_05', 'C', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「焦慮的競爭者」。想贏（14A），但內心總預見會失敗（05C）。警示：其競爭行為可能帶有強烈的攻擊性或不安全感，容易造成人際張力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1233, 'SPA_05', 'C', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「受困的野心家」。想往上衝（15A），但容易被潛在的困難嚇阻（05C）。管理建議：應協助其將長遠大目標拆解為可控的具體小目標，以降低其悲觀預期帶來的阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1234, 'SPA_05', 'C', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「易碎的火藥桶」。對事物解讀消極（05C）且情緒反應劇烈（18A），在受挫時極易爆發並做出毀滅性的反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1235, 'SPA_06', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「永不枯竭的動力源」。具備足夠的心理資本（01A）支持其高強度的投入（06A）。預測：這類人能維持長時間的高效產出，是組織在開拓期或衝刺業績時的核心戰力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1236, 'SPA_06', 'A', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「抗壓的執行長跑者」。在面對高壓與挫折時，不僅復原快（04A），且能迅速回到專注與奉獻的工作狀態（06A）。行為預測：即便在市場低迷期，仍能維持穩定且積極的工作節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1237, 'SPA_06', 'A', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「自我迭代的工作狂」。極度投入工作且渴望透過外部回饋（08A）來提升工作效能。管理建議：給予具體的優化方向與資源，其轉化效率會極高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1238, 'SPA_06', 'A', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高能的現場指揮官」。體力充沛（10A）配合精神上的高度專注（06A）。預測：在第一線銷售或高頻率互動場合中，具備極強的氣場與感染力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1239, 'SPA_06', 'A', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「使命必達的精英」。強大的晉升與成就慾望（15A）完全驅動了其在工作中的奉獻精神（06A）。警示：需關注其工作與生活的平衡，預防因過度透支而產生的崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1240, 'SPA_06', 'A', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「全神貫注的多面手」。雖然節奏急促且處理多項任務（16A），但每一項都能保持高度的專注力（06A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1241, 'SPA_06', 'C', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「休眠中的穩定者」。具備心理資源（01A）但目前處於低度參與狀態（06C）。管理建議：這類人具備能力，但缺乏被點燃的火種，需主管賦予具備「使命感」或「趣味性」的目標來活化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1242, 'SPA_06', 'C', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「消極的旁觀者」。對未來預期消極（05C），導致其在工作中僅投入最低限度的精力（06C）。風險：容易成為團隊中的負能量源，需介入輔導其歸因風格。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1243, 'SPA_06', 'C', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「心理罷工者」。因感到不公平（09C），故主動降低工作投入度（06C）以尋求心理補償。管理建議：應優先處理公平感議題，否則給予任何激勵都無效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1244, 'SPA_06', 'C', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「急躁的應付者」。行為上雖然顯得匆忙且具競爭欲望（13A），但其實並未將心力真正奉獻在任務本質上（06C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1245, 'SPA_06', 'C', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「投機的競爭者」。想贏過他人（14A），但不想付出實質的專注與奉獻（06C）。預測：這類人可能追求「短平快」的成果，但在需要深耕的長期業務中表現不佳。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1246, 'SPA_06', 'C', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「因不滿而離職的風險者」。投入度低（06C）且情緒易衝動（18A），一旦遭遇小挫折極易產生「不幹了」的極端行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1247, 'SPA_06', 'C', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「完美的安靜離職者」。行為上維持著社交認可的表現（12A），但內在精神已完全脫離工作（06C），極具隱蔽性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1248, 'SPA_07', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「穩健的高標專家」。心理資源充沛（01A）支持其長期的專業堅持（07A）。預測：在面對長期且高標準的客戶服務時，能維持極高的一致性，不因心理疲勞而降低專業水準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1249, 'SPA_07', 'A', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「策略型的高標者」。既能找到達成路徑（02A），又能在過程中維持極佳的專業細節（07A）。管理建議：其產出的方案不僅「可行」，且具備極高的「品牌價值感」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1250, 'SPA_07', 'A', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「極致的專業勞模」。高度投入工作（06A）且對產出標準有強烈執著（07A）。行為預測：是組織內流程與品質的標竿，能引導團隊建立高水準的工作慣性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1251, 'SPA_07', 'A', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「自我修正的高標者」。為了維持職業高度（07A），會極度主動地尋求並吸收改進建議（08A）。預測：其專業能力會隨職涯長度呈線性以上的成長。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1252, 'SPA_07', 'A', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「追求頂峰的精英」。強大的企圖心（15A）透過嚴謹的職業素養（07A）變現。管理建議：適合負責品牌關鍵業務或高端客戶開發，能建立極佳的市場口碑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1253, 'SPA_07', 'A', 'SPA_16', 'C', '與 SPA_16 (匆忙/多工性) C 聯動：表現為「慢工出細活的匠人」。不喜歡多工並行以防損害品質（16C），堅持完成一項高品質任務後才切換（07A）。警示：在節奏極快、需要大量「快餐式」產出的環境下可能感到壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1254, 'SPA_07', 'A', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「極致冷靜的專業代表」。遇到挫折時情緒穩定（18C），且始終維持代表公司的專業形象與應對準則（07A）。預測：在客訴或爭議場合中，是維護公司信譽的最佳人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1255, 'SPA_07', 'C', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「自信但粗放的行動者」。相信自己能搞定（03A），但容易忽略標準流程或職業禮儀（07C）。風險：個人表現雖強，但容易因不合規範而給公司帶來潛在的品牌形象風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1256, 'SPA_07', 'C', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高耗能的粗心者」。做事積極、步調極快（10A），但因為標準感較鬆（07C），容易在高速推進中漏失細節或破壞規範。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1257, 'SPA_07', 'C', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「急躁的交差者」。為了效率與掌控感（13A），往往會為了「做完」而犧牲「做精」（07C）。管理建議：需提供明確的 Check-list 強制其回頭確認細節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1258, 'SPA_07', 'C', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「只問贏不問流程的競爭者」。勝負心強（14A），但在追求第一的過程中可能採取非標準或有損一致性的路徑（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1259, 'SPA_07', 'C', 'SPA_17', 'A', '與 SPA_17 (時間壓力) A 聯動：表現為「時間壓力下的粗製濫造者」。當感到時間緊迫時（17A），會第一個放棄專業規範以求時程達標（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1260, 'SPA_07', 'C', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「表面專業的隨意者」。口頭上極度配合規範（12A），但實際操作時卻容易因為缺乏內在標準（07C）而出現行為落差。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1261, 'SPA_08', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「自信的優化者」。具備充足心理資源（01A）以緩衝負面反饋的衝擊，視回饋為成長工具而非否定。預測：面對嚴苛批評時能維持情緒穩定並精準提取改進建議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1262, 'SPA_08', 'A', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「目標導向的精進者」。對能力有信心（03A），故敢於詢問「我如何能做得更好」（08A）。管理建議：其成長曲線斜率最高，能將指導快速轉化為產出質量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1263, 'SPA_08', 'A', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「高標準的職人」。為了維持專業高度（07A），會反覆確認自身產出是否符合期待（08A）。預測：極少出現嚴重的執行偏差，是組織內部的品質標竿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1264, 'SPA_08', 'A', 'SPA_11', 'A', '與 SPA_11 (可塑性) A 聯動：表現為「終身學習者」。相信能力可變（11A）且積極透過他人視角識別盲點（08A）。管理建議：非常適合負責新技術導入或需要頻繁轉型的專案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1265, 'SPA_08', 'A', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「具侵略性的晉升者」。為了達成個人目標與權力（15A），會主動收集所有有利於調整戰術的資訊（08A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1266, 'SPA_08', 'A', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「冷靜的資訊吸收者」。能去情緒化地處理反饋內容。預測：即便是具備高度衝突性的回饋，也能理智地過濾雜訊、保留核心建議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1267, 'SPA_08', 'C', 'SPA_03', 'C', '與 SPA_03 (效能感) C 聯動：表現為「躲避評價的萎縮者」。因缺乏信心（03C）而害怕暴露弱點，故極力避免詢問他人意見（08C）。風險：容易在錯誤的道路上悶頭苦幹，最終導致無效產出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1268, 'SPA_08', 'C', 'SPA_04', 'C', '與 SPA_04 (韌性) C 聯動：表現為「玻璃心的自我封閉者」。抗壓韌性低（04C），為了保護脆弱的自尊而排斥外部評價（08C）。管理建議：需主管主動建立非正式、溫和的溝通管道。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1269, 'SPA_08', 'C', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「悲觀的宿命論者」。傾向認為現狀無法改變（05C），因此認為尋求反饋沒有意義（08C）。警示：容易產生職場怠惰或習得性無助。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1270, 'SPA_08', 'C', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「多疑的防禦者」。對公平性敏感（09C）且不信任外部評價（08C），傾向認為他人的反饋是出於偏見或權力打壓。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1271, 'SPA_08', 'C', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「固執的競速者」。追求效率與掌控（13A），往往會因為「沒時間」或「我最懂」而忽視外部修正意見（08C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1272, 'SPA_08', 'C', 'SPA_17', 'A', '與 SPA_17 (時間壓力) A 聯動：表現為「忙中出錯的執行員」。因感到時間緊迫（17A）而捨棄了必要的確認與回饋環節（08C）。風險：雖然交得快，但準確率往往堪憂。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1273, 'SPA_08', 'C', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「表面服從的封閉者」。口頭上同意回饋的重要性（12A），但實際上從不主動去開啟具備實質意義的評價對話（08C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1274, 'SPA_09', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「組織的定海神針」。心理資源充沛（01A）且對回報不計較（09A）。預測：在公司草創期或艱困期，能無怨無悔地投入，不因短期的待遇不均而動搖，是組織忠誠度的標竿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1275, 'SPA_09', 'A', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「純粹的奉獻者」。對工作高度投入（06A）且較不看重即時回報（09A）。管理建議：其動能來自成就感而非物質激勵，是極具使命感的員工，但須提防因過度付出而遭不當利用。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1276, 'SPA_09', 'A', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「自省的關係維護者」。主動尋求回饋（08A）是為了確保自己對團隊的貢獻足夠，而非爭取更多資源（09A）。其互動風格極具合作性，能降低團隊摩擦成本。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1277, 'SPA_09', 'A', 'SPA_11', 'A', '與 SPA_11 (可塑性) A 聯動：表現為「高彈性的長線投資者」。相信能力可變（11A），且願意在看到明確回報前先行投入學習與調整（09A）。預測：在需要跨領域轉型且前期回報不明時，其適應力最強。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1278, 'SPA_09', 'A', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「具格局的衝刺者」。有強大企圖心（15A），但能忍受「延遲滿足」。為了更宏大的長遠目標，願意承受當下的不對等對待或高強度付出（09A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1279, 'SPA_09', 'A', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「豁達的穩定器」。面對資源分配不均時情緒極度冷靜（18C）且內在容忍度高（09A），能有效緩衝團隊內的對立情緒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1280, 'SPA_09', 'C', 'SPA_01', 'C', '與 SPA_01 (心理資本) C 聯動：表現為「焦慮的防禦者」。心理資源緊繃（01C）且對公平性極度敏感（09C）。風險：一旦察覺資源分配微小不公，會迅速進入自我保護模式，降低產出甚至引發激進抗議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1281, 'SPA_09', 'C', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「條件式的拼命三郎」。投入度極高（06A），但要求回饋必須與其付出精確對等（09C）。管理建議：必須提供極其透明、量化的考核與獎勵機制，否則其高產出會瞬間消失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1282, 'SPA_09', 'C', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「具備契約精神的專業職人」。嚴守職業標準（07A），同時也要求公司必須嚴守制度一致性（09C）。警示：若公司帶頭破壞規則，他將是第一個站出來質疑規範合法性的人。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1283, 'SPA_09', 'C', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「急躁的利益爭取者」。進取心強（13A）且對資源分配極度敏感（09C）。其競爭行為往往伴隨著對權益的強烈防禦，容易與同事產生激烈的地盤或資源爭奪。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1284, 'SPA_09', 'C', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「精算型的競爭者」。求勝心切（14A），且會緊盯對手的回報與資源是否優於自己（09C）。風險：容易因感知不公而將競爭轉化為對體制的敵意。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1285, 'SPA_09', 'C', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「公平的正義使者（火藥桶型）」。對不公極度敏感（09C）且反應劇烈（18A）。管理建議：絕對不宜對其採取模糊的黑箱管理，任何決策的公平性解釋必須第一時間到位，否則會引發強烈對抗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1286, 'SPA_09', 'C', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「隱蔽的計較者」。雖然極度在意回饋（09C），但在公共場合會努力表現得合乎規範與優雅（12A）。隱憂：不滿情緒會轉向地下化，容易在背後影響團隊氛圍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1287, 'SPA_10', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「全方位的續航戰士」。體能充裕（10A）且心理韌性強（01A）。預測：在長期、跨國或極高壓的專案中，其身心穩定度極高，是帶領團隊衝破困難期的高產出領袖。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1288, 'SPA_10', 'A', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「高自信的衝鋒者」。既相信自己能做到（03A），且具備充足體力去實踐（10A）。管理建議：其行動力極強，適合承接第一線業務開拓，能維持極高密度的拜訪與工作頻率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1289, 'SPA_10', 'A', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「心流狀態的體踐者」。高度專注工作（06A）且生理動能十足（10A）。行為預測：在工作現場表現出極強的感染力，能同時維持高品質的產出與高昂的精神面貌。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1290, 'SPA_10', 'A', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「高壓競速的超人」。具備強烈的競爭欲與時間緊迫感（13A），且其生理能量（10A）剛好能匹配這種高節奏需求。警示：雖短期表現優異，仍需防範因長期無視疲勞信號而導致的突發性崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1291, 'SPA_10', 'A', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「目標導向的高產能精英」。對成功的強烈渴望（15A）與充沛精力（10A）結合，使其在追求目標時極具侵略性與持久力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1292, 'SPA_10', 'A', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「快節奏的多線處理者」。能在多項任務中快速切換且不顯疲態，是快節奏環境（如快消品、電商）中的理想人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1293, 'SPA_10', 'C', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「精神強大的穩健者」。雖然體能充沛度較低（10C），但靠著強大的內在心理底蘊（01A）維持穩定。管理建議：應優化其工作流程，減少無謂的體力消耗，發揮其心理資源的優勢。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1294, 'SPA_10', 'C', 'SPA_04', 'C', '與 SPA_04 (韌性) C 聯動：表現為「易碎的低能耗者」。生理動能弱（10C）且抗壓韌性低（04C）。風險：在突發的高強度壓力下極易產生逃避心理或生理不適，不宜配置於變動劇烈的環境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1295, 'SPA_05', 'C', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「消沉的悲觀者」。內在缺乏對未來的預期（05C），生理上亦表現出能量不足（10C）。預測：在團隊中表現極度被動，需透過環境刺激或高度結構化的激勵來拉動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1296, 'SPA_10', 'C', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「自律的長跑者」。雖能量有限（10C），但靠著對標準的堅持（07A）精準分配體力，確保留在場上的每一刻都符合專業水準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1297, 'SPA_10', 'C', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「心有餘而力不足的競爭者」。想贏（14A），但體力跟不上其野心（10C）。管理建議：需教導其「智慧工作（Smart Work）」而非體力透支，避免其因力不從心產生憤怒情緒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1298, 'SPA_10', 'C', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「疲憊導致的火藥桶」。生理能量低落時（10C），情緒調控力隨之下降，極易因為勞累而對身邊同事或客戶發火。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1299, 'SPA_10', 'C', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「強打精神的禮貌者」。生理已感到疲憊（10C），但為了維持正面形象（12A）仍苦撐社交。警示：下班後會有嚴重的「社交脫水」現象，需給予其安靜的補能空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1300, 'SPA_11', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「全方位的進化者」。相信能力可變（11A）且具備充足心理資源（01A）去支撐改變過程中的陣痛。預測：在企業轉型期能率先適應新角色，並將改變視為累積心理資本的機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1301, 'SPA_11', 'A', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「具備路徑靈活性的學習者」。因相信自己能改變（11A），故在目標受阻時，能更有動力去規劃全新的達成路徑（02A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1302, 'SPA_11', 'A', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「高效的自我重塑者」。對現有能力有信心（03A），且相信未來能透過學習變得更強（11A）。管理建議：給予挑戰性極高的任務，他們會將其視為「升級」的必經過程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1303, 'SPA_11', 'A', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「主動尋求進化的精英」。相信改進是有效的（11A），因此會不遺餘力地從回饋中挖掘優化空間（08A）。預測：其能力成長速度會顯著高於同儕。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1304, 'SPA_11', 'A', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「具備戰術調整力的競爭者」。渴望贏過他人（14A），且願意為了取勝而不斷調整自己的行為模式與技能（11A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1305, 'SPA_11', 'A', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「無邊界的攀登者」。強大的成就欲望（15A）配合對自我改造的開放性（11A）。管理建議：適合作為組織內部的跨領域人才儲備。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1306, 'SPA_11', 'C', 'SPA_01', 'C', '與 SPA_01 (心理資本) C 聯動：表現為「認命的枯竭者」。心理資源匱乏（01C）且不相信現狀能改善（11C）。風險：極易陷入長期的職業倦怠，對任何激勵與變革都表現出防禦性的消極。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1307, 'SPA_11', 'C', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「頑強的守舊者」。能扛住壓力不崩潰（04A），但其應對方式僵化，拒絕透過改變自我來適應新環境（11C）。管理建議：需主管透過外部強制作為強制其踏出舒適圈。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1308, 'SPA_11', 'C', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「宿命論的悲觀者」。認為未來是灰暗的（05C），且能力是天生的、不可改變的（11C）。警示：容易散播「努力無用論」，影響團隊士氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1309, 'SPA_11', 'C', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「刻板的職人」。高度遵守既定標準（07A），但對超越標準的新方法或技能轉型表現出極強的心理抗拒（11C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1310, 'SPA_11', 'C', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「防禦性的計算者」。因不相信未來可期（11C），故極度計較當下的得失與公平性（09C），缺乏為了長遠成長而暫時忍讓的格局。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1311, 'SPA_11', 'C', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「急躁的慣性者」。雖然行為匆忙、追求速度（13A），但其實只是在用舊有的方法加速運作，拒絕反思或調整核心策略（11C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1312, 'SPA_11', 'C', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「易爆的定型者」。當被要求改變或遭遇不順時，因認為自己「就是這樣」（11C），會引發強烈的情緒對抗或衝動反應（18A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1313, 'SPA_12', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「無懈可擊的職業典範」。心理資源充足（01A）且極其在意專業形象（12A）。預測：這類人會努力展現出完美戰士的狀態，即便感到疲累也會隱藏，直到資源耗盡。警示：主管需主動偵測其「面具」下的真實負擔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1314, 'SPA_12', 'A', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「極具感染力的模範生」。高度投入工作（06A）且展現出符合組織期望的高能量狀態（12A）。行為預測：能有效帶動團隊士氣，因為他們不僅做得多，且「看起來」極度樂觀積極。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1315, 'SPA_12', 'A', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「謙遜的認可追求者」。主動要回饋（08A）的一部分目的是為了確認自己是否符合他人的「優秀標籤」（12A）。管理建議：其改進動機深受外部肯定驅動，應多給予正面回饋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1316, 'SPA_12', 'A', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「優雅的競速者」。具備 A 型性格的急促與競爭欲（13A），但會透過形象管理（12A）修飾其侵略性。風險：這種長期的「外圓內方」會帶來極大的心理內耗，易在私下爆發。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1317, 'SPA_12', 'A', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「壓抑的火山」。天性情緒反應快（18A），但極力維持得體形象（12A）。行為預測：在公眾場合表現得體，但一旦在壓力點超過臨界值，會發生令人驚訝的斷裂式崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1318, 'SPA_12', 'C', 'SPA_01', 'C', '與 SPA_01 (心理資本) C 聯动：表現為「透明的困境者」。心理資源不足（01C）時會直白展現其無助與疲憊（12C）。管理建議：這是最容易識別並提供支援的對象，其求救信號通常是真實且及時的。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1319, 'SPA_12', 'C', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「求真务實的專才」。堅持標準（07A）並直接指出不合規之處（12C），不屑於為了職場政治而粉飾太平。預測：是組織中極佳的品質監察者或風險預警者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1320, 'SPA_12', 'C', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「直白的利益捍衛者」。對不公平敏感（09C）且會不加修飾地表達出來（12C）。警示：在資源分配衝突中，他們會是第一個發難的人，雖可能造成尷尬，但其反饋具有高度的環境真實性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1321, 'SPA_12', 'C', 'SPA_11', 'C', '與 SPA_11 (可塑性) C 聯動：表現為「頑強的自保者」。不相信改變（11C）且不屑於假裝配合（12C）。管理建議：這類人的阻力是顯性的，需透過硬性的資源交換或清晰的因果邏輯來說服，而非情感動員。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1322, 'SPA_12', 'C', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「赤裸的競爭者」。渴望贏過他人（14A）且毫不掩飾這種勝負欲（12C）。預測：在競爭中極具侵略性，不計較社交和諧，是以結果為絕對導向的戰士。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1323, 'SPA_12', 'C', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「坦蕩的野心家」。不掩飾對權力與成就的渴望（15A, 12C）。管理建議：給予清晰的晉升路徑即可有效激勵，他們對虛偽的讚美不感興趣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1324, 'SPA_12', 'C', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「火爆的直腸子」。情緒反應快（18A）且從不修飾（12C）。行為預測：喜怒哀樂全寫在臉上，雖容易造成人際張力，但合作者能隨時知道其真實狀態，溝通透明度高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1325, 'SPA_13', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「強悍的動力火車」。心理資源充沛（01A）支持其高競爭、快節奏的行為模式（13A）。預測：能承受極高強度的連軸轉工作，是組織在極端環境下搶占市佔率的核心力量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1326, 'SPA_13', 'A', 'SPA_04', 'C', '與 SPA_04 (韌性) C 聯動：表現為「易折斷的利刃」。進取心強且急躁（13A），但抗壓與復原力弱（04C）。警示：一旦進度受阻或遭遇突發打擊，這類人極易產生劇烈的挫折感甚至身心崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1327, 'SPA_13', 'A', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「嚴苛的高效職人」。既追求極致速度（13A），又不允許品質打折（07A）。管理建議：其自我要求極高，但也容易將壓力轉嫁給下屬或同事，需關注其在團隊中的人際張力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1328, 'SPA_13', 'A', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「迫切的自我修正者」。為了贏得競爭（13A），會主動要回饋以求第一時間調整（08A）。其對回饋的需求帶有強烈的目的性與時效感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1329, 'SPA_13', 'A', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「永動型戰鬥員」。體力與精神能量（10A）完全匹配其快節奏的追求（13A）。行為預測：在第一線銷售或高頻率商務開發中，展現出驚人的產能與氣場。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1330, 'SPA_13', 'A', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「極致的競技選手」。視所有任務為競賽（14A），且行動具備強烈的掌控欲與時效性（13A）。風險：可能因過度求勝而忽略團隊協作或合規細節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1331, 'SPA_13', 'A', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「易燃的進取者」。時間緊迫感強（13A）且情緒反應快（18A）。管理建議：在任務延誤或遭遇不配合時，極易爆發衝突。需建立明確的「降溫溝通規範」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1332, 'SPA_13', 'C', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「沉穩的長期主義者」。具備心理資源（01A），但不急於表現或爭奪，傾向步調穩定的產出（13C）。預測：在需要耐心蹲點、深耕關係的業務中展現極強的穩定性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1333, 'SPA_13', 'C', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高能的佛系戰士」。能量充裕（10A）但節奏平穩、不追求競速（13C）。管理建議：適合需要長時間、重複性高品質輸出的崗位，能做到「高效而不急躁」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1334, 'SPA_13', 'C', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「溫和的職場公關」。行為不具備侵略性（13C），且高度在意社交形象（12A）。行為預測：是建立團隊和諧氛圍的理想人選，深受客戶與同事信賴。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1335, 'SPA_13', 'C', 'SPA_14', 'C', '與 SPA_14 (競爭欲望) C 聯動：表現為「協作導向的守位者」。不以贏過他人為榮（14C），且工作步調穩定不亢奮（13C）。適合環境：強調內部支援、技術研發或法務控管等非強競爭崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1336, 'SPA_13', 'C', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「從容的多面手」。雖然同時處理多項任務（16A），但內在不帶有競速的焦慮（13C）。預測：在混亂環境中能保持清醒，一件一件穩紮穩打完成。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1337, 'SPA_13', 'C', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「極致理性的穩重者」。不具備敵意特質（13C）且情緒極度穩定（18C）。管理建議：是組織中最理想的衝突調停者與高階後勤支持者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1338, 'SPA_14', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「強悍且穩定的競賽者」。具備足夠的心理資源（01A）支持其強烈的贏球慾望（14A）。預測：在激烈的業績排名戰中，能維持高昂鬥志且不容易因為暫時落後而產生心理挫折。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1339, 'SPA_14', 'A', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「自信的進攻方」。既想贏（14A），也深信自己有贏的能力（03A）。管理建議：其主動性極高，適合承接對手強勁、需要「搶旗」的業務場景，是組織的突擊隊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1340, 'SPA_14', 'A', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「有風度的贏家」。追求領先（14A）但絕不以犧牲專業標準或品牌形象為代價（07A）。預測：能為組織爭取最高榮譽，且產出兼具競爭力與專業品質感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1341, 'SPA_14', 'A', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「戰術驅動的領先者」。為了確保贏過對手（14A），會極度主動地尋求反饋（08A）以找出敵我盲點。其回饋尋求帶有強烈的目的性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1342, 'SPA_14', 'A', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「對資源分配極度敏感的競爭者」。想贏（14A）且會緊盯自己與他人的回報對等性（09C）。風險：容易因為覺得公司分配不公而將競爭轉向內部摩擦，需明確其獎勵與付出的量化關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1343, 'SPA_14', 'A', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「侵略性極強的先行者」。競爭欲（14A）結合了急躁、掌控欲與敵意傾向（13A）。警示：雖能創造驚人戰績，但容易在團隊中造成「零和遊戲」的對立感，需注意人際張力管控。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1344, 'SPA_14', 'A', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「攀登權力巔峰的鬥士」。強大的晉升渴望（15A）與實戰中的勝負欲（14A）結合。管理建議：這類人是組織的核心幹部預備人選，應給予具備晉升誘因的戰鬥型職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1345, 'SPA_14', 'C', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「淡泊名利的穩健派」。具備心理資源（01A）但對贏過他人不感興趣（14C），更看重自身的穩定與成長。預測：在團隊中扮演協作者與守成者角色，是極佳的穩定力量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1346, 'SPA_14', 'C', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「利他的勞模」。高度投入工作（06A）並非為了贏過誰，而是為了達成團隊使命或個人價值實現。其投入行為不具攻擊性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1347, 'SPA_14', 'C', 'SPA_11', 'A', '與 SPA_11 (可塑性) A 聯動：表現為「共好型的學習者」。相信努力能改變（11A），且願意分享自己的學習所得，不擔心被他人超越（14C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1348, 'SPA_14', 'C', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「溫和的團隊潤滑劑」。較少展現進取心與敵意（14C），且高度在意社交形象與和諧（12A）。適合環境：需要高度團隊協作、客戶經營與客服相關的職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1349, 'SPA_14', 'C', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「忙碌但無害的支援者」。節奏雖快且處理多工（16A），但並非為了爭強好勝，而是為了維持流程運作（14C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1350, 'SPA_14', 'C', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「極致穩定的協作者」。既不想與人爭鋒（14C），情緒亦極其受控穩定（18C）。管理建議：是組織中最理想的資源分配者與後勤窗口，能客觀處理多方需求而不帶私利色彩。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1351, 'SPA_15', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「基石穩固的征服者」。強大的成功渴望（15A）配合充沛的心理資源（01A）。預測：在追求高難度目標時，不僅具備攻擊性，更能承受長期壓力而不崩潰，是高階管理者的核心特質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1352, 'SPA_15', 'A', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「具路徑感的野心家」。既想往上衝（15A），又能主動規劃出達成晉升的多條可行路徑（02A）。管理建議：應給予明確的晉升階梯，他們會自發性地找到方法達標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1353, 'SPA_15', 'A', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「極致自信的拓荒者」。追求頂尖成功（15A）且深信自己具備勝任的能力（03A）。行為預測：會主動請纓承擔難度最高、曝光度最大的任務以累積戰功。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1354, 'SPA_15', 'A', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「使命必達的精英」。將工作視為獲取成就的唯一修煉場，展現出驚人的奉獻精神（06A, 15A）。其投入往往帶有高度的目的性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1355, 'SPA_15', 'A', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「追求專業權威的精英」。不僅想贏，更要以極高標準贏得漂亮（07A）。預測：其成就不僅體現在數據，更體現在建立行業影響力與品牌標竿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1356, 'SPA_15', 'A', 'SPA_11', 'A', '與 SPA_11 (可塑性) A 聯動：表現為「無極限的進化者」。為了攀登更高職位（15A），極度願意學習新知識與改變舊習（11A）。管理建議：是組織進行跨領域輪調、培養接班人的首選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1357, 'SPA_15', 'A', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「侵略性的競技者」。渴望成功（15A）且必須透過擊敗對手來證明（14A）。風險：在內部合作中可能過於強勢，需建立良好的「共贏制度」來引導其能量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1358, 'SPA_15', 'C', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「精神富足的穩定者」。具備心理韌性與能量（01A），但對於權力或職位晉升缺乏強烈興趣（15C）。預測：在穩定崗位中表現極佳，是團隊中的「壓艙石」，不會因未獲提拔而抱怨。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1359, 'SPA_15', 'C', 'SPA_04', 'C', '與 SPA_15 (企圖心) C 聯動：表現為「安於現狀的自保者」。缺乏動力攀升（15C）且抗壓韌性低（04C）。管理建議：應配置於變動極小、無需主動開發的環境中，以發揮其守成功能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1360, 'SPA_15', 'C', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「純粹的職人」。對晉升沒興趣（15C），但對專業標準有極高執著（07A）。行為預測：會把現有工作做到極致，是技術、品質或內控領域的「隱形冠軍」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1361, 'SPA_15', 'C', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高能的執行員」。活力充沛、做事積極（10A），但缺乏成為領袖或追求社會地位的野心（15C）。管理建議：適合需要高度體力、重複性高能產出的職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1362, 'SPA_15', 'C', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「急躁的守位者」。雖然行為步調快且具緊迫感（13A），但動機並非追求更高的職位（15C），而是源於對現狀的掌控欲。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1363, 'SPA_15', 'C', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「淡泊的智者」。不追求功名（15C）且情緒極其穩定冷靜（18C）。適合角色：內控、審核、或任何需要高度客觀且不受利益引誘的崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1364, 'SPA_16', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「全能的高速引擎」。具備充足心理資源（01A）來支撐多線並行的心理負荷（16A）。預測：能同時處理多個高壓專案且維持積極態度，是組織在業績衝刺期或多角化經營時的核心戰力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1365, 'SPA_16', 'A', 'SPA_04', 'C', '與 SPA_04 (韌性) C 聯動：表現為「高速行駛的易碎者」。步調極快且多工（16A），但心理復原力與抗壓性不足（04C）。風險：極度容易發生身心燃盡（Burnout），一旦其中一項任務崩潰，會引發連鎖性的挫折感與失能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1366, 'SPA_16', 'A', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「具備高品質的競速者」。追求速度（16A）的同時，對專業標準有極高執著（07A）。警示：這類人常處於高度自我焦慮中，因其在「快」與「好」之間不斷拉扯，需適時提醒其資源分配的輕重緩急。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1367, 'SPA_16', 'A', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高能的現場指揮官」。生理動能充足（10A）完全匹配其多工需求（16A）。行為預測：在動態環境中具備極強的反應力與覆蓋面，能同時推進多個客戶關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1368, 'SPA_16', 'A', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「極速前進的戰鬥機」。多工、競速（16A）且帶有強烈的時間緊迫感與競爭欲（13A）。管理建議：其攻擊性與節奏感極強，但容易對慢節奏的同事展現敵意，需配置同樣高節奏的隊友。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1369, 'SPA_16', 'A', 'SPA_17', 'A', '與 SPA_17 (時間壓力) A 聯動：表現為「與時間賽跑的焦慮者」。因同時處理多項事務（16A），加上對時間極度敏感（17A），常處於緊繃與催促狀態。預測：雖然出件極快，但需嚴格複核其收尾細節，預防粗心導致的錯誤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1370, 'SPA_16', 'A', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「忙碌中的火藥桶」。多工帶來的心理負荷（16A）一旦遇到延誤，會迅速轉化為情緒爆發（18A）。風險：容易在忙碌中失言或做出衝動決定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1371, 'SPA_16', 'C', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「穩定且深耕的職人」。心理資源穩定（01A），傾向於一次處理好一件事（16C）。預測：在需要長期經營、複雜邏輯或高品質打磨的任務中，能展現出極高的可信度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1372, 'SPA_16', 'C', 'SPA_03', 'C', '與 SPA_03 (效能感) C 聯動：表現為「步步為營的遲疑者」。因信心不足（03C），故更依賴一次專注一件事（16C）來累積掌控感。管理建議：應避免將其置於多變、零散的工作環境，否則會因無法兼顧而產生嚴重的失能感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1373, 'SPA_16', 'C', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「不屈的慢跑者」。雖不追求多工並行（16C），但面對壓力極具韌性（04A）。行為預測：適合處理具有長期挑戰、需要耐心與持續磨合的難搞專案，雖然慢，但絕不放棄。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1374, 'SPA_16', 'C', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「注重細節的匠人」。堅持標準（07A）高於速度，偏好專注完成高品質作品（16C）。管理建議：適合品質控管、法務審查或精密數據分析等低容錯率崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1375, 'SPA_16', 'C', 'SPA_13', 'C', '與 SPA_13 (A型性格) C 聯動：表現為「平衡感極佳的協作者」。不急躁、不競速（13C, 16C），更重視合作與步調穩健。適合環境：強調團隊和諧與長線口碑經營的組織環境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1376, 'SPA_16', 'C', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「極致穩定的協調者」。節奏穩定（16C）且情緒極其理性冷靜（18C）。管理建議：在混亂的衝突現場，他是理順流程、穩定軍心的最佳協調人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1377, 'SPA_17', 'A', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「抗壓的短跑健將」。具備充足心理資源（01A）來緩衝高時間壓力（17A）。預測：能在極短期限內爆發高產能，且心理狀態不會崩潰，是處理緊急專案與危機公關的最佳人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1378, 'SPA_17', 'A', 'SPA_04', 'C', '與 SPA_04 (韌性) C 聯動：表現為「焦慮的溺水者」。時間敏感度高（17A）但心理復原力弱（04C）。風險：在截止日期臨近時，極易因為壓力過載而產生生理性不適或判斷力癱瘓，需主管介入協助任務拆解。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1379, 'SPA_17', 'A', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「追求極致的快槍手」。要在時限內（17A）交出超越標準的作品（07A）。警示：這類人常處於「自我壓榨」狀態，雖然產出優質，但長期身心損耗極大，需注意過勞風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1380, 'SPA_17', 'A', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高能的競速者」。生理動能十足（10A）配合強烈的時間緊迫感（17A）。行為預測：在第一線銷售開發中，其開發頻率與結案速度會顯著高於平均，適合節奏極快的環境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1381, 'SPA_17', 'A', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「分秒必爭的戰士」。時間緊迫（17A）與競爭欲（13A）高度重合。管理建議：其效率驚人，但對「延誤」容忍度極低。需防範其因他人速度跟不上而引發的職場衝突。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1382, 'SPA_17', 'A', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「高效但混亂的處理器」。同時做很多事（16A）且急於完成（17A）。風險：容易在追求速度的過程中發生細節失誤或「欲速則不達」，需配置行政輔助進行收尾查核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1383, 'SPA_17', 'A', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「壓力下的火藥桶」。時間緊迫（17A）且情緒易衝動（18A）。預測：在截止日當天最容易對同事發火，情緒波動與任務時程呈強烈正相關。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1384, 'SPA_17', 'C', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「從容的指揮官」。心理底蘊深厚（01A）且不受時間左右（17C）。預測：在混亂與延誤中仍能保持優雅節奏，是建立長期、穩定、高品質客戶關係的理想人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1385, 'SPA_17', 'C', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「沉浸式的職人」。高度投入（06A）且不被時間壓力干擾（17C），容易進入「心流」狀態。管理建議：適合負責需要深度思考、策略研究或長線耕耘的任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1386, 'SPA_17', 'C', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「慢工出細活的專家」。堅持標準（07A）重於速度，對他們而言，「做對」比「做快」更重要（17C）。適合角色：法務、風控、精密技術研發。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1387, 'SPA_17', 'C', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「冷靜的競爭者」。渴望贏（13A）但行動不帶有時間焦慮（17C）。行為預測：這類人像冷血殺手，會精確計算時機再出手，而非盲目衝刺。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1388, 'SPA_17', 'C', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「穩健的多面手」。能處理多項任務（16A）但步調極穩（17C）。預測：雖然多線進行，但產出節奏極度可信，不會因為趕工而犧牲任何一線的品質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1389, 'SPA_17', 'C', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「極致穩定的防線」。不被時間催促（17C）且情緒極受控（18C）。管理建議：是組織中最理想的緊急應變協調人，能在眾人焦慮時提供冷靜的決策支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1390, 'SPA_18', 'A', 'SPA_01', 'C', '與 SPA_01 (心理資本) C 聯動：表現為「脆弱的易燃物」。心理資源匱乏（01C）使其對負面訊號毫無緩衝力，受挫時會迅速爆發（18A）。預測：在業績不佳或被拒絕時，容易出現情緒崩潰或遷怒他人的行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1391, 'SPA_18', 'A', 'SPA_04', 'C', '與 SPA_04 (韌性) C 聯動：表現為「情緒復原慢的引爆點」。受挫時反應劇烈（18A），且因為韌性差（04C），情緒升溫後極難降溫，會長時間受困於負面心境中。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1392, 'SPA_18', 'A', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「追求專業的焦慮者」。雖然重視標準與形象（07A），但因天性衝動（18A），在流程出錯或他人不合規範時會立即展現嚴厲、語氣僵硬的對抗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1393, 'SPA_18', 'A', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「反應激烈的受教者」。雖主動要回饋（08A），但聽到批評的瞬間仍會反射性地防禦或情緒激動（18A）。管理建議：反饋應分段進行，並給予情緒冷卻期。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1394, 'SPA_18', 'A', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「公平的正義使者（火爆型）」。對不公極度敏感（09C）且會立即、大聲地表達不滿（18A）。風險：極易在資源分配不均時引發公開的衝突或集體抗議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1395, 'SPA_18', 'A', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「最具侵略性的戰將」。追求速度、掌控（13A）且伴隨易激發的敵意（18A）。警示：這是人際張力最高組合，雖能衝刺目標，但極度破壞團隊和諧。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1396, 'SPA_18', 'A', 'SPA_17', 'A', '與 SPA_17 (時間壓力) A 聯動：表現為「期限前的炸彈」。隨時間緊迫（17A），情緒升溫極快（18A），常因趕工對同事展現出極度不耐與急躁。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1397, 'SPA_18', 'C', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「深不可測的守護者」。強大的心理底蘊（01A）配合極高的情緒門檻（18C）。預測：即便在重大危機中也能面不改色地調度資源，是組織中最強的決策壓艙石。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1398, 'SPA_18', 'C', 'SPA_03', 'C', '與 SPA_03 (效能感) C 聯動：表現為「沉默的自我懷疑者」。雖對自己沒信心（03C），但受挫時情緒亦不會劇烈起伏，傾向於安靜地縮手。管理建議：需主管主動探詢，因為其負面情緒極其隱蔽。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1399, 'SPA_18', 'C', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「不動如山的長跑者」。遭遇打擊時能理性分析（18C）並快速重回戰場（04A）。行為預測：在長期、高頻被拒絕的業務中表現最為堅韌、穩定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1400, 'SPA_18', 'C', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「完美的學習者」。主動尋求回饋（08A）且能淡化情緒雜訊、理性吸納建議（18C）。其成長效率在 18 項特質組合中排名第一。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1401, 'SPA_18', 'C', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「冷靜的競速者」。追求效率與成果（13A），但過程情緒穩定、不具敵意（18C）。管理建議：適合作為跨部門專案經理，能推動節奏而不引發反感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (1402, 'SPA_18', 'C', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「理性的競技選手」。渴望贏（14A），但輸贏皆不形於色（18C）。這類人會精確分析對手強弱而非情緒化對抗，極其難纏。');
